import java.awt.image.*;
import java.util.Random;

public class Dbg2 {
    static final int FS_SCALE = 1 << 8;
    static final Random RANDOM = new Random();
    static IndexColorModel grey(int levels) {
        int[] c = new int[levels];
        for (int i = 0; i < levels; i++) {
            int v = (i * 255) / (levels - 1);
            c[i] = 0xFF000000 | (v << 16) | (v << 8) | v;
        }
        return new IndexColorModel(8, levels, c, 0, false, -1, DataBuffer.TYPE_BYTE);
    }
    static int toIntARGB(int[] p) { return 0xff000000 | (p[0] << 16) | (p[1] << 8) | p[2]; }
    static void toRGBArray(int a, int[] b) { b[0] = (a & 0xff0000) >> 16; b[1] = (a & 0xff00) >> 8; b[2] = a & 0xff; }

    public static void main(String[] args) {
        IndexColorModel cm = grey(256);
        int w = 24, h = 8;
        BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) img.setRGB(x, y, 0x808080);
        Raster src = img.getRaster();
        WritableRaster dst = cm.createCompatibleWritableRaster(w, h);
        int[][] currErr = new int[w + 2][3], nextErr = new int[w + 2][3];
        for (int i = 0; i < w + 2; i++) for (int c = 0; c < 3; c++) currErr[i][c] = RANDOM.nextInt(FS_SCALE*2) - FS_SCALE;
        int[] diff = new int[3], inRGB = new int[4], outRGB = new int[4];
        Object pixel = null;
        for (int y = 0; y < h; y++) {
            for (int i = nextErr.length; --i >= 0;) { nextErr[i][0] = nextErr[i][1] = nextErr[i][2] = 0; }
            for (int x = 0; x < w; x++) {
                src.getPixel(x, y, inRGB);
                for (int i = 0; i < 3; i++) {
                    inRGB[i] = ((inRGB[i] << 4) + currErr[x + 1][i] + 0x08) >> 4;
                    if (inRGB[i] > 255) inRGB[i] = 255;
                    else if (inRGB[i] < 0) inRGB[i] = 0;
                }
                pixel = cm.getDataElements(toIntARGB(inRGB), pixel);
                dst.setDataElements(x, y, pixel);
                dst.getPixel(x, y, outRGB);
                toRGBArray(cm.getRGB(outRGB[0]), outRGB);
                diff[0] = inRGB[0] - outRGB[0];
                if (y < 2 && diff[0] != 0) {
                    System.out.println("y=" + y + " x=" + x + " in=" + inRGB[0] + " out=" + outRGB[0] + " idx=" + outRGB[0] + " diff=" + diff[0] + " err=" + currErr[x+1][0]);
                }
                currErr[x + 2][0] += diff[0] * 7;
                nextErr[x][0] += diff[0] * 3;
                nextErr[x + 1][0] += diff[0] * 5;
                nextErr[x + 2][0] += diff[0];
            }
            int[][] t = currErr; currErr = nextErr; nextErr = t;
        }
    }
}
EOF
