package com.twelvemonkeys.image;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import java.awt.image.BufferedImage;
import java.awt.image.DataBuffer;
import java.awt.image.IndexColorModel;
import java.awt.image.Raster;
import java.awt.image.WritableRaster;
import java.util.Random;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests {@code DiffusionDither.filter(Raster, WritableRaster, IndexColorModel)}.
 * <p>
 * The filter injects a small amount of pseudo random error into the first row
 * of the image, so the exact output pixels are not reproducible. The tests
 * therefore verify invariants that must hold for any (valid) run of the
 * algorithm: the returned raster identity, geometry and layout, the palette
 * membership of every output sample, preservation of the source raster, and
 * the dithering behaviour (spatial and average colour reproduction).
 */
public class DiffusionDitherFilterTests {

    /** Black / white palette, far apart enough that quantisation is unambiguous. */
    private static final IndexColorModel BLACK_WHITE =
            new IndexColorModel(8, 2, new int[]{0xFF000000, 0xFFFFFFFF}, 0, false, -1, DataBuffer.TYPE_BYTE);

    /** Palette with a single colour; every pixel must quantise to index 0. */
    private static final IndexColorModel SINGLE_COLOUR =
            new IndexColorModel(8, 1, new int[]{0xFF3366CC}, 0, false, -1, DataBuffer.TYPE_BYTE);

    /** Complete grey ramp; every 8 bit grey value has an exact palette match. */
    private static final IndexColorModel GREY_RAMP = createGreyPalette(256);

    /** Coarse grey ramp, forces error diffusion over larger distances. */
    private static final IndexColorModel GREY_8 = createGreyPalette(8);

    private static IndexColorModel createGreyPalette(int pLevels) {
        int[] cmap = new int[pLevels];
        for (int i = 0; i < pLevels; i++) {
            int v = (i * 255) / (pLevels - 1);
            cmap[i] = 0xFF000000 | (v << 16) | (v << 8) | v;
        }
        return new IndexColorModel(8, pLevels, cmap, 0, false, -1, DataBuffer.TYPE_BYTE);
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static BufferedImage uniformImage(int pWidth, int pHeight, int pRGB) {
        BufferedImage image = new BufferedImage(pWidth, pHeight, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < pHeight; y++) {
            for (int x = 0; x < pWidth; x++) {
                image.setRGB(x, y, pRGB);
            }
        }
        return image;
    }

    private static BufferedImage horizontalGradient(int pWidth, int pHeight) {
        BufferedImage image = new BufferedImage(pWidth, pHeight, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < pHeight; y++) {
            for (int x = 0; x < pWidth; x++) {
                int v = (x * 255) / (pWidth - 1);
                image.setRGB(x, y, (v << 16) | (v << 8) | v);
            }
        }
        return image;
    }

    private static BufferedImage noiseImage(int pWidth, int pHeight, long pSeed) {
        BufferedImage image = new BufferedImage(pWidth, pHeight, BufferedImage.TYPE_INT_RGB);
        Random random = new Random(pSeed);
        for (int y = 0; y < pHeight; y++) {
            for (int x = 0; x < pWidth; x++) {
                image.setRGB(x, y, random.nextInt(0x1000000));
            }
        }
        return image;
    }

    /** Returns all samples of a single band raster, row major. */
    private static int[] samples(WritableRaster pRaster) {
        int[] samples = new int[pRaster.getWidth() * pRaster.getHeight()];
        int[] pixel = new int[pRaster.getNumBands()];
        int i = 0;
        for (int y = 0; y < pRaster.getHeight(); y++) {
            for (int x = 0; x < pRaster.getWidth(); x++) {
                pRaster.getPixel(x, y, pixel);
                samples[i++] = pixel[0];
            }
        }
        return samples;
    }

    private static int greyOf(IndexColorModel pColorModel, int pIndex) {
        return pColorModel.getRGB(pIndex) & 0xFF;
    }

    private static void assertAllSamplesInRange(int[] pSamples, int pMax) {
        for (int sample : pSamples) {
            assertTrue(sample >= 0 && sample <= pMax,
                    "Sample " + sample + " outside valid palette index range [0, " + pMax + "]");
        }
    }

    // ------------------------------------------------------------------
    // Return value / destination raster handling
    // ------------------------------------------------------------------

    @Test
    @DisplayName("filter() must return the supplied destination raster")
    void shouldReturnSuppliedDestinationRaster() {
        IndexColorModel icm = BLACK_WHITE;
        Raster source = uniformImage(7, 5, 0x808080).getRaster();
        WritableRaster dest = icm.createCompatibleWritableRaster(7, 5);

        WritableRaster result = new DiffusionDither(icm).filter(source, dest, icm);

        assertSame(dest, result, "Expected the provided destination raster to be returned unchanged");
    }

    @Test
    @DisplayName("filter() must create a compatible destination raster when dest is null")
    void shouldCreateCompatibleDestinationRasterWhenNull() {
        IndexColorModel icm = GREY_8;
        Raster source = uniformImage(13, 9, 0x404040).getRaster();

        WritableRaster result = new DiffusionDither(icm).filter(source, null, icm);

        assertNotNull(result, "Destination raster should have been created");
        assertEquals(13, result.getWidth(), "Width of created raster");
        assertEquals(9, result.getHeight(), "Height of created raster");
        assertEquals(1, result.getNumBands(), "Indexed rasters have exactly one band");
        assertEquals(DataBuffer.TYPE_BYTE, result.getTransferType(), "Indexed rasters use byte samples");
        assertTrue(icm.isCompatibleRaster(result), "Created raster should be compatible with the colour model");
    }

    @Test
    @DisplayName("filter() must overwrite pre-existing data in a supplied destination raster")
    void shouldOverwriteProvidedDestinationRaster() {
        IndexColorModel icm = BLACK_WHITE;
        int width = 16;
        int height = 4;
        Raster source = uniformImage(width, height, 0xFFFFFF).getRaster();
        WritableRaster dest = icm.createCompatibleWritableRaster(width, height);
        // Pre-fill with colour 0 (black); a white source must overwrite it
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                dest.setSample(x, y, 0, 0);
            }
        }

        WritableRaster result = new DiffusionDither(icm).filter(source, dest, icm);

        assertSame(dest, result);
        int[] samples = samples(result);
        assertEquals(width * height, samples.length);
        for (int sample : samples) {
            assertEquals(1, sample, "White source pixels must be dithered to the white palette entry");
        }
    }

    // ------------------------------------------------------------------
    // Palette membership
    // ------------------------------------------------------------------

    @Test
    @DisplayName("filter() with a single colour palette must map every pixel to index 0")
    void shouldMapEveryPixelToOnlyPaletteEntry() {
        IndexColorModel icm = SINGLE_COLOUR;
        Raster source = noiseImage(17, 11, 42L).getRaster();

        WritableRaster result = new DiffusionDither(icm).filter(source, null, icm);

        int[] samples = samples(result);
        assertEquals(17 * 11, samples.length);
        for (int sample : samples) {
            assertEquals(0, sample, "Only one palette entry exists, every pixel must use it");
        }
    }

    @ParameterizedTest(name = "source type {0}")
    @ValueSource(ints = {BufferedImage.TYPE_INT_RGB, BufferedImage.TYPE_INT_ARGB, BufferedImage.TYPE_3BYTE_BGR})
    @DisplayName("filter() must produce only valid palette indices for any sRGB-like source type")
    void shouldProduceOnlyValidPaletteIndices(int pSourceType) {
        IndexColorModel icm = GREY_8;
        int width = 21;
        int height = 13;
        BufferedImage sourceImage = new BufferedImage(width, height, pSourceType);
        Random random = new Random(4711L + pSourceType);
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                sourceImage.setRGB(x, y, random.nextInt(0x1000000));
            }
        }

        WritableRaster result = new DiffusionDither(icm).filter(sourceImage.getRaster(), null, icm);

        int[] samples = samples(result);
        assertEquals(width * height, samples.length);
        assertAllSamplesInRange(samples, 7);

        // Sanity: a dithered noise image must use more than a single palette entry
        boolean hasMoreThanOne = false;
        for (int sample : samples) {
            if (sample != samples[0]) {
                hasMoreThanOne = true;
                break;
            }
        }
        assertTrue(hasMoreThanOne, "Dithering a noisy image should use several palette entries");
    }

    @Test
    @DisplayName("filter() must quantise a pure black source to the black entry")
    void shouldQuantizeBlackSourceToBlackEntry() {
        IndexColorModel icm = BLACK_WHITE;
        Raster source = uniformImage(32, 16, 0x000000).getRaster();

        int[] samples = samples(new DiffusionDither(icm).filter(source, null, icm));

        assertEquals(32 * 16, samples.length);
        for (int sample : samples) {
            assertEquals(0, sample, "Black input must map to the black palette entry (index 0)");
        }
    }

    @Test
    @DisplayName("filter() must quantise a pure white source to the white entry")
    void shouldQuantizeWhiteSourceToWhiteEntry() {
        IndexColorModel icm = BLACK_WHITE;
        Raster source = uniformImage(32, 16, 0xFFFFFF).getRaster();

        int[] samples = samples(new DiffusionDither(icm).filter(source, null, icm));

        assertEquals(32 * 16, samples.length);
        for (int sample : samples) {
            assertEquals(1, sample, "White input must map to the white palette entry (index 1)");
        }
    }

    @Test
    @DisplayName("filter() with a complete grey palette must reproduce grey levels closely")
    void shouldReproduceExactValuesWithCompleteGreyPalette() {
        IndexColorModel icm = GREY_RAMP;
        int width = 24;
        int height = 8;
        Raster source = uniformImage(width, height, 0x808080).getRaster();

        WritableRaster result = new DiffusionDither(icm).filter(source, null, icm);

        // The only error source is the random initial error injected into the first
        // row. As every 8 bit grey value has an exact palette match, almost no
        // error is diffused into the following rows, which must reproduce the
        // source grey level.
        for (int y = 1; y < height; y++) {
            for (int x = 0; x < width; x++) {
                assertEquals(0x80, (double) greyOf(icm, result.getSample(x, y, 0)), 3.0,
                        "Pixel (" + x + "," + y + ") should keep the source grey level");
            }
        }

        // The first row is offset by the random error, which is scaled to at most
        // +/-16 8 bit steps before clamping.
        for (int x = 0; x < width; x++) {
            int grey = greyOf(icm, result.getSample(x, 0, 0));
            assertTrue(grey >= 0x70 && grey <= 0x90,
                    "First row pixel " + x + " grey " + grey + " outside expected 112..144 range");
        }
    }

    // ------------------------------------------------------------------
    // Dithering behaviour
    // ------------------------------------------------------------------

    @Test
    @DisplayName("filter() must dither mid grey into both black and white pixels")
    void shouldDitherMidGreyIntoBothPaletteEntries() {
        IndexColorModel icm = BLACK_WHITE;
        Raster source = uniformImage(48, 24, 0x808080).getRaster();

        int[] samples = samples(new DiffusionDither(icm).filter(source, null, icm));

        int black = 0;
        int white = 0;
        for (int sample : samples) {
            if (sample == 0) {
                black++;
            }
            else if (sample == 1) {
                white++;
            }
            else {
                throw new AssertionError("Illegal palette index: " + sample);
            }
        }

        assertTrue(black > 0, "Dithering mid grey must produce black pixels");
        assertTrue(white > 0, "Dithering mid grey must produce white pixels");
    }

    @Test
    @DisplayName("filter() of mid grey must preserve the average luminance")
    void shouldPreserveAverageLuminanceOfMidGrey() {
        IndexColorModel icm = BLACK_WHITE;
        Raster source = uniformImage(64, 32, 0x808080).getRaster();

        int[] samples = samples(new DiffusionDither(icm).filter(source, null, icm));

        int white = 0;
        for (int sample : samples) {
            if (sample == 1) {
                white++;
            }
        }
        double whiteRatio = white / (double) samples.length;

        assertTrue(whiteRatio > 0.35 && whiteRatio < 0.65,
                "White pixel ratio " + whiteRatio + " should be close to 128/255 ~ 0.5");
    }

    @Test
    @DisplayName("filter() must preserve the average grey level of a coarse palette quantisation")
    void shouldPreserveAverageGreyWithCoarsePalette() {
        IndexColorModel icm = GREY_8;
        int size = 32;
        BufferedImage sourceImage = noiseImage(size, size, 1234567L);

        int[] sourcePixels = sourceImage.getRaster().getPixels(0, 0, size, size, (int[]) null);
        double expectedAverage = 0;
        for (int value : sourcePixels) {
            expectedAverage += value;
        }
        expectedAverage /= sourcePixels.length;

        int[] samples = samples(new DiffusionDither(icm).filter(sourceImage.getRaster(), null, icm));

        double actualAverage = 0;
        for (int sample : samples) {
            actualAverage += greyOf(icm, sample);
        }
        actualAverage /= samples.length;

        assertEquals(expectedAverage, actualAverage, 12.0,
                "Average luminance should be preserved by error diffusion");
    }

    @Test
    @DisplayName("filter() must dither a horizontal gradient progressively brighter")
    void shouldDitherGradientProgressively() {
        IndexColorModel icm = BLACK_WHITE;
        int width = 64;
        int height = 16;
        Raster source = horizontalGradient(width, height).getRaster();

        WritableRaster result = new DiffusionDither(icm).filter(source, null, icm);

        int leftWhites = 0;
        int rightWhites = 0;
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < 16; x++) {
                if (result.getSample(x, y, 0) == 1) {
                    leftWhites++;
                }
            }
            for (int x = width - 16; x < width; x++) {
                if (result.getSample(x, y, 0) == 1) {
                    rightWhites++;
                }
            }
        }

        int blockSize = 16 * height;
        double leftRatio = leftWhites / (double) blockSize;
        double rightRatio = rightWhites / (double) blockSize;

        assertTrue(leftRatio < 0.3, "Dark part of the gradient should be mostly black, was " + leftRatio);
        assertTrue(rightRatio > 0.7, "Bright part of the gradient should be mostly white, was " + rightRatio);
        assertEquals(255, greyOf(icm, 1), "Palette sanity check");
    }

    @Test
    @DisplayName("filter() must support non alternating (raster) scans")
    void shouldSupportNonAlternatingScans() {
        IndexColorModel icm = BLACK_WHITE;
        int width = 40;
        int height = 20;
        Raster source = uniformImage(width, height, 0x808080).getRaster();

        DiffusionDither dither = new DiffusionDither(icm);
        dither.setAlternateScans(false);

        WritableRaster result = dither.filter(source, null, icm);

        int[] samples = samples(result);
        assertEquals(width * height, samples.length);
        int black = 0;
        int white = 0;
        for (int sample : samples) {
            assertTrue(sample == 0 || sample == 1, "Illegal palette index: " + sample);
            if (sample == 0) {
                black++;
            }
            else {
                white++;
            }
        }
        assertTrue(black > 0 && white > 0, "Non alternating scans must still dither mid grey");
    }

    // ------------------------------------------------------------------
    // Side effects and boundary sizes
    // ------------------------------------------------------------------

    @Test
    @DisplayName("filter() must not modify the source raster")
    void shouldNotModifySourceRaster() {
        IndexColorModel icm = GREY_8;
        int width = 19;
        int height = 7;
        BufferedImage sourceImage = noiseImage(width, height, 98765L);
        Raster source = sourceImage.getRaster();
        int[] before = source.getPixels(0, 0, width, height, (int[]) null);

        new DiffusionDither(icm).filter(source, null, icm);

        int[] after = source.getPixels(0, 0, width, height, (int[]) null);
        assertArrayEquals(before, after, "Source raster must not be modified by the filter");
    }

    @ParameterizedTest(name = "{0}x{0}")
    @ValueSource(ints = {1, 2, 3})
    @DisplayName("filter() must handle very small images")
    void shouldHandleSmallImages(int pSize) {
        IndexColorModel icm = BLACK_WHITE;
        Raster source = uniformImage(pSize, pSize, 0x808080).getRaster();

        WritableRaster result = new DiffusionDither(icm).filter(source, null, icm);

        assertEquals(pSize, result.getWidth());
        assertEquals(pSize, result.getHeight());
        assertAllSamplesInRange(samples(result), 1);
    }

    @Test
    @DisplayName("filter() must handle a single row image")
    void shouldHandleSingleRowImage() {
        IndexColorModel icm = BLACK_WHITE;
        int width = 40;
        Raster source = uniformImage(width, 1, 0xA0A0A0).getRaster();

        WritableRaster result = new DiffusionDither(icm).filter(source, null, icm);

        int[] samples = samples(result);
        assertEquals(width, samples.length);
        assertAllSamplesInRange(samples, 1);
        int black = 0;
        for (int sample : samples) {
            if (sample == 0) {
                black++;
            }
        }
        assertTrue(black > 0 && black < width, "A single dithered row should mix both palette entries");
    }

    @Test
    @DisplayName("filter() must handle a single column image")
    void shouldHandleSingleColumnImage() {
        IndexColorModel icm = BLACK_WHITE;
        int height = 40;

        // Dark column: error diffusion can never push the value above the midpoint
        int[] dark = samples(new DiffusionDither(icm)
                .filter(uniformImage(1, height, 0x202020).getRaster(), null, icm));
        assertEquals(height, dark.length);
        assertAllSamplesInRange(dark, 1);
        for (int sample : dark) {
            assertEquals(0, sample, "A very dark single column must dither to black");
        }

        // Bright column: the opposite
        int[] bright = samples(new DiffusionDither(icm)
                .filter(uniformImage(1, height, 0xF0F0F0).getRaster(), null, icm));
        assertEquals(height, bright.length);
        for (int sample : bright) {
            assertEquals(1, sample, "A very bright single column must dither to white");
        }

        // Mid grey column: a mix of both palette entries
        int[] mid = samples(new DiffusionDither(icm)
                .filter(uniformImage(1, height, 0xA0A0A0).getRaster(), null, icm));
        assertEquals(height, mid.length);
        assertAllSamplesInRange(mid, 1);
        int black = 0;
        for (int sample : mid) {
            if (sample == 0) {
                black++;
            }
        }
        assertTrue(black > 0 && black < height, "A single dithered column should mix both palette entries");
    }

    @Test
    @DisplayName("filter() with a fixed colour model must not depend on the source image colours")
    void shouldReuseIndexColorModelAcrossFilterCalls() {
        IndexColorModel icm = SINGLE_COLOUR;
        DiffusionDither dither = new DiffusionDither(icm);
        Raster first = uniformImage(6, 6, 0xFF0000).getRaster();
        Raster second = uniformImage(6, 6, 0x00FF00).getRaster();

        WritableRaster firstResult = dither.filter(first, null, icm);
        WritableRaster secondResult = dither.filter(second, null, icm);

        assertNotSame(firstResult, secondResult);
        assertAllSamplesInRange(samples(firstResult), 0);
        assertAllSamplesInRange(samples(secondResult), 0);
        assertEquals(0xFF3366CC, icm.getRGB(samples(firstResult)[0]), "Palette sanity check");
    }
