    void parsePrefersFileLocationInfoOverRelativePath() throws IOException {
        File expected = tempDir.resolve("absolute-wins.txt").toFile();
        byte[] payload = concatenate(
                fileLocationInfo(expected.getAbsolutePath()),
                relativePath("relative-should-not-win.txt")
        );
        File link = writeFile("both-paths.lnk", lnk(FLAG_FILE_LOC_INFO | FLAG_REL_PATH_STRING, payload));

        assertEquals(expected, Win32Lnk.parse(link));
    }

