package com.twelvemonkeys.lang;

import org.junit.jupiter.api.Test;

import java.awt.Color;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Tests for {@link StringUtil#toColor(String)}.
 */
class StringUtilToColorTests {

    @Test
    void nullStringReturnsNull() {
        assertNull(StringUtil.toColor(null));
    }

    @Test
    void emptyStringIsRejected() {
        // charAt(0) on an empty string throws before any parsing is attempted
        assertThrows(StringIndexOutOfBoundsException.class, () -> StringUtil.toColor(""));
    }

    // --- Named colors -------------------------------------------------------

    @Test
    void resolvesLowercaseNamedColors() {
        assertEquals(Color.black, StringUtil.toColor("black"));
        assertEquals(Color.red, StringUtil.toColor("red"));
        assertEquals(Color.green, StringUtil.toColor("green"));
        assertEquals(Color.blue, StringUtil.toColor("blue"));
        assertEquals(Color.white, StringUtil.toColor("white"));
        assertEquals(Color.orange, StringUtil.toColor("orange"));
        assertEquals(Color.cyan, StringUtil.toColor("cyan"));
        assertEquals(Color.magenta, StringUtil.toColor("magenta"));
    }

    @Test
    void namedColorsAreCaseInsensitiveWhenLowercaseFormExists() {
        assertEquals(Color.red, StringUtil.toColor("RED"));
        assertEquals(Color.blue, StringUtil.toColor("Blue"));
        assertEquals(Color.black, StringUtil.toColor("BLACK"));
        assertEquals(Color.white, StringUtil.toColor("White"));
    }

    @Test
    void camelCaseColorNamesMatchExactly() {
        assertEquals(Color.darkGray, StringUtil.toColor("darkGray"));
        assertEquals(Color.lightGray, StringUtil.toColor("lightGray"));
    }

    @Test
    void camelCaseColorNamesAreNotCaseInsensitive() {
        // Lower-casing "DarkGray" yields "darkgray", which is not a Color field
        assertThrows(IllegalArgumentException.class, () -> StringUtil.toColor("DarkGray"));
        assertThrows(IllegalArgumentException.class, () -> StringUtil.toColor("LIGHTGRAY"));
    }

    @Test
    void unknownColorNameThrowsIllegalArgumentException() {
        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class, () -> StringUtil.toColor("notAColor"));
        assertEquals("No such color: notAColor", exception.getMessage());
    }

    @Test
    void colorNamesAreNotTrimmed() {
        assertThrows(IllegalArgumentException.class, () -> StringUtil.toColor(" red"));
        assertThrows(IllegalArgumentException.class, () -> StringUtil.toColor("red "));
    }

    // --- #RRGGBB ------------------------------------------------------------

    @Test
    void parsesSixDigitHex() {
        Color color = StringUtil.toColor("#ABCDEF");
        assertNotNull(color);
        assertEquals(0xAB, color.getRed());
        assertEquals(0xCD, color.getGreen());
        assertEquals(0xEF, color.getBlue());
        assertEquals(255, color.getAlpha());
    }

    @Test
    void sixDigitHexMatchesEquivalentNamedColors() {
        assertEquals(Color.red, StringUtil.toColor("#FF0000"));
        assertEquals(Color.green, StringUtil.toColor("#00FF00"));
        assertEquals(Color.blue, StringUtil.toColor("#0000FF"));
        assertEquals(Color.white, StringUtil.toColor("#FFFFFF"));
        assertEquals(Color.black, StringUtil.toColor("#000000"));
    }

    @Test
    void hexDigitsAreCaseInsensitive() {
        assertEquals(StringUtil.toColor("#ABCDEF"), StringUtil.toColor("#abcdef"));
        assertEquals(Color.red, StringUtil.toColor("#ff0000"));
    }

    // --- #RRGGBB with trailing extra character -----------------------------

    @Test
    void eightCharacterHexIgnoresTrailingCharacterAndIsOpaque() {
        // Exactly 8 characters: too short for AA, so the 8th character is ignored
        assertEquals(Color.red, StringUtil.toColor("#FF00001"));
    }

    // --- #AARRGGBB ----------------------------------------------------------

    @Test
    void parsesEightDigitArgb() {
        Color color = StringUtil.toColor("#80FF0000");
        assertNotNull(color);
        assertEquals(255, color.getRed());
        assertEquals(0, color.getGreen());
        assertEquals(0, color.getBlue());
        assertEquals(0x80, color.getAlpha());
    }

    @Test
    void parsesEightDigitArgbWithNonOpaqueAlpha() {
        Color color = StringUtil.toColor("#7F00FF00");
        assertNotNull(color);
        assertEquals(0, color.getRed());
        assertEquals(255, color.getGreen());
        assertEquals(0, color.getBlue());
        assertEquals(0x7F, color.getAlpha());
    }

    @Test
    void fullyOpaqueEightDigitArgbEqualsOpaqueNamedColor() {
        assertEquals(Color.red, StringUtil.toColor("#FFFF0000"));
    }

    // --- #RGB ---------------------------------------------------------------

    @Test
    void parsesThreeDigitHex() {
        Color color = StringUtil.toColor("#F80");
        assertNotNull(color);
        assertEquals(0xF0, color.getRed());
        assertEquals(0x80, color.getGreen());
        assertEquals(0x00, color.getBlue());
        assertEquals(255, color.getAlpha());
    }

    @Test
    void threeDigitHexExpandsEachNibble() {
        assertEquals(new Color(0x11, 0x22, 0x33), StringUtil.toColor("#123"));
    }

    // --- #ARGB --------------------------------------------------------------

    @Test
    void parsesFourDigitArgb() {
        Color color = StringUtil.toColor("#8F00");
        assertNotNull(color);
        assertEquals(0xF0, color.getRed());
        assertEquals(0x00, color.getGreen());
        assertEquals(0x00, color.getBlue());
        assertEquals(0x80, color.getAlpha());
    }

    @Test
    void fourDigitArgbExpandsEachNibble() {
        Color color = StringUtil.toColor("#A123");
        assertNotNull(color);
        assertEquals(0xA0, color.getAlpha());
        assertEquals(0x10, color.getRed());
        assertEquals(0x20, color.getGreen());
        assertEquals(0x30, color.getBlue());
    }

    // --- Too short / malformed ---------------------------------------------

    @Test
    void tooShortHexStringsFallBackToBlack() {
        assertEquals(Color.black, StringUtil.toColor("#"));
        assertEquals(Color.black, StringUtil.toColor("#F"));
        assertEquals(Color.black, StringUtil.toColor("#FF"));
    }

    @Test
    void malformedHexThrowsNumberFormatException() {
        assertThrows(NumberFormatException.class, () -> StringUtil.toColor("#GGGGGG"));
        assertThrows(NumberFormatException.class, () -> StringUtil.toColor("#XYZ"));
        assertThrows(NumberFormatException.class, () -> StringUtil.toColor("#GGGGGGGG"));
    }
}
