    public static class ArrayHolder {
        private final int[] data;

        public ArrayHolder(int[] pData) {
            data = pData;
        }

        public int[] getData() {
            return data;
        }
    }

    private static String hex(int pValue) {
        return Integer.toHexString(pValue);
    }

    private static String deepLeaf(Leaf pLeaf) {
        return Leaf.class.getName() + " {hashCode=" + hex(pLeaf.hashCode()) + ", value=leaf}";
    }

    private static String deepNode(Node pNode, String pChildRepresentation) {
        return Node.class.getName() + " {hashCode=" + hex(pNode.hashCode()) + ", child=" + pChildRepresentation + "}";
    }

    // ------------------------------------------------------------------
    // null handling
    // ------------------------------------------------------------------

    @Test
    @DisplayName("null input returns null")
    void testNullReturnsNull() {
        assertNull(StringUtil.deepToString(null, false, 1));
        assertNull(StringUtil.deepToString(null, true, 1));
        assertNull(StringUtil.deepToString(null, false, 0));
        assertNull(StringUtil.deepToString(null, true, -1));
    }

    // ------------------------------------------------------------------
    // toString short-circuit (pForceDeep == false)
    // ------------------------------------------------------------------

    @Test
    @DisplayName("Object overriding toString is returned as-is when not forcing deep")
    void testToStringShortCircuit() {
        assertEquals("withToString", StringUtil.deepToString(new WithToString(), false, 1));
        assertEquals("custom!", StringUtil.deepToString(new ToStringOnly(), false, 1));
        assertEquals("42", StringUtil.deepToString(42, false, 1));
    }

    @Test
    @DisplayName("No class name or hash code leaks into the short circuit result")
    void testToStringShortCircuitHasNoReflectionInfo() {
        String result = StringUtil.deepToString(new WithToString(), false, 1);

        assertFalse(result.contains("hashCode"), "must not contain hashCode: " + result);
        assertFalse(result.contains("name="), "must not contain getters: " + result);
    }

    // ------------------------------------------------------------------
    // Objects using identity toString
    // ------------------------------------------------------------------

    @Test
    @DisplayName("java.lang.Object is rendered with class name, hash code and no getters")
    void testPlainObject() {
        Object value = new Object();

        assertEquals("java.lang.Object {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Object without getters is rendered with class name and hash code")
    void testIdentityToStringWithoutGetters() {
        Plain value = new Plain();

        assertEquals(Plain.class.getName() + " {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Getter value is appended as name=value")
    void testSingleGetter() {
        Bean value = new Bean();

        assertEquals(Bean.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", name=foo}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Primitive getter value is appended without decoration")
    void testPrimitiveGetter() {
        Primitives value = new Primitives();

        assertEquals(Primitives.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", count=42}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Null getter value is rendered as the string null")
    void testNullGetterValue() {
        NullReturning value = new NullReturning();

        assertEquals(NullReturning.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", value=null}",
                StringUtil.deepToString(value, false, 1));
    }

