package com.twelvemonkeys.lang;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@code StringUtil.deepToString(Object, boolean, int)}.
 */
@DisplayName("StringUtil.deepToString(Object, boolean, int)")
public class StringUtilDeepToStringTests {

    // ------------------------------------------------------------------
    // Helper / fixture types
    // ------------------------------------------------------------------

    /** Uses Object's identity {@code toString}. Has no getters. */
    public static class Plain {
    }

    /** Uses Object's identity {@code toString}. Has a single getter. */
    public static class Bean {
        public String getName() {
            return "foo";
        }
    }

    /** Overrides {@code toString} and has a single getter. */
    public static class WithToString {
        @Override
        public String toString() {
            return "withToString";
        }

        public String getName() {
            return "bar";
        }
    }

    /** Overrides {@code toString} only (no getters at all). */
    public static class ToStringOnly {
        @Override
        public String toString() {
            return "custom!";
        }
    }

    /** Getter with an acronym name, the case must be preserved. */
    public static class Naming {
        public String getURL() {
            return "url";
        }
    }

    /** Getter with a single character property name. */
    public static class ShortName {
        public String getX() {
            return "x";
        }
    }

    /** Single character property name from an "is" getter. */
    public static class ShortIsName {
        public boolean isX() {
            return true;
        }
    }

    /** Acronym style "is" getter, the case must be preserved. */
    public static class IsAcronym {
        public boolean isOK() {
            return true;
        }
    }

    /** Primitive returning getters. */
    public static class Primitives {
        public int getCount() {
            return 42;
        }
    }

    /** Methods that must be filtered out, plus one valid getter. */
    public static class Filtered {
        public String getname() {
            return "lower";
        }

        public void getNothing() {
        }

        public String getWithParams(String pValue) {
            return pValue;
        }

        public String getGood() {
            return "good";
        }
    }

    /** Getter that throws; the exception must be swallowed. */
    public static class Failing {
        public String getBroken() {
            throw new IllegalStateException("boom");
        }

        public String getFine() {
            return "ok";
        }
    }

    /** Getter returning null. */
    public static class NullReturning {
        public String getValue() {
            return null;
        }
    }

    /** Identity {@code toString} value used for recursion tests. */
    public static class Leaf {
        public String getValue() {
            return "leaf";
        }
    }

    /** Value that overrides {@code toString}. */
    public static class CustomValue {
        @Override
        public String toString() {
            return "customValue";
        }
    }

    /** Node with a child, used to exercise the depth parameter. */
    public static class Node {
        private final Object child;

        public Node(Object pChild) {
            child = pChild;
        }

        public Object getChild() {
            return child;
        }
    }

    /** Bean exposing an array property. */
    public static class ArrayHolder {
        private final int[] data;

        public ArrayHolder(int[] pData) {
            data = pData;
        }

        public int[] getData() {
            return data;
        }
    }

    private static String hex(int pValue) {
        return Integer.toHexString(pValue);
    }

    private static String deepLeaf(Leaf pLeaf) {
        return Leaf.class.getName() + " {hashCode=" + hex(pLeaf.hashCode()) + ", value=leaf}";
    }

    private static String deepNode(Node pNode, String pChildRepresentation) {
        return Node.class.getName() + " {hashCode=" + hex(pNode.hashCode()) + ", child=" + pChildRepresentation + "}";
    }

    // ------------------------------------------------------------------
    // null handling
    // ------------------------------------------------------------------

    @Test
    @DisplayName("null input returns null")
    void testNullReturnsNull() {
        assertNull(StringUtil.deepToString(null, false, 1));
        assertNull(StringUtil.deepToString(null, true, 1));
        assertNull(StringUtil.deepToString(null, false, 0));
        assertNull(StringUtil.deepToString(null, true, -1));
    }

    // ------------------------------------------------------------------
    // toString short-circuit (pForceDeep == false)
    // ------------------------------------------------------------------

    @Test
    @DisplayName("Object overriding toString is returned as-is when not forcing deep")
    void testToStringShortCircuit() {
        assertEquals("withToString", StringUtil.deepToString(new WithToString(), false, 1));
        assertEquals("custom!", StringUtil.deepToString(new ToStringOnly(), false, 1));
        assertEquals("42", StringUtil.deepToString(42, false, 1));
    }

    @Test
    @DisplayName("No class name or hash code leaks into the short circuit result")
    void testToStringShortCircuitHasNoReflectionInfo() {
        String result = StringUtil.deepToString(new WithToString(), false, 1);

        assertFalse(result.contains("hashCode"), "must not contain hashCode: " + result);
        assertFalse(result.contains("name="), "must not contain getters: " + result);
    }

    // ------------------------------------------------------------------
    // Objects using identity toString
    // ------------------------------------------------------------------

    @Test
    @DisplayName("java.lang.Object is rendered with class name, hash code and no getters")
    void testPlainObject() {
        Object value = new Object();

        assertEquals("java.lang.Object {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Object without getters is rendered with class name and hash code")
    void testIdentityToStringWithoutGetters() {
        Plain value = new Plain();

        assertEquals(Plain.class.getName() + " {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Getter value is appended as name=value")
    void testSingleGetter() {
        Bean value = new Bean();

        assertEquals(Bean.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", name=foo}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Primitive getter value is appended without decoration")
    void testPrimitiveGetter() {
        Primitives value = new Primitives();

        assertEquals(Primitives.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", count=42}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Null getter value is rendered as the string null")
    void testNullGetterValue() {
        NullReturning value = new NullReturning();

        assertEquals(NullReturning.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", value=null}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Identity toString object is expanded even when not forcing deep")
    void testIdentityObjectIsAlwaysExpanded() {
        Bean value = new Bean();

        String result = StringUtil.deepToString(value, false, 1);

        assertTrue(result.startsWith(Bean.class.getName() + " {"), "unexpected prefix: " + result);
        assertTrue(result.endsWith("}"), "unexpected suffix: " + result);
        assertTrue(result.contains("hashCode="), "missing hash code: " + result);
    }

    // ------------------------------------------------------------------
    // toString overridden + pForceDeep == true
    // ------------------------------------------------------------------

    @Test
    @DisplayName("toString is included when forcing deep")
    void testForceDeepIncludesToString() {
        WithToString value = new WithToString();

        assertEquals(WithToString.class.getName() + " {toString=withToString, hashCode="
                        + hex(value.hashCode()) + ", name=bar}",
                StringUtil.deepToString(value, true, 1));
    }

    @Test
    @DisplayName("toString overridden object without getters is expanded when forcing deep")
    void testForceDeepWithoutGetters() {
        ToStringOnly value = new ToStringOnly();

        assertEquals(ToStringOnly.class.getName() + " {toString=custom!, hashCode="
                        + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, true, 1));
    }

    @Test
    @DisplayName("String is expanded when forcing deep")
    void testForceDeepString() {
        String value = "foo";

        String result = StringUtil.deepToString(value, true, 1);

        assertTrue(result.startsWith("java.lang.String {toString=foo, hashCode=" + Integer.toHexString(value.hashCode())),
                "unexpected prefix: " + result);
        assertTrue(result.contains(", empty=false"), "missing isEmpty getter: " + result);
        assertTrue(result.endsWith("}"), "unexpected suffix: " + result);
    }

    @Test
    @DisplayName("Force deep does not affect the fact that null returns null")
    void testForceDeepArrayNotNull() {
        assertNotNull(StringUtil.deepToString(new Bean(), true, 0));
    }

    // ------------------------------------------------------------------
    // Getter name derivation
    // ------------------------------------------------------------------

    @Test
    @DisplayName("Acronym getter name keeps upper case")
    void testGetUrlName() {
        Naming value = new Naming();

        assertEquals(Naming.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", URL=url}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Single character getter name is kept as-is")
    void testShortGetterName() {
        ShortName value = new ShortName();

        assertEquals(ShortName.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", X=x}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Single character is-getter name is kept as-is")
    void testShortIsGetterName() {
        ShortIsName value = new ShortIsName();

        assertEquals(ShortIsName.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", X=true}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Acronym is-getter name keeps upper case")
    void testIsAcronymName() {
        IsAcronym value = new IsAcronym();

        assertEquals(IsAcronym.class.getName() + " {hashCode=" + hex(value.hashCode()) + ", OK=true}",
                StringUtil.deepToString(value, false, 1));
    }

    // ------------------------------------------------------------------
    // Method filtering
    // ------------------------------------------------------------------

    @Test
    @DisplayName("Invalid getters are filtered out")
    void testFilteredMethods() {
        Filtered value = new Filtered();

        String result = StringUtil.deepToString(value, true, 1);

        assertTrue(result.contains(", good=good"), "valid getter missing: " + result);
        assertFalse(result.contains("lower"), "lower case getter name must be filtered: " + result);
        assertFalse(result.contains("Nothing"), "void getter must be filtered: " + result);
        assertFalse(result.contains("WithParams"), "getter with parameters must be filtered: " + result);
        assertFalse(result.contains("good=") && result.contains("good=good, good=good"),
                "getter must only be included once: " + result);
    }

    @Test
    @DisplayName("Exceptions thrown by getters are swallowed")
    void testFailingGetter() {
        Failing value = new Failing();

        String result = StringUtil.deepToString(value, false, 1);

        assertTrue(result.contains(", fine=ok"), "valid getter missing: " + result);
        assertFalse(result.contains("broken"), "failing getter must be omitted: " + result);
        assertFalse(result.contains("boom"), "exception message must not leak: " + result);
        assertTrue(result.endsWith("}"), "output must still be closed: " + result);
    }

    // ------------------------------------------------------------------
    // pDepth behaviour
    // ------------------------------------------------------------------

    @Test
    @DisplayName("Leaf object is fully expanded")
    void testLeafExpanded() {
        Leaf leaf = new Leaf();

        assertEquals(deepLeaf(leaf), StringUtil.deepToString(leaf, false, 1));
    }

    @Test
    @DisplayName("Depth 1 expands the object one level")
    void testDepthOne() {
        Leaf leaf = new Leaf();
        Node node = new Node(leaf);

        assertEquals(deepNode(node, deepLeaf(leaf)), StringUtil.deepToString(node, false, 1));
    }

    @Test
    @DisplayName("Depth 0 does not recurse into property values")
    void testDepthZeroDoesNotRecurse() {
        Leaf leaf = new Leaf();
        Node node = new Node(leaf);

        assertEquals(deepNode(node, leaf.toString()), StringUtil.deepToString(node, false, 0));
    }

    @Test
    @DisplayName("Negative depth recurses indefinitely")
    void testNegativeDepthRecursesIndefinitely() {
        Leaf leaf = new Leaf();
        Node inner = new Node(leaf);
        Node outer = new Node(inner);

        String expected = deepNode(outer, deepNode(inner, deepLeaf(leaf)));

        assertEquals(expected, StringUtil.deepToString(outer, false, -1));
    }

    @Test
    @DisplayName("Depth 1 on a two level graph stops after one recursion")
    void testDepthOneOnTwoLevelGraph() {
        Leaf leaf = new Leaf();
        Node inner = new Node(leaf);
        Node outer = new Node(inner);

        assertEquals(deepNode(outer, deepNode(inner, leaf.toString())),
                StringUtil.deepToString(outer, false, 1));
    }

    @Test
    @DisplayName("Property values overriding toString are not recursed")
    void testPropertyWithToStringNotRecursed() {
        CustomValue custom = new CustomValue();
        Node node = new Node(custom);

        assertEquals(deepNode(node, "customValue"), StringUtil.deepToString(node, false, -1));
    }

    @Test
    @DisplayName("Array property is expanded when depth allows recursion")
    void testArrayPropertyRecursed() {
        int[] data = new int[]{1, 2, 3};
        ArrayHolder holder = new ArrayHolder(data);

        String expected = ArrayHolder.class.getName() + " {hashCode=" + hex(holder.hashCode())
                + ", data=int[3] {hashCode=" + hex(data.hashCode()) + "}}";

        assertEquals(expected, StringUtil.deepToString(holder, false, 1));
    }

    // ------------------------------------------------------------------
    // Array handling
    // ------------------------------------------------------------------

    @Test
    @DisplayName("Primitive int array renders component type and length")
    void testIntArray() {
        int[] value = new int[]{1, 2, 3};

        assertEquals("int[3] {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Force deep does not change array rendering")
    void testIntArrayForceDeep() {
        int[] value = new int[]{1, 2, 3};

        assertEquals("int[3] {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, true, 1));
    }

    @Test
    @DisplayName("Object array renders the full component type name")
    void testStringArray() {
        String[] value = new String[]{"a", "b"};

        assertEquals("class java.lang.String[2] {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("CharArray renders char component type")
    void testCharArray() {
        char[] value = new char[]{'a', 'b'};

        assertEquals("char[2] {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Empty array renders a zero length")
    void testEmptyArray() {
        Object[] value = new Object[0];

        assertEquals("class java.lang.Object[0] {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Multi dimensional array repeats the outermost length for every dimension")
    void testMultiDimensionalArray() {
        int[][] value = new int[][]{{1, 2, 3}, {4, 5, 6}};

        assertEquals("int[2][2] {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Array of custom objects renders the custom component type")
    void testCustomObjectArray() {
        Bean[] value = new Bean[]{new Bean(), new Bean()};

        assertEquals("class " + Bean.class.getName() + "[2] {hashCode=" + hex(value.hashCode()) + "}",
                StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Array elements are not rendered")
    void testArrayElementsAreNotRendered() {
        Bean bean = new Bean();
        Bean[] value = new Bean[]{bean};

        String result = StringUtil.deepToString(value, false, 1);

        assertFalse(result.contains("name=foo"), "elements must not be rendered: " + result);
        assertTrue(result.startsWith("class " + Bean.class.getName() + "[1] {hashCode="), "unexpected: " + result);
    }

    @Test
    @DisplayName("Array rendering is independent of the depth parameter")
    void testArrayDepthIndependent() {
        int[] value = new int[]{7};

        String expected = "int[1] {hashCode=" + hex(value.hashCode()) + "}";

        assertEquals(expected, StringUtil.deepToString(value, false, 0));
        assertEquals(expected, StringUtil.deepToString(value, false, -1));
    }

    @Test
    @DisplayName("Result is not null for arrays")
    void testArrayResultNotNull() {
        Object[] value = new Object[]{null};

        assertNotNull(StringUtil.deepToString(value, false, 1));
    }

    // ------------------------------------------------------------------
    // Misc observable behaviour
    // ------------------------------------------------------------------

    @Test
    @DisplayName("Hash code is rendered in lower case hexadecimal without padding")
    void testHashCodeFormat() {
        Object value = new Object();
        String expectedHash = Integer.toHexString(value.hashCode());

        String result = StringUtil.deepToString(value, false, 1);

        assertTrue(result.contains("hashCode=" + expectedHash), "unexpected hash: " + result);
        assertEquals(expectedHash.toLowerCase(), expectedHash);
    }

    @Test
    @DisplayName("Repeated invocations produce equal results")
    void testDeterministicForSameInstance() {
        Bean value = new Bean();

        assertEquals(StringUtil.deepToString(value, false, 1), StringUtil.deepToString(value, false, 1));
    }

    @Test
    @DisplayName("Deep output of an identity object starts with the runtime class name")
    void testStartsWithRuntimeClassName() {
        Leaf leaf = new Leaf();

        String result = StringUtil.deepToString(leaf, false, 1);

        assertTrue(result.startsWith(Leaf.class.getName()), "unexpected: " + result);
    }

    @Test
    @DisplayName("deepToString(Object) convenience overload keeps toString for overriding objects")
    void testConvenienceOverload() {
        WithToString value = new WithToString();

        assertSame(value.toString(), StringUtil.deepToString(value));
        assertEquals("withToString", StringUtil.deepToString(value));
    }
}
