package com.twelvemonkeys.lang;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.lang.reflect.Array;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests the {@link SystemUtil#clone(Cloneable)} method.
 */
class SystemUtilCloneTests {

    // --- null -----------------------------------------------------------------

    @Test
    void cloneNullReturnsNull() throws CloneNotSupportedException {
        assertNull(SystemUtil.clone((Cloneable) null));
    }

    // --- Reference (Object[]) arrays -----------------------------------------

    @Test
    void cloneStringArrayReturnsShallowCopyOfSameType() throws CloneNotSupportedException {
        String[] original = {"one", "two", "three"};

        Object result = SystemUtil.clone(original);

        assertNotSame(original, result);
        assertEquals(String[].class, result.getClass());
        assertArrayEquals(original, (String[]) result);
    }

    @Test
    void cloneObjectArrayIsShallowAndIndependentAtTopLevel() throws CloneNotSupportedException {
        Object shared = new Object();
        Object[] original = {shared, "text", 42};

        Object[] copy = (Object[]) SystemUtil.clone(original);

        assertNotSame(original, copy);
        assertEquals(original.length, copy.length);
        // Shallow copy: elements are the exact same references.
        assertSame(original[0], copy[0]);
        assertSame(original[1], copy[1]);
        assertSame(original[2], copy[2]);

        // Mutating the copy does not affect the original array slot.
        copy[0] = "replaced";
        assertSame(shared, original[0]);
    }

    @Test
    void cloneEmptyObjectArray() throws CloneNotSupportedException {
        String[] original = new String[0];

        Object result = SystemUtil.clone(original);

        assertNotSame(original, result);
        assertEquals(String[].class, result.getClass());
        assertEquals(0, ((String[]) result).length);
    }

    @Test
    void cloneMultiDimensionalObjectArrayOnlyClonesOutermostArray() throws CloneNotSupportedException {
        String[] inner = {"a", "b"};
        String[][] original = {inner, {"c"}};

        String[][] copy = (String[][]) SystemUtil.clone(original);

        assertNotSame(original, copy);
        assertEquals(original.length, copy.length);
        // The inner arrays are not deep-cloned.
        assertSame(original[0], copy[0]);
        assertSame(original[1], copy[1]);
    }

    // --- Primitive arrays ----------------------------------------------------

    @Test
    void cloneOneDimensionalPrimitiveArraysCopiesTypeLengthAndContent() throws CloneNotSupportedException {
        Object[] originals = {
                new byte[]{1, 2, 3},
                new short[]{4, 5, 6},
                new int[]{7, 8, 9},
                new long[]{10L, 11L, 12L},
                new float[]{1.5f, 2.5f},
                new double[]{3.5d, 4.5d},
                new char[]{'x', 'y', 'z'},
                new boolean[]{true, false, true}
        };

        for (Object original : originals) {
            Object copy = SystemUtil.clone((Cloneable) original);

            assertNotSame(original, copy, "A primitive array must be copied");
            assertEquals(original.getClass(), copy.getClass(), "Component type must be preserved");
            assertEquals(Array.getLength(original), Array.getLength(copy), "Length must be preserved");

            int length = Array.getLength(original);
            for (int i = 0; i < length; i++) {
                assertEquals(Array.get(original, i), Array.get(copy, i),
                        "Element " + i + " of " + original.getClass().getComponentType());
            }
        }
    }

    @Test
    void clonePrimitiveArrayIsIndependent() throws CloneNotSupportedException {
        int[] original = {1, 2, 3};

        int[] copy = (int[]) SystemUtil.clone(original);
        copy[0] = 99;

        assertArrayEquals(new int[]{1, 2, 3}, original);
        assertArrayEquals(new int[]{99, 2, 3}, copy);
    }

    @Test
    void cloneEmptyPrimitiveArray() throws CloneNotSupportedException {
        int[] original = new int[0];

        Object result = SystemUtil.clone(original);

        assertNotSame(original, result);
        assertEquals(int[].class, result.getClass());
        assertEquals(0, ((int[]) result).length);
    }

    @Test
    void cloneSingleElementPrimitiveArray() throws CloneNotSupportedException {
        char[] original = {'q'};

        char[] copy = (char[]) SystemUtil.clone(original);
        copy[0] = 'z';

        assertArrayEquals(new char[]{'q'}, original);
        assertArrayEquals(new char[]{'z'}, copy);
    }

    @Test
    void cloneMultiDimensionalPrimitiveArrayOnlyClonesOutermostArray() throws CloneNotSupportedException {
        int[][] original = {{1, 2}, {3, 4, 5}};

