    private static class ProtectedCloneable implements Cloneable {
        int value;
        int cloneCount;

        @Override
        protected Object clone() throws CloneNotSupportedException {
            ProtectedCloneable copy = (ProtectedCloneable) super.clone();
            copy.cloneCount = cloneCount + 1;
            return copy;
        }
    }

