        @Override
        public Object clone() throws CloneNotSupportedException {
            throw new CloneNotSupportedException("target-clone-not-supported");
        }
    }

    private static class ThrowingRuntimeException implements Cloneable {
        @Override
        public Object clone() {
            throw new IllegalStateException("target-runtime-failure");
        }
    }

    private static class ThrowingError implements Cloneable {
        @Override
        public Object clone() {
            throw new AssertionError("target-error");
        }
    }

    /**
     * Cloneable whose clone() "sneakily" throws a checked exception that is not
     * {@link CloneNotSupportedException}.
     */
    private static class SneakyCheckedThrowingCloneable implements Cloneable {
        @Override
        public Object clone() throws CloneNotSupportedException {
            SneakyCheckedThrowingCloneable.<RuntimeException>sneakyThrow(new IOException("sneaky-checked"));
            return null; // Unreachable
        }

        @SuppressWarnings("unchecked")
        private static <T extends Throwable> void sneakyThrow(Throwable throwable) throws T {
            throw (T) throwable;
        }
    }
