import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Tests the observable contract of
 * {@link TIFFUtilities#applyOrientation(BufferedImage, int)}.
 * <p>
 * Every TIFF orientation value is verified by its pixel level effect: which source
 * coordinate ends up at which destination coordinate, and whether the width and the
 * height of the image are swapped.
 */
class TIFFUtilitiesApplyOrientationTests {

    /** Interesting image shapes: square, landscape, portrait, odd, even and degenerate sizes. */
    private static final int[][] SIZES = {
            {4, 3}, {3, 4}, {5, 5}, {7, 5}, {13, 9}, {1, 1}, {1, 4}, {4, 1}
    };

    private static final int[] ALL_ORIENTATIONS = {1, 2, 3, 4, 5, 6, 7, 8};

    // === Helper methods ==============================================================================================

    /**
     * Creates an image where every pixel carries a unique, non opaque colour, so that
     * the pixel at (x, y) can be identified unambiguously in a transformed image.
     */
    private static BufferedImage createTestImage(int width, int height) {
        return createTestImage(width, height, BufferedImage.TYPE_INT_ARGB);
    }

    private static BufferedImage createTestImage(int width, int height, int type) {
        BufferedImage image = new BufferedImage(width, height, type);
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                image.setRGB(x, y, createTestPixel(x, y));
            }
        }
        return image;
    }

    /** Unique ARGB value for a coordinate; alpha is deliberately fully opaque. */
    private static int createTestPixel(int x, int y) {
        return 0xFF000000 | ((x + 1) << 16) | ((y + 1) << 8) | (x + y + 1);
    }

    /** Maps a destination coordinate back to the source coordinate it must originate from. */
    @FunctionalInterface
    private interface CoordinateMapper {
        int[] map(int x, int y, int sourceWidth, int sourceHeight);
    }

    private static int[] xy(int x, int y) {
        return new int[]{x, y};
    }

    /**
     * Asserts that {@code result} has the expected dimensions and that every destination pixel
     * holds the pixel of the source coordinate returned by the given mapper.
     */
    private static void assertMappedPixels(BufferedImage source, BufferedImage result,
                                           int expectedWidth, int expectedHeight,
                                           CoordinateMapper mapper, String description) {
        assertEquals(expectedWidth, result.getWidth(), description + ": unexpected width");
        assertEquals(expectedHeight, result.getHeight(), description + ": unexpected height");

        int w = source.getWidth();
        int h = source.getHeight();

        for (int y = 0; y < result.getHeight(); y++) {
            for (int x = 0; x < result.getWidth(); x++) {
                int[] sourceCoordinate = mapper.map(x, y, w, h);
                int expected = source.getRGB(sourceCoordinate[0], sourceCoordinate[1]);
                assertEquals(expected, result.getRGB(x, y),
                        String.format("%s: wrong pixel at (%d,%d), expected source pixel (%d,%d)",
                                description, x, y, sourceCoordinate[0], sourceCoordinate[1]));
            }
        }
    }

    private static void assertOrientationApplied(int orientation, boolean swapDimensions,
                                                 CoordinateMapper mapper, String description) {
        for (int[] size : SIZES) {
            BufferedImage source = createTestImage(size[0], size[1]);
            BufferedImage result = TIFFUtilities.applyOrientation(source, orientation);

            assertNotNull(result, description + ": result must not be null");
            assertNotSame(source, result, description + ": a transformed copy is expected");

            int expectedWidth = swapDimensions ? size[1] : size[0];
            int expectedHeight = swapDimensions ? size[0] : size[1];

            assertMappedPixels(source, result, expectedWidth, expectedHeight, mapper,
                    description + " (source " + size[0] + "x" + size[1] + ")");
        }
    }

