                (x, y, w, h) -> xy(w - 1 - y, x), "LEFTBOT (8)");
    }

    // === Colour model handling =======================================================================================

    @Test
    void orientationPreservesRgbImageType() {
        for (int orientation : ALL_ORIENTATIONS) {
            BufferedImage source = createTestImage(4, 3, BufferedImage.TYPE_INT_RGB);
            BufferedImage result = TIFFUtilities.applyOrientation(source, orientation);

            assertEquals(BufferedImage.TYPE_INT_RGB, result.getType(),
                    "Orientation " + orientation + " must preserve the image type");
        }
    }

    @Test
