            .parse(new org.xml.sax.InputSource(new StringReader("<svg xmlns='http://www.w3.org/2000/svg' width='10' height='20'/>")));
        Object r3 = newRasterizer();
        ((Transcoder) r3).addTranscodingHint(SVGAbstractTranscoder.KEY_DOM_IMPLEMENTATION, SVGDOMImplementation.getDOMImplementation());
        try {
            invoke(r3, jdk, null);
            System.out.println("clone with hint: defaultSize=" + field(r3, "defaultSize") + " storedDocClass=" + field(r3, "document").getClass() + " same=" + (field(r3, "document") == jdk));
        } catch (Throwable t) { System.out.println("clone with hint FAILED: " + t + " / cause " + t.getCause()); }

        // clone without hint
        Object r4 = newRasterizer();
        try {
            invoke(r4, jdk, null);
            System.out.println("clone no hint: defaultSize=" + field(r4, "defaultSize"));
        } catch (Throwable t) { System.out.println("clone no hint FAILED: " + t + " / cause " + t.getCause()); }

        // dynamic
        Object r5 = newRasterizer();
        Document dyn = parse("<svg xmlns='http://www.w3.org/2000/svg' width='10' height='20'><script>var x = 1;</script></svg>");
        ((Transcoder) r5).addTranscodingHint(SVGAbstractTranscoder.KEY_EXECUTE_ONLOAD, Boolean.TRUE);
        try {
            invoke(r5, dyn, null);
            Object ctx = field(r5, "context");
            System.out.println("dynamic: defaultSize=" + field(r5, "defaultSize") + " isDynamic=" + ctx.getClass().getMethod("isDynamic").invoke(ctx) + " ex=" + field(r5, "exception"));
        } catch (Throwable t) { System.out.println("dynamic FAILED: " + t + " / cause " + t.getCause()); }

        // non-dynamic (no hint) with script
        Object r6 = newRasterizer();
        invoke(r6, parse("<svg xmlns='http://www.w3.org/2000/svg' width='10' height='20'><script>var x = 1;</script></svg>"), null);
        Object ctx6 = field(r6, "context");
        System.out.println("static: isDynamic=" + ctx6.getClass().getMethod("isDynamic").invoke(ctx6));

        // execute onload false
        Object r7 = newRasterizer();
        ((Transcoder) r7).addTranscodingHint(SVGAbstractTranscoder.KEY_EXECUTE_ONLOAD, Boolean.FALSE);
        invoke(r7, dyn, null);
        System.out.println("onload=false: isDynamic=" + field(r7, "context").getClass().getMethod("isDynamic").invoke(field(r7, "context")));

        // two transcodes on same rasterizer: viewBox retained?
        Object r8 = newRasterizer();
        invoke(r8, parse("<svg xmlns='http://www.w3.org/2000/svg' width='10' height='20'/>"), null);
        invoke(r8, parse("<svg xmlns='http://www.w3.org/2000/svg' width='30' height='40'/>"), null);
        System.out.println("twice: defaultSize=" + field(r8, "defaultSize") + " viewBox=" + field(r8, "viewBox"));
    }

    static String desc(Map m) {
        StringBuilder sb = new StringBuilder();
        for (Object o : m.entrySet()) { Map.Entry e = (Map.Entry) o; sb.append(e.getKey()).append('=').append(e.getValue()).append(", "); }
