    }

    static void TranscodingHintSetter(Object r) {}

    static Object urlObject(Document d) throws Exception {
        return d.getClass().getMethod("getURLObject").invoke(d);
    }

    static Object newRasterizer() throws Exception {
        Object spi = spiClass.getConstructor().newInstance();
        ImageReader reader = (ImageReader) readerClass.getConstructor(javax.imageio.spi.ImageReaderSpi.class).newInstance(spi);
        return ctor.newInstance(reader);
    }

    static Object field(Object o, String name) throws Exception {
        Field f = findField(name);
        f.setAccessible(true);
        return f.get(o);
    }

    static Field findField(String name) throws Exception {
        Class<?> c = rasterizerClass;
        while (c != null) {
            try { return c.getDeclaredField(name); } catch (NoSuchFieldException e) { c = c.getSuperclass(); }
        }
        throw new NoSuchFieldException(name);
    }

    static Object transcode(Document doc, String uri, Object r) throws Exception {
        return null;
    }

    static void invoke(Object r, Document doc, String uri) throws Exception {
        try {
            transcode.invoke(r, doc, uri, null);
        } catch (InvocationTargetException e) {
            throw new RuntimeException(e.getCause());
        }
    }

    static void report(Object unused, CharSequence unused2) {}

    static Document parse(String svg) throws Exception {
