/**
 * Tests the (re)implementation of {@code SVGAbstractTranscoder.transcode} found in
 * {@code SVGImageReader.Rasterizer}, which is responsible for determining the
 * default (rendered) size of an SVG document, and for building its GVT tree.
 * <p>
 * The {@code Rasterizer} class is a private inner class, so the method under test
 * is invoked reflectively, and its state is inspected through reflection as well.
 * </p>
 */
class SVGImageReaderTranscodeTests {

    private static final String SVG_NAMESPACE = "http://www.w3.org/2000/svg";

    private static final Constructor<?> RASTERIZER_CONSTRUCTOR;
    private static final Method TRANSCODE;

    private static final Field DEFAULT_SIZE;
    private static final Field VIEW_BOX;
    private static final Field DOCUMENT;
    private static final Field URI;
    private static final Field EXCEPTION;
    private static final Field BRIDGE_CONTEXT;
    private static final Field GVT_ROOT;
    private static final Field TRANSCODER_CTX;

    static {
        try {
            Class<?> rasterizerClass = Class.forName(SVGImageReader.class.getName() + "$Rasterizer");

            RASTERIZER_CONSTRUCTOR = rasterizerClass.getDeclaredConstructor(SVGImageReader.class);
            RASTERIZER_CONSTRUCTOR.setAccessible(true);

            TRANSCODE = rasterizerClass.getDeclaredMethod("transcode", Document.class, String.class, TranscoderOutput.class);
            TRANSCODE.setAccessible(true);

            DEFAULT_SIZE = declaredField(rasterizerClass, "defaultSize");
            VIEW_BOX = declaredField(rasterizerClass, "viewBox");
            DOCUMENT = declaredField(rasterizerClass, "document");
            URI = declaredField(rasterizerClass, "uri");
            EXCEPTION = declaredField(rasterizerClass, "exception");
            BRIDGE_CONTEXT = declaredField(rasterizerClass, "context");
            GVT_ROOT = declaredField(rasterizerClass, "gvtRoot");
            // The (temporary) ctx field is inherited from SVGAbstractTranscoder
            TRANSCODER_CTX = inheritedField(rasterizerClass, "ctx");
        }
        catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to access SVGImageReader$Rasterizer internals", e);
        }
    }

    private SVGImageReader reader;
    private Object rasterizer;

    @BeforeEach
    void setUp() throws Exception {
        reader = new SVGImageReader(new SVGImageReaderSpi());
        rasterizer = RASTERIZER_CONSTRUCTOR.newInstance(reader);
    }

    // --- Normal cases: size derived from width/height and/or viewBox ---

    @Test
    void noSizeInformationFallsBackToBatikDefaultSize() throws Exception {
        Document document = createSvgDocument(null, null, null);

        transcode(document, null);

        assertEquals(new Dimension(400, 400), defaultSize(), "Default size");
        assertRectangle(0, 0, 400, 400, viewBox(), "View box");
        assertNotNull(gvtRoot(), "GVT tree should have been built");
        assertNull(exception(), "No exception expected");
        assertEquals(400, reader.getWidth(0), "Width reported by the reader");
        assertEquals(400, reader.getHeight(0), "Height reported by the reader");
    }

    @Test
    void widthAndHeightAttributesDefineDefaultSizeAndViewBox() throws Exception {
        Document document = createSvgDocument("50", "20", null);

        transcode(document, null);

        assertEquals(new Dimension(50, 20), defaultSize(), "Default size");
        assertRectangle(0, 0, 50, 20, viewBox(), "View box should match the default size");
        assertNotNull(gvtRoot(), "GVT tree should have been built");
    }

    @Test
    void viewBoxOnlyDefinesDefaultSize() throws Exception {
        Document document = createSvgDocument(null, null, "0 0 100 200");

        transcode(document, null);

        assertEquals(new Dimension(100, 200), defaultSize(), "Default size should equal the view box size");
        assertRectangle(0, 0, 100, 200, viewBox(), "View box should be preserved");
    }

    @Test
    void viewBoxWithOffsetIsPreservedVerbatim() throws Exception {
        Document document = createSvgDocument("100", null, "10 20 50 100");

        transcode(document, null);

        // Height is derived from the width and the view box aspect ratio (100 * 100 / 50)
        assertEquals(new Dimension(100, 200), defaultSize(), "Default size");
        assertRectangle(10, 20, 50, 100, viewBox(), "View box should keep its offset and size");
    }

    @Test
    void widthOnlyWithoutViewBoxAssumesSquareDocument() throws Exception {
        Document document = createSvgDocument("50", null, null);

        transcode(document, null);

        assertEquals(new Dimension(50, 50), defaultSize(), "Default size");
        assertRectangle(0, 0, 50, 50, viewBox(), "View box should be set to the default size");
    }

    @Test
    void heightOnlyWithoutViewBoxAssumesSquareDocument() throws Exception {
        Document document = createSvgDocument(null, "40", null);

        transcode(document, null);

        assertEquals(new Dimension(40, 40), defaultSize(), "Default size");
        assertRectangle(0, 0, 40, 40, viewBox(), "View box should be set to the default size");
    }

    @Test
    void widthOnlyWithViewBoxComputesHeightFromAspectRatio() throws Exception {
        Document document = createSvgDocument("50", null, "0 0 100 200");

        transcode(document, null);

        // 50 * 200 / 100
        assertEquals(new Dimension(50, 100), defaultSize(), "Height should be derived from the view box ratio");
        assertRectangle(0, 0, 100, 200, viewBox(), "View box should be preserved");
    }

    @Test
    void heightOnlyWithViewBoxComputesWidthFromAspectRatio() throws Exception {
        Document document = createSvgDocument(null, "50", "0 0 100 200");

        transcode(document, null);

        // 50 * 100 / 200
        assertEquals(new Dimension(25, 50), defaultSize(), "Width should be derived from the view box ratio");
        assertRectangle(0, 0, 100, 200, viewBox(), "View box should be preserved");
    }

    @Test
    void explicitWidthAndHeightWinOverViewBox() throws Exception {
        Document document = createSvgDocument("50", "50", "0 0 100 200");

        transcode(document, null);

        assertEquals(new Dimension(50, 50), defaultSize(), "Default size");
        assertRectangle(0, 0, 100, 200, viewBox(), "Declared view box should be preserved");
    }

    // --- Boundary and invalid values ---

    @Test
    void zeroDimensionsAreTreatedAsMissing() throws Exception {
        Document document = createSvgDocument("0", "0", null);

        transcode(document, null);

        assertEquals(new Dimension(400, 400), defaultSize(), "Zero sizes are not usable, fall back to defaults");
        assertRectangle(0, 0, 400, 400, viewBox(), "View box");
    }

    @Test
    void zeroWidthIsTreatedAsMissingAndDerivedFromViewBox() throws Exception {
        Document document = createSvgDocument("0", null, "0 0 100 200");

        transcode(document, null);

        assertEquals(new Dimension(100, 200), defaultSize(), "Both dimensions should come from the view box");
        assertRectangle(0, 0, 100, 200, viewBox(), "View box");
    }

    @Test
    void negativeDimensionsFallBackToDefaultSize() throws Exception {
        Document document = createSvgDocument("-10", "-20", null);

        transcode(document, null);

        assertEquals(new Dimension(400, 400), defaultSize(), "Negative sizes are not usable, fall back to defaults");
        assertRectangle(0, 0, 400, 400, viewBox(), "View box");
        // The GVT tree cannot be built for this document, but the size is still determined
        assertNull(gvtRoot(), "GVT tree should not have been built");
        assertNotNull(exception(), "The BridgeException should be recorded");
    }

    @Test
    void emptyDimensionsAreTreatedAsMissing() throws Exception {
        Document document = createSvgDocument("", "", null);

        transcode(document, null);

        assertEquals(new Dimension(400, 400), defaultSize(), "Empty sizes are not usable, fall back to defaults");
        assertRectangle(0, 0, 400, 400, viewBox(), "View box");
    }

    @Test
    void fractionalDimensionsAreTruncatedInSizeButKeptInViewBox() throws Exception {
        Document document = createSvgDocument("50.6", "10.9", null);

        transcode(document, null);

        assertEquals(new Dimension(50, 10), defaultSize(), "Size is stored as an integer dimension");
        assertRectangle(0, 0, 50.6, 10.9, viewBox(), "View box keeps the exact values");
    }

    @Test
    void physicalUnitsAreResolvedToPixels() throws Exception {
        Document document = createSvgDocument("2in", "1em", null);

        transcode(document, null);

        // Batik uses 96 DPI for 'in', and 16px for 'em' (medium font size)
        assertEquals(new Dimension(192, 16), defaultSize(), "Default size");
        assertRectangle(0, 0, 192, 16, viewBox(), "View box");
    }

    @Test
    void invalidDimensionValueThrowsBridgeException() throws Exception {
        Document document = createSvgDocument("not-a-number", "20", null);

        RuntimeException exception = assertThrows(BridgeException.class, () -> transcode(document, null));

        assertNotNull(exception.getMessage(), "Exception message");
    }

    @Test
    void nullDocumentThrows() {
        assertThrows(NullPointerException.class, () -> transcode(null, null));
    }

    // --- Document URI handling ---

    @Test
    void svgDocumentIsNotCloned() throws Exception {
        Document document = createSvgDocument("10", "20", null);
        assertInstanceOf(SVGDOMImplementation.class, document.getImplementation(), "Precondition");

        transcode(document, null);

        assertSame(document, document(), "An SVG DOM document should be used as-is");
    }

    @Test
    void validUriIsAppliedToDocument() throws Exception {
        String uri = "http://example.com/images/awesome.svg";
        Document document = createSvgDocument("10", "20", null);

        transcode(document, uri);

        assertEquals(uri, ((SVGOMDocument) document).getURLObject().toExternalForm(), "Document URL");
        assertEquals(uri, uri(), "Stored URI");
        assertEquals(new Dimension(10, 20), defaultSize(), "Default size");
    }

    @Test
    void malformedUriIsIgnored() throws Exception {
        Document document = parseSvgDocument("file:/base/dir/document.svg", "<svg xmlns='" + SVG_NAMESPACE + "' width='10' height='20'/>");
        URL urlBefore = ((SVGOMDocument) document).getURLObject();
        assertNotNull(urlBefore, "Precondition: Document has a base URL");

        transcode(document, "this is not a valid URI");

        assertSame(urlBefore, ((SVGOMDocument) document).getURLObject(), "Malformed URI should leave the document URL untouched");
        assertEquals("this is not a valid URI", uri(), "The URI is still stored as-is");
        assertEquals(new Dimension(10, 20), defaultSize(), "Default size");
    }

    @Test
    void nullUriLeavesDocumentUrlUntouched() throws Exception {
        Document document = parseSvgDocument("file:/base/dir/document.svg", "<svg xmlns='" + SVG_NAMESPACE + "' width='10' height='20'/>");
        URL urlBefore = ((SVGOMDocument) document).getURLObject();

        transcode(document, null);

        assertSame(urlBefore, ((SVGOMDocument) document).getURLObject(), "Document URL");
        assertNull(uri(), "Stored URI");
    }

    // --- Dynamic documents ---

    @Test
    void documentWithScriptIsNotDynamicWithoutExecuteOnloadHint() throws Exception {
        Document document = parseSvgDocument(null, scriptedSvg());

        transcode(document, null);

        BridgeContext context = bridgeContext();
        assertNotNull(context, "Bridge context should be retained");
        assertFalse(context.isDynamic(), "Document should not be dynamic without the hint");
        assertEquals(new Dimension(10, 20), defaultSize(), "Default size");
    }

    @Test
    void documentWithScriptIsDynamicWithExecuteOnloadHint() throws Exception {
        Document document = parseSvgDocument(null, scriptedSvg());
        ((Transcoder) rasterizer).addTranscodingHint(SVGAbstractTranscoder.KEY_EXECUTE_ONLOAD, Boolean.TRUE);

        transcode(document, null);

        BridgeContext context = bridgeContext();
        assertNotNull(context, "Bridge context should be retained");
        assertTrue(context.isDynamic(), "Document should be dynamic when onload execution is enabled");
        assertNotNull(gvtRoot(), "GVT tree should have been built");
    }

    @Test
    void documentWithoutScriptIsNotDynamicEvenWithExecuteOnloadHint() throws Exception {
        Document document = createSvgDocument("10", "20", null);
        ((Transcoder) rasterizer).addTranscodingHint(SVGAbstractTranscoder.KEY_EXECUTE_ONLOAD, Boolean.TRUE);

        transcode(document, null);

        assertFalse(bridgeContext().isDynamic(), "Document without scripts should not be dynamic");
    }

    // --- Bridge context lifecycle ---

    @Test
    void bridgeContextIsRetainedAndTemporaryContextIsCleared() throws Exception {
        transcode(createSvgDocument("10", "20", null), null);

        BridgeContext context = bridgeContext();
        assertNotNull(context, "Bridge context should be kept for later use");
        assertNull(TRANSCODER_CTX.get(rasterizer), "The inherited ctx field should be cleared");
        assertSame(document(), DOCUMENT.get(rasterizer), "Stored document");
    }

    // --- Failing GVT build ---

    @Test
    void bridgeExceptionDuringBuildIsRecordedAndSizeIsStillDetermined() throws Exception {
        // A reference to a non-existing element makes the GVT builder fail
        Document document = parseSvgDocument(null,
                "<svg xmlns='" + SVG_NAMESPACE + "' xmlns:xlink='http://www.w3.org/1999/xlink' width='30' height='15'>"
                        + "<use xlink:href='#does-not-exist'/>"
                        + "</svg>");

        transcode(document, null);

        assertEquals(new Dimension(30, 15), defaultSize(), "Size should still be determined");
        assertRectangle(0, 0, 30, 15, viewBox(), "View box");
        assertNull(gvtRoot(), "GVT tree should not have been built");
        assertInstanceOf(TranscoderException.class, exception(), "Exception should be recorded");
    }

    // --- Interaction with the reader ---

    @Test
    void readerDerivesSizeFromWidthAndHeightAttributes() throws Exception {
        SVGImageReader reader = createReader("/svg/sizes/w50h50.svg");
        try {
            assertEquals(50, reader.getWidth(0), "Width");
            assertEquals(50, reader.getHeight(0), "Height");
        }
        finally {
            reader.dispose();
        }
    }

    @Test
    void readerDerivesSizeFromWidthAttributeOnly() throws Exception {
        SVGImageReader reader = createReader("/svg/sizes/w50noview.svg");
        try {
            assertEquals(50, reader.getWidth(0), "Width");
            assertEquals(50, reader.getHeight(0), "Height should be assumed square");
        }
        finally {
            reader.dispose();
        }
    }

    @Test
    void readerDerivesHeightFromViewBoxAspectRatio() throws Exception {
        // width="50" viewBox="0 0 100 200"
        SVGImageReader reader = createReader("/svg/sizes/h50_1to2.svg");
        try {
            assertEquals(50, reader.getWidth(0), "Width");
            assertEquals(100, reader.getHeight(0), "Height should be derived from the view box");
        }
        finally {
            reader.dispose();
        }
    }

    @Test
    void readerDerivesWidthFromViewBoxAspectRatio() throws Exception {
        // height="50" viewBox="0 0 100 200"
        SVGImageReader reader = createReader("/svg/sizes/w50_1to2.svg");
        try {
            assertEquals(25, reader.getWidth(0), "Width should be derived from the view box");
            assertEquals(50, reader.getHeight(0), "Height");
        }
        finally {
            reader.dispose();
        }
    }

    @Test
    void readerRendersImageInTheTranscodedSize() throws Exception {
        SVGImageReader reader = createReader("/svg/blue-square.svg");
        try {
            assertEquals(100, reader.getWidth(0), "Width");
            assertEquals(100, reader.getHeight(0), "Height");

            BufferedImage image = reader.read(0);

            assertNotNull(image, "Image");
            assertEquals(100, image.getWidth(), "Image width");
            assertEquals(100, image.getHeight(), "Image height");
            assertEquals(0xFF0000FF, image.getRGB(50, 50), "The document should be rendered as an opaque blue square");
        }
        finally {
            reader.dispose();
        }
    }

    // --- Helpers ---

    private static String scriptedSvg() {
        return "<svg xmlns='" + SVG_NAMESPACE + "' width='10' height='20'>"
                + "<script type='text/ecmascript'>var a = 1;</script>"
                + "</svg>";
    }

    private void transcode(Document document, String uri) throws Exception {
        try {
            TRANSCODE.invoke(rasterizer, document, uri, null);
        }
        catch (InvocationTargetException e) {
            throw asRuntimeException(e.getCause());
        }
    }

    private Dimension defaultSize() throws Exception {
        return (Dimension) DEFAULT_SIZE.get(rasterizer);
    }

    private Rectangle2D viewBox() throws Exception {
        return (Rectangle2D) VIEW_BOX.get(rasterizer);
    }

    private Object gvtRoot() throws Exception {
        return GVT_ROOT.get(rasterizer);
    }

    private Document document() throws Exception {
        return (Document) DOCUMENT.get(rasterizer);
    }

    private String uri() throws Exception {
        return (String) URI.get(rasterizer);
    }

    private TranscoderException exception() throws Exception {
        return (TranscoderException) EXCEPTION.get(rasterizer);
    }

    private BridgeContext bridgeContext() throws Exception {
        return (BridgeContext) BRIDGE_CONTEXT.get(rasterizer);
    }

    private static Document createSvgDocument(String width, String height, String viewBox) {
        Document document = SVGDOMImplementation.getDOMImplementation().createDocument(SVG_NAMESPACE, "svg", null);
        Element root = document.getDocumentElement();

        if (width != null) {
            root.setAttributeNS(null, "width", width);
        }
        if (height != null) {
            root.setAttributeNS(null, "height", height);
        }
        if (viewBox != null) {
            root.setAttributeNS(null, "viewBox", viewBox);
        }

        return document;
    }

    private static Document parseSvgDocument(String uri, String xml) throws IOException {
        return new SAXSVGDocumentFactory(null).createDocument(uri, new StringReader(xml));
    }

    private static SVGImageReader createReader(String resource) throws IOException {
        ImageInputStream input = ImageIO.createImageInputStream(SVGImageReaderTranscodeTests.class.getResourceAsStream(resource));
        assertNotNull(input, "Missing test resource: " + resource);

        SVGImageReader reader = new SVGImageReader(new SVGImageReaderSpi());
        reader.setInput(input);

        return reader;
    }

    private static void assertRectangle(double x, double y, double width, double height, Rectangle2D actual, String message) {
        assertNotNull(actual, message);
        assertEquals(x, actual.getX(), 1e-6, message + " (x)");
        assertEquals(y, actual.getY(), 1e-6, message + " (y)");
        assertEquals(width, actual.getWidth(), 1e-6, message + " (width)");
        assertEquals(height, actual.getHeight(), 1e-6, message + " (height)");
    }

    private static RuntimeException asRuntimeException(Throwable cause) {
        if (cause instanceof RuntimeException) {
            return (RuntimeException) cause;
        }
        if (cause instanceof Error) {
            throw (Error) cause;
        }

        return new RuntimeException(cause);
    }

    private static Field declaredField(Class<?> type, String name) throws NoSuchFieldException {
        Field field = type.getDeclaredField(name);
        field.setAccessible(true);

        return field;
    }

