    @Test
    public void testReadRLE8With4BitDepthThrows() {
        byte[] file = bmp(4, 2, 4, DIB.COMPRESSION_RLE8, PALETTE_16.length, PALETTE_16,
                new byte[]{4, 0x12, 0, 1}, null, false);

        IIOException exception = assertThrows(IIOException.class, () -> read(file));
        assertEquals("Unsupported combination of bitCount/compression: 4/1", exception.getMessage());
    }

    @Test
    public void testReadRLE4With8BitDepthThrows() {
        int[] palette = {BLACK, RED, GREEN, BLUE};
        byte[] file = bmp(4, 1, 8, DIB.COMPRESSION_RLE4, palette.length, palette,
                new byte[]{2, 1, 0, 1}, null, false);

        IIOException exception = assertThrows(IIOException.class, () -> read(file));
        assertEquals("Unsupported combination of bitCount/compression: 8/2", exception.getMessage());
    }

    @Test
    public void testReadUnsupportedCompressionThrows() {
        int[] palette = {BLACK, WHITE};
        byte[] file = bmp(1, 1, 8, 7 /* unknown compression */, palette.length, palette,
                new byte[]{(byte) 0xFF, 0, 0, 0}, null, false);

        IIOException exception = assertThrows(IIOException.class, () -> read(file));
        assertEquals("Unsupported compression: 7", exception.getMessage());
    }

    @Test
    public void testRead24BitWithRLECompressionThrows() {
        byte[] file = bmp(2, 1, 24, DIB.COMPRESSION_RLE8, 0, null, new byte[8], null, false);

        IIOException exception = assertThrows(IIOException.class, () -> read(file));
        assertEquals("Unsupported compression for RGB: 1", exception.getMessage());
    }

    @Test
    public void testReadTruncatedPixelDataThrows() {
        // Header claims a 2x2 image, but only a single (bottom) row of pixel data is present
        byte[] file = bmp(2, 2, 24, DIB.COMPRESSION_RGB, 0, null, pixels(2, 24, new int[]{BLUE, GREEN}), null, false);

        assertThrows(EOFException.class, () -> read(file));
    }

    @Test
    public void testReadNotABmpThrows() {
        byte[] file = bmp(1, 1, 24, DIB.COMPRESSION_RGB, 0, null, new byte[4], null, false);
        file[1] = 'X';

        IIOException exception = assertThrows(IIOException.class, () -> read(file));
        assertEquals("Not a BMP", exception.getMessage());
    }

    @Test
    public void testReadInvalidPixelOffsetThrows() {
        byte[] file = bmp(1, 1, 24, DIB.COMPRESSION_RGB, 0, null, new byte[4], null, false);
        putIntLE(file, 10, 40); // Pixel data starts inside the file/DIB header

        IIOException exception = assertThrows(IIOException.class, () -> read(file));
        assertEquals("Invalid pixel offset: 40", exception.getMessage());
    }

    @Test
    public void testReadWithoutInputThrows() {
        assertThrows(IllegalStateException.class, () -> reader.read(0, null));
    }

    @Test
    public void testReadIndexOutOfBounds() throws IOException {
        reader.setInput(imageInputStream(bmp(1, 1, 24, DIB.COMPRESSION_RGB, 0, null, pixels(1, 24,
                new int[]{BLUE}), null, false)));

        assertThrows(IndexOutOfBoundsException.class, () -> reader.read(1, null));
        assertThrows(IndexOutOfBoundsException.class, () -> reader.read(-1, null));
    }

    @Test
    public void testReadHugeDeclaredDimensionsThrows() {
        // Header claims 10000x10000 pixels, while the input is only 54 bytes long
        byte[] file = bmp(10000, 10000, 24, DIB.COMPRESSION_RGB, 0, null, new byte[0], null, false);

        IIOException exception = assertThrows(IIOException.class, () -> read(file));
        assertTrue(exception.getMessage().contains("exceeding"),
                "Unexpected message: " + exception.getMessage());
    }

    // ---------------------------------------------------------------------
    // Read parameters: regions, subsampling, destination
    // ---------------------------------------------------------------------

    @Test
    public void testReadSourceRegion() throws IOException {
        byte[] file = pattern24Bit(3, 3);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceRegion(new Rectangle(1, 1, 2, 2));

        BufferedImage image = read(file, param);

        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());

        assertEquals(argb(pattern(1, 1)), image.getRGB(0, 0));
        assertEquals(argb(pattern(2, 1)), image.getRGB(1, 0));
        assertEquals(argb(pattern(1, 2)), image.getRGB(0, 1));
        assertEquals(argb(pattern(2, 2)), image.getRGB(1, 1));
    }

    @Test
    public void testReadSourceSubsampling() throws IOException {
        byte[] file = pattern24Bit(4, 4);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceSubsampling(2, 2, 0, 0);

        BufferedImage image = read(file, param);

        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());

        assertEquals(argb(pattern(0, 0)), image.getRGB(0, 0));
        assertEquals(argb(pattern(2, 0)), image.getRGB(1, 0));
        assertEquals(argb(pattern(0, 2)), image.getRGB(0, 1));
        assertEquals(argb(pattern(2, 2)), image.getRGB(1, 1));
    }

    @Test
    public void testReadSourceRegionCombinedWithSubsampling() throws IOException {
        byte[] file = pattern24Bit(3, 3);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceRegion(new Rectangle(1, 1, 2, 2));
        param.setSourceSubsampling(2, 2, 0, 0);

        BufferedImage image = read(file, param);

        assertEquals(1, image.getWidth());
        assertEquals(1, image.getHeight());
        assertEquals(argb(pattern(1, 1)), image.getRGB(0, 0));
    }

    @Test
    public void testReadDestinationOffset() throws IOException {
        byte[] file = bmp(2, 2, 24, DIB.COMPRESSION_RGB, 0, null, pixels(2, 24,
                new int[]{RED, WHITE},
                new int[]{BLUE, GREEN}), null, false);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestinationOffset(new Point(1, 2));

        BufferedImage image = read(file, param);

        assertEquals(3, image.getWidth());
        assertEquals(4, image.getHeight());

        assertEquals(0, image.getRGB(0, 0));
        assertEquals(0, image.getRGB(2, 1));
        assertEquals(argb(RED), image.getRGB(1, 2));
        assertEquals(argb(WHITE), image.getRGB(2, 2));
        assertEquals(argb(BLUE), image.getRGB(1, 3));
        assertEquals(argb(GREEN), image.getRGB(2, 3));
    }

    @Test
    public void testReadIntoExplicitDestinationReturnsSameInstance() throws IOException {
        byte[] file = bmp(2, 2, 24, DIB.COMPRESSION_RGB, 0, null, pixels(2, 24,
                new int[]{RED, WHITE},
                new int[]{BLUE, GREEN}), null, false);

        BufferedImage destination = new BufferedImage(2, 2, BufferedImage.TYPE_3BYTE_BGR);
        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestination(destination);

        assertSame(destination, read(file, param));
        assertEquals(argb(RED), destination.getRGB(0, 0));
        assertEquals(argb(WHITE), destination.getRGB(1, 0));
        assertEquals(argb(BLUE), destination.getRGB(0, 1));
        assertEquals(argb(GREEN), destination.getRGB(1, 1));
    }

