    @Test
    public void testWarningWhenColorMapIsLargerThanRaster() throws IOException {
        int[] palette = {BLACK, RED, GREEN, BLUE};

        // Declares 256 colors, but only 4 palette entries are physically present before the pixel data
        BufferedImage image = read(bmp(2, 1, 8, DIB.COMPRESSION_RGB, 256, palette, pixels(2, 8,
                new int[]{1, 3}), null, false));

        assertEquals(argb(RED), image.getRGB(0, 0));
        assertEquals(argb(BLUE), image.getRGB(1, 0));

        assertEquals(Arrays.asList(
                "Color map contains more colors than raster allows (256). Ignoring entries above 4."), warnings);
    }

    @Test
    public void testNoWarningWhenColorMapMatchesRaster() throws IOException {
        int[] palette = {BLACK, RED, GREEN, BLUE};

        BufferedImage image = read(bmp(2, 1, 8, DIB.COMPRESSION_RGB, palette.length, palette, pixels(2, 8,
                new int[]{1, 3}), null, false));

        assertEquals(argb(RED), image.getRGB(0, 0));
        assertEquals(argb(BLUE), image.getRGB(1, 0));
        assertTrue(warnings.isEmpty(), "No warnings expected, was: " + warnings);
    }

    @Test
    public void testReadAbortedBeforeReadOnlyReadsFirstRow() throws IOException {
        byte[] file = bmp(2, 4, 24, DIB.COMPRESSION_RGB, 0, null, pixels(2, 24,
                new int[]{RED, RED},         // rows given top first...
                new int[]{GREEN, GREEN},
                new int[]{BLUE, BLUE},
                new int[]{WHITE, WHITE}), null, false);

        final int[] aborts = {0};
        reader.addIIOReadProgressListener(new ProgressListenerBase() {
            @Override
            public void readAborted(ImageReader source) {
                aborts[0]++;
