@Test
public void testReadSourceRegion() throws IOException {
    byte[] file = pattern24Bit(3, 3);

    ImageReadParam param = reader.getDefaultReadParam();
    param.setSourceRegion(new Rectangle(1, 1, 2, 2));

    BufferedImage image = read(file, param);

