package com.twelvemonkeys.imageio;

import org.junit.jupiter.api.Test;

import javax.imageio.IIOException;
import javax.imageio.ImageReadParam;
import javax.imageio.ImageTypeSpecifier;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.color.ColorSpace;
import java.awt.image.BufferedImage;
import java.awt.image.ColorModel;
import java.awt.image.DataBuffer;
import java.awt.image.SinglePixelPackedSampleModel;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ImageReaderBaseGetDestinationTests {

    private static final ImageTypeSpecifier RGB =
            ImageTypeSpecifier.createFromBufferedImageType(BufferedImage.TYPE_INT_RGB);
    private static final ImageTypeSpecifier GRAY =
            ImageTypeSpecifier.createFromBufferedImageType(BufferedImage.TYPE_BYTE_GRAY);
    private static final ImageTypeSpecifier BGR =
            ImageTypeSpecifier.createFromBufferedImageType(BufferedImage.TYPE_3BYTE_BGR);

    @Test
    void rejectsNullTypes() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> ImageReaderBase.getDestination(null, null, 10, 20));

        assertEquals("imageTypes null or empty!", exception.getMessage());
    }

    @Test
    void rejectsEmptyTypes() {
        assertThrows(IllegalArgumentException.class,
                () -> ImageReaderBase.getDestination(null,
                        Collections.<ImageTypeSpecifier>emptyList().iterator(), 10, 20));
    }

    @Test
    void usesFirstTypeWhenParamIsNull() {
        BufferedImage image = ImageReaderBase.getDestination(null, types(RGB, GRAY), 13, 7);

        assertNotNull(image);
        assertEquals(13, image.getWidth());
        assertEquals(7, image.getHeight());
        assertEquals(BufferedImage.TYPE_INT_RGB, image.getType());
    }

    @Test
    void usesFirstTypeWhenParamHasNoDestinationOrType() {
        ImageReadParam param = new ImageReadParam();

        BufferedImage image = ImageReaderBase.getDestination(param, types(GRAY, RGB), 11, 9);

        assertEquals(11, image.getWidth());
        assertEquals(9, image.getHeight());
        assertEquals(BufferedImage.TYPE_BYTE_GRAY, image.getType());
    }

    @Test
    void returnsExplicitDestinationForKnownMatchingType() {
        BufferedImage destination = new BufferedImage(4, 5, BufferedImage.TYPE_INT_RGB);
        ImageReadParam param = new ImageReadParam();
        param.setDestination(destination);

        BufferedImage image = ImageReaderBase.getDestination(param, types(RGB), 100, 50);

        assertSame(destination, image);
    }

    @Test
    void returnsExplicitDestinationWhenSampleModelAndBandsAreCompatible() {
        ImageTypeSpecifier byteRgb = ImageTypeSpecifier.createInterleaved(
                ColorSpace.getInstance(ColorSpace.CS_sRGB),
                new int[]{0, 1, 2}, DataBuffer.TYPE_BYTE, false, false);
        BufferedImage destination = new BufferedImage(6, 4, BufferedImage.TYPE_3BYTE_BGR);
        ImageReadParam param = new ImageReadParam();
        param.setDestination(destination);

        BufferedImage image = ImageReaderBase.getDestination(param, types(byteRgb), 30, 20);

        assertSame(destination, image);
    }

    @Test
    void rejectsExplicitDestinationThatDoesNotMatchAnyType() {
        BufferedImage destination = new BufferedImage(4, 5, BufferedImage.TYPE_INT_RGB);
        ImageReadParam param = new ImageReadParam();
        param.setDestination(destination);
        ImageTypeSpecifier byteRgb = ImageTypeSpecifier.createInterleaved(
                ColorSpace.getInstance(ColorSpace.CS_sRGB),
                new int[]{0, 1, 2}, DataBuffer.TYPE_BYTE, false, false);

        IIOException exception = assertThrows(IIOException.class,
                () -> ImageReaderBase.getDestination(param, types(GRAY, byteRgb), 4, 5));

        assertTrue(exception.getMessage().contains(
                "Destination image from ImageReadParam does not match legal imageTypes from reader"));
    }

    @Test
    void usesRequestedDestinationTypeWhenItOccursInIterator() {
        ImageReadParam param = new ImageReadParam();
        param.setDestinationType(BGR);

        BufferedImage image = ImageReaderBase.getDestination(param, types(RGB, BGR), 8, 6);

        assertEquals(8, image.getWidth());
        assertEquals(6, image.getHeight());
        assertEquals(BufferedImage.TYPE_3BYTE_BGR, image.getType());
    }

    @Test
    void rejectsRequestedDestinationTypeThatDoesNotOccurInIterator() {
        ImageReadParam param = new ImageReadParam();
        param.setDestinationType(RGB);

        IIOException exception = assertThrows(IIOException.class,
                () -> ImageReaderBase.getDestination(param, types(GRAY, BGR), 8, 6));

        assertTrue(exception.getMessage().contains(
                "Destination type from ImageReadParam does not match legal imageTypes from reader"));
    }

    @Test
    void computesDestinationSizeFromSourceRegion() {
        ImageReadParam param = new ImageReadParam();
        param.setSourceRegion(new Rectangle(2, 3, 4, 5));

        BufferedImage image = ImageReaderBase.getDestination(param, types(RGB), 10, 20);

        assertEquals(4, image.getWidth());
        assertEquals(5, image.getHeight());
    }

    @Test
    void computesDestinationSizeFromSourceSubsampling() {
        ImageReadParam param = new ImageReadParam();
        param.setSourceSubsampling(2, 3, 0, 0);

        BufferedImage image = ImageReaderBase.getDestination(param, types(RGB), 10, 20);

        assertEquals(5, image.getWidth());
        assertEquals(7, image.getHeight());
    }

    @Test
    void includesDestinationOffsetInDestinationSize() {
        ImageReadParam param = new ImageReadParam();
        param.setDestinationOffset(new Point(7, 9));

        BufferedImage image = ImageReaderBase.getDestination(param, types(RGB), 10, 20);

        assertEquals(17, image.getWidth());
        assertEquals(29, image.getHeight());
    }

    @Test
    void rejectsNonPositiveSourceDimensions() {
        assertThrows(IllegalArgumentException.class,
                () -> ImageReaderBase.getDestination(null, types(RGB), 0, 20));
        assertThrows(IllegalArgumentException.class,
                () -> ImageReaderBase.getDestination(null, types(RGB), 10, 0));
        assertThrows(IllegalArgumentException.class,
                () -> ImageReaderBase.getDestination(null, types(RGB), -1, 20));
    }

    @Test
    void rejectsEmptySourceRegionAfterClipping() {
        ImageReadParam param = new ImageReadParam();
        param.setSourceRegion(new Rectangle(20, 30, 5, 5));

        assertThrows(IllegalArgumentException.class,
                () -> ImageReaderBase.getDestination(param, types(RGB), 10, 20));
    }

    @Test
    void rejectsDestinationPixelCountGreaterThanIntegerMaxValue() {
        IIOException exception = assertThrows(IIOException.class,
                () -> ImageReaderBase.getDestination(null, types(RGB), 50_000, 50_000));

        assertTrue(exception.getMessage().contains("destination width * height > Integer.MAX_VALUE"));
    }

    @Test
    void rejectsDestinationSampleCountGreaterThanIntegerMaxValue() {
        ImageTypeSpecifier interleavedRgb = ImageTypeSpecifier.createInterleaved(
                ColorSpace.getInstance(ColorSpace.CS_sRGB),
                new int[]{0, 1, 2}, DataBuffer.TYPE_BYTE, false, false);
        assertEquals(3, interleavedRgb.getSampleModel().getNumDataElements());

        IIOException exception = assertThrows(IIOException.class,
                () -> ImageReaderBase.getDestination(null, types(interleavedRgb), 1_000_000_000, 2));

        assertTrue(exception.getMessage().contains(
                "destination width * height * samplesPerPixel > Integer.MAX_VALUE"));
    }

    @Test
    void wrapsOutOfMemoryErrorFromImageAllocation() {
        OutOfMemoryError failure = new OutOfMemoryError("simulated allocation failure");
        ImageTypeSpecifier failingType = new OomImageTypeSpecifier(failure);

        IIOException exception = assertThrows(IIOException.class,
                () -> ImageReaderBase.getDestination(null, types(failingType), 1, 1));

        assertTrue(exception.getMessage().contains("Unable to allocate destination image, out of memory"));
        assertSame(failure, exception.getCause());
    }

    private static Iterator<ImageTypeSpecifier> types(ImageTypeSpecifier... imageTypes) {
        return Arrays.asList(imageTypes).iterator();
    }

    private static final class OomImageTypeSpecifier extends ImageTypeSpecifier {
        private final OutOfMemoryError failure;

        OomImageTypeSpecifier(OutOfMemoryError failure) {
            super(ColorModel.getRGBdefault(), new SinglePixelPackedSampleModel(
                    DataBuffer.TYPE_INT, 1, 1,
                    new int[]{0x00ff0000, 0x0000ff00, 0x000000ff, 0xff000000}));
            this.failure = failure;
        }

        @Override
        public BufferedImage createBufferedImage(int width, int height) {
            throw failure;
        }
    }
}
