private static DDSReader readerFor(DDSType type, int width, int height, int mipMapCount) {
   if (type.isFourCC()) { // compressed
       return reader(width,height,mipMapCount, DDS.PIXEL_FORMAT_FLAG_FOURCC, type.fourCC(), 0, null);
   }
   // uncompressed
   int flags = DDS.PIXEL_FORMAT_FLAG_RGB;
   int[] masks = type.rgbaMasks;
   int bitCount = 8 * type.blockSize(); // blockSize for uncompressed is bytes per pixel: 2,3,4
   if (masks[3] != 0) flags |= DDS.PIXEL_FORMAT_FLAG_ALPHAPIXELS;
   return reader(width,height,mipMapCount,flags,0,bitCount,masks);
}
