        // Row 0 has the index pattern 0, 1, 2, 3; all remaining rows use index 0 (c0)
        byte[] data = new byte[] {
                (byte) 0xFF, (byte) 0xFF,   // color0
                0x00, 0x00,                 // color1
                (byte) 0xE4, 0x00, 0x00, 0x00 // 3 << 6 | 2 << 4 | 1 << 2 | 0
        };

        ImageInputStream input = imageInput(data);
        int[] pixels = reader.read(input, 0);

        assertNotNull(pixels);
        assertEquals(16, pixels.length);

        // c0 > c1 -> 4 color mode
        assertEquals(0xFFFFFFFF, pixels[0], "index 0 must be color0");
        assertEquals(0xFF000000, pixels[1], "index 1 must be color1");
        assertEquals(0xFFAAAAAA, pixels[2], "index 2 must be (2 * color0 + color1) / 3");
        assertEquals(0xFF555555, pixels[3], "index 3 must be (color0 + 2 * color1) / 3");

        for (int i = 4; i < pixels.length; i++) {
            assertEquals(0xFFFFFFFF, pixels[i], "index 0 must be color0, pixel " + i);
        }

        assertEquals(data.length, input.getStreamPosition(), "Whole block should have been consumed");
    }

