    @Test
    public void testReadSecondMipmapLevelSkipsBaseLevel() throws IOException {
        DDSReader reader = readerFor(DDSType.A8B8G8R8, 4, 4, 2);

        // Base level 4x4 (64 bytes) followed by level 1 2x2 (16 bytes)
        byte[] data = new byte[64 + 16];
        Arrays.fill(data, 0, 64, (byte) 0x7F);

        int offset = 64;
        for (int i = 0; i < 4; i++) {
            data[offset + 4 * i] = (byte) (1 + i);
            data[offset + 4 * i + 1] = (byte) (11 + i);
            data[offset + 4 * i + 2] = (byte) (21 + i);
            data[offset + 4 * i + 3] = (byte) (31 + i);
        }

        ImageInputStream input = imageInput(data);
        int[] pixels = reader.read(input, 1);

        assertArrayEquals(new int[] {
                0x1F0B01, 0x20100C02, 0x21150D03, 0x221A0E04
        }, pixels);
        assertEquals(data.length, input.getStreamPosition(), "Both mipmap levels should have been consumed");
