        byte[] data = new byte[64 + 16 + 4];
        Arrays.fill(data, (byte) 0xEE);

        data[data.length - 4] = 0x01;
        data[data.length - 3] = 0x02;
        data[data.length - 2] = 0x03;
        data[data.length - 1] = 0x04;

