    @Test
    public void testReadUsesDXT10DXGIFormat() throws IOException {
        // A DX10 header maps the DXGI format to a DDSType; B8G8R8A8_UNORM is A8R8G8B8 (blue, green, red, alpha)
        DDSReader reader = new DDSReader(DDSHeader.read(dxt10Header(1, 1, DXGI.DXGI_FORMAT_B8G8R8A8_UNORM)));

