        // BC2_UNORM maps to DXT2, which decodes alpha nibbles like DXT3
        DDSReader reader = new DDSReader(DDSHeader.read(dxt10Header(4, 4, DXGI.DXGI_FORMAT_BC2_UNORM)));

        int[] pixels = reader.read(imageInput(dxt3StyleBlock()), 0);

        assertEquals(16, pixels.length);
        assertEquals(0xFFFFFFFF, pixels[0]);
