import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests {@link DDSReader#read(ImageInputStream, int)}, that is: reading and decoding the pixel data of a
 * single (mipmap) image, given a {@link DDSHeader} describing the surface layout.
 */
public class DDSReaderReadTests {

    private static final int HEADER_BYTES = 128;

    // --------------------------------------------------------------------------------------------
    // Block compressed (DXT) formats
    // --------------------------------------------------------------------------------------------

    @Test
    public void testReadDXT1DecodesAllFourColorModes() throws IOException {
        DDSReader reader = readerFor(DDSType.DXT1, 4, 4);

        // One 4x4 block: c0 = white (0xFFFF), c1 = black (0x0000)
        // Row 0 has the index pattern 0, 1, 2, 3; all remaining rows use index 0 (c0)
        byte[] data = new byte[] {
                (byte) 0xFF, (byte) 0xFF,   // color0
                0x00, 0x00,                 // color1
                (byte) 0xE4, 0x00, 0x00, 0x00 // 3 << 6 | 2 << 4 | 1 << 2 | 0
        };

        ImageInputStream input = imageInput(data);
        int[] pixels = reader.read(input, 0);

        assertNotNull(pixels);
        assertEquals(16, pixels.length);

        // c0 > c1 -> 4 color mode
        assertEquals(0xFFFFFFFF, pixels[0], "index 0 must be color0");
        assertEquals(0xFF000000, pixels[1], "index 1 must be color1");
        assertEquals(0xFFAAAAAA, pixels[2], "index 2 must be (2 * color0 + color1) / 3");
        assertEquals(0xFF555555, pixels[3], "index 3 must be (color0 + 2 * color1) / 3");

        for (int i = 4; i < pixels.length; i++) {
            assertEquals(0xFFFFFFFF, pixels[i], "index 0 must be color0, pixel " + i);
        }

        assertEquals(data.length, input.getStreamPosition(), "Whole block should have been consumed");
    }

    @Test
    public void testReadDXT1PartialBlock() throws IOException {
        // 2x2 image occupies only the top-left corner of a 4x4 DXT1 block
        DDSReader reader = readerFor(DDSType.DXT1, 2, 2);

        byte[] data = new byte[] {
                (byte) 0xFF, (byte) 0xFF,   // color0 = white
                0x00, 0x00,                 // color1 = black
                (byte) 0xE4, 0x00, 0x00, 0x00
        };

        ImageInputStream input = imageInput(data);
        int[] pixels = reader.read(input, 0);

        assertArrayEquals(new int[] {
                0xFFFFFFFF, // row 0, index 0 -> color0
                0xFF000000, // row 0, index 1 -> color1
                0xFFFFFFFF, // row 1, index 0 -> color0
                0xFF000000  // row 1, index 1 -> color1
        }, pixels);

        assertEquals(8, input.getStreamPosition(), "A single 8 byte DXT1 block should have been read");
    }

    @Test
    public void testReadDXT2DecodesAlphaNibblesLikeDXT3() throws IOException {
        DDSReader reader = readerFor(DDSType.DXT2, 4, 4);

        byte[] data = dxt3StyleBlock();

        int[] pixels = reader.read(imageInput(data), 0);

        assertEquals(16, pixels.length);
        assertEquals(0xFFFFFFFF, pixels[0], "Row 0 alpha nibble 15 -> alpha 255");
        assertEquals(0x00FFFFFF, pixels[1], "Row 0 alpha nibble 0 -> alpha 0");
        assertEquals(0x00FFFFFF, pixels[2], "Row 0 alpha nibble 0 -> alpha 0");
        assertEquals(0x88FFFFFF, pixels[3], "Row 0 alpha nibble 8 -> alpha 136");

        for (int i = 4; i < pixels.length; i++) {
            assertEquals(0x00FFFFFF, pixels[i], "Row 1..3 alpha nibbles are all 0, pixel " + i);
        }
    }

    @Test
    public void testReadDXT3DecodesAlphaNibbles() throws IOException {
