    /**
     * A DXT2/DXT3 style block: alpha row 0 has the 4bit values 15, 0, 0, 8, all other rows 0.
     * Colors are white ({@code 0xFFFF}) and black ({@code 0x0000}), all color indices are 0 (color0).
     */
    private static byte[] dxt3StyleBlock() {
        byte[] data = new byte[16];
        data[0] = (byte) 0xF0; // alpha values 15 and 0 for row 0
        data[1] = 0x08; // alpha values 0 and 8 for row 0
        data[8] = (byte) 0xFF;
        data[9] = (byte) 0xFF; // color0 = white, color1 = black, all color indices 0
        return data;
    }

    /**
     * A DXT4/DXT5 style block: a0 = 255, a1 = 0 and alpha indices 0, 1, 2, 3 for row 0, 0 for remaining rows.
     * Colors are white ({@code 0xFFFF}) and black ({@code 0x0000}), all color indices are 0 (color0).
     */
    private static byte[] dxt5StyleBlock() {
        byte[] data = new byte[16];
        data[0] = (byte) 0xFF; // a0
        data[1] = 0x00; // a1

        int bits = 0 | (1 << 3) | (2 << 6) | (3 << 9);
        data[2] = (byte) (bits & 0xFF);
        data[3] = (byte) ((bits >> 8) & 0xFF);
        data[4] = (byte) ((bits >> 16) & 0xFF);

        data[8] = (byte) 0xFF;
        data[9] = (byte) 0xFF;
        return data;
    }

    private static DDSReader readerFor(DDSType type, int width, int height) throws IOException {
        return readerFor(type, width, height, 1);
    }

    private static DDSReader readerFor(DDSType type, int width, int height, int mipMapCount) throws IOException {
        ByteBuffer header = headerBuffer(width, height, mipMapCount);

        if (type.isFourCC()) {
            header.putInt(DDSType.DXT10 == type ? 0 : DDS.PIXEL_FORMAT_FLAG_FOURCC);
            // NOTE: fourCC is written by the caller-specific helpers
        }

        // Written out explicitly below to keep a single, readable header layout
        throw new IllegalStateException("unreachable");
    }

    private static ByteBuffer headerBuffer(int width, int height, int mipMapCount) {
        ByteBuffer buffer = ByteBuffer.allocate(HEADER_BYTES).order(ByteOrder.LITTLE_ENDIAN);

        buffer.putInt(DDS.HEADER_SIZE);
        buffer.putInt(DDS.FLAG_CAPS | DDS.FLAG_HEIGHT | DDS.FLAG_WIDTH | DDS.FLAG_PIXELFORMAT);
        buffer.putInt(height);
        buffer.putInt(width);
        buffer.putInt(0); // pitch/linear size
        buffer.putInt(0); // depth
        buffer.putInt(mipMapCount);
        buffer.put(new byte[44]); // reserved

        return buffer;
    }

    private static ImageInputStream imageInput(byte[] data) {
        return new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
    }

    private static ImageInputStream headerInput(byte[] headerBytes) {
        ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(headerBytes));
        input.setByteOrder(ByteOrder.LITTLE_ENDIAN);

        return input;
    }
