        int[] pixels = reader.read(input, 0);

        assertEquals(16, pixels.length);
        assertEquals(0xFFFFFFFF, pixels[0]);
        assertEquals(0x00FFFFFF, pixels[1]);
        assertEquals(0x00FFFFFF, pixels[2]);
        assertEquals(0x88FFFFFF, pixels[3]);
        assertEquals(0x00FFFFFF, pixels[4]);
        assertEquals(0x00FFFFFF, pixels[15]);

        assertEquals(16, input.getStreamPosition(), "A single 16 byte DXT3 block should have been read");
    }

    @Test
    public void testReadDXT4DecodesInterpolatedAlphaLikeDXT5() throws IOException {
        DDSReader reader = readerFor(DDSType.DXT4, 4, 4);

        int[] pixels = reader.read(imageInput(dxt5StyleBlock()), 0);

        assertEquals(16, pixels.length);
        assertEquals(0xFFFFFFFF, pixels[0], "Alpha index 0 -> a0 (255)");
        assertEquals(0x00FFFFFF, pixels[1], "Alpha index 1 -> a1 (0)");
        assertEquals(0xDAFFFFFF, pixels[2], "Alpha index 2 -> (6 * 255 + 0) / 7 = 218");
        assertEquals(0xB6FFFFFF, pixels[3], "Alpha index 3 -> (5 * 255 + 2 * 0) / 7 = 182");

        for (int i = 4; i < pixels.length; i++) {
