    @Test
    public void testReadDXT5WithA0LessThanOrEqualToA1UsesSixValueInterpolation() throws IOException {
        // a0 <= a1 selects the second interpolation table, where index 6 is fully transparent and 7 fully opaque
        DDSReader reader = readerFor(DDSType.DXT5, 4, 4);

        byte[] data = new byte[16];
        data[0] = 0x00;        // a0 = 0
        data[1] = (byte) 0xFF; // a1 = 255

        // Row 0 alpha indices: 4, 5, 6, 7
        int bits = 4 | (5 << 3) | (6 << 6) | (7 << 9);
        data[2] = (byte) (bits & 0xFF);
        data[3] = (byte) ((bits >> 8) & 0xFF);
        data[4] = (byte) ((bits >> 16) & 0xFF);

        data[8] = (byte) 0xFF;
        data[9] = (byte) 0xFF; // color0 = white, color1 = black, all color indices 0

        int[] pixels = reader.read(imageInput(data), 0);

        assertEquals(0x99FFFFFF, pixels[0], "Alpha index 4 -> (2 * 0 + 3 * 255) / 5 = 153");
        assertEquals(0xCCFFFFFF, pixels[1], "Alpha index 5 -> (0 + 4 * 255) / 5 = 204");
        assertEquals(0x00FFFFFF, pixels[2], "Alpha index 6 -> 0");
        assertEquals(0xFFFFFFFF, pixels[3], "Alpha index 7 -> 255");
    }

