                0x00, 0x00,               // color1 = black
                (byte) 0xE4, 0x00, 0x00, 0x00
        };

        ImageInputStream input = imageInput(data);
        int[] pixels = reader.read(input, 0);

        assertArrayEquals(new int[] {
                0xFFFFFFFF, // row 0, index 0 -> color0
                0xFF000000, // row 0, index 1 -> color1
                0xFFFFFFFF, // row 1, index 0 -> color0
                0xFF000000  // row 1, index 1 -> color1
        }, pixels);

        assertEquals(8, input.getStreamPosition(), "A single 8 byte DXT1 block should have been read");
    }

