        assertEquals(0x00FFFFFF, pixels[1], "Row 0 alpha nibble 0 -> alpha 0");
        assertEquals(0x00FFFFFF, pixels[2], "Row 0 alpha nibble 0 -> alpha 0");
        assertEquals(0x88FFFFFF, pixels[3], "Row 0 alpha nibble 8 -> alpha 136");

