        for (int i = 0; i < 4; i++) {
            data[offset + 4 * i] = (byte) (0x01 + i);
            data[offset + 4 * i + 1] = (byte) (0x0B + i);
            data[offset + 4 * i + 2] = (byte) (0x15 + i);
