        DDSReader reader = new DDSReader(DDSHeader.read(dxt10Header(1, 1, DXGI.DXGI_FORMAT_B8G8R8A8_UNORM)));

        int[] pixels = reader.read(imageInput(new byte[] {0x11, 0x22, 0x33, 0x44}), 0);

        assertArrayEquals(new int[] {0x44332211}, pixels);
    }

