    /**
     * A DXT2/DXT3 style block where the alpha nibbles of row 0 are 15, 0, 0 and 8.
     * All other alpha nibbles are 0. Colors are white ({@code 0xFFFF}) and black ({@code 0x0000}),
     * and all color indices are 0 (that is, color0).
     */
    private static byte[] dxt3StyleBlock() {
        byte[] data = new byte[16];
        data[0] = (byte) 0xF0; // alpha values 15 and 0 for row 0
        data[1] = 0x08;        // alpha values 0 and 8 for row 0
        data[8] = (byte) 0xFF;
        data[9] = (byte) 0xFF; // color0 = white, color1 = black, all color indices 0

        return data;
    }

    /**
     * A DXT4/DXT5 style block where a0 = 255, a1 = 0, and the alpha indices of row 0 are 0, 1, 2 and 3.
     * All other alpha indices are 0. Colors are white ({@code 0xFFFF}) and black ({@code 0x0000}),
     * and all color indices are 0 (that is, color0).
     */
    private static byte[] dxt5StyleBlock() {
        byte[] data = new byte[16];
        data[0] = (byte) 0xFF; // a0
        data[1] = 0x00;        // a1

        int bits = 0 | (1 << 3) | (2 << 6) | (3 << 9);
        data[2] = (byte) (bits & 0xFF);
        data[3] = (byte) ((bits >> 8) & 0xFF);
        data[4] = (byte) ((bits >> 16) & 0xFF);

        data[8] = (byte) 0xFF;
        data[9] = (byte) 0xFF;

        return data;
    }

    private static DDSReader readerFor(DDSType type, int width, int height) throws IOException {
        return readerFor(type, width, height, 1);
    }

    private static DDSReader readerFor(DDSType type, int width, int height, int mipMapCount) throws IOException {
        ByteBuffer header = headerBuffer(width, height, mipMapCount);

        if (type.isFourCC()) {
            header.putInt(DDS.PIXEL_FORMAT_FLAG_FOURCC);
            header.putInt(type.fourCC());
            header.putInt(0); // bit count
            header.putInt(0).putInt(0).putInt(0).putInt(0); // channel masks
        }
        else {
            int[] masks = type.rgbaMasks;
            int pixelFormatFlags = DDS.PIXEL_FORMAT_FLAG_RGB;
            if (masks[3] != 0) {
                pixelFormatFlags |= DDS.PIXEL_FORMAT_FLAG_ALPHAPIXELS;
            }

            header.putInt(pixelFormatFlags);
            header.putInt(0); // fourCC
            header.putInt(8 * type.blockSize()); // bit count == bits per pixel for uncompressed types
            header.putInt(masks[0]).putInt(masks[1]).putInt(masks[2]).putInt(masks[3]);
        }

        putCaps(header);

        return new DDSReader(DDSHeader.read(headerInput(header)));
    }

    private static ImageInputStream dxt10Header(int width, int height, int dxgiFormat) {
        ByteBuffer header = headerBuffer(width, height, 1);

        header.putInt(DDS.PIXEL_FORMAT_FLAG_FOURCC);
        header.putInt(DDSType.DXT10.fourCC());
        header.putInt(0); // bit count
        header.putInt(0).putInt(0).putInt(0).putInt(0); // channel masks
        putCaps(header);

        // DDS_HEADER_DXT10
        header.putInt(dxgiFormat);
        header.putInt(DDS.D3D10_RESOURCE_DIMENSION_TEXTURE2D);
        header.putInt(0); // miscFlag
        header.putInt(1); // arraySize
        header.putInt(0); // miscFlags2

        return headerInput(header);
    }

    private static void putCaps(ByteBuffer header) {
        header.putInt(0x1000); // dwCaps: DDSCAPS_TEXTURE
        header.putInt(0); // dwCaps2
        header.putInt(0); // dwCaps3
        header.putInt(0); // dwCaps4
        header.putInt(0); // dwReserved2
    }

    private static ByteBuffer headerBuffer(int width, int height, int mipMapCount) {
        ByteBuffer buffer = ByteBuffer.allocate(HEADER_BYTES + 20).order(ByteOrder.LITTLE_ENDIAN);

        buffer.putInt(DDS.HEADER_SIZE);
        buffer.putInt(DDS.FLAG_CAPS | DDS.FLAG_HEIGHT | DDS.FLAG_WIDTH | DDS.FLAG_PIXELFORMAT);
        buffer.putInt(height);
        buffer.putInt(width);
        buffer.putInt(0); // dwPitchOrLinearSize
        buffer.putInt(0); // dwDepth
        buffer.putInt(mipMapCount);
        buffer.put(new byte[44]); // dwReserved1

        buffer.putInt(DDS.PIXELFORMAT_SIZE);

        return buffer;
    }

    private static ImageInputStream headerInput(ByteBuffer header) {
        byte[] headerBytes = Arrays.copyOf(header.array(), header.position());
        ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(headerBytes));
        input.setByteOrder(ByteOrder.LITTLE_ENDIAN);

        return input;
    }

    private static ImageInputStream imageInput(byte[] data) {
        return new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
    }
