package com.twelvemonkeys.imageio.plugins.hdr;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

/**
 * Tests for {@code RGBE.readHeader(DataInput)}.
 */
public class RGBEReadHeaderTests {

    private static final String FORMAT = "FORMAT=32-bit_rle_rgbe";

    // --- helpers -------------------------------------------------------------------------------

    private static DataInput lines(final String... lines) {
        StringBuilder builder = new StringBuilder();
        for (String line : lines) {
            builder.append(line).append('\n');
        }

        return stream(builder.toString());
    }

    private static DataInput stream(final String content) {
        return new DataInputStream(new ByteArrayInputStream(content.getBytes(StandardCharsets.ISO_8859_1)));
    }

    // --- normal cases --------------------------------------------------------------------------

    @Test
    public void testMinimalHeaderUsesDefaults() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(FORMAT, "-Y 10 +X 20"));

        assertNotNull(header);
        assertEquals(20, header.getWidth());
        assertEquals(10, header.getHeight());
        assertEquals(1.0f, header.getGamma(), 0.0f);
        assertEquals(1.0f, header.getExposure(), 0.0f);
        assertNull(header.getProgramType());
        assertFalse(header.isProgramTypeValid());
        assertFalse(header.isGammaValid());
        assertFalse(header.isExposureValid());
    }

    @Test
    public void testFullyPopulatedHeader() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(
                "#?RGBE",
                "GAMMA=2.2",
                "EXPOSURE=1.5",
                FORMAT,
                "-Y 512 +X 1024"
        ));

        assertTrue(header.isProgramTypeValid());
        assertEquals("RGBE", header.getProgramType());

        assertTrue(header.isGammaValid());
        assertEquals(2.2f, header.getGamma(), 0.0f);

        assertTrue(header.isExposureValid());
        assertEquals(1.5f, header.getExposure(), 0.0f);

        assertEquals(1024, header.getWidth());
        assertEquals(512, header.getHeight());
    }

    @Test
    public void testProgramTypeIsTakenFromMagicToken() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines("#?RADIANCE", FORMAT, "-Y 8 +X 4"));

        assertTrue(header.isProgramTypeValid());
        assertEquals("RADIANCE", header.getProgramType());
        assertEquals(4, header.getWidth());
        assertEquals(8, header.getHeight());
    }

    @Test
    public void testEmptyProgramType() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines("#?", FORMAT, "-Y 1 +X 2"));

        assertTrue(header.isProgramTypeValid());
        assertEquals("", header.getProgramType());
        assertEquals(2, header.getWidth());
        assertEquals(1, header.getHeight());
    }

    @Test
    public void testDimensionLineIsHeightThenWidth() throws IOException {
        // "-Y <height> +X <width>"
        RGBE.Header header = RGBE.readHeader(lines(FORMAT, "-Y 7 +X 13"));

        assertEquals(13, header.getWidth());
        assertEquals(7, header.getHeight());
    }

    @Test
    public void testGammaOnly() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines("GAMMA=1.0", FORMAT, "-Y 2 +X 3"));

        assertTrue(header.isGammaValid());
        assertEquals(1.0f, header.getGamma(), 0.0f);
        assertFalse(header.isExposureValid());
        assertEquals(1.0f, header.getExposure(), 0.0f);
        assertFalse(header.isProgramTypeValid());
    }

    @Test
    public void testExposureOnly() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines("EXPOSURE=0.25", FORMAT, "-Y 2 +X 3"));

        assertTrue(header.isExposureValid());
        assertEquals(0.25f, header.getExposure(), 0.0f);
        assertFalse(header.isGammaValid());
        assertEquals(1.0f, header.getGamma(), 0.0f);
    }

    @Test
    public void testHeaderValuesInArbitraryOrder() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(
                "#?RGBE",
                "EXPOSURE=2",
                "COMMENT=some comment",
                "GAMMA=0.5",
                FORMAT,
                "-Y 3 +X 5"
        ));

        assertTrue(header.isExposureValid());
        assertEquals(2.0f, header.getExposure(), 0.0f);
        assertTrue(header.isGammaValid());
        assertEquals(0.5f, header.getGamma(), 0.0f);
        assertEquals(5, header.getWidth());
        assertEquals(3, header.getHeight());
    }

    @Test
    public void testUnknownAndBlankLinesAreIgnored() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(
                "COMMENT=written by a test",
                "",
                "SOFTWARE=twelvemonkeys",
                FORMAT,
                "   ",
                "-Y 6 +X 9"
        ));

        assertEquals(9, header.getWidth());
        assertEquals(6, header.getHeight());
        assertFalse(header.isGammaValid());
        assertFalse(header.isExposureValid());
        assertFalse(header.isProgramTypeValid());
    }

    @Test
    public void testLastValueWinsWhenRepeated() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(
                "GAMMA=1.0",
                "GAMMA=3.5",
                "EXPOSURE=1",
                "EXPOSURE=4",
                FORMAT,
                "-Y 1 +X 1"
        ));

        assertEquals(3.5f, header.getGamma(), 0.0f);
        assertEquals(4.0f, header.getExposure(), 0.0f);
    }

    @Test
    public void testGammaInExponentNotation() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines("GAMMA=1e-2", FORMAT, "-Y 1 +X 1"));

        assertTrue(header.isGammaValid());
        assertEquals(0.01f, header.getGamma(), 0.0f);
    }

    @Test
    public void testExtraWhitespaceInDimensionLineIsAccepted() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(FORMAT, "-Y   42   +X   17"));

        assertEquals(17, header.getWidth());
        assertEquals(42, header.getHeight());
    }

    @Test
    public void testZeroDimensionsAreAccepted() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(FORMAT, "-Y 0 +X 0"));

        assertEquals(0, header.getWidth());
        assertEquals(0, header.getHeight());
    }

    @Test
    public void testLinesAfterDimensionLineAreNotConsumed() throws IOException {
        DataInput input = lines(FORMAT, "-Y 2 +X 2", "PIXEL-DATA");

        RGBE.Header header = RGBE.readHeader(input);

        assertEquals(2, header.getWidth());
        assertEquals(2, header.getHeight());

        // The pixel data following the header must still be readable from the stream
        assertEquals("PIXEL-DATA", input.readLine());
    }

    @Test
    public void testMagicLookingLineAfterFirstLineIsNotProgramType() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(FORMAT, "#?RGBE", "-Y 1 +X 1"));

        assertFalse(header.isProgramTypeValid());
        assertNull(header.getProgramType());
    }

    @Test
    public void testCommentLineStartingWithHashIsIgnored() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines("# this is a comment", FORMAT, "-Y 2 +X 5"));

        assertFalse(header.isProgramTypeValid());
        assertNull(header.getProgramType());
        assertEquals(5, header.getWidth());
        assertEquals(2, header.getHeight());
    }

    // --- error cases ---------------------------------------------------------------------------

    @Test
    public void testEmptyInputThrowsIOException() {
        IOException exception = assertThrows(IOException.class, () -> RGBE.readHeader(stream("")));

        assertEquals("Unexpected EOF reading magic token", exception.getMessage());
    }

    @Test
    public void testEofAfterMagicTokenThrowsIOException() {
        IOException exception = assertThrows(IOException.class, () -> RGBE.readHeader(lines("#?RGBE")));

        assertEquals("Unexpected EOF reading line after magic token", exception.getMessage());
    }

    @Test
    public void testEofBeforeDimensionLineThrowsIOException() {
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("#?RGBE", FORMAT, "GAMMA=1.0")));

        assertEquals("Unexpected EOF reading header", exception.getMessage());
    }

    @Test
    public void testEofWithOnlyUnknownLinesThrowsIOException() {
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("COMMENT=foo", "SOFTWARE=bar")));

        assertEquals("Unexpected EOF reading header", exception.getMessage());
    }

    @Test
    public void testMissingFormatSpecifierThrowsIOException() {
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("#?RGBE", "GAMMA=2.2", "-Y 10 +X 20")));

        assertEquals("No FORMAT specifier found", exception.getMessage());
    }

    @Test
    public void testUnsupportedFormatSpecifierIsNotAccepted() {
        // Only 32-bit RLE RGBE is supported; the header must be rejected
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("FORMAT=32-bit_rle_xyze", "-Y 10 +X 20")));

        assertEquals("No FORMAT specifier found", exception.getMessage());
    }

    @Test
    public void testFormatLineWithTrailingWhitespaceIsNotAccepted() {
        // Exact match required, a trailing space must not be silently accepted
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("FORMAT=32-bit_rle_rgbe ", "-Y 10 +X 20")));

        assertEquals("No FORMAT specifier found", exception.getMessage());
    }

    @Test
    public void testDimensionLineWithTrailingGarbageIsNotMatched() {
        // The whole line must match "-Y <digits> +X <digits>"
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines(FORMAT, "-Y 10 +X 20 (comment)")));

        assertEquals("Unexpected EOF reading header", exception.getMessage());
    }

    @Test
    public void testNegativeDimensionIsNotMatched() {
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines(FORMAT, "-Y -1 +X 20")));

        assertEquals("Unexpected EOF reading header", exception.getMessage());
    }

    @Test
    public void testNonNumericGammaThrowsNumberFormatException() {
        assertThrows(NumberFormatException.class,
                () -> RGBE.readHeader(lines("GAMMA=not-a-number", FORMAT, "-Y 1 +X 1")));
    }

    @Test
    public void testEmptyGammaValueThrowsNumberFormatException() {
        assertThrows(NumberFormatException.class,
                () -> RGBE.readHeader(lines("GAMMA=", FORMAT, "-Y 1 +X 1")));
    }

    @Test
    public void testNonNumericExposureThrowsNumberFormatException() {
        assertThrows(NumberFormatException.class,
                () -> RGBE.readHeader(lines("EXPOSURE=lots", FORMAT, "-Y 1 +X 1")));
    }

    @Test
    public void testDimensionOverflowThrowsNumberFormatException() {
        assertThrows(NumberFormatException.class,
                () -> RGBE.readHeader(lines(FORMAT, "-Y 99999999999 +X 1")));
    }

    @Test
    public void testSingleCharacterFirstLineIsRejected() {
        // The magic token check inspects the first two characters, a lone '#' is not a valid line
        try {
            RGBE.readHeader(lines("#"));
            fail("Expected exception for single character first line");
        }
        catch (IOException e) {
            fail("Expected an unchecked exception, got IOException: " + e.getMessage());
        }
        catch (RuntimeException expected) {
            // expected: index out of bounds while inspecting the magic token
        }
    }
}
