        assertFalse(header.isProgramTypeValid());
    }

    @Test
    public void testLastValueWinsWhenRepeated() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(
                "GAMMA=1.0",
                "GAMMA=3.5",
                "EXPOSURE=1",
                "EXPOSURE=4",
                FORMAT,
                "-Y 1 +X 1"
        ));

        assertEquals(3.5f, header.getGamma(), 0.0f);
        assertEquals(4.0f, header.getExposure(), 0.0f);
    }

    @Test
    public void testGammaInExponentNotation() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines("GAMMA=1e-2", FORMAT, "-Y 1 +X 1"));

        assertTrue(header.isGammaValid());
        assertEquals(0.01f, header.getGamma(), 0.0f);
    }

    @Test
    public void testExtraSpaceAfterMarkerMakesLineNotMatch() {
        // Exactly one space is required after "-Y" and "+X"
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines(FORMAT, "-Y  42 +X 17")));

        assertEquals("Unexpected EOF reading header", exception.getMessage());
    }

    @Test
    public void testZeroDimensionsAreAccepted() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(FORMAT, "-Y 0 +X 0"));

        assertEquals(0, header.getWidth());
        assertEquals(0, header.getHeight());
    }

    @Test
    public void testLinesAfterDimensionLineAreNotConsumed() throws IOException {
        DataInput input = lines(FORMAT, "-Y 2 +X 2", "PIXEL-DATA");

        RGBE.Header header = RGBE.readHeader(input);

        assertEquals(2, header.getWidth());
        assertEquals(2, header.getHeight());

        // The pixel data following the header must still be readable from the stream
        assertEquals("PIXEL-DATA", input.readLine());
    }

    @Test
    public void testMagicLookingLineAfterFirstLineIsNotProgramType() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines(FORMAT, "#?RGBE", "-Y 1 +X 1"));

        assertFalse(header.isProgramTypeValid());
        assertNull(header.getProgramType());
    }

    @Test
    public void testCommentLineStartingWithHashIsIgnored() throws IOException {
        RGBE.Header header = RGBE.readHeader(lines("# this is a comment", FORMAT, "-Y 2 +X 5"));

        assertFalse(header.isProgramTypeValid());
        assertNull(header.getProgramType());
        assertEquals(5, header.getWidth());
        assertEquals(2, header.getHeight());
    }

    // --- error cases ---------------------------------------------------------------------------

    @Test
    public void testEmptyInputThrowsIOException() {
        IOException exception = assertThrows(IOException.class, () -> RGBE.readHeader(stream("")));

        assertEquals("Unexpected EOF reading magic token", exception.getMessage());
    }

    @Test
    public void testEofAfterMagicTokenThrowsIOException() {
        IOException exception = assertThrows(IOException.class, () -> RGBE.readHeader(lines("#?RGBE")));

        assertEquals("Unexpected EOF reading line after magic token", exception.getMessage());
    }

    @Test
    public void testEofBeforeDimensionLineThrowsIOException() {
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("#?RGBE", FORMAT, "GAMMA=1.0")));

        assertEquals("Unexpected EOF reading header", exception.getMessage());
    }

    @Test
    public void testEofWithOnlyUnknownLinesThrowsIOException() {
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("COMMENT=foo", "SOFTWARE=bar")));

        assertEquals("Unexpected EOF reading header", exception.getMessage());
    }

    @Test
    public void testMissingFormatSpecifierThrowsIOException() {
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("#?RGBE", "GAMMA=2.2", "-Y 10 +X 20")));

        assertEquals("No FORMAT specifier found", exception.getMessage());
    }

    @Test
    public void testUnsupportedFormatSpecifierIsNotAccepted() {
        // Only 32-bit RLE RGBE is supported; the header must be rejected
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("FORMAT=32-bit_rle_xyze", "-Y 10 +X 20")));

        assertEquals("No FORMAT specifier found", exception.getMessage());
    }

    @Test
    public void testFormatLineWithTrailingWhitespaceIsNotAccepted() {
        // Exact match required, a trailing space must not be silently accepted
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines("FORMAT=32-bit_rle_rgbe ", "-Y 10 +X 20")));

        assertEquals("No FORMAT specifier found", exception.getMessage());
    }

    @Test
    public void testDimensionLineWithTrailingGarbageIsNotMatched() {
        // The whole line must match "-Y <digits> +X <digits>"
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines(FORMAT, "-Y 10 +X 20 (comment)")));

        assertEquals("Unexpected EOF reading header", exception.getMessage());
    }

    @Test
    public void testNegativeDimensionIsNotMatched() {
        IOException exception = assertThrows(IOException.class,
                () -> RGBE.readHeader(lines(FORMAT, "-Y -1 +X 20")));

        assertEquals("Unexpected EOF reading header", exception.getMessage());
    }

    @Test
    public void testNonNumericGammaThrowsNumberFormatException() {
        assertThrows(NumberFormatException.class,
                () -> RGBE.readHeader(lines("GAMMA=not-a-number", FORMAT, "-Y 1 +X 1")));
    }

    @Test
    public void testEmptyGammaValueThrowsNumberFormatException() {
        assertThrows(NumberFormatException.class,
                () -> RGBE.readHeader(lines("GAMMA=", FORMAT, "-Y 1 +X 1")));
    }

    @Test
    public void testNonNumericExposureThrowsNumberFormatException() {
        assertThrows(NumberFormatException.class,
                () -> RGBE.readHeader(lines("EXPOSURE=lots", FORMAT, "-Y 1 +X 1")));
    }

    @Test
    public void testDimensionOverflowThrowsNumberFormatException() {
        assertThrows(NumberFormatException.class,
                () -> RGBE.readHeader(lines(FORMAT, "-Y 99999999999 +X 1")));
    }

    @Test
    public void testSingleCharacterFirstLineIsRejected() {
        // The magic token check inspects the first two characters, a lone '#' cannot be handled
        assertThrows(IndexOutOfBoundsException.class, () -> RGBE.readHeader(lines("#")));
    }

    @Test
    public void testEmptyFirstLineIsRejected() {
        assertThrows(IndexOutOfBoundsException.class, () -> RGBE.readHeader(lines("")));
    }
}

