package com.twelvemonkeys.imageio.plugins.jpeg;

import org.junit.jupiter.api.Test;

import java.awt.Point;
import java.awt.image.DataBuffer;
import java.awt.image.Raster;
import java.awt.image.WritableRaster;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for the raster conversion performed by {@link FastCMYKToRGB#filter}.
 */
public class FastCMYKToRGBFilterTests {

    private final FastCMYKToRGB op = new FastCMYKToRGB();

    // --- Validation -------------------------------------------------------

    @Test
    public void nullSourceIsRejected() {
        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> op.filter(null, null)
        );

        assertTrue(exception.getMessage().contains("src may not be null"),
                "Unexpected message: " + exception.getMessage());
    }

    @Test
    public void sameSourceAndDestinationIsRejected() {
        WritableRaster raster = createByteRaster(4, 1, 1, new int[]{0, 0, 0, 0});

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> op.filter(raster, raster)
        );

        assertTrue(exception.getMessage().contains("src and dest raster may not be same"),
                "Unexpected message: " + exception.getMessage());
    }

    @Test
    public void nonByteSourceTransferTypeIsRejected() {
        WritableRaster src = Raster.createInterleavedRaster(DataBuffer.TYPE_USHORT, 1, 1, 4, new Point(0, 0));

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> op.filter(src, null)
        );

        assertTrue(exception.getMessage().contains("only TYPE_BYTE rasters supported as src"),
                "Unexpected message: " + exception.getMessage());
    }

    @Test
    public void sourceWithTooFewDataElementsIsRejected() {
        WritableRaster src = createByteRaster(3, 1, 1, new int[]{0, 0, 0});

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> op.filter(src, null)
        );

        assertTrue(exception.getMessage().contains("at least 4 data elements"),
                "Unexpected message: " + exception.getMessage());
    }

    @Test
    public void invalidDestinationTransferTypeIsRejected() {
        WritableRaster src = createByteRaster(4, 1, 1, new int[]{0, 0, 0, 0});
        WritableRaster dest = Raster.createInterleavedRaster(DataBuffer.TYPE_USHORT, 1, 1, 3, new Point(0, 0));

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> op.filter(src, dest)
        );

        assertTrue(exception.getMessage().contains("only 3 or 4 byte TYPE_BYTE or 1 int TYPE_INT rasters supported as dest"),
                "Unexpected message: " + exception.getMessage());
    }

    @Test
    public void byteDestinationWithTooFewDataElementsIsRejected() {
        WritableRaster src = createByteRaster(4, 1, 1, new int[]{0, 0, 0, 0});
        WritableRaster dest = Raster.createInterleavedRaster(DataBuffer.TYPE_BYTE, 1, 1, 2, new Point(0, 0));

        assertThrows(IllegalArgumentException.class, () -> op.filter(src, dest));
    }

    @Test
    public void intDestinationWithMoreThanOneDataElementIsRejected() {
        WritableRaster src = createByteRaster(4, 1, 1, new int[]{0, 0, 0, 0});
        WritableRaster dest = Raster.createInterleavedRaster(DataBuffer.TYPE_INT, 1, 1, 2, new Point(0, 0));

        assertThrows(IllegalArgumentException.class, () -> op.filter(src, dest));
    }

    // --- Byte destination -------------------------------------------------

    @Test
    public void convertsToThreeByteRgbDestination() {
        // 2x2 image: white, black, cyan (C=255), and 50% black (K=128).
        WritableRaster src = createByteRaster(4, 2, 2,
                new int[]{0, 0, 0, 0},
                new int[]{0, 0, 0, 255},
                new int[]{255, 0, 0, 0},
