/**
 * Tests for {@code JPEGImageReader.getEmbeddedICCProfile(boolean)}.
 * <p>
 * The tests build minimal, but syntactically valid, JPEG streams (SOI ... APP2 ... EOI)
 * containing zero or more {@code ICC_PROFILE} APP2 segments, and verify how the reader
 * assembles (or rejects) the embedded ICC profile.
 */
class JPEGImageReaderGetEmbeddedICCProfileTests {

    private static final String ICC_IDENTIFIER = "ICC_PROFILE";

    /** A known good, 3 component display profile (the JRE built-in sRGB profile). */
    private static final byte[] SRGB_PROFILE_DATA = ICC_Profile.getInstance(ColorSpace.CS_sRGB).getData();

    private final List<String> warnings = new ArrayList<>();
    private JPEGImageReader reader;
    private ImageInputStream input;

    @BeforeAll
    static void scanForPlugins() {
        ImageIO.scanForPlugins();
    }

    @BeforeEach
    void createReader() {
        reader = createJPEGImageReader();
    }

    @AfterEach
    void disposeReader() throws IOException {
        if (input != null) {
            input.close();
            input = null;
        }
        if (reader != null) {
            reader.dispose();
            reader = null;
        }
    }

    // ---------------------------------------------------------------------------------------------
    // Normal cases
    // ---------------------------------------------------------------------------------------------

    @Test
    void noAppSegmentsShouldReturnNull() throws IOException {
        setInput(jpeg());

        assertNull(reader.getEmbeddedICCProfile(false));
        assertNull(reader.getEmbeddedICCProfile(true));
        assertTrue(warnings.isEmpty(), "Expected no warnings, was: " + warnings);
    }

    @Test
    void app2SegmentWithOtherIdentifierShouldBeIgnored() throws IOException {
        setInput(jpeg(app2Segment("OTHER_NAME", new byte[] {1, 2, 3, 4, 5})));

        assertNull(reader.getEmbeddedICCProfile(false));
        assertNull(reader.getEmbeddedICCProfile(true));
        assertTrue(warnings.isEmpty(), "Expected no warnings, was: " + warnings);
    }

    @Test
    void singleSegmentSingleChunkShouldReadProfile() throws IOException {
        setInput(jpeg(iccSegment(1, 1, SRGB_PROFILE_DATA)));

        ICC_Profile profile = reader.getEmbeddedICCProfile(false);

        assertNotNull(profile);
        assertEquals(3, profile.getNumComponents());
        assertEquals(ColorSpace.TYPE_RGB, profile.getColorSpaceType());
        assertArrayEquals(SRGB_PROFILE_DATA, profile.getData(), "Profile data should be identical to the embedded data");
        assertTrue(warnings.isEmpty(), "Expected no warnings, was: " + warnings);
    }

    @Test
    void singleSegmentSingleChunkShouldAlsoReadProfileWhenBadIndexesAllowed() throws IOException {
        setInput(jpeg(iccSegment(1, 1, SRGB_PROFILE_DATA)));

        ICC_Profile profile = reader.getEmbeddedICCProfile(true);

    }

    @Test
    void zeroBasedChunkIndexesShouldBeIgnoredWhenBadIndexesNotAllowed() throws IOException {
        byte[][] chunks = split(SRGB_PROFILE_DATA, 2);
        setInput(jpeg(
                iccSegment(0, 0, chunks[0]),
                iccSegment(0, 0, chunks[1])
        ));

        assertNull(reader.getEmbeddedICCProfile(false));

        assertTrue(warnings.contains("Bad 'ICC_PROFILE' chunk count: 0. Ignoring ICC profile."),
                "Expected warning about bad chunk count, was: " + warnings);
    }

    // ---------------------------------------------------------------------------------------------
