    }

    @Test
    void inconsistentChunkCountsShouldThrowIIOException() throws IOException {
        byte[][] chunks = split(SRGB_PROFILE_DATA, 2);
        setInput(jpeg(
                iccSegment(1, 2, chunks[0]),
                iccSegment(1, 1, chunks[1]) // Inconsistent chunk count
        ));

        IIOException exception = assertThrows(IIOException.class, () -> reader.getEmbeddedICCProfile(false));
