    // Corrupt / invalid descriptions
    // ---------------------------------------------------------------------------------------------

    @Test
    void testDecompressDataSizeTooSmall() {
        byte[] data = new byte[12];

        ImageInputStream stream = stream(data);
        ImageDesc description = description(2, 2, 24, data.length - 1);

        IIOException exception = assertThrows(IIOException.class, () -> decompressor.decompress(description, stream));

        String message = exception.getMessage();
        assertNotNull(message);
        assertTrue(message.contains("Corrupt QuickTime RAW"), "Unexpected message: " + message);
        assertTrue(message.contains("11"), "Message should mention declared data size: " + message);
        assertTrue(message.contains("2x2"), "Message should mention width x height: " + message);
        assertTrue(message.contains("24"), "Message should mention depth: " + message);

        // Nothing should have been read from the stream
        assertEquals(0, stream.getStreamPosition());
    }

