    /** As above, but reports an unknown ({@code -1}) length, like a streaming source. */
    private static ImageInputStream streamWithUnknownLength(byte[] data) {
        return new MemoryImageInputStream(data, -1);
    }

    private static final class MemoryImageInputStream extends ImageInputStreamImpl {
        private final byte[] data;
        private final long length;

        MemoryImageInputStream(byte[] data, long length) {
            this.data = data.clone();
            this.length = length;
        }

        @Override
        public int read() {
            if (streamPos >= data.length) {
                return -1;
            }

            return data[(int) streamPos++] & 0xff;
        }

        @Override
        public int read(byte[] bytes, int offset, int len) {
            if (streamPos >= data.length) {
                return -1;
            }

            int count = (int) Math.min(len, data.length - streamPos);
            System.arraycopy(data, (int) streamPos, bytes, offset, count);
            streamPos += count;

            return count;
        }

        @Override
        public long length() {
            return length;
        }

        @Override
        public void close() {
            // Allow repeated use in tests, no resources to release
        }
    }

