    @Test
    void testDecompress32BitARGBDoesNotMixPixels() throws IOException {
        // Large enough to catch stride/offset errors in the channel swapping loop
        int width = 17;
        int height = 5;
        byte[] data = new byte[width * height * 4];

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int offset = 4 * (y * width + x);
                data[offset] = (byte) 0xff;       // A
                data[offset + 1] = (byte) (x + 1); // R
                data[offset + 2] = (byte) (y + 1); // G
                data[offset + 3] = (byte) 0x7f;    // B
            }
        }

        BufferedImage image = decompressor.decompress(description(width, height, 32, data.length), stream(data));

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                assertEquals(x + 1, image.getRaster().getSample(x, y, 0), "R at " + x + "," + y);
                assertEquals(y + 1, image.getRaster().getSample(x, y, 1), "G at " + x + "," + y);
                assertEquals(0x7f, image.getRaster().getSample(x, y, 2), "B at " + x + "," + y);
                assertEquals(0xff, image.getRaster().getSample(x, y, 3), "A at " + x + "," + y);
            }
        }
    }

