package com.twelvemonkeys.imageio.plugins.pict;

import org.junit.jupiter.api.Test;

import java.awt.Shape;
import java.awt.geom.GeneralPath;
import java.awt.geom.PathIterator;
import java.awt.geom.Rectangle2D;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link QuickDrawContext.RectangleStroke#createStrokedShape(Shape)}.
 *
 * The stroke places a copy of its (centered) stamp shape at every whole unit of
 * distance along the outline of the supplied path, starting at distance 0.
 * These tests observe the resulting path structurally (number of sub-paths and
 * segment types) as well as through geometric queries (bounds and containment).
 */
class QuickDrawContextCreateStrokedShapeTests {

    private static final double EPS = 1e-3;

    // --- helpers -----------------------------------------------------------

    private static QuickDrawContext.RectangleStroke squareStamp(double size) {
        return new QuickDrawContext.RectangleStroke(new Rectangle2D.Double(0, 0, size, size));
    }

    private static GeneralPath line(float x0, float y0, float x1, float y1) {
        GeneralPath path = new GeneralPath();
        path.moveTo(x0, y0);
        path.lineTo(x1, y1);
        return path;
    }

    private static int countSegments(Shape shape, int segmentType) {
        PathIterator it = shape.getPathIterator(null);
        float[] coords = new float[6];
        int count = 0;
        while (!it.isDone()) {
            if (it.currentSegment(coords) == segmentType) {
                count++;
            }
            it.next();
        }
        return count;
    }

    private static int countSegments(Shape shape) {
        PathIterator it = shape.getPathIterator(null);
        float[] coords = new float[6];
        int count = 0;
        while (!it.isDone()) {
            it.currentSegment(coords);
            count++;
            it.next();
        }
        return count;
    }

    private static void assertBounds(Shape shape, double x, double y, double w, double h) {
        Rectangle2D bounds = shape.getBounds2D();
        assertEquals(x, bounds.getX(), EPS, "bounds x");
        assertEquals(y, bounds.getY(), EPS, "bounds y");
        assertEquals(w, bounds.getWidth(), EPS, "bounds width");
        assertEquals(h, bounds.getHeight(), EPS, "bounds height");
    }

    // --- tests -------------------------------------------------------------

    @Test
    void emptyInputShapeProducesEmptyResult() {
        Shape result = squareStamp(2).createStrokedShape(new GeneralPath());

        assertTrue(result.getPathIterator(null).isDone(), "no segments expected");
        assertEquals(0, countSegments(result));
    }

    @Test
    void inputWithOnlyMoveToPlacesNoStamp() {
        GeneralPath input = new GeneralPath();
        input.moveTo(5, 5);

        Shape result = squareStamp(2).createStrokedShape(input);

        // Only the start point is emitted; no stamp can be positioned without a segment.
        assertEquals(1, countSegments(result));
        assertEquals(1, countSegments(result, PathIterator.SEG_MOVETO));
        assertBounds(result, 5, 5, 0, 0);
    }

    @Test
    void horizontalLinePlacesStampAtEachWholeUnit() {
        // Line of length 10 -> stamps centred at x = 0,1,...,10 (11 stamps).
        Shape result = squareStamp(2).createStrokedShape(line(0, 0, 10, 0));

        // Each stamp contributes one MOVETO. The bare MOVETO emitted for the input
        // start point is superseded by the first stamp (no drawing command in between),
        // so there are exactly 11 MOVETO segments for the 11 stamps.
        assertEquals(11, countSegments(result, PathIterator.SEG_MOVETO));

        // Stamps of 2x2 centred on [0..10]x{0}.
        assertBounds(result, -1, -1, 12, 2);

        // Area covered by the stamps is reported as inside; area beyond the end is not.
        assertTrue(result.contains(0, 0), "start stamp centre");
        assertTrue(result.contains(5, 0), "middle stamp centre");
        assertTrue(result.contains(10, 0), "end stamp centre");
        assertTrue(result.contains(5, 0.9), "inside stamp vertical extent");
        assertFalse(result.contains(5, 1.5), "outside stamp vertical extent");
        assertFalse(result.contains(12, 0), "beyond the end of the line");
    }

    @Test
    void fractionalLinePlacesOnlyWholeUnitStamps() {
        // Line of length 2.9 -> stamps centred at x = 0,1,2 (3 stamps), none at 3.
        Shape result = squareStamp(2).createStrokedShape(line(0, 0, 2.9f, 0));

        assertEquals(3, countSegments(result, PathIterator.SEG_MOVETO));
        // If a stamp were erroneously placed at 3, the width would be 5.
        assertBounds(result, -1, -1, 4, 2);
        assertTrue(result.contains(2, 0));
        assertFalse(result.contains(3.5, 0));
    }

    @Test
    void remainderCarriesOverBetweenPathSegments() {
        // (0,0)->(2,0)->(2,2): stamps at (0,0),(1,0),(2,0),(2,1),(2,2).
        GeneralPath input = new GeneralPath();
        input.moveTo(0, 0);
        input.lineTo(2, 0);
        input.lineTo(2, 2);

        Shape result = squareStamp(2).createStrokedShape(input);

        assertEquals(5, countSegments(result, PathIterator.SEG_MOVETO));
        assertBounds(result, -1, -1, 4, 4);
        assertTrue(result.contains(0, 0));
