 * distance along the outline of the supplied path, starting at distance 0.
 * These tests observe the resulting path structurally (number of sub-paths and
 * segment types) as well as through geometric queries (bounds and containment).
 */
class QuickDrawContextCreateStrokedShapeTests {

    private static final double EPS = 1e-3;

    // --- helpers -----------------------------------------------------------

    private static QuickDrawContext.RectangleStroke squareStamp(double size) {
        return new QuickDrawContext.RectangleStroke(new Rectangle2D.Double(0, 0, size, size));
    }

    private static GeneralPath line(float x0, float y0, float x1, float y1) {
        GeneralPath path = new GeneralPath();
        path.moveTo(x0, y0);
        path.lineTo(x1, y1);
        return path;
    }

    private static int countSegments(Shape shape, int segmentType) {
        PathIterator it = shape.getPathIterator(null);
        float[] coords = new float[6];
        int count = 0;
        while (!it.isDone()) {
            if (it.currentSegment(coords) == segmentType) {
                count++;
            }
            it.next();
        }
        return count;
    }

    private static int countSegments(Shape shape) {
        PathIterator it = shape.getPathIterator(null);
        float[] coords = new float[6];
        int count = 0;
        while (!it.isDone()) {
            it.currentSegment(coords);
            count++;
            it.next();
        }
        return count;
    }

    private static void assertBounds(Shape shape, double x, double y, double w, double h) {
        Rectangle2D bounds = shape.getBounds2D();
        assertEquals(x, bounds.getX(), EPS, "bounds x");
        assertEquals(y, bounds.getY(), EPS, "bounds y");
        assertEquals(w, bounds.getWidth(), EPS, "bounds width");
        assertEquals(h, bounds.getHeight(), EPS, "bounds height");
    }

