package com.twelvemonkeys.imageio.plugins.pnm;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageIO;
import javax.imageio.ImageReadParam;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.stream.ImageInputStream;
import java.awt.image.BufferedImage;
import java.awt.image.Raster;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

public class PNMImageReaderReadTests {

    private static byte[] concat(String header, int... body) {
        byte[] h = header.getBytes(StandardCharsets.US_ASCII);
        byte[] result = new byte[h.length + body.length];
        System.arraycopy(h, 0, result, 0, h.length);
        for (int i = 0; i < body.length; i++) {
            result[h.length + i] = (byte) body[i];
        }
        return result;
    }

    private static PNMImageReader reader(byte[] data) throws IOException {
        PNMImageReader reader = new PNMImageReader(null);
        ImageInputStream stream = ImageIO.createImageInputStream(new ByteArrayInputStream(data));
        reader.setInput(stream);
        return reader;
    }

    @Test
    public void probePgm() throws IOException {
        PNMImageReader reader = reader(concat("P5\n2 2\n255\n", 10, 20, 30, 40));
        BufferedImage image = reader.read(0, null);
        System.out.println("PGM type=" + image.getType() + " w=" + image.getWidth() + " h=" + image.getHeight());
        Raster r = image.getRaster();
        System.out.println("PGM samples=" + r.getSample(0,0,0) + "," + r.getSample(1,0,0) + "," + r.getSample(0,1,0) + "," + r.getSample(1,1,0));
        System.out.println("PGM rgb=" + Integer.toHexString(image.getRGB(0,0)) + "," + Integer.toHexString(image.getRGB(1,1)));
    }

    @Test
    public void probePpmDefault() throws IOException {
        PNMImageReader reader = reader(concat("P6\n2 1\n255\n", 10, 20, 30, 40, 50, 60));
        BufferedImage image = reader.read(0, null);
        System.out.println("PPM default type=" + image.getType() + " w=" + image.getWidth() + " h=" + image.getHeight());
        Raster r = image.getRaster();
        System.out.println("PPM default samples x0=" + r.getSample(0,0,0) + "," + r.getSample(0,0,1) + "," + r.getSample(0,0,2));
        System.out.println("PPM default samples x1=" + r.getSample(1,0,0) + "," + r.getSample(1,0,1) + "," + r.getSample(1,0,2));
        System.out.println("PPM default rgb=" + Integer.toHexString(image.getRGB(0,0)) + "," + Integer.toHexString(image.getRGB(1,0)));
    }

    @Test
    public void probePpmRaw() throws IOException {
        PNMImageReader reader = reader(concat("P6\n2 1\n255\n", 10, 20, 30, 40, 50, 60));
        ImageReadParam param = reader.getDefaultReadParam();
        ImageTypeSpecifier raw = reader.getRawImageType(0);
        param.setDestinationType(raw);
        BufferedImage image = reader.read(0, param);
        System.out.println("PPM raw type=" + image.getType() + " bands=" + image.getRaster().getNumBands());
        Raster r = image.getRaster();
        System.out.println("PPM raw samples x0=" + r.getSample(0,0,0) + "," + r.getSample(0,0,1) + "," + r.getSample(0,0,2));
        System.out.println("PPM raw samples x1=" + r.getSample(1,0,0) + "," + r.getSample(1,0,1) + "," + r.getSample(1,0,2));
        System.out.println("PPM raw rgb=" + Integer.toHexString(image.getRGB(0,0)) + "," + Integer.toHexString(image.getRGB(1,0)));
    }

    @Test
    public void probePamRgba() throws IOException {
        PNMImageReader reader = reader(concat("P7\nWIDTH 1\nHEIGHT 1\nDEPTH 4\nMAXVAL 255\nTUPLTYPE RGB_ALPHA\nENDHDR\n", 10, 20, 30, 40));
        BufferedImage image = reader.read(0, null);
        System.out.println("PAM rgba type=" + image.getType() + " bands=" + image.getRaster().getNumBands() + " premult=" + image.isAlphaPremultiplied());
        Raster r = image.getRaster();
        System.out.println("PAM rgba samples=" + r.getSample(0,0,0) + "," + r.getSample(0,0,1) + "," + r.getSample(0,0,2) + "," + r.getSample(0,0,3));
        System.out.println("PAM rgba rgb=" + Integer.toHexString(image.getRGB(0,0)));
    }

    @Test
    public void probePfm() throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.write("PF\n2 1\n1.0\n".getBytes(StandardCharsets.US_ASCII));
        writeFloatBE(out, 0.5f);
        writeFloatBE(out, 0.25f);
        writeFloatBE(out, 0.75f);
        writeFloatBE(out, 1.5f);
        writeFloatBE(out, -0.5f);
        writeFloatBE(out, 0.0f);
        PNMImageReader reader = reader(out.toByteArray());
        BufferedImage image = reader.read(0, null);
        System.out.println("PFM type=" + image.getType() + " bands=" + image.getRaster().getNumBands());
        Raster r = image.getRaster();
        for (int b = 0; b < r.getNumBands(); b++) {
            System.out.println("PFM band " + b + " x0=" + r.getSampleFloat(0,0,b) + " x1=" + r.getSampleFloat(1,0,b));
        }
    }

    private static void writeFloatBE(ByteArrayOutputStream out, float f) {
        int bits = Float.floatToIntBits(f);
        out.write((bits >>> 24) & 0xff);
        out.write((bits >>> 16) & 0xff);
        out.write((bits >>> 8) & 0xff);
        out.write(bits & 0xff);
    }
}
