    @Test
    public void readsBigEndianPfmGrayBottomUpAndClamps() throws IOException {
        PNMImageReader reader = newReader(pfm("Pf\n2 2\n1.0\n", false,
                -0.5f, 0.5f,    // first stored row becomes the bottom row
                0.25f, 1.5f));  // second stored row becomes the top row

        BufferedImage image = reader.read(0, null);

        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(1, image.getRaster().getNumBands());

        assertEquals(-0.5f, image.getRaster().getSampleFloat(0, 0 + 1, 0), 1e-6f);
        assertEquals(0.5f, image.getRaster().getSampleFloat(1, 0 + 1, 0), 1e-6f);

        assertEquals(0.25f, image.getRaster().getSampleFloat(0, 0, 0), 1e-6f);
        assertEquals(1.0f, image.getRaster().getSampleFloat(1, 0, 0), 1e-6f); // 1.5 clamped to 1.0
    }

    @Test
    public void readsLittleEndianPfmRgbBottomUpAndClamps() throws IOException {
        PNMImageReader reader = newReader(pfm("PF\n1 2\n-1.0\n", true,
                0.1f, 0.2f, 0.3f,
                1.1f, 0.4f, 0.5f));

        BufferedImage image = reader.read(0, null);

        assertEquals(1, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(3, image.getRaster().getNumBands());

        // First stored row is the bottom row
        assertEquals(0.1f, image.getRaster().getSampleFloat(0, 1, 0), 1e-6f);
        assertEquals(0.2f, image.getRaster().getSampleFloat(0, 1, 1), 1e-6f);
        assertEquals(0.3f, image.getRaster().getSampleFloat(0, 1, 2), 1e-6f);

        // Second stored row is the top row, and 1.1 is clamped
        assertEquals(1.0f, image.getRaster().getSampleFloat(0, 0, 0), 1e-6f);
        assertEquals(0.4f, image.getRaster().getSampleFloat(0, 0, 1), 1e-6f);
        assertEquals(0.5f, image.getRaster().getSampleFloat(0, 0, 2), 1e-6f);
    }

    @Test
    public void honorsSourceRegion() throws IOException {
        PNMImageReader reader = newReader(pnm("P6\n3 2\n255\n",
                10, 11, 12, 20, 21, 22, 30, 31, 32,
                40, 41, 42, 50, 51, 52, 60, 61, 62));

        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceRegion(new Rectangle(1, 1, 2, 1));

        BufferedImage image = reader.read(0, param);

        assertEquals(2, image.getWidth());
        assertEquals(1, image.getHeight());
        assertEquals(50, sample(image, 0, 0, 0));
        assertEquals(51, sample(image, 0, 0, 1));
        assertEquals(52, sample(image, 0, 0, 2));
        assertEquals(60, sample(image, 1, 0, 0));
        assertEquals(61, sample(image, 1, 0, 1));
        assertEquals(62, sample(image, 1, 0, 2));
    }

    @Test
    public void honorsSourceSubsampling() throws IOException {
        PNMImageReader reader = newReader(pnm("P6\n4 4\n255\n",
                1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4,
                5, 5, 5, 6, 6, 6, 7, 7, 7, 8, 8, 8,
                9, 9, 9, 10, 10, 10, 11, 11, 11, 12, 12, 12,
                13, 13, 13, 14, 14, 14, 15, 15, 15, 16, 16, 16));

        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceSubsampling(2, 2, 0, 0);

        BufferedImage image = reader.read(0, param);

        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(1, sample(image, 0, 0, 0));
        assertEquals(3, sample(image, 1, 0, 0));
        assertEquals(9, sample(image, 0, 1, 0));
        assertEquals(11, sample(image, 1, 1, 0));
    }

    @Test
    public void honorsDestinationOffsetAndReturnsProvidedDestination() throws IOException {
        PNMImageReader reader = newReader(pnm("P5\n2 1\n255\n", 10, 20));

        BufferedImage destination = new BufferedImage(4, 3, BufferedImage.TYPE_BYTE_GRAY);
        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestination(destination);
        param.setDestinationOffset(new Point(1, 1));

        BufferedImage image = reader.read(0, param);

        assertSame(destination, image);
        assertEquals(4, image.getWidth());
        assertEquals(3, image.getHeight());

        assertEquals(10, sample(image, 1, 1, 0));
        assertEquals(20, sample(image, 2, 1, 0));

        // Everything outside the destination region is left untouched
        assertEquals(0, sample(image, 0, 1, 0));
        assertEquals(0, sample(image, 1, 0, 0));
        assertEquals(0, sample(image, 3, 1, 0));
        assertEquals(0, sample(image, 1, 2, 0));
    }

    @Test
    public void abortStopsReadingAfterFirstRow() throws IOException {
        PNMImageReader reader = newReader(pnm("P5\n2 3\n255\n", 6, 7, 8, 9, 10, 11));

        final boolean[] started = {false};
        final boolean[] aborted = {false};
        reader.addIIOReadProgressListener(new IIOReadProgressListener() {
            @Override
            public void sequenceStarted(ImageReader source, int minIndex) {
            }

            @Override
            public void sequenceComplete(ImageReader source) {
            }

            @Override
            public void imageStarted(ImageReader source, int imageIndex) {
                started[0] = true;
            }

            @Override
            public void imageProgress(ImageReader source, float percentageDone) {
                source.abort();
            }

            @Override
            public void imageComplete(ImageReader source) {
            }

            @Override
            public void thumbnailStarted(ImageReader source, int imageIndex, int thumbnailIndex) {
            }

            @Override
            public void thumbnailProgress(ImageReader source, float percentageDone) {
            }

            @Override
            public void thumbnailComplete(ImageReader source) {
            }

            @Override
            public void readAborted(ImageReader source) {
                aborted[0] = true;
            }
        });

        BufferedImage image = reader.read(0, null);

        assertTrue(started[0], "imageStarted should have been fired");
        assertTrue(aborted[0], "read should have been aborted");
        assertEquals(6, sample(image, 0, 0, 0));
        assertEquals(7, sample(image, 1, 0, 0));
        assertEquals(0, sample(image, 0, 1, 0));
        assertEquals(0, sample(image, 0, 2, 0));
    }

    @Test
    public void throwsOnTruncatedInput() throws IOException {
        // Declares two complete rows, but provides only one and a half rows of data
        PNMImageReader reader = newReader(pnm("P5\n2 2\n255\n", 1, 2, 3));

        IOException exception = assertThrows(IOException.class, () -> reader.read(0, null));
        assertTrue(exception instanceof EOFException,
                "Expected an EOFException for truncated data, got: " + exception);
    }

    @Test
    public void rejectsImplausiblyLargeImageDimensions() throws IOException {
        PNMImageReader reader = newReader(pnm("P5\n100000 100000\n255\n", 0));

        IIOException exception = assertThrows(IIOException.class, () -> reader.read(0, null));
        assertTrue(exception.getMessage().contains("exceeding"), exception.getMessage());
    }

    @Test
    public void rejectsIncompatibleDestinationType() throws IOException {
        PNMImageReader reader = newReader(pnm("P5\n1 1\n255\n", 42));

        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestinationType(ImageTypeSpecifier.createFromBufferedImageType(BufferedImage.TYPE_3BYTE_BGR));

        assertThrows(IIOException.class, () -> reader.read(0, param));
    }

    @Test
    public void throwsForOutOfBoundsImageIndex() throws IOException {
        PNMImageReader reader = newReader(pnm("P5\n1 1\n255\n", 42));

        assertThrows(IndexOutOfBoundsException.class, () -> reader.read(1, null));
    }
}
