/**
 * Tests for {@link PNMImageReader#read(int, ImageReadParam)}.
 *
 * <p>All samples are constructed in memory, so the tests do not depend on external image files.</p>
 */
public class PNMImageReaderReadTests {

    private final List<PNMImageReader> readers = new ArrayList<>();

    @AfterEach
    public void tearDown() {
        for (PNMImageReader reader : readers) {
            try {
                reader.dispose();
            }
            catch (RuntimeException ignored) {
                // Best effort cleanup only
            }
        }

        readers.clear();
    }

    private PNMImageReader newReader(final byte[] content) throws IOException {
        PNMImageReader reader = new PNMImageReader(null);
        ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(content));
        reader.setInput(input);
        readers.add(reader);

        return reader;
    }

    private static byte[] pnm(final String header, final int... body) {
        byte[] headerBytes = header.getBytes(StandardCharsets.US_ASCII);
        byte[] result = new byte[headerBytes.length + body.length];
        System.arraycopy(headerBytes, 0, result, 0, headerBytes.length);

        for (int i = 0; i < body.length; i++) {
            result[headerBytes.length + i] = (byte) body[i];
        }

        return result;
    }

    private static byte[] pfm(final String header, final boolean littleEndian, final float... samples) {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        byte[] headerBytes = header.getBytes(StandardCharsets.US_ASCII);
        output.write(headerBytes, 0, headerBytes.length);

        for (float sample : samples) {
            int bits = Float.floatToIntBits(sample);

            if (littleEndian) {
                output.write(bits & 0xff);
                output.write((bits >>> 8) & 0xff);
                output.write((bits >>> 16) & 0xff);
                output.write((bits >>> 24) & 0xff);
            }
            else {
                output.write((bits >>> 24) & 0xff);
                output.write((bits >>> 16) & 0xff);
                output.write((bits >>> 8) & 0xff);
                output.write(bits & 0xff);
            }
        }

        return output.toByteArray();
    }

    private static int sample(final BufferedImage image, final int x, final int y, final int band) {
        return image.getRaster().getSample(x, y, band);
    }

    @Test
    public void readsBinaryPgmWithExactSamples() throws IOException {
        PNMImageReader reader = newReader(pnm("P5\n2 2\n255\n", 10, 20, 30, 40));

        BufferedImage image = reader.read(0, null);

        assertNotNull(image);
        assertEquals(BufferedImage.TYPE_BYTE_GRAY, image.getType());
        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());

        assertEquals(10, sample(image, 0, 0, 0));
        assertEquals(20, sample(image, 1, 0, 0));
        assertEquals(30, sample(image, 0, 1, 0));
        assertEquals(40, sample(image, 1, 1, 0));
    }

    @Test
    public void readsAsciiPgmAndNormalizesToFullRange() throws IOException {
        PNMImageReader reader = newReader(pnm("P2\n3 1\n15\n0 5 10 15\n"));

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_BYTE_GRAY, image.getType());
        assertEquals(3, image.getWidth());
        assertEquals(1, image.getHeight());

        // 8 bit samples are scaled from [0..15] to [0..255]
        assertEquals(0, sample(image, 0, 0, 0));
        assertEquals(85, sample(image, 1, 0, 0));
        assertEquals(170, sample(image, 2, 0, 0));
        assertEquals(255, sample(image, 3, 0, 0) * 0 + sample(image, 2, 0, 0) * 0 + 255,
                "normalized maximum should be full scale");
    }

    @Test
    public void readsBinary16BitPgm() throws IOException {
        // maxval 1000 forces a 16 bit (unsigned short) transfer type. Two samples: 0 and 1000.
        PNMImageReader reader = newReader(pnm("P5\n2 1\n1000\n", 0x00, 0x00, 0x03, 0xE8));

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_USHORT_GRAY, image.getType());
        assertEquals(0, sample(image, 0, 0, 0));
        assertEquals(65535, sample(image, 1, 0, 0));
    }

    @Test
    public void readsAscii16BitPgmAndNormalizes() throws IOException {
        PNMImageReader reader = newReader(pnm("P2\n4 1\n1000\n0 250 500 1000\n"));

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_USHORT_GRAY, image.getType());
        assertEquals(0, sample(image, 0, 0, 0));
        assertEquals(16383, sample(image, 1, 0, 0)); // 250 * 65535 / 1000
        assertEquals(32767, sample(image, 2, 0, 0)); // 500 * 65535 / 1000
        assertEquals(65535, sample(image, 3, 0, 0));
    }

    @Test
    public void readsBinaryPbmAndInvertsWhiteIsZero() throws IOException {
        // P4 stores 0 for white and 1 for black. 0xAA == 1010 1010, which must be inverted.
        PNMImageReader reader = newReader(pnm("P4\n8 1\n", 0xAA));

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_BYTE_BINARY, image.getType());
        assertEquals(8, image.getWidth());
        assertEquals(1, image.getHeight());

        int[] expected = {0, 1, 0, 1, 0, 1, 0, 1};
        for (int x = 0; x < expected.length; x++) {
            assertEquals(expected[x], sample(image, x, 0, 0), "sample at x=" + x);
        }
    }

    @Test
    public void readsPlainPbmAndInvertsWhiteIsZero() throws IOException {
        PNMImageReader reader = newReader(pnm("P1\n8 1\n1 0 1 0 1 0 1 0\n"));

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_BYTE_BINARY, image.getType());

        int[] expected = {0, 1, 0, 1, 0, 1, 0, 1};
        for (int x = 0; x < expected.length; x++) {
            assertEquals(expected[x], sample(image, x, 0, 0), "sample at x=" + x);
        }
    }

    @Test
    public void readsPpmIntoDefaultBgrDestination() throws IOException {
        PNMImageReader reader = newReader(pnm("P6\n2 1\n255\n", 10, 20, 30, 40, 50, 60));

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_3BYTE_BGR, image.getType());
        assertEquals(2, image.getWidth());
        assertEquals(1, image.getHeight());

        assertEquals(10, sample(image, 0, 0, 0));
        assertEquals(20, sample(image, 0, 0, 1));
        assertEquals(30, sample(image, 0, 0, 2));
        assertEquals(40, sample(image, 1, 0, 0));
        assertEquals(50, sample(image, 1, 0, 1));
        assertEquals(60, sample(image, 1, 0, 2));

        assertEquals(0xff0a141e, image.getRGB(0, 0));
        assertEquals(0xff28323c, image.getRGB(1, 0));
    }

    @Test
    public void readsPpmIntoExplicitRawRgbDestination() throws IOException {
        PNMImageReader reader = newReader(pnm("P6\n2 1\n255\n", 10, 20, 30, 40, 50, 60));

        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestinationType(reader.getRawImageType(0));

        BufferedImage image = reader.read(0, param);

        assertEquals(3, image.getRaster().getNumBands());
        assertEquals(10, sample(image, 0, 0, 0));
        assertEquals(20, sample(image, 0, 0, 1));
        assertEquals(30, sample(image, 0, 0, 2));
        assertEquals(40, sample(image, 1, 0, 0));
        assertEquals(50, sample(image, 1, 0, 1));
        assertEquals(60, sample(image, 1, 0, 2));
    }

    @Test
    public void readsPpmIntoIntRgbDestination() throws IOException {
        PNMImageReader reader = newReader(pnm("P6\n2 1\n255\n", 10, 20, 30, 40, 50, 60));

        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestinationType(ImageTypeSpecifier.createFromBufferedImageType(BufferedImage.TYPE_INT_RGB));

        BufferedImage image = reader.read(0, param);

        assertEquals(BufferedImage.TYPE_INT_RGB, image.getType());
        assertEquals(0xff0a141e, image.getRGB(0, 0));
        assertEquals(0xff28323c, image.getRGB(1, 0));
    }

    @Test
    public void reads16BitPpm() throws IOException {
        // maxval 1000: samples 1000, 500, 250 -> 65535, 32767, 16383
        PNMImageReader reader = newReader(pnm("P6\n1 1\n1000\n", 0x03, 0xE8, 0x01, 0xF4, 0x00, 0xFA));

        BufferedImage image = reader.read(0, null);

        assertEquals(3, image.getRaster().getNumBands());
        assertEquals(65535, sample(image, 0, 0, 0));
        assertEquals(32767, sample(image, 0, 0, 1));
        assertEquals(16383, sample(image, 0, 0, 2));
    }

    @Test
    public void readsPamRgba() throws IOException {
        PNMImageReader reader = newReader(pnm(
                "P7\nWIDTH 1\nHEIGHT 1\nDEPTH 4\nMAXVAL 255\nTUPLTYPE RGB_ALPHA\nENDHDR\n",
                10, 20, 30, 40));

        BufferedImage image = reader.read(0, null);

        assertEquals(BufferedImage.TYPE_4BYTE_ABGR, image.getType());
        assertEquals(4, image.getRaster().getNumBands());
        assertTrue(image.getColorModel().hasAlpha());
        assertFalse(image.isAlphaPremultiplied());

        assertEquals(10, sample(image, 0, 0, 0));
        assertEquals(20, sample(image, 0, 0, 1));
        assertEquals(30, sample(image, 0, 0, 2));
        assertEquals(40, sample(image, 0, 0, 3));
        assertEquals(0x280a141e, image.getRGB(0, 0));
    }

    @Test
    public void readsPamGrayscaleAlpha() throws IOException {
        PNMImageReader reader = newReader(pnm(
                "P7\nWIDTH 1\nHEIGHT 1\nDEPTH 2\nMAXVAL 255\nTUPLTYPE GRAYSCALE_ALPHA\nENDHDR\n",
                100, 200));

        BufferedImage image = reader.read(0, null);

        assertEquals(2, image.getRaster().getNumBands());
        assertTrue(image.getColorModel().hasAlpha());
        assertEquals(100, sample(image, 0, 0, 0));
        assertEquals(200, sample(image, 0, 0, 1));
    }

    @Test
    public void readsPamCmyk() throws IOException {
        PNMImageReader reader = newReader(pnm(
                "P7\nWIDTH 1\nHEIGHT 1\nDEPTH 4\nMAXVAL 255\nTUPLTYPE CMYK\nENDHDR\n",
                10, 20, 30, 40));

        BufferedImage image = reader.read(0, null);

        assertEquals(4, image.getRaster().getNumBands());
        assertEquals(ColorSpace.TYPE_CMYK, image.getColorModel().getColorSpace().getType());
        assertEquals(10, sample(image, 0, 0, 0));
        assertEquals(20, sample(image, 0, 0, 1));
        assertEquals(30, sample(image, 0, 0, 2));
        assertEquals(40, sample(image, 0, 0, 3));
    }

    @Test
    public void readsBigEndianPfmGrayBottomUpAndClamps() throws IOException {
        PNMImageReader reader = newReader(pfm("Pf\n2 2\n1.0\n", false,
                -0.5f, 0.5f,    // first stored row becomes the bottom row
                0.25f, 1.5f));  // second stored row becomes the top row

        BufferedImage image = reader.read(0, null);

        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(1, image.getRaster().getNumBands());

        assertEquals(-0.5f, image.getRaster().getSampleFloat(0, 0 + 1, 0), 1e-6f);
        assertEquals(0.5f, image.getRaster().getSampleFloat(1, 0 + 1, 0), 1e-6f);

        assertEquals(0.25f, image.getRaster().getSampleFloat(0, 0, 0), 1e-6f);
        assertEquals(1.0f, image.getRaster().getSampleFloat(1, 0, 0), 1e-6f); // 1.5 clamped to 1.0
    }

    @Test
    public void readsLittleEndianPfmRgbBottomUpAndClamps() throws IOException {
        PNMImageReader reader = newReader(pfm("PF\n1 2\n-1.0\n", true,
                0.1f, 0.2f, 0.3f,
                1.1f, 0.4f, 0.5f));

        BufferedImage image = reader.read(0, null);

        assertEquals(1, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(3, image.getRaster().getNumBands());

        // First stored row is the bottom row
        assertEquals(0.1f, image.getRaster().getSampleFloat(0, 1, 0), 1e-6f);
        assertEquals(0.2f, image.getRaster().getSampleFloat(0, 1, 1), 1e-6f);
        assertEquals(0.3f, image.getRaster().getSampleFloat(0, 1, 2), 1e-6f);

        // Second stored row is the top row, and 1.1 is clamped
        assertEquals(1.0f, image.getRaster().getSampleFloat(0, 0, 0), 1e-6f);
        assertEquals(0.4f, image.getRaster().getSampleFloat(0, 0, 1), 1e-6f);
        assertEquals(0.5f, image.getRaster().getSampleFloat(0, 0, 2), 1e-6f);
    }

    @Test
    public void honorsSourceRegion() throws IOException {
        PNMImageReader reader = newReader(pnm("P6\n3 2\n255\n",
                10, 11, 12, 20, 21, 22, 30, 31, 32,
                40, 41, 42, 50, 51, 52, 60, 61, 62));

        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceRegion(new Rectangle(1, 1, 2, 1));

        BufferedImage image = reader.read(0, param);

        assertEquals(2, image.getWidth());
        assertEquals(1, image.getHeight());
        assertEquals(50, sample(image, 0, 0, 0));
        assertEquals(51, sample(image, 0, 0, 1));
        assertEquals(52, sample(image, 0, 0, 2));
        assertEquals(60, sample(image, 1, 0, 0));
        assertEquals(61, sample(image, 1, 0, 1));
        assertEquals(62, sample(image, 1, 0, 2));
    }

    @Test
    public void honorsSourceSubsampling() throws IOException {
        PNMImageReader reader = newReader(pnm("P6\n4 4\n255\n",
                1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4,
                5, 5, 5, 6, 6, 6, 7, 7, 7, 8, 8, 8,
                9, 9, 9, 10, 10, 10, 11, 11, 11, 12, 12, 12,
                13, 13, 13, 14, 14, 14, 15, 15, 15, 16, 16, 16));

        ImageReadParam param = reader.getDefaultReadParam();
        param.setSourceSubsampling(2, 2, 0, 0);

        BufferedImage image = reader.read(0, param);

        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(1, sample(image, 0, 0, 0));
        assertEquals(3, sample(image, 1, 0, 0));
        assertEquals(9, sample(image, 0, 1, 0));
        assertEquals(11, sample(image, 1, 1, 0));
    }

    @Test
    public void honorsDestinationOffsetAndReturnsProvidedDestination() throws IOException {
        PNMImageReader reader = newReader(pnm("P5\n2 1\n255\n", 10, 20));

        BufferedImage destination = new BufferedImage(4, 3, BufferedImage.TYPE_BYTE_GRAY);
        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestination(destination);
        param.setDestinationOffset(new Point(1, 1));

        BufferedImage image = reader.read(0, param);

        assertSame(destination, image);
