/**
 * Tests for {@link PNMImageReader#read(int, ImageReadParam)}.
 *
 * <p>All samples are constructed in memory, so the tests do not depend on external image files.</p>
 */
public class PNMImageReaderReadTests {

    private final List<PNMImageReader> readers = new ArrayList<>();

    @AfterEach
    public void tearDown() {
        for (PNMImageReader reader : readers) {
            try {
                reader.dispose();
            }
            catch (RuntimeException ignored) {
                // Best effort cleanup only
            }
        }

        readers.clear();
    }

    private PNMImageReader newReader(final byte[] content) throws IOException {
        PNMImageReader reader = new PNMImageReader(null);
        ImageInputStream input = new MemoryCacheImageInputStream(new ByteArrayInputStream(content));
        reader.setInput(input);
        readers.add(reader);

        return reader;
    }

    private static byte[] pnm(final String header, final int... body) {
        byte[] headerBytes = header.getBytes(StandardCharsets.US_ASCII);
        byte[] result = new byte[headerBytes.length + body.length];
        System.arraycopy(headerBytes, 0, result, 0, headerBytes.length);

        for (int i = 0; i < body.length; i++) {
            result[headerBytes.length + i] = (byte) body[i];
        }

        return result;
    }

    private static byte[] pfm(final String header, final boolean littleEndian, final float... samples) {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        byte[] headerBytes = header.getBytes(StandardCharsets.US_ASCII);
        output.write(headerBytes, 0, headerBytes.length);

        for (float sample : samples) {
            int bits = Float.floatToIntBits(sample);

            if (littleEndian) {
                output.write(bits & 0xff);
                output.write((bits >>> 8) & 0xff);
                output.write((bits >>> 16) & 0xff);
                output.write((bits >>> 24) & 0xff);
            }
            else {
                output.write((bits >>> 24) & 0xff);
                output.write((bits >>> 16) & 0xff);
                output.write((bits >>> 8) & 0xff);
                output.write(bits & 0xff);
            }
        }

        return output.toByteArray();
    }

    private static int sample(final BufferedImage image, final int x, final int y, final int band) {
        return image.getRaster().getSample(x, y, band);
    }

    @Test
    public void readsBinaryPgmWithExactSamples() throws IOException {
        PNMImageReader reader = newReader(pnm("P5\n2 2\n255\n", 10, 20, 30, 40));

        BufferedImage image = reader.read(0, null);

        assertNotNull(image);
        assertEquals(BufferedImage.TYPE_BYTE_GRAY, image.getType());
        assertEquals(2, image.getWidth());
        assertEquals(2, image.getHeight());

        assertEquals(10, sample(image, 0, 0, 0));
        assertEquals(20, sample(image, 1, 0, 0));
        assertEquals(30, sample(image, 0, 1, 0));
        assertEquals(40, sample(image, 1, 1, 0));
    }

