    @Test
    public void testReadTruncatedInputThrowsEof() throws IOException {
        byte[] full = validHeader(PSD.VERSION_PSD);
        assertEquals(HEADER_SIZE, full.length);

        for (int length = 0; length < HEADER_SIZE; length++) {
            byte[] truncated = new byte[length];
            System.arraycopy(full, 0, truncated, 0, length);

            assertThrows(EOFException.class, () -> read(truncated),
                    "Truncated header of " + length + " bytes should throw EOFException");
        }
    }

