import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests the package private {@code PSDHeader.read(DataInput)} method.
 * <p>
 * All tests build the 26 byte PSD/PSB file header in memory and feed it to the
 * method under test, so no external resources are needed.
 */
public class PSDHeaderReadTests {

    /** Total size of the PSD header, in bytes. */
    private static final int HEADER_SIZE = 26;

    // -----------------------------------------------------------------------
    // Helpers
    // -----------------------------------------------------------------------

    /**
     * Builds a complete PSD header.
     *
     * @param signature the 4 byte file signature, usually "8BPS"
     * @param version the version number, 1 (PSD) or 2 (PSB)
     * @param channels number of channels (1 - 56)
     * @param height image height, aka rows
     * @param width image width, aka columns
     * @param bits bits per channel
     * @param mode the color mode
     * @return the header, as a byte array
     */
    private static byte[] header(int signature, int version, int channels, int height, int width, int bits, int mode) {
        return header(signature, version, new byte[6], channels, height, width, bits, mode, new byte[0]);
    }

    /**
     * Builds a complete PSD header, with controllable reserved bytes and optional trailing data.
     */
    private static byte[] header(int signature, int version, byte[] reserved, int channels, int height, int width,
                                 int bits, int mode, byte[] trailer) {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream(HEADER_SIZE + trailer.length);

        try (DataOutputStream out = new DataOutputStream(bytes)) {
            out.writeInt(signature);
            out.writeShort(version);
            out.write(reserved, 0, 6);
            out.writeShort(channels);
            out.writeInt(height);
            out.writeInt(width);
            out.writeShort(bits);
            out.writeShort(mode);
            out.write(trailer);
            out.flush();
        }
        catch (IOException e) {
            throw new AssertionError("Unexpected failure creating test data", e);
        }

        return bytes.toByteArray();
    }

    /**
     * Builds a header with a valid signature.
     */
    private static byte[] header(int version, int channels, int height, int width, int bits, int mode) {
        return header(PSD.SIGNATURE_8BPS, version, channels, height, width, bits, mode);
    }

    /**
     * Builds a well formed header for the given version, using sane defaults for all other fields.
     */
    private static byte[] validHeader(int version) {
        return header(version, 3, 200, 300, 8, PSD.COLOR_MODE_RGB);
    }

    private static DataInputStream stream(byte[] data) {
        return new DataInputStream(new ByteArrayInputStream(data));
    }

    private static PSDHeader read(byte[] data) throws IOException {
        return PSDHeader.read(stream(data));
    }

