                () -> assertEquals(1, min.width),
                () -> assertEquals(1, min.height),
                () -> assertTrue(min.hasValidDimensions())
        );
    }

    @Test
    public void testReadDimensionBoundariesForPsb() throws IOException {
        // 300000 x 300000 is the largest allowed PSB image
        PSDHeader max = read(header(PSD.VERSION_PSB, 4, PSDHeader.PSB_MAX_SIZE, PSDHeader.PSB_MAX_SIZE, 32, PSD.COLOR_MODE_RGB));
        assertAll(
                () -> assertEquals(PSDHeader.PSB_MAX_SIZE, max.width),
                () -> assertEquals(PSDHeader.PSB_MAX_SIZE, max.height),
                () -> assertTrue(max.hasValidDimensions()),
                () -> assertTrue(max.largeFormat)
        );

        // Dimensions that are too large for PSD are still fine for PSB
        PSDHeader psbOnly = read(header(PSD.VERSION_PSB, 3, PSDHeader.PSD_MAX_SIZE + 1, PSDHeader.PSD_MAX_SIZE + 1, 8, PSD.COLOR_MODE_RGB));
        assertAll(
                () -> assertEquals(PSDHeader.PSD_MAX_SIZE + 1, psbOnly.width),
                () -> assertEquals(PSDHeader.PSD_MAX_SIZE + 1, psbOnly.height),
                () -> assertTrue(psbOnly.hasValidDimensions())
        );
    }

    @Test
    public void testReadToStringReflectsHeader() throws IOException {
        String psd = read(validHeader(PSD.VERSION_PSD)).toString();
        assertTrue(psd.contains("version: 1"), psd);
        assertTrue(psd.contains("channels: 3"), psd);
        assertTrue(psd.contains("width: 300"), psd);
        assertTrue(psd.contains("height: 200"), psd);
        assertTrue(psd.contains("depth: 8"), psd);
        assertTrue(psd.contains("RGB"), psd);

        String psb = read(validHeader(PSD.VERSION_PSB)).toString();
        assertTrue(psb.contains("version: 2"), psb);
        assertTrue(psb.contains("RGB"), psb);
    }

