    @Test
    public void testReadInvalidSignature() {
        int signature = ('8' << 24) + ('B' << 16) + ('P' << 8) + 'X'; // "8BPX"

        IIOException exception = assertThrows(IIOException.class, () -> read(header(signature, PSD.VERSION_PSD, 3, 200, 300, 8, PSD.COLOR_MODE_RGB)));

        String message = exception.getMessage();
        assertNotNull(message);
        assertAll(
                () -> assertTrue(message.contains("Not a PSD document"), message),
                () -> assertTrue(message.contains("\"8BPX\""), message),
                () -> assertTrue(message.contains("0x38425058"), message)
        );
    }

    @Test
    public void testReadInvalidSignatureIsDetectedBeforeVersion() {
        // Even though the version is bogus too, the signature check must happen first
        IIOException exception = assertThrows(IIOException.class, () -> read(header(0x00000000, 42, 3, 200, 300, 8, PSD.COLOR_MODE_RGB)));
        assertTrue(exception.getMessage().contains("Not a PSD document"), exception.getMessage());
    }

    // -----------------------------------------------------------------------
    // Invalid version
    // -----------------------------------------------------------------------

    @Test
    public void testReadInvalidVersion() {
        int[] invalidVersions = {0, 3, 4, 0xFF, 0xFFFF};

        for (int version : invalidVersions) {
            IIOException exception = assertThrows(IIOException.class,
                    () -> read(header(PSD.SIGNATURE_8BPS, version, 3, 200, 300, 8, PSD.COLOR_MODE_RGB)),
                    "Version " + version + " should be rejected");

            String message = exception.getMessage();
            assertNotNull(message);
            assertTrue(message.contains("Unknown PSD version"), message);
            assertTrue(message.contains(String.format("0x%08x", version)), message);
        }
    }

