    @Test
    public void testReadInvalidChannelCount() {
        // 0, 57 and values that do not fit in an unsigned/signed short (read as short)
        short[] invalidChannels = {0, 57, 100, -1, Short.MAX_VALUE, Short.MIN_VALUE};

        for (short channels : invalidChannels) {
            IIOException exception = assertThrows(IIOException.class,
                    () -> read(header(PSD.VERSION_PSD, channels, 200, 300, 8, PSD.COLOR_MODE_RGB)),
                    "Channels " + channels + " should be rejected");

            String message = exception.getMessage();
            assertNotNull(message);
            assertTrue(message.contains("Unsupported number of channels for PSD"), message);
            assertTrue(message.endsWith(": " + channels), message);
        }
