    @Test
    public void testReadUnsignedShortChannelValueIsReadAsSignedShort() {
        // 0xFFFF in the channel field is read as -1 by DataInput.readShort()
        byte[] data = header(PSD.VERSION_PSD, -1, 200, 300, 8, PSD.COLOR_MODE_RGB);

        IIOException exception = assertThrows(IIOException.class, () -> read(data));
        assertTrue(exception.getMessage().endsWith(": -1"), exception.getMessage());
