    private long readLength(final ImageInputStream stream) throws IOException {
        return header.largeFormat
               ? validatePositiveLength(stream.readLong())
               : stream.readUnsignedInt();
    }

    private long readLength(final ImageInputStream stream, final int resId) throws IOException {
        // Only the following resources use long (64 bit) lengths:
        // LMsk, Lr16, Lr32, Layr, Mt16, Mt32, Mtrn, Alph, FMsk, lnk2, FEid, FXid, PxSD
        if (header.largeFormat) {
            switch (resId) {
                case PSD.LMsk:
                case PSD.Lr16:
                case PSD.Lr32:
                case PSD.Layr:
                case PSD.Mt16:
                case PSD.Mt32:
                case PSD.Mtrn:
                case PSD.Alph:
                case PSD.FMsk:
                case PSD.lnk2:
                case PSD.FEid:
                case PSD.FXid:
                case PSD.PxSD:
                    return validatePositiveLength(stream.readLong());
                default:
                    // Fall through to 32 bit length
            }
        }

        return stream.readUnsignedInt();
    }

    static long validatePositiveLength(long value) throws IIOException {
        if (value < 0) {
            throw new IIOException(String.format("Length field exceeds Long.MAX_VALUE: %s", Long.toUnsignedString(value)));
        }

        return value;
    }

    private List<PSDLayerInfo> readLayerInfo(int layerCount) throws IOException {
        if (layerCount > 8000) {
            processWarningOccurred("Bad layer count for PSD, expected <= 8000: " + layerCount);
        }

        PSDLayerInfo[] layerInfos = new PSDLayerInfo[Math.min(8000, layerCount)];

        Stack<List<PSDLayerInfo>> groupStack = new Stack<>();
        List<PSDLayerInfo> currentGroup = Collections.emptyList();

        for (int i = 0; i < layerInfos.length; i++) {
            PSDLayerInfo layerInfo = new PSDLayerInfo(header.largeFormat, imageInput);
            layerInfos[i] = layerInfo;

            if (layerInfo.isDivider) {
                groupStack.push(currentGroup);
                currentGroup = new ArrayList<>();
            }
            else if (layerInfo.isGroup) {
                for (PSDLayerInfo info : currentGroup) {
                    info.groupId = layerInfo.getLayerId();
                }

                currentGroup = groupStack.pop();
            }

            if (currentGroup != Collections.EMPTY_LIST) {
                currentGroup.add(layerInfo);
            }
        }

        return Arrays.asList(layerInfos);
    }

