    private static PSDImageReader createReader(int channels, int bits, int mode, boolean hasAlpha) throws Exception {
        PSDImageReader reader = new PSDImageReader(null);
        reader.setInput(new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0])));

        PSDHeader header = new PSDHeader(channels, 1, 1, bits, mode, false);

        PSDMetadata metadata = new PSDMetadata();
        metadata.header = header;
        // A negative layer count means the composite image has a separate alpha channel.
        metadata.layerCount = hasAlpha ? -1 : 0;
        // Pre-populate the parsed sections so getNumImages()/getEmbeddedColorSpace() don't parse input.
        metadata.imageResources = Collections.emptyList();
        metadata.layerAndMaskInfoStart = 1L;
        metadata.imageDataStart = 1L;

        setField(reader, "header", header);
        setField(reader, "metadata", metadata);

        return reader;
    }

    private static void setColorSpace(PSDImageReader reader, ColorSpace colorSpace) throws Exception {
        setField(reader, "colorSpace", colorSpace);
    }

    private static void setField(PSDImageReader reader, String name, Object value) throws Exception {
        Field field = PSDImageReader.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(reader, value);
    }

    private static List<ImageTypeSpecifier> getTypes(PSDImageReader reader, int imageIndex) throws Exception {
        Iterator<ImageTypeSpecifier> iterator = reader.getImageTypes(imageIndex);

        List<ImageTypeSpecifier> types = new ArrayList<>();
        while (iterator.hasNext()) {
            types.add(iterator.next());
        }

        return types;
    }

    private static void assertRawTypeIsLast(PSDImageReader reader, List<ImageTypeSpecifier> types) throws Exception {
        assertFalse(types.isEmpty());
        assertEquals(reader.getRawImageType(0), types.get(types.size() - 1));
    }

    private static void assertType(ImageTypeSpecifier type, int bands, int bitsPerBand, int dataType, boolean alpha) {
        assertEquals(bands, type.getNumBands());
        assertEquals(bitsPerBand, type.getBitsPerBand(0));
        assertEquals(dataType, type.getSampleModel().getDataType());
        assertEquals(alpha, type.getColorModel().hasAlpha());
    }

    private static void assertBandOffsets(ImageTypeSpecifier type, int... expectedOffsets) {
        assertTrue(type.getSampleModel() instanceof ComponentSampleModel,
                "Expected a ComponentSampleModel for interleaved/banded type");
        assertArrayEquals(expectedOffsets, ((ComponentSampleModel) type.getSampleModel()).getBandOffsets());
    }
}
