package com.twelvemonkeys.imageio.plugins.psd;

import com.twelvemonkeys.imageio.metadata.Directory;

import javax.imageio.IIOException;
import javax.imageio.stream.ImageInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;

/**
 * PSDDirectoryResource
 */
abstract class PSDDirectoryResource extends PSDImageResource {
    // Safeguard for streams of unknown length, XMP data written by Photoshop may be megabytes
    private static final int MAX_SIZE_UNKNOWN_LENGTH = 64 * 1024 * 1024;

    byte[] data;
    private Directory directory;

    PSDDirectoryResource(short resourceId, ImageInputStream input) throws IOException {
        super(resourceId, input);
    }

    @Override
    protected void readData(final ImageInputStream pInput) throws IOException {
        long limit = pInput.length() < 0 ? MAX_SIZE_UNKNOWN_LENGTH : pInput.length() - pInput.getStreamPosition();

        if (size > Integer.MAX_VALUE || size > limit) {
            throw new IIOException(String.format("PSD Resource size exceeds limit (%d): %d", limit, size));
        }

        data = new byte[(int) size];
        pInput.readFully(data);
    }

    abstract Directory parseDirectory() throws IOException;

    final void initDirectory() throws IOException {
        if (directory == null) {
            directory = parseDirectory();
        }
    }

    Directory getDirectory() {
        return directory;
    }

    @Override
    public String toString() {
        StringBuilder builder = toStringBuilder();

        if (directory != null) {
            builder.append(", ").append(directory);
            builder.append("]");
        }
        else {
            int length = Math.min(256, data.length);
            String data = new String(this.data, 0, length, StandardCharsets.US_ASCII)
                                  .replace('\uFFFD', '.')
                                  .replaceAll("\\s+", " ")
                                  .replaceAll("[^\\p{Print}]", ".");
            builder.append(", data: \"").append(data);

            if (length < this.data.length) {
                builder.append("...");
            }

            builder.append("\"]");
        }

        return builder.toString();
    }
}
