/**
 * Tests for {@link PSDImageResource#read(ImageInputStream)}.
 * <p>
 * The tests build the on-disk image resource block layout:
 * <pre>
 * 4 bytes resource type / signature (for example "8BIM")
 * 2 bytes resource id
 * n bytes Pascal string name (length byte + characters + optional pad byte)
 * 4 bytes data size (unsigned)
 * n bytes data
 * 0-1 byte even-padding
 * </pre>
 */
class PSDImageResourceReadTests {

    private static final int UNKNOWN_ID = 0x1234;

    @Test
    void readDispatchesResolutionInfo() throws IOException {
        byte[] data = new DataBuilder()
                .writeInt(0x00480000) // 72.0 fixed point
                .writeShort(1)        // pixels per inch
                .writeShort(1)        // inches
                .writeInt(0x00480000) // 72.0 fixed point
                .writeShort(1)
                .writeShort(1)
                .toByteArray();

        PSDImageResource resource = read(resource(PSD.RESOURCE_TYPE, (short) PSD.RES_RESOLUTION_INFO, "", data));

        assertSame(PSDResolutionInfo.class, resource.getClass());
        assertEquals((short) PSD.RES_RESOLUTION_INFO, resource.id);
        assertEquals(16, resource.size);

        PSDResolutionInfo info = (PSDResolutionInfo) resource;
        assertEquals(72.0f, info.hRes, 0.0001f);
        assertEquals(1, info.hResUnit);
        assertEquals(1, info.widthUnit);
        assertEquals(72.0f, info.vRes, 0.0001f);
        assertEquals(1, info.vResUnit);
        assertEquals(1, info.heightUnit);
    }

