        assertSame(PSDAlphaChannelInfo.class, resource.getClass());
        assertEquals((short) PSD.RES_ALPHA_CHANNEL_INFO, resource.id);

        List<String> names = ((PSDAlphaChannelInfo) resource).names;
        assertNotNull(names);
        assertEquals(1, names.size());
        assertEquals("Alpha", names.get(0));
    }

