    private static byte[] resource(int type, short id, String name, byte[] data) throws IOException {
        DataBuilder builder = new DataBuilder()
                .writeInt(type)
                .writeShort(id & 0xffff);

        byte[] nameBytes = name.getBytes(StandardCharsets.US_ASCII);
        builder.writeByte(nameBytes.length).write(nameBytes);
        if ((nameBytes.length + 1) % 2 != 0) {
            builder.writeByte(0);
        }

        builder.writeInt(data.length).write(data);
        if (data.length % 2 != 0) {
            builder.writeByte(0);
        }

        return builder.toByteArray();
    }

    private static byte[] concat(byte[] first, byte[] second) {
        byte[] result = new byte[first.length + second.length];
        System.arraycopy(first, 0, result, 0, first.length);
        System.arraycopy(second, 0, result, first.length, second.length);
        return result;
    }

    private static final class DataBuilder {
        private final ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        private final DataOutputStream output = new DataOutputStream(buffer);

        DataBuilder writeByte(int value) throws IOException {
            output.writeByte(value);
            return this;
        }

        DataBuilder writeShort(int value) throws IOException {
            output.writeShort(value);
            return this;
        }

        DataBuilder writeInt(int value) throws IOException {
            output.writeInt(value);
            return this;
        }

        DataBuilder writeBoolean(boolean value) throws IOException {
            output.writeBoolean(value);
            return this;
        }

        DataBuilder writeFloat(float value) throws IOException {
            output.writeFloat(value);
            return this;
        }

        DataBuilder writeDouble(double value) throws IOException {
            output.writeDouble(value);
            return this;
        }

        DataBuilder write(byte[] value) throws IOException {
            output.write(value);
            return this;
        }

        byte[] toByteArray() throws IOException {
            output.flush();
            return buffer.toByteArray();
        }
    }
