    @Test
    void writeWithoutOutputThrowsIllegalStateException() {
        PSDImageWriter writer = new PSDImageWriter(new PSDImageWriterSpi());
        BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_INT_RGB);

        IllegalStateException exception = assertThrows(
                IllegalStateException.class,
                () -> writer.write(null, new IIOImage(image, null, null), null)
        );

        assertTrue(exception.getMessage().contains("getOutput() == null"));
    }

    @Test
    void writeRgbImageWritesPsdHeaderAndPlanarPixels() throws IOException {
        BufferedImage image = new BufferedImage(2, 2, BufferedImage.TYPE_INT_RGB);
        image.setRGB(0, 0, 0x123456);
        image.setRGB(1, 0, 0xAABBCC);
        image.setRGB(0, 1, 0x010203);
        image.setRGB(1, 1, 0xFFFFFF);

        PSDOutput output = PSDOutput.parse(write(image, null));

        assertEquals(PSD.SIGNATURE_8BPS, output.signature);
        assertEquals(PSD.VERSION_PSD, output.version);
        assertEquals(3, output.channels);
        assertEquals(2, output.width);
        assertEquals(2, output.height);
        assertEquals(8, output.bits);
        assertEquals(PSD.COLOR_MODE_RGB, output.mode);
        assertEquals(0, output.colorModeDataLength);
        assertTrue(output.imageResourcesLength > 0);
        assertEquals(0L, output.layerMaskLength);
        assertEquals(PSD.COMPRESSION_NONE, output.compression);
        assertEquals(0, output.byteCounts.length);
        assertArrayEquals(
                new byte[] {
                        0x12, (byte) 0xAA, 0x01, (byte) 0xFF,
                        0x34, (byte) 0xBB, 0x02, (byte) 0xFF,
                        0x56, (byte) 0xCC, 0x03, (byte) 0xFF
                },
                output.imageData()
        );
    }

    @Test
    void writeRleImageWritesPerScanlineByteCountsAndDecodableRows() throws IOException {
        BufferedImage image = new BufferedImage(3, 2, BufferedImage.TYPE_INT_ARGB);
        image.setRGB(0, 0, 0xFF102030);
        image.setRGB(1, 0, 0x80112233);
        image.setRGB(2, 0, 0x00445566);
        image.setRGB(0, 1, 0xFFFFFFFF);
        image.setRGB(1, 1, 0x00000000);
        image.setRGB(2, 1, 0x7F123456);

        PSDImageWriteParam param = new PSDImageWriteParam(Locale.ROOT);
        param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
        param.setCompressionType("PackBits");

        PSDOutput output = PSDOutput.parse(write(image, param));

        assertEquals(PSD.VERSION_PSD, output.version);
        assertEquals(4, output.channels);
        assertEquals(8, output.bits);
        assertEquals(PSD.COLOR_MODE_RGB, output.mode);
        assertEquals(PSD.COMPRESSION_RLE, output.compression);
        assertEquals(8, output.byteCounts.length);

        byte[] expectedPlanarRows = new byte[] {
                0x10, 0x11, 0x44, (byte) 0xFF, 0x00, 0x12,
                0x20, 0x22, 0x55, (byte) 0xFF, 0x00, 0x34,
                0x30, 0x33, 0x66, (byte) 0xFF, 0x00, 0x56,
                (byte) 0xFF, (byte) 0x80, 0x00, (byte) 0xFF, 0x00, 0x7F
        };

        ByteArrayOutputStream decoded = new ByteArrayOutputStream();
        int position = output.imageDataOffset;
        for (int count : output.byteCounts) {
            assertTrue(count > 0, "Every encoded scanline should contain data");
            decoded.write(decodePackBits(Arrays.copyOfRange(output.bytes, position, position + count)));
            position += count;
        }

        assertEquals(output.bytes.length, position, "Byte counts should cover all remaining image data");
        assertArrayEquals(expectedPlanarRows, decoded.toByteArray());
    }

