    private static BufferedImage createComponentImage(ColorSpace colorSpace, int transferType, int width, int height) {
        ColorModel colorModel = new ComponentColorModel(
                colorSpace, false, false, Transparency.OPAQUE, transferType
        );
        WritableRaster raster = colorModel.createCompatibleWritableRaster(width, height);
        return new BufferedImage(colorModel, raster, false, null);
    }

    private static byte[] write(RenderedImage image, ImageWriteParam param) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ImageOutputStream output = new MemoryCacheImageOutputStream(bytes)) {
            PSDImageWriter writer = new PSDImageWriter(new PSDImageWriterSpi());
            writer.setOutput(output);
            output.setByteOrder(ByteOrder.LITTLE_ENDIAN);
            writer.write(null, new IIOImage(image, null, null), param);
            output.flush();
        }
        return bytes.toByteArray();
    }

    private static byte[] decodePackBits(byte[] encoded) {
        ByteArrayOutputStream decoded = new ByteArrayOutputStream();
        for (int i = 0; i < encoded.length; ) {
            int header = encoded[i++];
            if (header >= 0) {
                int count = header + 1;
                decoded.write(encoded, i, count);
                i += count;
            }
            else if (header != -128) {
                int count = 1 - header;
                byte value = encoded[i++];
                for (int j = 0; j < count; j++) {
                    decoded.write(value);
                }
            }
        }
        return decoded.toByteArray();
    }

    private static final class PSDOutput {
        final byte[] bytes;
        final int signature;
        final int version;
        final int channels;
        final int width;
        final int height;
        final int bits;
        final int mode;
        final int colorModeDataOffset;
        final int colorModeDataLength;
        final int imageResourcesOffset;
        final int imageResourcesLength;
        final int layerMaskLengthOffset;
        final long layerMaskLength;
        final int compression;
        final int[] byteCounts;
        final int imageDataOffset;

        private PSDOutput(
                byte[] bytes,
                int signature,
                int version,
                int channels,
                int width,
                int height,
                int bits,
                int mode,
                int colorModeDataOffset,
                int colorModeDataLength,
                int imageResourcesOffset,
                int imageResourcesLength,
                int layerMaskLengthOffset,
                long layerMaskLength,
                int compression,
                int[] byteCounts,
                int imageDataOffset
        ) {
            this.bytes = bytes;
            this.signature = signature;
            this.version = version;
            this.channels = channels;
            this.width = width;
            this.height = height;
            this.bits = bits;
            this.mode = mode;
            this.colorModeDataOffset = colorModeDataOffset;
            this.colorModeDataLength = colorModeDataLength;
            this.imageResourcesOffset = imageResourcesOffset;
            this.imageResourcesLength = imageResourcesLength;
            this.layerMaskLengthOffset = layerMaskLengthOffset;
            this.layerMaskLength = layerMaskLength;
            this.compression = compression;
            this.byteCounts = byteCounts;
            this.imageDataOffset = imageDataOffset;
        }

        static PSDOutput parse(byte[] bytes) {
            ByteBuffer input = ByteBuffer.wrap(bytes).order(ByteOrder.BIG_ENDIAN);

            int signature = input.getInt();
            int version = input.getShort() & 0xffff;
            input.position(input.position() + 6);
            int channels = input.getShort() & 0xffff;
            int height = input.getInt();
            int width = input.getInt();
            int bits = input.getShort() & 0xffff;
            int mode = input.getShort() & 0xffff;

            int colorModeDataOffset = input.position();
            int colorModeDataLength = input.getInt();
            input.position(input.position() + colorModeDataLength);

            int imageResourcesOffset = input.position();
            int imageResourcesLength = input.getInt();
            input.position(input.position() + imageResourcesLength);

            int layerMaskLengthOffset = input.position();
            long layerMaskLength = version == PSD.VERSION_PSB
                                  ? input.getLong()
                                  : Integer.toUnsignedLong(input.getInt());
            input.position(input.position() + (int) layerMaskLength);

            int compression = input.getShort() & 0xffff;
            int[] byteCounts = new int[0];
            if (compression == PSD.COMPRESSION_RLE) {
                byteCounts = new int[height * channels];
                for (int i = 0; i < byteCounts.length; i++) {
                    byteCounts[i] = version == PSD.VERSION_PSB
                                    ? input.getInt()
                                    : input.getShort() & 0xffff;
                }
            }

            return new PSDOutput(
                    bytes, signature, version, channels, width, height, bits, mode,
                    colorModeDataOffset, colorModeDataLength,
                    imageResourcesOffset, imageResourcesLength,
                    layerMaskLengthOffset, layerMaskLength,
                    compression, byteCounts, input.position()
            );
        }

        byte[] colorModeData() {
            return Arrays.copyOfRange(bytes, colorModeDataOffset, colorModeDataOffset + colorModeDataLength);
        }

        byte[] layerMaskLengthBytes() {
            int length = version == PSD.VERSION_PSB ? 8 : 4;
            return Arrays.copyOfRange(bytes, layerMaskLengthOffset, layerMaskLengthOffset + length);
        }

        byte[] imageData() {
            return Arrays.copyOfRange(bytes, imageDataOffset, bytes.length);
        }
    }
}
