        PSDImageWriter writer = new PSDImageWriter(new PSDImageWriterSpi());

        final int[] started = {-1};
        final boolean[] complete = {false};
        final boolean[] aborted = {false};
        final List<Float> progress = new ArrayList<>();

        try (ImageOutputStream output = new MemoryCacheImageOutputStream(bytes)) {
            writer.setOutput(output);
            writer.addIIOWriteProgressListener(new IIOWriteProgressListener() {
                @Override
                public void imageStarted(ImageWriter source, int imageIndex) {
                    started[0] = imageIndex;
                }

                @Override
                public void imageProgress(ImageWriter source, float percentageDone) {
                    progress.add(percentageDone);
                }

                @Override
                public void imageComplete(ImageWriter source) {
                    complete[0] = true;
                }

                @Override
                public void thumbnailStarted(ImageWriter source, int imageIndex, int thumbnailIndex) {
                }

                @Override
                public void thumbnailProgress(ImageWriter source, float percentageDone) {
                }

                @Override
                public void thumbnailComplete(ImageWriter source) {
                }

                @Override
                public void writeAborted(ImageWriter source) {
                    aborted[0] = true;
                }
            });

            writer.write(null, new IIOImage(image, null, null), null);
            output.flush();
        }

        assertEquals(0, started[0]);
        assertTrue(complete[0]);
        assertTrue(!aborted[0]);
        assertEquals(3, progress.size());
        assertEquals(0f, progress.get(0), 0.0001f);
        assertEquals(100f / 3f, progress.get(1), 0.0001f);
        assertEquals(200f / 3f, progress.get(2), 0.0001f);
