import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Tests the {@code toString()} representation of {@link PSDLayerBlendMode}.
 *
 * <p>The textual format is part of the debugging/observable contract of the class, and is
 * built from the blend mode, opacity, clipping and flags read from the layer record.</p>
 */
class PSDLayerBlendModeToStringTests {

    /**
     * Creates a {@code PSDLayerBlendMode} instance from a synthetic layer blend mode record
     * (signature, blend mode, opacity, clipping, flags and one pad byte).
     */
    private static PSDLayerBlendMode blendMode(final int mode, final int opacity, final int clipping, final int flags) throws IOException {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream(13);
        DataOutputStream stream = new DataOutputStream(buffer);

        stream.writeInt(PSD.RESOURCE_TYPE); // 8BIM
        stream.writeInt(mode);
        stream.writeByte(opacity);
        stream.writeByte(clipping);
        stream.writeByte(flags);
        stream.writeByte(0); // Pad

        stream.flush();

        return new PSDLayerBlendMode(new ByteArrayImageInputStream(buffer.toByteArray()));
    }

    @Test
    void toStringNormalModeBaseClippingNoFlags() throws IOException {
        // Sanity: the values are actually read back through the constructor
        PSDLayerBlendMode value = blendMode(PSD.BLEND_NORM, 255, 0, 0);

        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 00000000 ()]",
                value.toString());
    }

    @Test
    void toStringIncludesFourCharacterBlendModeVerbatim() throws IOException {
        int mode = ('m' << 24) + ('u' << 16) + ('l' << 8) + 't';

        assertEquals("PSDLayerBlendMode[mode: \"mult\", opacity: 100, clipping: 0 (base), flags: 00000000 ()]",
                blendMode(mode, 100, 0, 0).toString());
    }

    @Test
    void toStringPreservesTrailingSpaceInBlendMode() throws IOException {
        // "pass" and "hue " style codes may contain significant trailing spaces
        assertEquals("PSDLayerBlendMode[mode: \"hue \", opacity: 50, clipping: 0 (base), flags: 00000000 ()]",
                blendMode(PSD.BLEND_HUE, 50, 0, 0).toString());
    }

    @Test
    void toStringNonBaseClipping() throws IOException {
        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 1 (non-base), flags: 00000000 ()]",
                blendMode(PSD.BLEND_NORM, 255, 1, 0).toString());
    }

    @Test
    void toStringUnknownClippingValues() throws IOException {
        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 2 (unknown), flags: 00000000 ()]",
                blendMode(PSD.BLEND_NORM, 255, 2, 0).toString());

        // Clipping is read as an unsigned byte, so 255 must not be reported as "non-base"/negative
        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 255 (unknown), flags: 00000000 ()]",
                blendMode(PSD.BLEND_NORM, 255, 255, 0).toString());
    }

    @Test
    void toStringOpacityBounds() throws IOException {
        assertEquals("PSDLayerBlendMode[mode: \"dark\", opacity: 0, clipping: 0 (base), flags: 00000000 ()]",
                blendMode(PSD.BLEND_DARK, 0, 0, 0).toString());

        assertEquals("PSDLayerBlendMode[mode: \"lite\", opacity: 128, clipping: 0 (base), flags: 00000000 ()]",
                blendMode(PSD.BLEND_LITE, 128, 0, 0).toString());
    }

    @Test
    void toStringSingleFlagBits() throws IOException {
        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 00000001 (Transp. protected)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x01).toString());

        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 00000010 (Hidden)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x02).toString());

        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 00000100 (Obsolete bit)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x04).toString());

        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 00001000 (PS 5.0 data present)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x08).toString());

        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 00010000 (Pixel data irrelevant)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x10).toString());

        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 00100000 (Unknown bit 5)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x20).toString());

        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 01000000 (Unknown bit 6)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x40).toString());
