        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 1 (non-base), flags: 00000011 (Transp. protected, Hidden)]",
                blendMode(PSD.BLEND_NORM, 255, 1, 0x03).toString());

        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 01100000 (Unknown bit 5, Unknown bit 6)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x60).toString());
    }

    @Test
    void toStringAllDocumentedBitsSet() throws IOException {
        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 00011111 "
                        + "(Transp. protected, Hidden, Obsolete bit, PS 5.0 data present, Pixel data irrelevant)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x1F).toString());
    }

    @Test
    void toStringAllLowSevenBitsSet() throws IOException {
        assertEquals("PSDLayerBlendMode[mode: \"norm\", opacity: 255, clipping: 0 (base), flags: 01111111 "
                        + "(Transp. protected, Hidden, Obsolete bit, PS 5.0 data present, Pixel data irrelevant, Unknown bit 5, Unknown bit 6)]",
                blendMode(PSD.BLEND_NORM, 255, 0, 0x7F).toString());
    }

    @Test
    void toStringNoFlagsHasEmptyParenthesis() throws IOException {
        // No bits set => no trailing ", " to strip, and the description must be an empty pair of parentheses
        String result = blendMode(PSD.BLEND_NORM, 255, 0, 0).toString();

        assertEquals(true, result.contains("flags: 00000000 ()"), "Expected empty flag description in: " + result);
    }

    @Test
    void toStringIsStableAcrossInvocations() throws IOException {
        PSDLayerBlendMode value = blendMode(PSD.BLEND_NORM, 42, 1, 0x09);
        String expected = "PSDLayerBlendMode[mode: \"norm\", opacity: 42, clipping: 1 (non-base), "
                + "flags: 00001001 (Transp. protected, PS 5.0 data present)]";

        assertEquals(expected, value.toString());
        assertEquals(expected, value.toString());
    }

    @Test
    void toStringWithTopFlagBitSetThrows() throws IOException {
        // The flags field is a signed byte; formatter padding only handles 0..127 (8 bits), so a
        // negative flags value (top bit set) cannot currently be rendered.
        PSDLayerBlendMode value = blendMode(PSD.BLEND_NORM, 255, 0, 0x80);

        assertThrows(StringIndexOutOfBoundsException.class, value::toString);
    }
}
