                0x02, 0x00, 0, 0.0, 0, 0.0);

        assertEquals(
                "PSDLayerMaskData[top: 0, left: 0, bottom: 0, right: 0, "
                        + "default color: 0, flags: 10 (absolute, disabled)]",
                data.toString());
    }

    @Test
    void toStringReportsInvertedFlag() throws IOException {
        PSDLayerMaskData data = createMaskData(
                0, 0, 0, 0, 0,
                0x04, 0x00, 0, 0.0, 0, 0.0);

        assertEquals(
                "PSDLayerMaskData[top: 0, left: 0, bottom: 0, right: 0, "
                        + "default color: 0, flags: 100 (absolute, enabled, inverted)]",
                data.toString());
    }

    @Test
    void toStringReportsFromRenderedDataFlag() throws IOException {
        PSDLayerMaskData data = createMaskData(
                0, 0, 0, 0, 0,
                0x08, 0x00, 0, 0.0, 0, 0.0);

        assertEquals(
                "PSDLayerMaskData[top: 0, left: 0, bottom: 0, right: 0, "
                        + "default color: 0, flags: 1000 "
                        + "(absolute, enabled, from rendered data)]",
                data.toString());
    }

    @Test
    void toStringReportsAllUnknownHighFlagBits() throws IOException {
        PSDLayerMaskData data = createMaskData(
                0, 0, 0, 0, 0,
                0xE0, 0x00, 0, 0.0, 0, 0.0);

        assertEquals(
                "PSDLayerMaskData[top: 0, left: 0, bottom: 0, right: 0, "
                        + "default color: 0, flags: 11100000 "
                        + "(absolute, enabled, unknown flag (bit 5), "
                        + "unknown flag (bit 6), unknown flag (bit 7))]",
                data.toString());
    }

    @Test
    void toStringReportsHasParametersWithoutSelectedMaskParameterValues() throws IOException {
        PSDLayerMaskData data = createMaskData(
                0, 0, 0, 0, 0,
                0x10, 0x00, 12, 1.5, -7, -2.5);

        assertEquals(
                "PSDLayerMaskData[top: 0, left: 0, bottom: 0, right: 0, "
                        + "default color: 0, flags: 10000 "
                        + "(absolute, enabled, has parameters)]",
                data.toString());
    }

    @Test
    void toStringReportsOnlySelectedMaskParameterValues() throws IOException {
        PSDLayerMaskData data = createMaskData(
                0, 0, 0, 0, 0,
                0x10, 0x05, 12, 1.5, -7, -2.5);

        assertEquals(
                "PSDLayerMaskData[top: 0, left: 0, bottom: 0, right: 0, "
                        + "default color: 0, flags: 10000 "
                        + "(absolute, enabled, has parameters), "
                        + "userMaskDensity: 12, vectorMaskDensity: -7]",
                data.toString());
    }

    @Test
    void toStringReportsAllMaskParametersUsingSignedDensities() throws IOException {
        PSDLayerMaskData data = createMaskData(
                0, 0, 0, 0, 0,
                0x10, 0x0F, -1, 1.25, -128, -2.5);

        assertEquals(
                "PSDLayerMaskData[top: 0, left: 0, bottom: 0, right: 0, "
                        + "default color: 0, flags: 10000 "
                        + "(absolute, enabled, has parameters), "
                        + "userMaskDensity: -1, userMaskFeather: 1.25, "
                        + "vectorMaskDensity: -128, vectorMaskFeather: -2.5]",
                data.toString());
    }

    @Test
    void toStringReportsAllFlagsAndAllMaskParametersTogether() throws IOException {
        PSDLayerMaskData data = createMaskData(
                10, 20, 30, 40, 128,
                0xFF, 0x0F, 42, 0.0, 0, 3.75);

        assertEquals(
                "PSDLayerMaskData[top: 10, left: 20, bottom: 30, right: 40, "
                        + "default color: 128, flags: 11111111 "
                        + "(relative, disabled, inverted, from rendered data, has parameters, "
                        + "unknown flag (bit 5), unknown flag (bit 6), unknown flag (bit 7)), "
                        + "userMaskDensity: 42, userMaskFeather: 0.0, "
                        + "vectorMaskDensity: 0, vectorMaskFeather: 3.75]",
                data.toString());
    }

    private static PSDLayerMaskData createMaskData(
            int top, int left, int bottom, int right, int defaultColor, int flags,
            int maskParams, int userMaskDensity, double userMaskFeather,
            int vectorMaskDensity, double vectorMaskFeather) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        DataOutputStream output = new DataOutputStream(bytes);

        output.writeInt(top);
        output.writeInt(left);
        output.writeInt(bottom);
        output.writeInt(right);
        output.writeByte(defaultColor);
        output.writeByte(flags);

        if ((flags & 0x10) != 0) {
            output.writeByte(maskParams);
            if ((maskParams & 0x01) != 0) {
                output.writeByte(userMaskDensity);
            }
            if ((maskParams & 0x02) != 0) {
                output.writeDouble(userMaskFeather);
            }
            if ((maskParams & 0x04) != 0) {
                output.writeByte(vectorMaskDensity);
            }
            if ((maskParams & 0x08) != 0) {
                output.writeDouble(vectorMaskFeather);
            }
        }

        // The constructor requires a declared size in [20, 55]. For layouts without
        // mask parameters, these two trailing bytes are the documented padding.
        while (bytes.size() < 20) {
            output.writeByte(0);
        }
        output.flush();

        byte[] payload = bytes.toByteArray();
        MemoryCacheImageInputStream input = new MemoryCacheImageInputStream(
                new ByteArrayInputStream(payload));
        return new PSDLayerMaskData(input, payload.length);
    }
}
