    private static void assertRow(BufferedImage image, int y, int... expected) {
        assertEquals(expected.length, image.getWidth(), "Unexpected row width");
        for (int x = 0; x < expected.length; x++) {
            assertEquals(expected[x], image.getRaster().getSample(x, y, 0),
                    "Unexpected sample at (" + x + ", " + y + ")");
        }
    }

    private static byte[] bytes(int... values) {
        byte[] result = new byte[values.length];
        for (int i = 0; i < values.length; i++) {
            result[i] = (byte) values[i];
        }
        return result;
    }

    private static byte[] uncompressed8(int width, int height, int channels,
                                        int min, int max, int colorMode, byte[] pixels) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream data = new DataOutputStream(output);
        writeHeader(data, width, height, channels, 1, SGI.COMPRESSION_NONE, min, max, colorMode);
        data.write(pixels);
        data.flush();
        return output.toByteArray();
    }

    private static byte[] uncompressed16(int width, int height, int channels,
                                         int min, int max, int colorMode, int[] samples) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream data = new DataOutputStream(output);
        writeHeader(data, width, height, channels, 2, SGI.COMPRESSION_NONE, min, max, colorMode);
        for (int sample : samples) {
            data.writeShort(sample);
        }
        data.flush();
        return output.toByteArray();
    }

    private static byte[] rle8(int width, int height, int channels,
                               int min, int max, int colorMode, byte[] pixels) throws IOException {
        byte[][] rows = new byte[height * channels][width];
        int offset = 0;
        for (int row = 0; row < rows.length; row++) {
            System.arraycopy(pixels, offset, rows[row], 0, width);
            offset += width;
        }

        return rle(width, height, channels, 1, min, max, colorMode, rows);
    }

    private static byte[] rle16(int width, int height, int channels,
                                int min, int max, int colorMode, int[] samples) throws IOException {
        byte[][] rows = new byte[height * channels][width * 2];
        int sampleIndex = 0;
        for (byte[] row : rows) {
            for (int i = 0; i < row.length; i += 2) {
                int sample = samples[sampleIndex++];
                row[i] = (byte) (sample >>> 8);
                row[i + 1] = (byte) sample;
            }
        }

        return rle(width, height, channels, 2, min, max, colorMode, rows);
    }

    private static byte[] rle(int width, int height, int channels, int bytesPerPixel,
                              int min, int max, int colorMode, byte[][] rows) throws IOException {
        byte[][] encodedRows = new byte[rows.length][];
        int[] offsets = new int[rows.length];
        int[] lengths = new int[rows.length];

        int dataOffset = HEADER_SIZE + rows.length * 8;
        for (int i = 0; i < rows.length; i++) {
            encodedRows[i] = encodeRleRow(rows[i]);
            offsets[i] = dataOffset;
            lengths[i] = encodedRows[i].length;
            dataOffset += encodedRows[i].length;
        }

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        DataOutputStream data = new DataOutputStream(output);
        writeHeader(data, width, height, channels, bytesPerPixel, SGI.COMPRESSION_RLE, min, max, colorMode);
        for (int offset : offsets) {
            data.writeInt(offset);
        }
        for (int length : lengths) {
            data.writeInt(length);
        }
        for (byte[] encodedRow : encodedRows) {
            data.write(encodedRow);
        }
        data.flush();
        return output.toByteArray();
    }

    private static byte[] encodeRleRow(byte[] row) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        boolean uniform = true;
        for (int i = 1; i < row.length; i++) {
            if (row[i] != row[0]) {
                uniform = false;
                break;
            }
        }

        if (uniform) {
            output.write(row.length);
            output.write(row[0]);
        }
        else {
            output.write(0x80 | row.length);
            output.write(row);
        }

        return output.toByteArray();
    }

    private static void writeHeader(DataOutputStream data, int width, int height, int channels,
                                    int bytesPerPixel, int compression,
                                    int min, int max, int colorMode) throws IOException {
        data.writeShort(SGI.MAGIC);
        data.writeByte(compression);
        data.writeByte(bytesPerPixel);
        data.writeShort(2);
        data.writeShort(width);
        data.writeShort(height);
        data.writeShort(channels);
        data.writeInt(min);
        data.writeInt(max);
        data.writeInt(0);
        data.write(new byte[80]);
        data.writeInt(colorMode);
        data.write(new byte[404]);
    }

    private static final class ReaderFixture implements AutoCloseable {
        final SGIImageReader reader;
        final ImageInputStream input;

        ReaderFixture(byte[] data) throws IOException {
            reader = new SGIImageReader(null);
            input = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
            reader.setInput(input);
        }

        @Override
        public void close() throws IOException {
            try {
                reader.dispose();
            }
            finally {
                input.close();
            }
        }
    }

    private static final class RecordingProgressListener implements IIOReadProgressListener {
        final List<String> events = new ArrayList<>();
        private final Runnable onStarted;

        RecordingProgressListener(Runnable onStarted) {
            this.onStarted = onStarted;
        }

        @Override
        public void sequenceStarted(ImageReader source, int minIndex) {
            events.add("sequenceStarted");
        }

        @Override
        public void sequenceComplete(ImageReader source) {
            events.add("sequenceComplete");
        }

        @Override
        public void imageStarted(ImageReader source, int imageIndex) {
            events.add("started:" + imageIndex);
            if (onStarted != null) {
                onStarted.run();
            }
        }

        @Override
        public void imageProgress(ImageReader source, float percentageDone) {
            events.add("progress");
        }

        @Override
        public void imageComplete(ImageReader source) {
            events.add("complete");
        }

        @Override
        public void thumbnailStarted(ImageReader source, int imageIndex, int thumbnailIndex) {
            events.add("thumbnailStarted");
        }

        @Override
        public void thumbnailProgress(ImageReader source, float percentageDone) {
            events.add("thumbnailProgress");
        }

        @Override
        public void thumbnailComplete(ImageReader source) {
            events.add("thumbnailComplete");
        }

        @Override
        public void readAborted(ImageReader source) {
            events.add("aborted");
        }
    }
