package com.twelvemonkeys.imageio.plugins.tga;

import com.twelvemonkeys.imageio.stream.ByteArrayImageInputStream;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

import javax.imageio.IIOException;
import javax.imageio.ImageReadParam;
import javax.imageio.stream.ImageInputStream;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class TGAImageReaderReadTests {

    private static final int ORIGIN_UPPER_LEFT = 2;

    private TGAImageReader reader;
    private ImageInputStream input;

    @AfterEach
    void disposeReader() throws IOException {
        if (reader != null) {
            reader.dispose();
        }
        if (input != null) {
            input.close();
        }
    }

    @Test
    void readsUncompressedTrueColor24BitInUpperLeftOriginOrder() throws IOException {
        byte[] pixels = {
                // B, G, R
                0, 0, (byte) 255,    0, (byte) 255, 0,    (byte) 255, 0, 0,
                3, 2, 1,             30, 20, 10,          50, 100, (byte) 200
        };

        BufferedImage image = read(trueColor24(3, 2, ORIGIN_UPPER_LEFT, pixels), null);

        assertEquals(3, image.getWidth());
        assertEquals(2, image.getHeight());
        assertEquals(BufferedImage.TYPE_3BYTE_BGR, image.getType());
        assertRgb(image, 0, 0, rgb(255, 0, 0));
        assertRgb(image, 1, 0, rgb(0, 255, 0));
        assertRgb(image, 2, 0, rgb(0, 0, 255));
        assertRgb(image, 0, 1, rgb(1, 2, 3));
        assertRgb(image, 1, 1, rgb(10, 20, 30));
        assertRgb(image, 2, 1, rgb(200, 100, 50));
    }

    @Test
    void readsUncompressedTrueColor24BitInLowerLeftOriginOrder() throws IOException {
        // The first row in the file is the bottom row of the image.
        byte[] pixels = {
                0, 0, (byte) 255,    0, (byte) 255, 0,
                3, 2, 1,             30, 20, 10
        };

        BufferedImage image = read(trueColor24(2, 2, 0, pixels), null);

        assertRgb(image, 0, 1, rgb(255, 0, 0));
        assertRgb(image, 1, 1, rgb(0, 255, 0));
        assertRgb(image, 0, 0, rgb(1, 2, 3));
        assertRgb(image, 1, 0, rgb(10, 20, 30));
    }

    @Test
    void readsUncompressedTrueColor32BitWithoutAlphaAttributeAsOpaqueRgb() throws IOException {
        byte[] pixels = {
                0x11, 0x22, 0x33, 0x44,
                (byte) 0xAA, (byte) 0xBB, (byte) 0xCC, (byte) 0xDD
        };

        BufferedImage image = read(trueColor32(2, 1, ORIGIN_UPPER_LEFT, 0, pixels), null);

        assertEquals(BufferedImage.TYPE_INT_RGB, image.getType());
        assertRgb(image, 0, 0, rgb(0x33, 0x22, 0x11));
        assertRgb(image, 1, 0, rgb(0xCC, 0xBB, 0xAA));
    }

...
    }

    @Test
    void stopsAfterFirstDecodedRowWhenAbortWasRequested() throws IOException {
        byte[] pixels = {
                0, 0, (byte) 255,
                0, (byte) 255, 0,
                (byte) 255, 0, 0
        };

        reader = open(trueColor24(1, 3, ORIGIN_UPPER_LEFT, pixels));
        reader.abort();

        BufferedImage image = reader.read(0, null);

        assertRgb(image, 0, 0, rgb(255, 0, 0));
        assertRgb(image, 0, 1, rgb(0, 0, 0));
        assertRgb(image, 0, 2, rgb(0, 0, 0));
    }

    @Test
    void rejectsDeclaredDimensionsThatExceedInputDerivedLimit() {
        byte[] truncated = trueColor24HeaderOnly(1000, 1000);

        IIOException exception = assertThrows(IIOException.class, () -> read(truncated, null));

        assertTrue(exception.getMessage().contains("Image dimensions imply an allocation"));
        assertTrue(exception.getMessage().contains("maximum expansion ratio"));
    }

    @Test
    void propagatesEofWhenPixelDataIsTruncated() throws IOException {
        // Four rows are required, but only the first six pixel bytes are present before EOF.
        byte[] truncated = trueColor24WithPixels(4, 4, new byte[]{0, 0, (byte) 255, 0, (byte) 255, 0});

        assertThrows(IOException.class, () -> read(truncated, null));
    }

    @Test
    void rejectsUnsupportedImageOrigin() {
        byte[] data = trueColor24(2, 1, 1, new byte[]{0, 0, (byte) 255, 0, (byte) 255, 0});

        IIOException exception = assertThrows(IIOException.class, () -> read(data, null));

        assertTrue(exception.getMessage().contains("Unsupported origin"));
    }

    @Test
    void rejectsMismatchedSourceAndDestinationBandCounts() throws IOException {
        byte[] pixels = new byte[2 * 2 * 3];

        ImageReadParam param = new ImageReadParam();
        param.setSourceBands(new int[]{0, 1});
        param.setDestinationBands(new int[]{0});

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> read(trueColor24(2, 2, ORIGIN_UPPER_LEFT, pixels), param));

        assertTrue(exception.getMessage().contains("num source & dest bands differ"));
    }

    @Test
    void rejectsInvalidImageIndex() {
        assertThrows(IndexOutOfBoundsException.class, () -> {
            reader = open(trueColor24(1, 1, ORIGIN_UPPER_LEFT, new byte[]{0, 0, (byte) 255}));
            reader.read(1, null);
        });
    }

    @Test
    void rejectsReadWithoutInput() {
        reader = new TGAImageReader(new TGAImageReaderSpi());

        assertThrows(IllegalStateException.class, () -> reader.read(0, null));
    }

    private BufferedImage read(byte[] data, ImageReadParam param) throws IOException {
        return open(data).read(0, param);
    }

    private TGAImageReader open(byte[] data) throws IOException {
        input = new ByteArrayImageInputStream(data);
        assertNotNull(input);
        reader = new TGAImageReader(new TGAImageReaderSpi());
        reader.setInput(input);
        return reader;
    }

    private static void assertRgb(BufferedImage image, int x, int y, int expected) {
        assertEquals(expected, image.getRGB(x, y), "Unexpected ARGB value at (" + x + ", " + y + ")");
    }

    private static int rgb(int red, int green, int blue) {
        return 0xFF000000 | red << 16 | green << 8 | blue;
    }

    private static int argb(int alpha, int red, int green, int blue) {
        return alpha << 24 | red << 16 | green << 8 | blue;
    }

    private static byte[] trueColor24(int width, int height, int origin, byte[] pixels) {
        return tga(2, 0, 0, 0, 0, width, height, 24, origin, 0,
                new byte[0], pixels);
    }

    private static byte[] trueColor24WithPixels(int width, int height, byte[] pixels) {
        return tga(2, 0, 0, 0, 0, width, height, 24, ORIGIN_UPPER_LEFT, 0,
                new byte[0], pixels);
    }

    private static byte[] trueColor24HeaderOnly(int width, int height) {
        return tga(2, 0, 0, 0, 0, width, height, 24, ORIGIN_UPPER_LEFT, 0,
                new byte[0], new byte[0]);
    }

    private static byte[] trueColor32(int width, int height, int origin, int attributeBits, byte[] pixels) {
        return tga(2, 0, 0, 0, 0, width, height, 32, origin, attributeBits,
                new byte[0], pixels);
    }

    private static byte[] trueColor16(int width, int height, byte[] pixels) {
        return tga(2, 0, 0, 0, 0, width, height, 16, ORIGIN_UPPER_LEFT, 0,
                new byte[0], pixels);
    }

    private static byte[] monochrome8(int width, int height, byte[] pixels) {
        return tga(3, 0, 0, 0, 0, width, height, 8, ORIGIN_UPPER_LEFT, 0,
                new byte[0], pixels);
    }

    private static byte[] monochrome16(int width, int height, byte[] pixels) {
        return tga(3, 0, 0, 0, 0, width, height, 16, ORIGIN_UPPER_LEFT, 0,
                new byte[0], pixels);
    }

    private static byte[] colorMapped8(int width, int height, byte[] palette, byte[] indices) {
        return tga(1, 1, 0, palette.length / 3, 24, width, height, 8,
                ORIGIN_UPPER_LEFT, 0, palette, indices);
    }

    private static byte[] trueColorRle24(int width, int height, byte[] pixels) {
        return tga(10, 0, 0, 0, 0, width, height, 24, ORIGIN_UPPER_LEFT, 0,
                new byte[0], pixels);
    }

    private static byte[] tga(int imageType, int colorMapType, int colorMapStart, int colorMapSize,
                              int colorMapDepth, int width, int height, int pixelDepth, int origin,
                              int attributeBits, byte[] colorMap, byte[] pixels) {
        try {
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            DataOutputStream out = new DataOutputStream(bytes);

            out.writeByte(0); // ID length
            out.writeByte(colorMapType);
            out.writeByte(imageType);
            writeLittleEndianShort(out, colorMapStart);
            writeLittleEndianShort(out, colorMapSize);
            out.writeByte(colorMapDepth);
            writeLittleEndianShort(out, 0); // x origin
            writeLittleEndianShort(out, 0); // y origin
            writeLittleEndianShort(out, width);
            writeLittleEndianShort(out, height);
            out.writeByte(pixelDepth);
            out.writeByte(attributeBits | origin << 4);

            out.write(colorMap);
            out.write(pixels);

            // A zeroed TGA 2.0 footer keeps all test inputs longer than the
            // footer window inspected by TGAImageReader.readHeader().
            out.write(new byte[26]);
            out.flush();

            return bytes.toByteArray();
        }
        catch (IOException exception) {
            throw new AssertionError("Unexpected error creating test input", exception);
        }
    }

    private static void writeLittleEndianShort(DataOutputStream out, int value) throws IOException {
        out.writeByte(value & 0xFF);
        out.writeByte(value >>> 8 & 0xFF);
    }
}

