        System.arraycopy(prefix, 0, data, 0, prefix.length);
        System.arraycopy(header, 0, data, prefix.length, header.length);

        ImageInputStream stream = new ByteArrayImageInputStream(data);
        stream.seek(prefix.length);

        assertTrue(spi.canDecodeInput(stream), "Valid header at an offset should be decodable");
        assertEquals(prefix.length, stream.getStreamPosition(), "Stream position should be restored to the offset");
    }

