    // --- Helpers --------------------------------------------------------------------------------------------------

    private boolean canDecode(byte[] data) throws IOException {
        try (ImageInputStream stream = new ByteArrayImageInputStream(data)) {
            return spi.canDecodeInput(stream);
        }
    }

    private static byte[] validHeader() {
        return header(0, TGA.COLORMAP_NONE, TGA.IMAGETYPE_TRUECOLOR, 0, 0, 0, 0, 0, 64, 64, 24, 0);
    }

    @SuppressWarnings("SameParameterValue")
    private static byte[] header(int idLength, int colorMapType, int imageType,
                                 int colorMapStart, int colorMapSize, int colorMapDepth,
                                 int xOrigin, int yOrigin, int width, int height,
                                 int pixelDepth, int imageDescriptor) {
        byte[] header = new byte[TGA.HEADER_SIZE];

        header[0] = (byte) idLength;
        header[1] = (byte) colorMapType;
        header[2] = (byte) imageType;
        putShort(header, 3, colorMapStart);
        putShort(header, 5, colorMapSize);
        header[7] = (byte) colorMapDepth;
        putShort(header, 8, xOrigin);
        putShort(header, 10, yOrigin);
        putShort(header, 12, width);
        putShort(header, 14, height);
        header[16] = (byte) pixelDepth;
        header[17] = (byte) imageDescriptor;

        return header;
    }

    private static void putShort(byte[] buffer, int offset, int value) {
        buffer[offset] = (byte) value;
        buffer[offset + 1] = (byte) (value >> 8);
    }
