public void testIoErrorOnResetIsPropagated() {
    final byte[] data = validHeader();

    ImageInputStream failingResetStream = new ImageInputStreamImpl() {
        private int pos;

        @Override
        public int read() {
            return pos < data.length ? data[pos++] & 0xff : -1;
        }

        @Override
        public int read(byte[] buffer, int offset, int length) {
            if (pos >= data.length) {
                return -1;
            }

            int count = Math.min(length, data.length - pos);
            System.arraycopy(data, pos, buffer, offset, count);
            pos += count;

            return count;
        }

        @Override
        public void reset() throws IOException {
            throw new IOException("Reset failed");
        }
    };

    IOException exception = assertThrows(IOException.class, () -> spi.canDecodeInput(failingResetStream));
    assertEquals("Reset failed", exception.getMessage(), "The IOException from the stream should be propagated");
}

