import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@code TGAImageWriter.write(IIOMetadata, IIOImage, ImageWriteParam)}.
 * <p>
 * The test images are deliberately kept larger than 44 bytes, as the TGA reader
 * used for verification does not support (very) small files.
 */
class TGAImageWriterWriteTests {

    private static final int WIDTH = 8;
    private static final int HEIGHT = 4;

    private static TGAImageWriter createWriter() {
        return new TGAImageWriter(new TGAImageWriterSpi());
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static byte[] write(final BufferedImage image, final ImageWriteParam param, final IIOMetadata metadata) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        ImageOutputStream stream = ImageIO.createImageOutputStream(bytes);
        TGAImageWriter writer = createWriter();
        writer.setOutput(stream);
        writer.write(null, new IIOImage(image, null, metadata), param);
        stream.flush();
        stream.close();

        return bytes.toByteArray();
    }

    private static ImageOutputStream createStream(final ByteArrayOutputStream bytes) throws IOException {
        return ImageIO.createImageOutputStream(bytes);
    }

    private static TGAHeader readHeader(final byte[] data) throws IOException {
        ImageInputStream stream = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
        try {
            // TGA header is stored in little endian byte order
            stream.setByteOrder(ByteOrder.LITTLE_ENDIAN);

            return TGAHeader.read(stream);
        }
        finally {
            stream.close();
        }
    }

    private static BufferedImage read(final byte[] data) throws IOException {
        ImageInputStream stream = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
        try {
            TGAImageReader reader = new TGAImageReader(new TGAImageReaderSpi());
            reader.setInput(stream);

            return reader.read(0, null);
        }
        finally {
            stream.close();
        }
    }

    private static BufferedImage createBGRImage() {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_3BYTE_BGR);
        fill(image);

        return image;
    }

    private static BufferedImage createIntRgbImage() {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_RGB);
        fill(image);

        return image;
    }

    private static void fill(final BufferedImage image) {
        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                image.setRGB(x, y, 0xFF000000 | (x * 31 << 16) | (y * 63 << 8) | ((x + y) * 17));
            }
        }
    }

    /**
     * Expected pixel data for a 24/32 bit true color image, in TGA (BGR/BGRA) order.
     */
    private static byte[] expectedTruecolorData(final BufferedImage image, final int bytesPerPixel) {
        byte[] result = new byte[image.getWidth() * image.getHeight() * bytesPerPixel];
        int i = 0;

        for (int y = 0; y < image.getHeight(); y++) {
            for (int x = 0; x < image.getWidth(); x++) {
                int argb = image.getRGB(x, y);
                result[i++] = (byte) (argb);        // B
                result[i++] = (byte) (argb >> 8);   // G
                result[i++] = (byte) (argb >> 16);  // R
                if (bytesPerPixel == 4) {
                    result[i++] = (byte) (argb >>> 24); // A
                }
            }
        }

        return result;
    }

    private static void assertPixelsEqual(final BufferedImage expected, final BufferedImage actual) {
        assertEquals(expected.getWidth(), actual.getWidth(), "width");
        assertEquals(expected.getHeight(), actual.getHeight(), "height");

        for (int y = 0; y < expected.getHeight(); y++) {
            for (int x = 0; x < expected.getWidth(); x++) {
                assertEquals(expected.getRGB(x, y), actual.getRGB(x, y), String.format("pixel (%d, %d)", x, y));
            }
        }
    }

    private static void assertSamplesEqual(final BufferedImage expected, final BufferedImage actual) {
        assertEquals(expected.getWidth(), actual.getWidth(), "width");
        assertEquals(expected.getHeight(), actual.getHeight(), "height");

        for (int y = 0; y < expected.getHeight(); y++) {
            for (int x = 0; x < expected.getWidth(); x++) {
                assertEquals(expected.getRaster().getSample(x, y, 0), actual.getRaster().getSample(x, y, 0),
                             String.format("sample (%d, %d)", x, y));
            }
        }
    }

    // ---------------------------------------------------------------------
    // Precondition / argument validation
    // ---------------------------------------------------------------------

    @Test
    void writeWithoutOutput() {
        TGAImageWriter writer = createWriter();

        IllegalStateException exception = assertThrows(IllegalStateException.class,
                () -> writer.write(null, new IIOImage(createBGRImage(), null, null), null));

        assertEquals("getOutput() == null", exception.getMessage());
    }

    @Test
    void writeNullImage() throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        TGAImageWriter writer = createWriter();
        writer.setOutput(createStream(bytes));

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> writer.write(null, null, null));

        assertEquals("image may not be null", exception.getMessage());
        assertEquals(0, bytes.size(), "Nothing should have been written");
    }

    @Test
    void writeImageWithRasterOnly() throws IOException {
        BufferedImage image = createIntRgbImage();
        IIOImage iioImage = new IIOImage(image.getRaster(), null, null);
        assertTrue(iioImage.hasRaster());
        assertNotNull(iioImage.getRaster());

        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        TGAImageWriter writer = createWriter();
        writer.setOutput(createStream(bytes));

        UnsupportedOperationException exception = assertThrows(UnsupportedOperationException.class,
                () -> writer.write(null, iioImage, null));

        assertEquals("Raster not supported", exception.getMessage());
        assertEquals(0, bytes.size(), "Nothing should have been written");
    }

    // ---------------------------------------------------------------------
    // Normal cases
    // ---------------------------------------------------------------------

    @Test
    void writeTruecolorByteBGR() throws IOException {
        BufferedImage image = createBGRImage();

        byte[] data = write(image, null, null);

        // 18 byte header + full image, 24 bits per pixel
        assertEquals(TGA.HEADER_SIZE + WIDTH * HEIGHT * 3, data.length);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_TRUECOLOR, header.getImageType());
        assertEquals(TGA.COLORMAP_NONE, data[1] & 0xff, "Color map type");
        assertEquals(0, data[0] & 0xff, "Image ID length");
        assertEquals(WIDTH, header.getWidth());
        assertEquals(HEIGHT, header.getHeight());
        assertEquals(24, header.getPixelDepth());
        assertEquals(0, header.getAttributeBits());
        assertEquals(TGA.ORIGIN_UPPER_LEFT, header.getOrigin());
        assertEquals(TGA.INTERLEAVED_NON_INTERLEAVED, header.getInterleave());
        assertNull(header.getColorMap());
        assertNull(header.getIdentification());
        assertEquals(0x20, data[17] & 0xff, "Image descriptor: origin upper left, no alpha bits");

        // Pixel data is BGR, top-down (upper left origin)
        assertArrayEquals(expectedTruecolorData(image, 3),
                          Arrays.copyOfRange(data, TGA.HEADER_SIZE, data.length), "BGR pixel data");

        assertPixelsEqual(image, read(data));
    }

    @Test
    void writeSinglePixelImage() throws IOException {
        BufferedImage image = new BufferedImage(1, 1, BufferedImage.TYPE_3BYTE_BGR);
        image.setRGB(0, 0, 0xFF123456);

        byte[] data = write(image, null, null);

        assertEquals(TGA.HEADER_SIZE + 3, data.length);

        TGAHeader header = readHeader(data);
        assertEquals(1, header.getWidth());
        assertEquals(1, header.getHeight());
        assertEquals(24, header.getPixelDepth());

        assertArrayEquals(new byte[] {0x56, 0x34, 0x12}, Arrays.copyOfRange(data, TGA.HEADER_SIZE, data.length),
                          "Single BGR pixel");
    }

    @Test
    void writeTruecolorIntRGB() throws IOException {
        BufferedImage image = createIntRgbImage();
        assertEquals(DataBuffer.TYPE_INT, image.getRaster().getTransferType());

        byte[] data = write(image, null, null);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_TRUECOLOR, header.getImageType());
        assertEquals(24, header.getPixelDepth());
        assertEquals(WIDTH, header.getWidth());
        assertEquals(HEIGHT, header.getHeight());
        assertEquals(TGA.HEADER_SIZE + WIDTH * HEIGHT * 3, data.length);

        // TYPE_INT rasters are converted to bytes in BGR order
        assertArrayEquals(expectedTruecolorData(image, 3),
                          Arrays.copyOfRange(data, TGA.HEADER_SIZE, data.length), "BGR pixel data");

        assertPixelsEqual(image, read(data));
    }

    @Test
    void writeTruecolorWithAlpha() throws IOException {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_4BYTE_ABGR);
        for (int y = 0; y < HEIGHT; y++) {
            for (int x = 0; x < WIDTH; x++) {
                int alpha = 0x10 * (y * WIDTH + x) + 0x0F;
                image.setRGB(x, y, alpha << 24 | (x * 31 << 16) | (y * 63 << 8) | ((x + y) * 17));
            }
        }

        byte[] data = write(image, null, null);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_TRUECOLOR, header.getImageType());
        assertEquals(32, header.getPixelDepth());
        assertEquals(8, header.getAttributeBits(), "All eight attribute bits used for alpha");
        assertEquals(0x28, data[17] & 0xff, "Image descriptor: origin upper left + 8 alpha bits");
        assertEquals(TGA.HEADER_SIZE + WIDTH * HEIGHT * 4, data.length);

        // Pixel data is BGRA, top-down
        assertArrayEquals(expectedTruecolorData(image, 4),
                          Arrays.copyOfRange(data, TGA.HEADER_SIZE, data.length), "BGRA pixel data");

        BufferedImage result = read(data);
        assertEquals(BufferedImage.TYPE_INT_ARGB, result.getType());
        assertPixelsEqual(image, result);
    }

    @Test
    void writeUshortRgbImage() throws IOException {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_USHORT_555_RGB);
        fill(image);

        byte[] data = write(image, null, null);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_TRUECOLOR, header.getImageType());
        assertEquals(16, header.getPixelDepth());
        assertEquals(0, header.getAttributeBits());
        assertEquals(TGA.HEADER_SIZE + WIDTH * HEIGHT * 2, data.length);

        // Pixels are written as packed 15/16 bit values, in little endian order
        short[] samples = ((DataBufferUShort) image.getRaster().getDataBuffer()).getData();
        for (int y = 0; y < HEIGHT; y++) {
            for (int x = 0; x < WIDTH; x++) {
                int sample = samples[y * WIDTH + x] & 0xffff;
                int offset = TGA.HEADER_SIZE + (y * WIDTH + x) * 2;
                assertEquals(sample & 0xff, data[offset] & 0xff, String.format("low byte (%d, %d)", x, y));
                assertEquals(sample >> 8, data[offset + 1] & 0xff, String.format("high byte (%d, %d)", x, y));
            }
        }

        BufferedImage result = read(data);
        assertEquals(BufferedImage.TYPE_USHORT_555_RGB, result.getType());
        assertPixelsEqual(image, result);
    }

    @Test
    void writeMonochromeImage() throws IOException {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_BYTE_GRAY);
        byte[] gray = new byte[WIDTH * HEIGHT];
        for (int i = 0; i < gray.length; i++) {
            gray[i] = (byte) (i * 7 + 3);
            image.getRaster().setSample(i % WIDTH, i / WIDTH, 0, gray[i] & 0xff);
        }

        byte[] data = write(image, null, null);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_MONOCHROME, header.getImageType());
        assertEquals(8, header.getPixelDepth());
        assertEquals(0, header.getAttributeBits());
        assertEquals(TGA.HEADER_SIZE + WIDTH * HEIGHT, data.length);
        assertArrayEquals(gray, Arrays.copyOfRange(data, TGA.HEADER_SIZE, data.length), "Gray samples");

        BufferedImage result = read(data);
        assertEquals(BufferedImage.TYPE_BYTE_GRAY, result.getType());
        assertSamplesEqual(image, result);
    }

    @Test
    void writeIndexedImage() throws IOException {
        byte[] r = {(byte) 0xff, 0x00, 0x00, (byte) 0xff};
        byte[] g = {0x00, (byte) 0xff, 0x00, (byte) 0xff};
        byte[] b = {0x00, 0x00, (byte) 0xff, (byte) 0xff};
        IndexColorModel colorModel = new IndexColorModel(8, 4, r, g, b);

        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_BYTE_INDEXED, colorModel);
        byte[] indices = new byte[WIDTH * HEIGHT];
        for (int i = 0; i < indices.length; i++) {
            indices[i] = (byte) (i % 4);
            image.getRaster().setSample(i % WIDTH, i / WIDTH, 0, indices[i]);
        }

        byte[] data = write(image, null, null);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_COLORMAPPED, header.getImageType());
        assertEquals(TGA.COLORMAP_PALETTE, data[1] & 0xff, "Color map type");
        assertEquals(8, header.getPixelDepth());
        assertEquals(0, header.getAttributeBits());

        assertNotNull(header.getColorMap(), "Color map should be present");
        assertEquals(4, header.getColorMap().getMapSize());
        assertEquals(24, data[7] & 0xff, "Color map entry size");

        // Header + palette (4 entries * 3 bytes) + index data
        int paletteEnd = TGA.HEADER_SIZE + 4 * 3;
        assertEquals(paletteEnd + WIDTH * HEIGHT, data.length);
        assertArrayEquals(new byte[] {
                        0x00, 0x00, (byte) 0xff,
                        0x00, (byte) 0xff, 0x00,
                        (byte) 0xff, 0x00, 0x00,
                        (byte) 0xff, (byte) 0xff, (byte) 0xff
                },
                Arrays.copyOfRange(data, TGA.HEADER_SIZE, paletteEnd), "BGR palette");
        assertArrayEquals(indices, Arrays.copyOfRange(data, paletteEnd, data.length), "Index data");

        assertPixelsEqual(image, read(data));
    }

    // ---------------------------------------------------------------------
    // Compression
    // ---------------------------------------------------------------------

    @Test
    void writeRleCompressedImage() throws IOException {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_3BYTE_BGR);
        // All pixels identical, ideal for RLE
        for (int y = 0; y < HEIGHT; y++) {
            for (int x = 0; x < WIDTH; x++) {
                image.setRGB(x, y, 0xFF336699);
            }
        }

        TGAImageWriteParam param = new TGAImageWriteParam();
        param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
        param.setCompressionType("RLE");

        byte[] data = write(image, param, null);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_TRUECOLOR_RLE, header.getImageType());
        assertEquals(24, header.getPixelDepth());

        int uncompressedLength = TGA.HEADER_SIZE + WIDTH * HEIGHT * 3;
        assertTrue(data.length < uncompressedLength,
                   String.format("Compressed length (%d) should be smaller than uncompressed length (%d)",
                                 data.length, uncompressedLength));

        // One RLE packet per row, each holding all identical pixels
        int packetSize = 1 + 3;
        assertEquals(TGA.HEADER_SIZE + HEIGHT * packetSize, data.length);

        for (int y = 0; y < HEIGHT; y++) {
            int offset = TGA.HEADER_SIZE + y * packetSize;
            assertEquals(0x80 | (WIDTH - 1), data[offset] & 0xff, String.format("RLE packet header, row %d", y));
            assertArrayEquals(new byte[] {(byte) 0x99, 0x66, 0x33},
                              Arrays.copyOfRange(data, offset + 1, offset + packetSize),
                              String.format("RLE packet pixel value (BGR), row %d", y));
        }

        assertPixelsEqual(image, read(data));
    }

    @Test
    void writeExplicitUncompressedImage() throws IOException {
        BufferedImage image = createBGRImage();

        TGAImageWriteParam param = new TGAImageWriteParam();
        param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
        param.setCompressionType("None");

        byte[] data = write(image, param, null);

        assertEquals(TGA.IMAGETYPE_TRUECOLOR, readHeader(data).getImageType());
        assertEquals(TGA.HEADER_SIZE + WIDTH * HEIGHT * 3, data.length);
        assertPixelsEqual(image, read(data));
    }

