        BufferedImage image = createBGRImage();
        ImageTypeSpecifier type = ImageTypeSpecifiers.createFromBufferedImageType(BufferedImage.TYPE_3BYTE_BGR);

        TGAImageWriteParam rleParam = new TGAImageWriteParam();
        rleParam.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
        rleParam.setCompressionType("RLE");

