        assertPixelsEqual(image, read(data));
    }

    @Test
    void writeCompressionCopiedFromUncompressedMetadata() throws IOException {
        BufferedImage image = createBGRImage();
        ImageTypeSpecifier type = ImageTypeSpecifiers.createFromBufferedImageType(BufferedImage.TYPE_3BYTE_BGR);

        TGAImageWriteParam noneParam = new TGAImageWriteParam();
        noneParam.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
        noneParam.setCompressionType("None");

        IIOMetadata metadata = createWriter().getDefaultImageMetadata(type, noneParam);

        TGAImageWriteParam copyParam = new TGAImageWriteParam();
