    // ---------------------------------------------------------------------
    // Progress and abort
    // ---------------------------------------------------------------------

    @Test
    void writeShouldNotifyProgressListeners() throws IOException {
        BufferedImage image = createBGRImage();

        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        TGAImageWriter writer = createWriter();
        writer.setOutput(createStream(bytes));

        RecordingWriteProgressListener listener = new RecordingWriteProgressListener(writer);
        writer.addIIOWriteProgressListener(listener);

        writer.write(null, new IIOImage(image, null, null), null);

        assertEquals(1, listener.imageStarted, "imageStarted notifications");
        assertEquals(0, listener.imageIndex, "image index");
        assertEquals(1, listener.imageCompleted, "imageComplete notifications");
        assertEquals(0, listener.writeAborted, "Aborted images");

        assertFalse(listener.percentages.isEmpty(), "At least one progress notification expected");
        for (float percentage : listener.percentages) {
            assertTrue(percentage >= 0f && percentage <= 100f, "Percentage should be within 0-100, was " + percentage);
        }
    }

    @Test
    void writeAbortedByListenerShouldOnlyWriteHeader() throws IOException {
        BufferedImage image = createBGRImage();

        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        TGAImageWriter writer = createWriter();
        writer.setOutput(createStream(bytes));

        RecordingWriteProgressListener listener = new RecordingWriteProgressListener(writer);
        listener.abortOnStart = true;
        writer.addIIOWriteProgressListener(listener);

        writer.write(null, new IIOImage(image, null, null), null);
        // Flush the cached stream, so the written bytes are available
        ((ImageOutputStream) writer.getOutput()).flush();

        assertEquals(1, listener.imageStarted);
        // Header is written before the abort check, but no pixel data
        assertEquals(TGA.HEADER_SIZE, bytes.size(), "Only the header should have been written before abort");
    }

    // ---------------------------------------------------------------------
    // Unsupported input
    // ---------------------------------------------------------------------

    @Test
    void writeImageWithFloatRasterShouldFail() throws IOException {
        ColorSpace sRGB = ColorSpace.getInstance(ColorSpace.CS_sRGB);
        ColorModel colorModel = new ComponentColorModel(sRGB, false, false, Transparency.OPAQUE, DataBuffer.TYPE_FLOAT);
        WritableRaster raster = colorModel.createCompatibleWritableRaster(WIDTH, HEIGHT);
        BufferedImage image = new BufferedImage(colorModel, raster, false, null);

        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        TGAImageWriter writer = createWriter();
        writer.setOutput(createStream(bytes));

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> writer.write(null, new IIOImage(image, null, null), null));

        assertTrue(exception.getMessage() != null && exception.getMessage().contains("not supported"),
                   "Unexpected message: " + exception.getMessage());
    }

    // ---------------------------------------------------------------------
    // Helper types
    // ---------------------------------------------------------------------

    private static final class RecordingWriteProgressListener implements IIOWriteProgressListener {
        private final TGAImageWriter writer;

        int imageStarted;
        int imageIndex = -1;
        int imageCompleted;
        int writeAborted;
        boolean abortOnStart;
        final List<Float> percentages = new ArrayList<>();

        private RecordingWriteProgressListener(final TGAImageWriter writer) {
            this.writer = writer;
        }

        @Override
        public void imageStarted(final ImageWriter source, final int imageIndex) {
            imageStarted++;
            this.imageIndex = imageIndex;
            if (abortOnStart) {
                writer.abort();
            }
        }

        @Override
        public void imageProgress(final ImageWriter source, final float percentageDone) {
            percentages.add(percentageDone);
        }

        @Override
        public void imageComplete(final ImageWriter source) {
            imageCompleted++;
        }

        @Override
        public void thumbnailStarted(final ImageWriter source, final int imageIndex, final int thumbnailIndex) {
        }

        @Override
        public void thumbnailProgress(final ImageWriter source, final float percentageDone) {
        }

        @Override
        public void thumbnailComplete(final ImageWriter source) {
        }

        @Override
        public void writeAborted(final ImageWriter source) {
            writeAborted++;
        }
    }
