    @Test
    void writeShouldNotifyProgressListeners() throws IOException {
        BufferedImage image = createBGRImage();

        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        TGAImageWriter writer = createWriter();
        writer.setOutput(createStream(bytes));

        RecordingWriteProgressListener listener = new RecordingWriteProgressListener(writer);
        writer.addIIOWriteProgressListener(listener);

        writer.write(null, new IIOImage(image, null, null), null);

        assertEquals(1, listener.imageStarted, "imageStarted notifications");
        assertEquals(0, listener.imageIndex, "image index");
        assertEquals(1, listener.imageCompleted, "imageComplete notifications");
        assertEquals(0, listener.writeAborted, "Aborted images");

        assertFalse(listener.percentages.isEmpty(), "At least one progress notification expected");
        for (float percentage : listener.percentages) {
            assertTrue(percentage >= 0f && percentage <= 100f, "Percentage should be within 0-100, was " + percentage);
        }
    }

    @Test
    void writeAbortedByListenerShouldOnlyWriteHeader() throws IOException {
        BufferedImage image = createBGRImage();

        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        TGAImageWriter writer = createWriter();
        writer.setOutput(createStream(bytes));

        RecordingWriteProgressListener listener = new RecordingWriteProgressListener(writer);
        listener.abortOnStart = true;
        writer.addIIOWriteProgressListener(listener);

        writer.write(null, new IIOImage(image, null, null), null);
        // Flush the cached stream, so the written bytes are available
        ((ImageOutputStream) writer.getOutput()).flush();

        assertEquals(1, listener.imageStarted);
        // Header is written before the abort check, but no pixel data
        assertEquals(TGA.HEADER_SIZE, bytes.size(), "Only the header should have been written before abort");
    }

