/**
 * Tests for {@code TGAImageWriter.write(IIOMetadata, IIOImage, ImageWriteParam)}.
 * <p>
 * The test images are deliberately kept larger than 44 bytes, as the TGA reader
 * used for verification does not support (very) small files.
 */
class TGAImageWriterWriteTests {

    private static final int WIDTH = 8;
    private static final int HEIGHT = 4;

    private static TGAImageWriter createWriter() {
        return new TGAImageWriter(new TGAImageWriterSpi());
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static byte[] write(final BufferedImage image, final ImageWriteParam param, final IIOMetadata metadata) throws IOException {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        ImageOutputStream stream = ImageIO.createImageOutputStream(bytes);
        TGAImageWriter writer = createWriter();
        writer.setOutput(stream);
        writer.write(null, new IIOImage(image, null, metadata), param);
        stream.flush();
        stream.close();

        return bytes.toByteArray();
    }

    private static ImageOutputStream createStream(final ByteArrayOutputStream bytes) throws IOException {
        return ImageIO.createImageOutputStream(bytes);
    }

    private static TGAHeader readHeader(final byte[] data) throws IOException {
        ImageInputStream stream = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
        try {
            // TGA header is stored in little endian byte order
            stream.setByteOrder(ByteOrder.LITTLE_ENDIAN);

            return TGAHeader.read(stream);
        }
        finally {
            stream.close();
        }
    }

    private static BufferedImage read(final byte[] data) throws IOException {
        ImageInputStream stream = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
        try {
            TGAImageReader reader = new TGAImageReader(new TGAImageReaderSpi());
            reader.setInput(stream);

            return reader.read(0, null);
        }
        finally {
            stream.close();
        }
    }

    private static BufferedImage createBGRImage() {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_3BYTE_BGR);
        fill(image);

        return image;
    }

    private static BufferedImage createIntRgbImage() {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_RGB);

        byte[] data = write(image, null, null);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_TRUECOLOR, header.getImageType());
        assertEquals(24, header.getPixelDepth());
        assertEquals(WIDTH, header.getWidth());
        assertEquals(HEIGHT, header.getHeight());
        assertEquals(TGA.HEADER_SIZE + WIDTH * HEIGHT * 3, data.length);

        // TYPE_INT rasters are converted to bytes in BGR order
        assertArrayEquals(expectedTruecolorData(image, 3),
                          Arrays.copyOfRange(data, TGA.HEADER_SIZE, data.length), "BGR pixel data");

        assertPixelsEqual(image, read(data));
    }

    @Test
    void writeTruecolorWithAlpha() throws IOException {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_4BYTE_ABGR);
        for (int y = 0; y < HEIGHT; y++) {
            for (int x = 0; x < WIDTH; x++) {
                int alpha = 0x10 * (y * WIDTH + x) + 0x0F;
                image.setRGB(x, y, alpha << 24 | (x * 31 << 16) | (y * 63 << 8) | ((x + y) * 17));
            }
        }

        byte[] data = write(image, null, null);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_TRUECOLOR, header.getImageType());
        assertEquals(32, header.getPixelDepth());
        assertEquals(8, header.getAttributeBits(), "All eight attribute bits used for alpha");
        assertEquals(0x28, data[17] & 0xff, "Image descriptor: origin upper left + 8 alpha bits");
        assertEquals(TGA.HEADER_SIZE + WIDTH * HEIGHT * 4, data.length);

        // Pixel data is BGRA, top-down
        assertArrayEquals(expectedTruecolorData(image, 4),
                          Arrays.copyOfRange(data, TGA.HEADER_SIZE, data.length), "BGRA pixel data");

        BufferedImage result = read(data);
        assertEquals(BufferedImage.TYPE_INT_ARGB, result.getType());
        assertPixelsEqual(image, result);
    }

    @Test
    void writeUshortRgbImage() throws IOException {
        BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_USHORT_555_RGB);
        fill(image);

        byte[] data = write(image, null, null);

        TGAHeader header = readHeader(data);
        assertEquals(TGA.IMAGETYPE_TRUECOLOR, header.getImageType());
        assertEquals(16, header.getPixelDepth());
        assertEquals(0, header.getAttributeBits());
        assertEquals(TGA.HEADER_SIZE + WIDTH * HEIGHT * 2, data.length);

        // Pixels are written as packed 15/16 bit values, in little endian order
        short[] samples = ((DataBufferUShort) image.getRaster().getDataBuffer()).getData();
        for (int y = 0; y < HEIGHT; y++) {
            for (int x = 0; x < WIDTH; x++) {
                int sample = samples[y * WIDTH + x] & 0xffff;
                int offset = TGA.HEADER_SIZE + (y * WIDTH + x) * 2;
                assertEquals(sample & 0xff, data[offset] & 0xff, String.format("low byte (%d, %d)", x, y));
                assertEquals(sample >> 8, data[offset + 1] & 0xff, String.format("high byte (%d, %d)", x, y));
            }
        }

        BufferedImage result = read(data);
        assertEquals(BufferedImage.TYPE_USHORT_555_RGB, result.getType());
        assertPixelsEqual(image, result);
    }

