package com.twelvemonkeys.imageio.plugins.tiff;

import com.twelvemonkeys.imageio.metadata.Entry;
import com.twelvemonkeys.imageio.metadata.tiff.TIFF;
import com.twelvemonkeys.imageio.metadata.tiff.TIFFEntry;
import org.junit.jupiter.api.Test;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import javax.imageio.metadata.IIOMetadataFormatImpl;
import javax.imageio.metadata.IIOMetadataNode;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@code TIFFImageMetadata.getStandardChromaNode()}.
 */
public class TIFFImageMetadataGetStandardChromaNodeTests {

    private static final String COLOR_SPACE_TYPE = "ColorSpaceType";
    private static final String NUM_CHANNELS = "NumChannels";
    private static final String BLACK_IS_ZERO = "BlackIsZero";
    private static final String PALETTE = "Palette";
    private static final String PALETTE_ENTRY = "PaletteEntry";

    // --- Factory helpers ------------------------------------------------------------------------------------

    private static TIFFImageMetadata metadata(final Entry... entries) {
        return new TIFFImageMetadata(Arrays.asList(entries));
    }

    private static Entry photometric(final int value) {
        return new TIFFEntry(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, value);
    }

    private static Entry samplesPerPixel(final int value) {
        return new TIFFEntry(TIFF.TAG_SAMPLES_PER_PIXEL, value);
    }

    private static Entry extraSamples(final int... values) {
        short[] samples = new short[values.length];
        for (int i = 0; i < values.length; i++) {
            samples[i] = (short) values[i];
        }
        return new TIFFEntry(TIFF.TAG_EXTRA_SAMPLES, samples);
    }

    private static Entry bitsPerSample(final int... values) {
        short[] bits = new short[values.length];
        for (int i = 0; i < values.length; i++) {
            bits[i] = (short) values[i];
        }
        return new TIFFEntry(TIFF.TAG_BITS_PER_SAMPLE, bits);
    }

    private static Entry compression(final int value) {
        return new TIFFEntry(TIFF.TAG_COMPRESSION, value);
    }

    private static Entry colorMap(final int... values) {
        // Explicit type, so that an empty array does not trip up type guessing.
        return new TIFFEntry(TIFF.TAG_COLOR_MAP, TIFF.TYPE_SHORT, values);
    }

    // --- Standard tree node helpers -------------------------------------------------------------------------

    private static IIOMetadataNode chroma(final TIFFImageMetadata metadata) {
        Node standardTree = metadata.getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName);
        assertNotNull(standardTree, "Standard metadata tree should not be null");

        NodeList children = standardTree.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if ("Chroma".equals(child.getNodeName())) {
                return (IIOMetadataNode) child;
            }
        }

        throw new AssertionError("Chroma node not present in standard metadata tree");
    }

    private static List<IIOMetadataNode> childrenNamed(final IIOMetadataNode parent, final String name) {
        List<IIOMetadataNode> result = new ArrayList<IIOMetadataNode>();
        NodeList children = parent.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if (name.equals(child.getNodeName())) {
                result.add((IIOMetadataNode) child);
            }
        }
        return result;
    }

    private static IIOMetadataNode childNamed(final IIOMetadataNode parent, final String name) {
        List<IIOMetadataNode> nodes = childrenNamed(parent, name);
        assertEquals(1, nodes.size(), "Expected exactly one " + name + " child of " + parent.getNodeName());
        return nodes.get(0);
    }

    private static void assertColorSpaceType(final IIOMetadataNode chroma, final String expectedName) {
        IIOMetadataNode colorSpaceType = childNamed(chroma, COLOR_SPACE_TYPE);
        assertEquals(expectedName, colorSpaceType.getAttribute("name"));
    }

    private static void assertNumChannels(final IIOMetadataNode chroma, final String expectedValue) {
        IIOMetadataNode numChannels = childNamed(chroma, NUM_CHANNELS);
        assertEquals(expectedValue, numChannels.getAttribute("value"));
    }

    private static void assertBlackIsZeroDefault(final IIOMetadataNode chroma) {
        IIOMetadataNode blackIsZero = childNamed(chroma, BLACK_IS_ZERO);
        assertFalse(blackIsZero.hasAttribute("value"), "BlackIsZero should default (no value attribute)");
        assertEquals("", blackIsZero.getAttribute("value"));
    }

    private static void assertBlackIsZeroFalse(final IIOMetadataNode chroma) {
        IIOMetadataNode blackIsZero = childNamed(chroma, BLACK_IS_ZERO);
        assertTrue(blackIsZero.hasAttribute("value"));
        assertEquals("FALSE", blackIsZero.getAttribute("value"));
    }

    // --- ColorSpaceType mapping -----------------------------------------------------------------------------

    @Test
    public void rgbPhotometricProducesRgbColorSpace() {
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_RGB), samplesPerPixel(3)));

        assertColorSpaceType(chroma, "RGB");
        assertNumChannels(chroma, "3");
        assertBlackIsZeroDefault(chroma);
        assertEquals(3, chroma.getChildNodes().getLength(), "No Palette expected without a ColorMap");
    }

    @Test
    public void whiteIsZeroProducesGrayAndBlackIsZeroFalse() {
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_WHITE_IS_ZERO), samplesPerPixel(1)));

        assertColorSpaceType(chroma, "GRAY");
        assertNumChannels(chroma, "1");
        assertBlackIsZeroFalse(chroma);
    }

    @Test
    public void blackIsZeroProducesGrayAndDefaultBlackIsZero() {
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO), samplesPerPixel(1)));

        assertColorSpaceType(chroma, "GRAY");
        assertNumChannels(chroma, "1");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void maskProducesGray() {
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_MASK), samplesPerPixel(1)));

        assertColorSpaceType(chroma, "GRAY");
        assertNumChannels(chroma, "1");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void paletteProducesRgbAndAlwaysThreeChannels() {
        // SamplesPerPixel is deliberately different from 3, PALETTE must still report 3 channels.
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_PALETTE), samplesPerPixel(8)));

        assertColorSpaceType(chroma, "RGB");
        assertNumChannels(chroma, "3");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void yCbCrProducesYCbCr() {
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFExtension.PHOTOMETRIC_YCBCR), samplesPerPixel(3)));

        assertColorSpaceType(chroma, "YCbCr");
        assertNumChannels(chroma, "3");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void labPhotometricsProduceLab() {
        int[] labPhotometrics = {
                TIFFExtension.PHOTOMETRIC_CIELAB,
                TIFFExtension.PHOTOMETRIC_ICCLAB,
                TIFFExtension.PHOTOMETRIC_ITULAB
        };

        for (int photometric : labPhotometrics) {
            IIOMetadataNode chroma = chroma(metadata(photometric(photometric), samplesPerPixel(3)));

            assertColorSpaceType(chroma, "Lab");
            assertNumChannels(chroma, "3");
            assertBlackIsZeroDefault(chroma);
        }
    }

    @Test
    public void separatedWithThreeChannelsProducesCmy() {
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFExtension.PHOTOMETRIC_SEPARATED), samplesPerPixel(3)));

        assertColorSpaceType(chroma, "CMY");
        assertNumChannels(chroma, "3");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void separatedWithFourChannelsProducesCmyk() {
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFExtension.PHOTOMETRIC_SEPARATED), samplesPerPixel(4)));

        assertColorSpaceType(chroma, "CMYK");
        assertNumChannels(chroma, "4");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void separatedWithAnyOtherChannelCountProducesCmyk() {
        for (int channels : new int[]{1, 2, 5, 16}) {
            IIOMetadataNode chroma = chroma(metadata(photometric(TIFFExtension.PHOTOMETRIC_SEPARATED), samplesPerPixel(channels)));

            assertColorSpaceType(chroma, "CMYK");
            assertNumChannels(chroma, Integer.toString(channels));
        }
    }

    @Test
    public void loglPhotometricsProduceLuv() {
        int[] logPhotometrics = {TIFFCustom.PHOTOMETRIC_LOGL, TIFFCustom.PHOTOMETRIC_LOGLUV};

        for (int photometric : logPhotometrics) {
            IIOMetadataNode chroma = chroma(metadata(photometric(photometric), samplesPerPixel(3)));

            assertColorSpaceType(chroma, "Luv");
            assertNumChannels(chroma, "3");
        }
    }

    @Test
    public void cfaAndLinearRawProduce3Clr() {
        int[] rawPhotometrics = {TIFFCustom.PHOTOMETRIC_CFA, TIFFCustom.PHOTOMETRIC_LINEAR_RAW};

        for (int photometric : rawPhotometrics) {
            IIOMetadataNode chroma = chroma(metadata(photometric(photometric), samplesPerPixel(4)));

            assertColorSpaceType(chroma, "3CLR");
            assertNumChannels(chroma, "4");
        }
    }

    @Test
    public void unknownPhotometricUsesHexadecimalChannelCount() {
        IIOMetadataNode chroma = chroma(metadata(photometric(99), samplesPerPixel(16)));

        assertColorSpaceType(chroma, "10CLR");
        assertNumChannels(chroma, "16");
        assertBlackIsZeroDefault(chroma);
    }

    // --- SamplesPerPixel fallback ---------------------------------------------------------------------------

    @Test
    public void numChannelsFallsBackToBitsPerSampleCount() {
        IIOMetadataNode chroma = chroma(metadata(photometric(99), bitsPerSample(8, 8, 8)));

        assertEquals("3CLR", childNamed(chroma, COLOR_SPACE_TYPE).getAttribute("name"));
        assertNumChannels(chroma, "3");
    }

    @Test
    public void numChannelsDefaultsToOneWithoutSamplesPerPixelOrBitsPerSample() {
        IIOMetadataNode chroma = chroma(metadata(photometric(99)));

        assertColorSpaceType(chroma, "1CLR");
        assertNumChannels(chroma, "1");
    }

    // --- PhotometricInterpretation fallback -----------------------------------------------------------------

    @Test
    public void emptyMetadataFallsBackToBlackIsZero() {
        IIOMetadataNode chroma = chroma(metadata());

        assertColorSpaceType(chroma, "GRAY");
        assertNumChannels(chroma, "1");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void ccittCompressionFallbackProducesWhiteIsZero() {
        IIOMetadataNode chroma = chroma(metadata(compression(TIFFBaseline.COMPRESSION_CCITT_MODIFIED_HUFFMAN_RLE)));

        assertColorSpaceType(chroma, "GRAY");
        assertNumChannels(chroma, "1");
        assertBlackIsZeroFalse(chroma);
    }

    @Test
    public void colorMapFallbackProducesPalette() {
        IIOMetadataNode chroma = chroma(metadata(colorMap(0x1100, 0x2200, 0x3300)));

        assertColorSpaceType(chroma, "RGB");
        assertNumChannels(chroma, "3");
        assertBlackIsZeroDefault(chroma);
        assertEquals(1, childrenNamed(chroma, PALETTE).size());
    }

    @Test
    public void threeSamplesFallbackProducesRgb() {
        IIOMetadataNode chroma = chroma(metadata(samplesPerPixel(3)));

        assertColorSpaceType(chroma, "RGB");
        assertNumChannels(chroma, "3");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void threeOpaqueSamplesFallbackProducesRgb() {
        // Four samples per pixel, but one extra sample (alpha) => three colour samples.
        IIOMetadataNode chroma = chroma(metadata(samplesPerPixel(4), extraSamples(1)));

        assertColorSpaceType(chroma, "RGB");
        assertNumChannels(chroma, "4");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void fourSamplesFallbackProducesSeparated() {
        IIOMetadataNode chroma = chroma(metadata(samplesPerPixel(4)));

        assertColorSpaceType(chroma, "CMYK");
        assertNumChannels(chroma, "4");
        assertBlackIsZeroDefault(chroma);
    }

    @Test
    public void singleSampleFallbackProducesBlackIsZero() {
        IIOMetadataNode chroma = chroma(metadata(samplesPerPixel(1)));

        assertColorSpaceType(chroma, "GRAY");
        assertNumChannels(chroma, "1");
        assertBlackIsZeroDefault(chroma);
    }

    // --- Palette --------------------------------------------------------------------------------------------

    @Test
    public void colorMapAddsPaletteWithExpectedEntries() {
        int[] values = {
                0xAB00, 0xCD00,
                0x1200, 0x3400,
                0x5600, 0x7800
        };

        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_PALETTE), colorMap(values)));

        assertColorSpaceType(chroma, "RGB");
        assertNumChannels(chroma, "3");

        IIOMetadataNode palette = childNamed(chroma, PALETTE);
        List<IIOMetadataNode> entries = childrenNamed(palette, PALETTE_ENTRY);
        assertEquals(2, entries.size(), "ColorMap length / 3 should be the number of PaletteEntry nodes");

        assertPaletteEntry(entries.get(0), 0, 0xAB, 0x12, 0x56);
        assertPaletteEntry(entries.get(1), 1, 0xCD, 0x34, 0x78);
    }

    @Test
    public void colorMapUsesHighByteOfEachValue() {
        // The low byte should be ignored; only bits 8-15 are used.
        int[] values = {0x12FF, 0x34FF, 0x56FF};

        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_PALETTE), colorMap(values)));

        IIOMetadataNode palette = childNamed(chroma, PALETTE);
        List<IIOMetadataNode> entries = childrenNamed(palette, PALETTE_ENTRY);
        assertEquals(1, entries.size());
        assertPaletteEntry(entries.get(0), 0, 0x12, 0x34, 0x56);
    }

    @Test
    public void colorMapLengthNotMultipleOfThreeOnlyAddsCompleteEntries() {
        int[] values = {0x1100, 0x2200, 0x3300, 0x4400};

        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_PALETTE), colorMap(values)));

        IIOMetadataNode palette = childNamed(chroma, PALETTE);
        List<IIOMetadataNode> entries = childrenNamed(palette, PALETTE_ENTRY);
        assertEquals(1, entries.size(), "Incomplete trailing colour components should not create entries");
        assertPaletteEntry(entries.get(0), 0, 0x11, 0x22, 0x33);
    }

    @Test
    public void emptyColorMapAddsEmptyPalette() {
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_PALETTE), colorMap()));

        IIOMetadataNode palette = childNamed(chroma, PALETTE);
        assertEquals(0, childrenNamed(palette, PALETTE_ENTRY).size());
        assertColorSpaceType(chroma, "RGB");
        assertNumChannels(chroma, "3");
    }

    @Test
    public void colorMapAddsPaletteEvenForNonPalettePhotometric() {
        IIOMetadataNode chroma = chroma(metadata(photometric(TIFFBaseline.PHOTOMETRIC_RGB), samplesPerPixel(3), colorMap(0x1100, 0x2200, 0x3300)));

        assertColorSpaceType(chroma, "RGB");
        assertNumChannels(chroma, "3");

        IIOMetadataNode palette = childNamed(chroma, PALETTE);
        List<IIOMetadataNode> entries = childrenNamed(palette, PALETTE_ENTRY);
        assertEquals(1, entries.size());
        assertPaletteEntry(entries.get(0), 0, 0x11, 0x22, 0x33);
    }

    private static void assertPaletteEntry(final IIOMetadataNode entry, final int index, final int red, final int green, final int blue) {
        assertEquals(Integer.toString(index), entry.getAttribute("index"));
        assertEquals(Integer.toString(red), entry.getAttribute("red"));
        assertEquals(Integer.toString(green), entry.getAttribute("green"));
        assertEquals(Integer.toString(blue), entry.getAttribute("blue"));
    }
}
