        assertNull(lossless.getFirstChild(), "Lossless should be a leaf node");
    }

    @Test
    public void testCompressionTypeNameChildHasNoUserObject() {
        IIOMetadataNode compression = compressionNodeFor(TIFFExtension.COMPRESSION_LZW);
        IIOMetadataNode typeName = childElement(compression, COMPRESSION_TYPE_NAME);

        assertNotNull(typeName);
        assertNull(typeName.getUserObject());
        assertNull(typeName.getNodeValue());
    }

    // ----- Different entry value representations -----

    @Test
    public void testCompressionValueAsShortArray() {
        Entry entry = new TIFFEntry(TIFF.TAG_COMPRESSION, TIFF.TYPE_SHORT, new short[]{(short) TIFFExtension.COMPRESSION_LZW});
        IIOMetadataNode compression = compressionNode(metadata(entry));

        assertEquals("LZW", compressionTypeName(compression));
    }

    @Test
    public void testCompressionValueAsIntArray() {
        Entry entry = new TIFFEntry(TIFF.TAG_COMPRESSION, TIFF.TYPE_LONG, new int[]{TIFFExtension.COMPRESSION_JPEG});
        IIOMetadataNode compression = compressionNode(metadata(entry));

        assertEquals("JPEG", compressionTypeName(compression));
        assertEquals("FALSE", attribute(childElement(compression, LOSSLESS), VALUE));
    }

    @Test
    public void testCompressionValueAsBoxedInteger() {
        Entry entry = new TIFFEntry(TIFF.TAG_COMPRESSION, Integer.valueOf(TIFFBaseline.COMPRESSION_PACKBITS));
        IIOMetadataNode compression = compressionNode(metadata(entry));

        assertEquals("PackBits", compressionTypeName(compression));
    }

    @Test
    public void testCompressionValueAsBoxedShort() {
        Entry entry = new TIFFEntry(TIFF.TAG_COMPRESSION, TIFF.TYPE_SHORT, (short) TIFFExtension.COMPRESSION_DEFLATE);
        IIOMetadataNode compression = compressionNode(metadata(entry));

        assertEquals("Deflate", compressionTypeName(compression));
    }

    // ----- Interactions with other tags / repeated calls -----

    @Test
    public void testOtherTagsDoNotAffectCompressionNode() {
        List<Entry> entries = new ArrayList<>();
        entries.add(new TIFFEntry(TIFF.TAG_IMAGE_WIDTH, 32));
        entries.add(new TIFFEntry(TIFF.TAG_COMPRESSION, TIFFExtension.COMPRESSION_LZW));
        entries.add(new TIFFEntry(TIFF.TAG_IMAGE_HEIGHT, 16));
        entries.add(new TIFFEntry(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, TIFFBaseline.PHOTOMETRIC_RGB));

        IIOMetadataNode compression = compressionNode(new TIFFImageMetadata(entries));

        assertEquals("LZW", compressionTypeName(compression));
        assertNotNull(childElement(compression, LOSSLESS));
    }

    @Test
    public void testEachCallReturnsFreshNode() {
        TIFFImageMetadata metadata = metadataWithCompression(TIFFExtension.COMPRESSION_LZW);

        IIOMetadataNode first = metadata.getStandardCompressionNode();
        IIOMetadataNode second = metadata.getStandardCompressionNode();

        assertNotSame(first, second);
        assertEquals("LZW", compressionTypeName(first));
        assertEquals("LZW", compressionTypeName(second));
    }

    @Test
    public void testModifyingReturnedNodeDoesNotAffectSubsequentCalls() {
        TIFFImageMetadata metadata = metadataWithCompression(TIFFExtension.COMPRESSION_LZW);

        IIOMetadataNode first = metadata.getStandardCompressionNode();
        childElement(first, COMPRESSION_TYPE_NAME).setAttribute(VALUE, "Modified");
        first.appendChild(new IIOMetadataNode("Extra"));

        IIOMetadataNode second = metadata.getStandardCompressionNode();

        assertEquals("LZW", compressionTypeName(second));
        assertNull(childElement(second, "Extra"));
        assertEquals(2, childElements(second).size());
    }

