    public void testCompressionNodeFromStandardTree() {
        TIFFImageMetadata metadata = metadataWithCompression(TIFFExtension.COMPRESSION_JPEG);

        Node standardTree = metadata.getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName);
        assertNotNull(standardTree);

        IIOMetadataNode compression = childElement(standardTree, "Compression");
        assertNotNull(compression, "Standard metadata tree should contain a Compression node");
        assertEquals("JPEG", compressionTypeName(compression));

        IIOMetadataNode lossless = childElement(compression, LOSSLESS);
        assertNotNull(lossless);
        assertEquals("FALSE", attribute(lossless, VALUE));
    }

    @Test
    public void testCompressionNodeIsChildOfStandardTreeForUncompressed() {
        Node standardTree = new TIFFImageMetadata().getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName);

        IIOMetadataNode compression = childElement(standardTree, "Compression");
        assertNotNull(compression);
        assertEquals("None", compressionTypeName(compression));
        assertNull(childElement(compression, LOSSLESS));
    }

