 * The method is {@code protected}, but is accessible from this test as it resides in the same package.
 */
public class TIFFImageMetadataGetStandardCompressionNodeTests {

    private static final String COMPRESSION_TYPE_NAME = "CompressionTypeName";
    private static final String LOSSLESS = "Lossless";
    private static final String VALUE = "value";

    // ----- Helpers -----

    private static TIFFImageMetadata metadata(final Entry... entries) {
        return new TIFFImageMetadata(Arrays.asList(entries));
    }

    private static TIFFImageMetadata metadataWithCompression(final Object compressionValue) {
        return metadata(new TIFFEntry(TIFF.TAG_COMPRESSION, compressionValue));
    }

    private static IIOMetadataNode compressionNode(final TIFFImageMetadata metadata) {
        IIOMetadataNode node = metadata.getStandardCompressionNode();
        assertNotNull(node, "getStandardCompressionNode() must never return null");
        return node;
    }

    private static IIOMetadataNode compressionNodeFor(final int compressionValue) {
        return compressionNode(metadataWithCompression(compressionValue));
    }

    private static List<IIOMetadataNode> childElements(final Node parent) {
        List<IIOMetadataNode> children = new ArrayList<>();
        for (Node child = parent.getFirstChild(); child != null; child = child.getNextSibling()) {
            if (child instanceof IIOMetadataNode) {
                children.add((IIOMetadataNode) child);
            }
            else {
                throw new AssertionError("Expected IIOMetadataNode child, was: " + child.getClass());
            }
        }
        return children;
    }

    private static IIOMetadataNode childElement(final Node parent, final String name) {
        IIOMetadataNode found = null;
        for (IIOMetadataNode child : childElements(parent)) {
            if (name.equals(child.getNodeName())) {
                if (found != null) {
                    throw new AssertionError("More than one child named " + name);
                }
                found = child;
            }
        }
        return found;
    }

    private static String attribute(final Node node, final String name) {
        NamedNodeMap attributes = node.getAttributes();
        if (attributes == null) {
            return null;
        }
        Node attribute = attributes.getNamedItem(name);
        return attribute == null ? null : attribute.getNodeValue();
    }

    private static String compressionTypeName(final IIOMetadataNode compressionNode) {
        IIOMetadataNode typeName = childElement(compressionNode, COMPRESSION_TYPE_NAME);
        assertNotNull(typeName, "Compression node must contain a CompressionTypeName child");
        return attribute(typeName, VALUE);
    }

    private static void assertCompressionName(final int compressionValue, final String expectedName) {
        assertEquals(expectedName, compressionTypeName(compressionNodeFor(compressionValue)),
                     "Unexpected CompressionTypeName for compression value: " + compressionValue);
    }

    private static void assertLosslessAttributeAbsent(final IIOMetadataNode lossless) {
        assertNull(attribute(lossless, VALUE),
                   "Lossless value attribute should be absent, meaning TRUE (the default)");
    }

    // ----- No compression tag (default) -----

    @Test
    public void testNoCompressionTagDefaultsToNone() {
        IIOMetadataNode compression = compressionNode(new TIFFImageMetadata());

        assertEquals("Compression", compression.getNodeName());
        assertEquals("None", compressionTypeName(compression));
    }

    @Test
    public void testNoCompressionTagHasNoLosslessChild() {
        IIOMetadataNode compression = compressionNode(new TIFFImageMetadata());

        assertNull(childElement(compression, LOSSLESS), "Uncompressed data should not have a Lossless node");
    }

    // ----- Explicit COMPRESSION_NONE -----

    @Test
    public void testCompressionNone() {
        IIOMetadataNode compression = compressionNodeFor(TIFFBaseline.COMPRESSION_NONE);

        assertEquals("Compression", compression.getNodeName());
        assertEquals("None", compressionTypeName(compression));
        assertNull(childElement(compression, LOSSLESS), "Uncompressed data should not have a Lossless node");
    }

