    public TIFFImageMetadata(final Directory ifd) {
        super(true, TIFFImageMetadataFormat.SUN_NATIVE_IMAGE_METADATA_FORMAT_NAME, TIFFImageMetadataFormat.class.getName(), null, null);
        this.ifd = Validate.notNull(ifd, "IFD");
        this.original = ifd;
    }

