package com.twelvemonkeys.imageio.plugins.tiff;

import com.twelvemonkeys.imageio.metadata.Entry;
import com.twelvemonkeys.imageio.metadata.tiff.TIFF;
import com.twelvemonkeys.imageio.metadata.tiff.TIFFEntry;
import org.junit.jupiter.api.Test;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import javax.imageio.metadata.IIOMetadataNode;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for {@link TIFFImageMetadata#getStandardDataNode()}.
 *
 * @author Harald Kuhr
 */
class TIFFImageMetadataGetStandardDataNodeTests {

    private static IIOMetadataNode dataNode(final Entry... entries) {
        TIFFImageMetadata metadata = new TIFFImageMetadata(Arrays.asList(entries));
        IIOMetadataNode node = metadata.getStandardDataNode();

        assertNotNull(node, "getStandardDataNode must not return null");
        return node;
    }

    private static IIOMetadataNode child(final IIOMetadataNode parent, final String name) {
        NodeList nodes = parent.getElementsByTagName(name);
        assertEquals(1, nodes.getLength(), "Expected exactly one \"" + name + "\" node");
        return (IIOMetadataNode) nodes.item(0);
    }

    private static String valueOf(final IIOMetadataNode parent, final String name) {
        IIOMetadataNode node = child(parent, name);
        assertTrue(node.hasAttribute("value"), "Node \"" + name + "\" should have a \"value\" attribute");
        return node.getAttribute("value");
    }

    private static List<String> childNames(final IIOMetadataNode parent) {
        List<String> names = new ArrayList<>();
        NodeList children = parent.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node node = children.item(i);
            names.add(node.getNodeName());
        }
        return names;
    }

    // Defaults / structure

    @Test
    void testDataNodeNameAndChildren() {
        IIOMetadataNode data = dataNode();

        assertEquals("Data", data.getNodeName());
        assertEquals(Arrays.asList("PlanarConfiguration", "SampleFormat", "BitsPerSample", "SampleMSB"), childNames(data));
    }

    @Test
    void testDataNodeDefaultsForEmptyIFD() {
        IIOMetadataNode data = dataNode();

        assertEquals("PixelInterleaved", valueOf(data, "PlanarConfiguration"));
        assertEquals("UnsignedIntegral", valueOf(data, "SampleFormat"));
        assertEquals("1", valueOf(data, "BitsPerSample"));
        assertEquals("0", valueOf(data, "SampleMSB"));
    }

    @Test
    void testEachInvocationCreatesNewNode() {
        TIFFImageMetadata metadata = new TIFFImageMetadata();

        IIOMetadataNode first = metadata.getStandardDataNode();
        IIOMetadataNode second = metadata.getStandardDataNode();

        assertNotSame(first, second, "A new tree should be created for each invocation");
        assertEquals("Data", second.getNodeName());
        assertEquals("PixelInterleaved", valueOf(second, "PlanarConfiguration"));
    }

    // PlanarConfiguration

    @Test
    void testPlanarConfigurationChunky() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_PLANAR_CONFIGURATION, (short) TIFFBaseline.PLANARCONFIG_CHUNKY));

        assertEquals("PixelInterleaved", valueOf(data, "PlanarConfiguration"));
    }

    @Test
    void testPlanarConfigurationPlanar() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_PLANAR_CONFIGURATION, (short) TIFFExtension.PLANARCONFIG_PLANAR));

        assertEquals("PlaneInterleaved", valueOf(data, "PlanarConfiguration"));
    }

    @Test
    void testPlanarConfigurationPlanarFromArrayValue() {
        IIOMetadataNode data = dataNode(
                new TIFFEntry(TIFF.TAG_PLANAR_CONFIGURATION, new short[]{(short) TIFFExtension.PLANARCONFIG_PLANAR, (short) TIFFExtension.PLANARCONFIG_PLANAR})
        );

        assertEquals("PlaneInterleaved", valueOf(data, "PlanarConfiguration"));
    }

    @Test
    void testPlanarConfigurationUnknownValue() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_PLANAR_CONFIGURATION, (short) 3));

        assertEquals("Unknown 3", valueOf(data, "PlanarConfiguration"));
    }

    @Test
    void testPlanarConfigurationZeroIsUnknown() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_PLANAR_CONFIGURATION, (short) 0));

        assertEquals("Unknown 0", valueOf(data, "PlanarConfiguration"));
    }

    @Test
    void testPlanarConfigurationUnsupportedValueTypeThrows() {
        TIFFImageMetadata metadata = new TIFFImageMetadata(
                Arrays.asList(new TIFFEntry(TIFF.TAG_PLANAR_CONFIGURATION, "not a number"))
        );

        assertThrows(IllegalArgumentException.class, metadata::getStandardDataNode);
    }

    // SampleFormat (and its dependency on PhotometricInterpretation)

    @Test
    void testSampleFormatUnsignedIntegral() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_SAMPLE_FORMAT, (short) TIFFBaseline.SAMPLEFORMAT_UINT));

        assertEquals("UnsignedIntegral", valueOf(data, "SampleFormat"));
    }

    @Test
    void testSampleFormatIndexForPalettePhotometric() {
        IIOMetadataNode data = dataNode(
                new TIFFEntry(TIFF.TAG_SAMPLE_FORMAT, (short) TIFFBaseline.SAMPLEFORMAT_UINT),
                new TIFFEntry(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, (short) TIFFBaseline.PHOTOMETRIC_PALETTE)
        );

        assertEquals("Index", valueOf(data, "SampleFormat"));
    }

    @Test
    void testSampleFormatSignedIntegral() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_SAMPLE_FORMAT, (short) TIFFExtension.SAMPLEFORMAT_INT));

        assertEquals("SignedIntegral", valueOf(data, "SampleFormat"));
    }

    @Test
    void testSampleFormatSignedIntegralIgnoresPalettePhotometric() {
        IIOMetadataNode data = dataNode(
                new TIFFEntry(TIFF.TAG_SAMPLE_FORMAT, (short) TIFFExtension.SAMPLEFORMAT_INT),
                new TIFFEntry(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, (short) TIFFBaseline.PHOTOMETRIC_PALETTE)
        );

        assertEquals("SignedIntegral", valueOf(data, "SampleFormat"));
    }

    @Test
    void testSampleFormatReal() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_SAMPLE_FORMAT, (short) TIFFExtension.SAMPLEFORMAT_FP));

        assertEquals("Real", valueOf(data, "SampleFormat"));
    }

    @Test
    void testSampleFormatUnknown() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_SAMPLE_FORMAT, (short) TIFFExtension.SAMPLEFORMAT_UNDEFINED));

        assertEquals("Unknown " + TIFFExtension.SAMPLEFORMAT_UNDEFINED, valueOf(data, "SampleFormat"));
    }

    @Test
    void testSampleFormatFromArrayUsesFirstValue() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_SAMPLE_FORMAT, new int[]{TIFFExtension.SAMPLEFORMAT_FP, TIFFExtension.SAMPLEFORMAT_FP, TIFFExtension.SAMPLEFORMAT_FP}));

        assertEquals("Real", valueOf(data, "SampleFormat"));
    }

    // BitsPerSample

    @Test
    void testBitsPerSampleSingleValue() {
        IIOMetadataNode data = dataNode(new TIFFEntry(TIFF.TAG_BITS_PER_SAMPLE, (short) 1));

        assertEquals("1", valueOf(data, "BitsPerSample"));
