private String createListValue(final int itemCount, final String... values) {
    StringBuilder buffer = new StringBuilder();

    for (int i = 0; i < itemCount; i++) {
        if (buffer.length() > 0) {
            buffer.append(' ');
        }

        buffer.append(values[i % values.length]);
    }
}

/**
