package com.twelvemonkeys.imageio.plugins.tiff;

import com.twelvemonkeys.imageio.metadata.Entry;
import com.twelvemonkeys.imageio.metadata.tiff.Rational;
import com.twelvemonkeys.imageio.metadata.tiff.TIFF;
import com.twelvemonkeys.imageio.metadata.tiff.TIFFEntry;
import org.junit.jupiter.api.Test;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import javax.imageio.metadata.IIOMetadataFormatImpl;
import javax.imageio.metadata.IIOMetadataNode;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@code TIFFImageMetadata#getStandardDimensionNode()}.
 * <p>
 * The tests describe the observable contract of the standard "Dimension" node:
 * <ul>
 *     <li>Always contains a {@code PixelAspectRatio} child (defaulting to 72 DPI).</li>
 *     <li>Contains an {@code ImageOrientation} child for known orientation values only.</li>
 *     <li>Contains {@code HorizontalPixelSize}/{@code VerticalPixelSize} children for
 *     DPI and centimeter resolution units only.</li>
 *     <li>Contains {@code HorizontalPosition}/{@code VerticalPosition} children only when
 *     both positions are present.</li>
 * </ul>
 */
class TIFFImageMetadataGetStandardDimensionNodeTests {

    private static final double EPSILON = 1e-12;

    // 25.4 millimetres per inch, 10 millimetres per centimetre
    private static final double MM_PER_INCH = 25.4;
    private static final double MM_PER_CM = 10.0;
    private static final double DEFAULT_RESOLUTION = 72.0;

    private static TIFFImageMetadata metadata(Entry... entries) {
        return new TIFFImageMetadata(Arrays.asList(entries));
    }

    private static TIFFEntry rational(int tag, long numerator, long denominator) {
        return new TIFFEntry(tag, new Rational(numerator, denominator));
    }

    private static TIFFEntry integer(int tag, int value) {
        return new TIFFEntry(tag, value);
    }

    private static IIOMetadataNode child(IIOMetadataNode parent, String name) {
        NodeList children = parent.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node node = children.item(i);
            if (name.equals(node.getNodeName())) {
                return (IIOMetadataNode) node;
            }
        }

        return null;
    }

    private static List<String> childNames(IIOMetadataNode parent) {
        List<String> names = new ArrayList<>();
        NodeList children = parent.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            names.add(children.item(i).getNodeName());
        }

        return names;
    }

    private static double valueOf(IIOMetadataNode node) {
        assertNotNull(node, "Expected node to be present");
        assertTrue(node.hasAttribute("value"), "Expected a value attribute on " + node.getNodeName());

        return Double.parseDouble(node.getAttribute("value"));
    }

    @Test
    void emptyMetadataShouldUseDefaultsAndProducePixelAspectRatioOfOne() {
        IIOMetadataNode dimension = metadata().getStandardDimensionNode();

        assertNotNull(dimension);
        assertEquals("Dimension", dimension.getNodeName());

        // Default resolution is 72 DPI for both directions -> aspect ratio 1.0
        IIOMetadataNode pixelAspectRatio = child(dimension, "PixelAspectRatio");
        assertNotNull(pixelAspectRatio, "PixelAspectRatio is always present");
        assertEquals(1.0, valueOf(pixelAspectRatio), EPSILON);

        // Resolution unit defaults to DPI, so pixel sizes must be present
        assertEquals(
                Arrays.asList("PixelAspectRatio", "HorizontalPixelSize", "VerticalPixelSize"),
                childNames(dimension)
        );

        assertEquals(MM_PER_INCH / DEFAULT_RESOLUTION, valueOf(child(dimension, "HorizontalPixelSize")), EPSILON);
        assertEquals(MM_PER_INCH / DEFAULT_RESOLUTION, valueOf(child(dimension, "VerticalPixelSize")), EPSILON);

        // No orientation and no positions in empty metadata
        assertNull(child(dimension, "ImageOrientation"));
        assertNull(child(dimension, "HorizontalPosition"));
        assertNull(child(dimension, "VerticalPosition"));
    }

    @Test
    void equalXAndYResolutionShouldGivePixelAspectRatioOfOne() {
        IIOMetadataNode dimension = metadata(
                rational(TIFF.TAG_X_RESOLUTION, 300, 1),
                rational(TIFF.TAG_Y_RESOLUTION, 300, 1)
        ).getStandardDimensionNode();

        assertEquals(1.0, valueOf(child(dimension, "PixelAspectRatio")), EPSILON);
        assertEquals(MM_PER_INCH / 300.0, valueOf(child(dimension, "HorizontalPixelSize")), EPSILON);
        assertEquals(MM_PER_INCH / 300.0, valueOf(child(dimension, "VerticalPixelSize")), EPSILON);
    }

    @Test
    void differentXAndYResolutionShouldReflectInPixelAspectRatioAndPixelSizes() {
        // 300 DPI horizontally, 150 DPI vertically -> pixel is twice as high as wide
        IIOMetadataNode dimension = metadata(
                rational(TIFF.TAG_X_RESOLUTION, 300, 1),
                rational(TIFF.TAG_Y_RESOLUTION, 150, 1)
        ).getStandardDimensionNode();

        double pixelAspectRatio = valueOf(child(dimension, "PixelAspectRatio"));
        assertEquals((1.0 / 300.0) / (1.0 / 150.0), pixelAspectRatio, EPSILON);
        assertEquals(0.5, pixelAspectRatio, EPSILON);

        assertEquals(MM_PER_INCH / 300.0, valueOf(child(dimension, "HorizontalPixelSize")), EPSILON);
        assertEquals(MM_PER_INCH / 150.0, valueOf(child(dimension, "VerticalPixelSize")), EPSILON);
    }

    @Test
    void resolutionValueShouldBeReadAsNumberRegardlessOfRationalRepresentation() {
        // Rational 200/1 == 200 DPI, but expressed as a non-normalized rational
        IIOMetadataNode dimension = metadata(
                rational(TIFF.TAG_X_RESOLUTION, 400, 2),
                rational(TIFF.TAG_Y_RESOLUTION, 400, 2)
        ).getStandardDimensionNode();

        assertEquals(1.0, valueOf(child(dimension, "PixelAspectRatio")), EPSILON);
        assertEquals(MM_PER_INCH / 200.0, valueOf(child(dimension, "HorizontalPixelSize")), EPSILON);
        assertEquals(MM_PER_INCH / 200.0, valueOf(child(dimension, "VerticalPixelSize")), EPSILON);
    }

    @Test
    void explicitDpiResolutionUnitShouldBehaveLikeDefault() {
        IIOMetadataNode dimension = metadata(
                integer(TIFF.TAG_RESOLUTION_UNIT, TIFFBaseline.RESOLUTION_UNIT_DPI)
        ).getStandardDimensionNode();

        assertEquals(
                Arrays.asList("PixelAspectRatio", "HorizontalPixelSize", "VerticalPixelSize"),
                childNames(dimension)
        );
        assertEquals(MM_PER_INCH / DEFAULT_RESOLUTION, valueOf(child(dimension, "HorizontalPixelSize")), EPSILON);
        assertEquals(MM_PER_INCH / DEFAULT_RESOLUTION, valueOf(child(dimension, "VerticalPixelSize")), EPSILON);
    }

    @Test
    void centimeterResolutionUnitShouldScalePixelSizesByTen() {
        IIOMetadataNode dimension = metadata(
                integer(TIFF.TAG_RESOLUTION_UNIT, TIFFBaseline.RESOLUTION_UNIT_CENTIMETER)
        ).getStandardDimensionNode();

        assertEquals(1.0, valueOf(child(dimension, "PixelAspectRatio")), EPSILON);
        assertEquals(MM_PER_CM / DEFAULT_RESOLUTION, valueOf(child(dimension, "HorizontalPixelSize")), EPSILON);
        assertEquals(MM_PER_CM / DEFAULT_RESOLUTION, valueOf(child(dimension, "VerticalPixelSize")), EPSILON);
    }

    @Test
    void noneResolutionUnitShouldProduceNoPixelSizesNorPositions() {
        IIOMetadataNode dimension = metadata(
                integer(TIFF.TAG_RESOLUTION_UNIT, TIFFBaseline.RESOLUTION_UNIT_NONE),
                rational(TIFF.TAG_X_RESOLUTION, 100, 1),
                rational(TIFF.TAG_Y_RESOLUTION, 200, 1),
                rational(TIFF.TAG_X_POSITION, 1, 1),
                rational(TIFF.TAG_Y_POSITION, 2, 1)
        ).getStandardDimensionNode();

        // Pixel aspect ratio is computed independently of the resolution unit
        assertEquals(2.0, valueOf(child(dimension, "PixelAspectRatio")), EPSILON);

        assertEquals(Arrays.asList("PixelAspectRatio"), childNames(dimension));
        assertNull(child(dimension, "HorizontalPixelSize"));
        assertNull(child(dimension, "VerticalPixelSize"));
        assertNull(child(dimension, "HorizontalPosition"));
        assertNull(child(dimension, "VerticalPosition"));
    }

    @Test
    void allKnownOrientationsShouldMapToStandardNames() {
        assertEquals("Normal", orientationNameFor(TIFFBaseline.ORIENTATION_TOPLEFT));
        assertEquals("FlipH", orientationNameFor(TIFFExtension.ORIENTATION_TOPRIGHT));
        assertEquals("Rotate180", orientationNameFor(TIFFExtension.ORIENTATION_BOTRIGHT));
        assertEquals("FlipV", orientationNameFor(TIFFExtension.ORIENTATION_BOTLEFT));
        assertEquals("FlipHRotate90", orientationNameFor(TIFFExtension.ORIENTATION_LEFTTOP));
        assertEquals("Rotate270", orientationNameFor(TIFFExtension.ORIENTATION_RIGHTTOP));
        assertEquals("FlipVRotate90", orientationNameFor(TIFFExtension.ORIENTATION_RIGHTBOT));
        assertEquals("Rotate90", orientationNameFor(TIFFExtension.ORIENTATION_LEFTBOT));
    }

    private static String orientationNameFor(int orientation) {
        IIOMetadataNode dimension = metadata(integer(TIFF.TAG_ORIENTATION, orientation)).getStandardDimensionNode();
        IIOMetadataNode imageOrientation = child(dimension, "ImageOrientation");

        assertNotNull(imageOrientation, "Expected ImageOrientation for orientation " + orientation);
        assertEquals("ImageOrientation", imageOrientation.getNodeName());

        return imageOrientation.getAttribute("value");
    }

    @Test
    void unknownOrientationShouldProduceNoImageOrientationNode() {
        for (int orientation : new int[]{0, 9, -1, Integer.MAX_VALUE}) {
            IIOMetadataNode dimension = metadata(integer(TIFF.TAG_ORIENTATION, orientation)).getStandardDimensionNode();

            assertNotNull(dimension);
            assertNull(child(dimension, "ImageOrientation"), "No ImageOrientation expected for " + orientation);
        }
    }

    @Test
    void orientationValuesInArrayTypesShouldBeSupported() {
        IIOMetadataNode fromInts = metadata(new TIFFEntry(TIFF.TAG_ORIENTATION, new int[]{TIFFExtension.ORIENTATION_RIGHTTOP}))
                .getStandardDimensionNode();
        assertEquals("Rotate270", child(fromInts, "ImageOrientation").getAttribute("value"));

        IIOMetadataNode fromShorts = metadata(new TIFFEntry(TIFF.TAG_ORIENTATION, new short[]{(short) TIFFExtension.ORIENTATION_BOTRIGHT}))
                .getStandardDimensionNode();
        assertEquals("Rotate180", child(fromShorts, "ImageOrientation").getAttribute("value"));
    }

    @Test
    void orientationShouldBePlacedAfterPixelAspectRatioAndBeforePixelSizes() {
        IIOMetadataNode dimension = metadata(
                integer(TIFF.TAG_ORIENTATION, TIFFBaseline.ORIENTATION_TOPLEFT)
        ).getStandardDimensionNode();

        assertEquals(
                Arrays.asList("PixelAspectRatio", "ImageOrientation", "HorizontalPixelSize", "VerticalPixelSize"),
                childNames(dimension)
        );
        assertEquals("Normal", child(dimension, "ImageOrientation").getAttribute("value"));
    }

    @Test
    void unsupportedOrientationValueTypeShouldThrowIllegalArgumentException() {
        TIFFImageMetadata metadata = metadata(new TIFFEntry(TIFF.TAG_ORIENTATION, "not a number"));

        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, metadata::getStandardDimensionNode);
        assertTrue(exception.getMessage().contains("Unsupported type"), "Unexpected message: " + exception.getMessage());
    }

    @Test
    void positionsShouldBeIncludedWhenBothArePresent() {
        IIOMetadataNode dimension = metadata(
                rational(TIFF.TAG_X_POSITION, 3, 2),
                rational(TIFF.TAG_Y_POSITION, 2, 1)
        ).getStandardDimensionNode();

        assertEquals(
                Arrays.asList(
                        "PixelAspectRatio", "HorizontalPixelSize", "VerticalPixelSize",
                        "HorizontalPosition", "VerticalPosition"
                ),
                childNames(dimension)
        );

        assertEquals(1.5 * MM_PER_INCH, valueOf(child(dimension, "HorizontalPosition")), EPSILON);
        assertEquals(2.0 * MM_PER_INCH, valueOf(child(dimension, "VerticalPosition")), EPSILON);
    }

    @Test
    void positionsShouldScaleWithCentimeterResolutionUnit() {
        IIOMetadataNode dimension = metadata(
                integer(TIFF.TAG_RESOLUTION_UNIT, TIFFBaseline.RESOLUTION_UNIT_CENTIMETER),
                rational(TIFF.TAG_X_POSITION, 3, 2),
                rational(TIFF.TAG_Y_POSITION, 2, 1)
        ).getStandardDimensionNode();

        assertEquals(1.5 * MM_PER_CM, valueOf(child(dimension, "HorizontalPosition")), EPSILON);
        assertEquals(2.0 * MM_PER_CM, valueOf(child(dimension, "VerticalPosition")), EPSILON);
    }

    @Test
    void positionShouldBeIgnoredWhenOnlyOneIsPresent() {
        IIOMetadataNode onlyX = metadata(rational(TIFF.TAG_X_POSITION, 3, 2)).getStandardDimensionNode();
        assertNull(child(onlyX, "HorizontalPosition"));
        assertNull(child(onlyX, "VerticalPosition"));

        IIOMetadataNode onlyY = metadata(rational(TIFF.TAG_Y_POSITION, 2, 1)).getStandardDimensionNode();
        assertNull(child(onlyY, "HorizontalPosition"));
        assertNull(child(onlyY, "VerticalPosition"));
    }

    @Test
    void positionsShouldBeIgnoredForNoneResolutionUnitEvenWhenBothPresent() {
        IIOMetadataNode dimension = metadata(
                integer(TIFF.TAG_RESOLUTION_UNIT, TIFFBaseline.RESOLUTION_UNIT_NONE),
                rational(TIFF.TAG_X_POSITION, 3, 2),
                rational(TIFF.TAG_Y_POSITION, 2, 1)
        ).getStandardDimensionNode();

        assertNull(child(dimension, "HorizontalPosition"));
        assertNull(child(dimension, "VerticalPosition"));
    }

    @Test
    void xResolutionWithoutYResolutionIsNotToleratedByCurrentImplementation() {
        TIFFImageMetadata metadata = metadata(rational(TIFF.TAG_X_RESOLUTION, 300, 1));

        // Documents current behaviour: a missing Y resolution with a present X resolution
        // results in a NullPointerException rather than falling back to the default.
        assertThrows(NullPointerException.class, metadata::getStandardDimensionNode);
    }

    @Test
    void dimensionNodeShouldBePartOfTheStandardTree() {
        TIFFImageMetadata metadata = metadata(
                rational(TIFF.TAG_X_RESOLUTION, 300, 1),
                rational(TIFF.TAG_Y_RESOLUTION, 300, 1),
                integer(TIFF.TAG_ORIENTATION, TIFFExtension.ORIENTATION_BOTLEFT)
        );

        IIOMetadataNode standardTree =
                (IIOMetadataNode) metadata.getAsTree(IIOMetadataFormatImpl.standardMetadataFormatName);

        assertNotNull(standardTree);
        IIOMetadataNode dimension = child(standardTree, "Dimension");
        assertNotNull(dimension, "Standard metadata tree should contain a Dimension node");

        assertEquals(1.0, valueOf(child(dimension, "PixelAspectRatio")), EPSILON);
        assertEquals("FlipV", child(dimension, "ImageOrientation").getAttribute("value"));
        assertEquals(MM_PER_INCH / 300.0, valueOf(child(dimension, "HorizontalPixelSize")), EPSILON);
    }
}
