                                                                               0x0,
                                                                               DataBuffer.TYPE_INT,
                                                                               false);
    private static final ImageTypeSpecifier TYPE_INT_BGR = createPackedOddBits(ColorSpace.getInstance(ColorSpace.CS_sRGB), 24,
                                                                               0x0000FF,
