package com.twelvemonkeys.imageio.plugins.tiff;

import com.twelvemonkeys.imageio.metadata.tiff.TIFF;
import com.twelvemonkeys.imageio.stream.ByteArrayImageInputStream;
import org.junit.jupiter.api.Test;

import javax.imageio.IIOException;
import javax.imageio.ImageTypeSpecifier;
import java.awt.color.ColorSpace;
import java.awt.image.BandedSampleModel;
import java.awt.image.ColorModel;
import java.awt.image.ComponentColorModel;
import java.awt.image.DataBuffer;
import java.awt.image.IndexColorModel;
import java.awt.image.MultiPixelPackedSampleModel;
import java.awt.image.PixelInterleavedSampleModel;
import java.awt.image.SampleModel;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class TIFFImageReaderGetRawImageTypeTests {

    @Test
    void oneBitBlackIsZeroReturnsOneBitGrayscale() throws IOException {
        ImageTypeSpecifier type = readType(base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 1, 1));

        assertEquals(1, type.getNumBands());
        assertEquals(1, type.getNumComponents());
        assertEquals(1, type.getBitsPerBand(0));

        ComponentColorModel colorModel = assertInstanceOf(ComponentColorModel.class, type.getColorModel());
        assertEquals(ColorSpace.TYPE_GRAY, colorModel.getColorSpace().getType());
        assertFalse(colorModel.hasAlpha());
        assertEquals(DataBuffer.TYPE_BYTE, colorModel.getTransferType());

        SampleModel sampleModel = type.getSampleModel(3, 2);
        assertEquals(3, sampleModel.getWidth());
        assertEquals(2, sampleModel.getHeight());
        assertEquals(DataBuffer.TYPE_BYTE, sampleModel.getDataType());
    }

    @Test
    void oneBitWhiteIsZeroReturnsInvertedIndexedType() throws IOException {
        ImageTypeSpecifier type = readType(base(TIFFBaseline.PHOTOMETRIC_WHITE_IS_ZERO, 1, 1));

        assertEquals(1, type.getNumBands());
        assertEquals(1, type.getBitsPerBand(0));

        IndexColorModel colorModel = assertInstanceOf(IndexColorModel.class, type.getColorModel());
        assertEquals(1, colorModel.getPixelSize());
        assertEquals(2, colorModel.getMapSize());
        assertEquals(255, colorModel.getRed(0));
        assertEquals(255, colorModel.getGreen(0));
        assertEquals(255, colorModel.getBlue(0));
        assertEquals(0, colorModel.getRed(1));
        assertEquals(0, colorModel.getGreen(1));
        assertEquals(0, colorModel.getBlue(1));
        assertEquals(255, colorModel.getAlpha(0));
        assertEquals(255, colorModel.getAlpha(1));
        assertFalse(colorModel.hasAlpha());

        MultiPixelPackedSampleModel sampleModel = assertInstanceOf(MultiPixelPackedSampleModel.class, type.getSampleModel(1, 1));
        assertEquals(1, sampleModel.getPixelBitStride());
        assertEquals(DataBuffer.TYPE_BYTE, sampleModel.getDataType());
    }

    @Test
    void eightBitWhiteIsZeroUsesNormalGrayscalePath() throws IOException {
        ImageTypeSpecifier type = readType(base(TIFFBaseline.PHOTOMETRIC_WHITE_IS_ZERO, 8, 1));

        assertEquals(1, type.getNumBands());
        assertEquals(8, type.getBitsPerBand(0));

        ColorModel colorModel = type.getColorModel();
        assertEquals(ColorSpace.TYPE_GRAY, colorModel.getColorSpace().getType());
        assertFalse(colorModel.hasAlpha());
        assertEquals(DataBuffer.TYPE_BYTE, colorModel.getTransferType());
    }

    @Test
    void twoAndFourBitBlackIsZeroUsePackedGrayscale() throws IOException {
        for (int bits : new int[]{2, 4}) {
            ImageTypeSpecifier type = readType(base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, bits, 1));

            assertEquals(1, type.getNumBands());
            assertEquals(bits, type.getBitsPerBand(0));

            IndexColorModel colorModel = assertInstanceOf(IndexColorModel.class, type.getColorModel());
            assertEquals(bits, colorModel.getPixelSize());
            assertEquals(1 << bits, colorModel.getMapSize());

            MultiPixelPackedSampleModel sampleModel = assertInstanceOf(MultiPixelPackedSampleModel.class, type.getSampleModel(1, 1));
            assertEquals(bits, sampleModel.getPixelBitSize());
        }
    }

    @Test
    void grayWithAlphaWithoutExtraSamplesAssumesUnassociatedAlpha() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 8, 2);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(2, type.getNumBands());
        assertEquals(2, type.getNumComponents());
        assertEquals(8, type.getBitsPerBand(0));
        assertEquals(8, type.getBitsPerBand(1));

        ComponentColorModel colorModel = assertInstanceOf(ComponentColorModel.class, type.getColorModel());
        assertEquals(ColorSpace.TYPE_GRAY, colorModel.getColorSpace().getType());
        assertTrue(colorModel.hasAlpha());
        assertFalse(colorModel.isAlphaPremultiplied());
        assertEquals(DataBuffer.TYPE_BYTE, colorModel.getTransferType());
        assertInstanceOf(PixelInterleavedSampleModel.class, type.getSampleModel(1, 1));
    }

    @Test
    void grayWithAssociatedAlphaIsPremultiplied() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 16, 2)
                .addShort(TIFF.TAG_EXTRA_SAMPLES, TIFFBaseline.EXTRASAMPLE_ASSOCIATED_ALPHA);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(2, type.getNumBands());
        assertEquals(16, type.getBitsPerBand(0));

        ColorModel colorModel = type.getColorModel();
        assertEquals(ColorSpace.TYPE_GRAY, colorModel.getColorSpace().getType());
        assertTrue(colorModel.hasAlpha());
        assertTrue(colorModel.isAlphaPremultiplied());
        assertEquals(DataBuffer.TYPE_USHORT, colorModel.getTransferType());
    }

    @Test
    void grayWithAlphaPlanarUsesBandedSampleModel() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 8, 2)
                .addShort(TIFF.TAG_PLANAR_CONFIGURATION, TIFFExtension.PLANARCONFIG_PLANAR);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(2, type.getNumBands());
        BandedSampleModel sampleModel = assertInstanceOf(BandedSampleModel.class, type.getSampleModel(1, 1));
        assertEquals(2, sampleModel.getNumBands());
        assertEquals(0, sampleModel.getBankIndices()[0]);
        assertEquals(1, sampleModel.getBankIndices()[1]);
        assertEquals(0, sampleModel.getBandOffsets()[0]);
        assertEquals(0, sampleModel.getBandOffsets()[1]);
    }

    @Test
    void unsupportedGrayBitsPerSampleThrows() {
        IIOException exception = assertThrows(IIOException.class,
                () -> readType(base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 3, 1)));
        assertTrue(exception.getMessage().contains("Unsupported BitsPerSample"));
    }

    @Test
    void extraSamplesWithSubByteGrayThrows() {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 4, 2)
                .addShort(TIFF.TAG_EXTRA_SAMPLES, TIFFBaseline.EXTRASAMPLE_UNSPECIFIED);

        IIOException exception = assertThrows(IIOException.class, () -> readType(tiff));
        assertTrue(exception.getMessage().contains("ExtraSamples not supported"));
    }

    @Test
    void rgbThreeSamplesChunkyReturnsInterleavedSrgb() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 8, 3);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(3, type.getNumBands());
        assertEquals(3, type.getNumComponents());

        ComponentColorModel colorModel = assertInstanceOf(ComponentColorModel.class, type.getColorModel());
        assertEquals(ColorSpace.TYPE_RGB, colorModel.getColorSpace().getType());
        assertFalse(colorModel.hasAlpha());
        assertEquals(DataBuffer.TYPE_BYTE, colorModel.getTransferType());
        assertInstanceOf(PixelInterleavedSampleModel.class, type.getSampleModel(1, 1));
    }

    @Test
    void rgbThreeSamplesPlanarReturnsBandedType() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 16, 3)
                .addShort(TIFF.TAG_PLANAR_CONFIGURATION, TIFFExtension.PLANARCONFIG_PLANAR);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(3, type.getNumBands());
        ComponentColorModel colorModel = assertInstanceOf(ComponentColorModel.class, type.getColorModel());
        assertEquals(ColorSpace.TYPE_RGB, colorModel.getColorSpace().getType());
        assertEquals(DataBuffer.TYPE_USHORT, colorModel.getTransferType());
        assertInstanceOf(BandedSampleModel.class, type.getSampleModel(1, 1));
    }

    @Test
    void rgbaWithoutExtraSamplesUsesAlpha() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 8, 4);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(4, type.getNumBands());
        ColorModel colorModel = type.getColorModel();
        assertEquals(ColorSpace.TYPE_RGB, colorModel.getColorSpace().getType());
        assertTrue(colorModel.hasAlpha());
        assertFalse(colorModel.isAlphaPremultiplied());
    }

    @Test
    void rgbaWithAssociatedExtraSampleIsPremultiplied() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 8, 4)
                .addShort(TIFF.TAG_EXTRA_SAMPLES, TIFFBaseline.EXTRASAMPLE_ASSOCIATED_ALPHA);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(4, type.getNumBands());
        ColorModel colorModel = type.getColorModel();
        assertTrue(colorModel.hasAlpha());
        assertTrue(colorModel.isAlphaPremultiplied());
    }

    @Test
    void rgbTwoBitChunkyUsesPackedTypeWithCorrectMasks() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 2, 3);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(3, type.getNumBands());
        assertEquals(2, type.getBitsPerBand(0));

        ColorModel colorModel = type.getColorModel();
        assertEquals(DataBuffer.TYPE_BYTE, colorModel.getTransferType());
        assertEquals(6, colorModel.getPixelSize());
        assertFalse(colorModel.hasAlpha());
        assertInstanceOf(PixelInterleavedSampleModel.class, type.getSampleModel(1, 1));
    }

    @Test
    void rgbFourBitChunkyUsesPackedUshortType() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 4, 3);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(3, type.getNumBands());
        assertEquals(4, type.getBitsPerBand(0));

        ColorModel colorModel = type.getColorModel();
        assertEquals(DataBuffer.TYPE_USHORT, colorModel.getTransferType());
        assertEquals(12, colorModel.getPixelSize());
        assertFalse(colorModel.hasAlpha());
    }

    @Test
    void rgbaTwoAndFourBitChunkyUsesPackedTypeWithAlpha() throws IOException {
        for (int bits : new int[]{2, 4}) {
            ImageTypeSpecifier type = readType(base(TIFFBaseline.PHOTOMETRIC_RGB, bits, 4));

            assertEquals(4, type.getNumBands());
            ColorModel colorModel = type.getColorModel();
            assertTrue(colorModel.hasAlpha());
            assertEquals(bits * 4, colorModel.getPixelSize());
        }
    }

    @Test
    void rgbUnsupportedBitsThrows() {
        IIOException exception = assertThrows(IIOException.class,
                () -> readType(base(TIFFBaseline.PHOTOMETRIC_RGB, 1, 3)));
        assertTrue(exception.getMessage().contains("Unsupported SamplesPerPixel/BitsPerSample"));
    }

    @Test
    void rgbaUnsupportedBitsThrows() {
        IIOException exception = assertThrows(IIOException.class,
                () -> readType(base(TIFFBaseline.PHOTOMETRIC_RGB, 1, 4)));
        assertTrue(exception.getMessage().contains("Unsupported SamplesPerPixel/BitsPerSample"));
    }

    @Test
    void rgbInvalidPlanarConfigurationThrows() {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 8, 3)
                .addShort(TIFF.TAG_PLANAR_CONFIGURATION, 3);

        IIOException exception = assertThrows(IIOException.class, () -> readType(tiff));
        assertTrue(exception.getMessage().contains("Unsupported PlanarConfiguration"));
    }

    @Test
    void rgbExtraUnspecifiedSampleHasNoAlphaButRetainsExtraBand() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 8, 4)
                .addShort(TIFF.TAG_EXTRA_SAMPLES, TIFFBaseline.EXTRASAMPLE_UNSPECIFIED);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(4, type.getNumBands());
        assertEquals(4, type.getNumComponents());
        assertFalse(type.getColorModel().hasAlpha());
        PixelInterleavedSampleModel sampleModel = assertInstanceOf(PixelInterleavedSampleModel.class, type.getSampleModel(1, 1));
        assertEquals(4, sampleModel.getNumBands());
    }

    private static TiffBuilder base(int photometricInterpretation, int bitsPerSample, int samplesPerPixel) {
        return new TiffBuilder()
                .addLong(TIFF.TAG_IMAGE_WIDTH, 1)
                .addLong(TIFF.TAG_IMAGE_LENGTH, 1)
                .addShort(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, photometricInterpretation)
                .addShort(TIFF.TAG_SAMPLES_PER_PIXEL, samplesPerPixel)
                .addShort(TIFF.TAG_BITS_PER_SAMPLE, repeat(bitsPerSample, samplesPerPixel));
    }

    private static int[] repeat(int value, int count) {
        int[] values = new int[count];
        java.util.Arrays.fill(values, value);
        return values;
    }

    private static ImageTypeSpecifier readType(TiffBuilder tiff) throws IOException {
        byte[] data = tiff.build();
        try (ByteArrayImageInputStream input = new ByteArrayImageInputStream(data)) {
            TIFFImageReader reader = new TIFFImageReaderSpi().createReaderInstance();
            reader.setInput(input);
            try {
                return reader.getRawImageType(0);
            }
            finally {
                reader.dispose();
            }
        }
    }

    private static final class TiffBuilder {
        private static final short TYPE_SHORT = 3;
        private static final short TYPE_LONG = 4;

        private final List<Entry> entries = new ArrayList<>();

        TiffBuilder addShort(int tag, int... values) {
            return add(tag, TYPE_SHORT, values);
        }

        TiffBuilder addLong(int tag, long... values) {
            return add(tag, TYPE_LONG, values);
        }

        private TiffBuilder add(int tag, short type, int... values) {
            byte[] data = new byte[values.length * (type == TYPE_SHORT ? 2 : 4)];
            int offset = 0;
            for (int value : values) {
                if (type == TYPE_SHORT) {
                    data[offset++] = (byte) value;
                    data[offset++] = (byte) (value >>> 8);
                }
                else {
                    data[offset++] = (byte) value;
                    data[offset++] = (byte) (value >>> 8);
                    data[offset++] = (byte) (value >>> 16);
                    data[offset++] = (byte) (value >>> 24);
                }
            }
            entries.add(new Entry(tag, type, values.length, data));
            return this;
        }

        byte[] build() {
            int ifdOffset = 8;
            int ifdSize = 2 + entries.size() * 12 + 4;
            int externalOffset = ifdOffset + ifdSize;
            int[] offsets = new int[entries.size()];

            for (int i = 0; i < entries.size(); i++) {
                Entry entry = entries.get(i);
                if (entry.data.length > 4) {
                    if ((externalOffset & 1) != 0) {
                        externalOffset++;
                    }
                    offsets[i] = externalOffset;
                    externalOffset += entry.data.length;
                }
            }

            byte[] bytes = new byte[externalOffset];
            bytes[0] = 'I';
            bytes[1] = 'I';
            putShort(bytes, 2, TIFF.TIFF_MAGIC);
            putInt(bytes, 4, ifdOffset);
            putShort(bytes, ifdOffset, entries.size());

            int entryOffset = ifdOffset + 2;
            for (int i = 0; i < entries.size(); i++) {
                Entry entry = entries.get(i);
                putShort(bytes, entryOffset, entry.tag);
                putShort(bytes, entryOffset + 2, entry.type);
                putInt(bytes, entryOffset + 4, entry.count);

                if (entry.data.length <= 4) {
                    System.arraycopy(entry.data, 0, bytes, entryOffset + 8, entry.data.length);
                }
                else {
                    putInt(bytes, entryOffset + 8, offsets[i]);
                    System.arraycopy(entry.data, 0, bytes, offsets[i], entry.data.length);
                }

                entryOffset += 12;
            }

            putInt(bytes, entryOffset, 0);
            return bytes;
        }

        private static void putShort(byte[] bytes, int offset, int value) {
            bytes[offset] = (byte) value;
            bytes[offset + 1] = (byte) (value >>> 8);
        }

        private static void putInt(byte[] bytes, int offset, int value) {
            bytes[offset] = (byte) value;
            bytes[offset + 1] = (byte) (value >>> 8);
            bytes[offset + 2] = (byte) (value >>> 16);
            bytes[offset + 3] = (byte) (value >>> 24);
        }

        private static final class Entry {
            final int tag;
            final short type;
            final int count;
            final byte[] data;

            Entry(int tag, short type, int count, byte[] data) {
                this.tag = tag;
                this.type = type;
                this.count = count;
                this.data = data;
            }
        }
    }
}
