                () -> readType(base(42, 8, 1)));
        assertTrue(exception.getMessage().contains("Unknown TIFF PhotometricInterpretation"));
    }

    @Test
    void missingPhotometricFallsBackToWhiteIsZeroForCcittCompression() throws IOException {
        TiffBuilder tiff = withoutPhotometric(1, 1)
                .addShort(TIFF.TAG_COMPRESSION, TIFFExtension.COMPRESSION_CCITT_T6);

        ImageTypeSpecifier type = readType(tiff);

        IndexColorModel colorModel = assertInstanceOf(IndexColorModel.class, type.getColorModel());
        assertEquals(255, colorModel.getRed(0));
        assertEquals(0, colorModel.getRed(1));
    }

    @Test
    void missingPhotometricFallsBackToPaletteWhenColorMapPresent() throws IOException {
        TiffBuilder tiff = withoutPhotometric(8, 1)
                .addShort(TIFF.TAG_COLOR_MAP, palette(256));

        ImageTypeSpecifier type = readType(tiff);

        assertInstanceOf(IndexColorModel.class, type.getColorModel());
        assertEquals(256, ((IndexColorModel) type.getColorModel()).getMapSize());
    }

    @Test
    void missingPhotometricFallsBackToRgbForThreeOpaqueSamples() throws IOException {
        TiffBuilder tiff = withoutPhotometric(8, 3);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(3, type.getNumBands());
        assertEquals(ColorSpace.TYPE_RGB, type.getColorModel().getColorSpace().getType());
    }

    @Test
    void missingPhotometricFallsBackToSeparatedForFourOpaqueSamples() throws IOException {
        TiffBuilder tiff = withoutPhotometric(8, 4);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(4, type.getNumBands());
        assertEquals(ColorSpace.TYPE_CMYK, type.getColorModel().getColorSpace().getType());
    }

    @Test
    void missingPhotometricFallsBackToBlackIsZeroByDefault() throws IOException {
        TiffBuilder tiff = withoutPhotometric(8, 1);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(1, type.getNumBands());
        assertEquals(ColorSpace.TYPE_GRAY, type.getColorModel().getColorSpace().getType());
    }

    @Test
    void missingPhotometricEmitsWarning() throws IOException {
        List<String> warnings = new ArrayList<>();

        readType(withoutPhotometric(8, 3), warnings);

        assertTrue(warnings.stream().anyMatch(message -> message.contains("Missing PhotometricInterpretation")));
    }

    @Test
    void compatibleIccProfileForRgbIsAccepted() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 8, 3)
                .addUndefined(TIFF.TAG_ICC_PROFILE, iccProfile(ColorSpace.CS_sRGB));
        List<String> warnings = new ArrayList<>();

        ImageTypeSpecifier type = readType(tiff, warnings);

        assertEquals(ColorSpace.TYPE_RGB, type.getColorModel().getColorSpace().getType());
        assertTrue(warnings.isEmpty(), "Unexpected warnings: " + warnings);
    }

    @Test
    void incompatibleIccProfileForGrayWarnsAndFallsBackToGray() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 8, 1)
                .addUndefined(TIFF.TAG_ICC_PROFILE, iccProfile(ColorSpace.CS_sRGB));
        List<String> warnings = new ArrayList<>();

        ImageTypeSpecifier type = readType(tiff, warnings);

        assertEquals(ColorSpace.TYPE_GRAY, type.getColorModel().getColorSpace().getType());
        assertTrue(warnings.stream().anyMatch(message -> message.contains("incompatible with image data (GRAY/type 6)")));
    }

    @Test
    void oneBitWhiteIsZeroIgnoresEmbeddedIccProfileWithWarning() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_WHITE_IS_ZERO, 1, 1)
                .addUndefined(TIFF.TAG_ICC_PROFILE, iccProfile(ColorSpace.CS_sRGB));
        List<String> warnings = new ArrayList<>();

        ImageTypeSpecifier type = readType(tiff, warnings);

        assertInstanceOf(IndexColorModel.class, type.getColorModel());
        assertTrue(warnings.stream().anyMatch(message -> message.contains("Ignoring embedded ICC color profile")));
    }

    @Test
    void signedIntegerSampleFormatSelectsSignedShortForRgb() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 16, 3)
                .addShort(TIFF.TAG_SAMPLE_FORMAT, repeat(TIFFExtension.SAMPLEFORMAT_INT, 3));

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(3, type.getNumBands());
        assertEquals(DataBuffer.TYPE_SHORT, type.getColorModel().getTransferType());
    }

    @Test
    void floatingPointSampleFormatSelectsFloatForRgb() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 32, 3)
                .addShort(TIFF.TAG_SAMPLE_FORMAT, repeat(TIFFExtension.SAMPLEFORMAT_FP, 3));

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(3, type.getNumBands());
        assertEquals(DataBuffer.TYPE_FLOAT, type.getColorModel().getTransferType());
    }

    @Test
    void floatingPointSampleFormatSelectsDoubleForSixtyFourBitGray() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 64, 1)
                .addShort(TIFF.TAG_SAMPLE_FORMAT, TIFFExtension.SAMPLEFORMAT_FP);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(1, type.getNumBands());
        assertEquals(DataBuffer.TYPE_DOUBLE, type.getColorModel().getTransferType());
    }

    @Test
    void undefinedSampleFormatBehavesAsUnsignedInteger() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 8, 1)
                .addShort(TIFF.TAG_SAMPLE_FORMAT, TIFFExtension.SAMPLEFORMAT_UNDEFINED);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(DataBuffer.TYPE_BYTE, type.getColorModel().getTransferType());
    }

    @Test
    void invalidSignedIntegerBitsPerSampleThrows() {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 12, 1)
                .addShort(TIFF.TAG_SAMPLE_FORMAT, TIFFExtension.SAMPLEFORMAT_INT);

        IIOException exception = assertThrows(IIOException.class, () -> readType(tiff));
        assertTrue(exception.getMessage().contains("Unsupported BitsPerSample for SampleFormat 2"));
    }

    @Test
    void invalidFloatingPointBitsPerSampleThrows() {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 8, 1)
                .addShort(TIFF.TAG_SAMPLE_FORMAT, TIFFExtension.SAMPLEFORMAT_FP);

        IIOException exception = assertThrows(IIOException.class, () -> readType(tiff));
        assertTrue(exception.getMessage().contains("Unsupported BitsPerSample for SampleFormat 3"));
    }

    @Test
    void unknownSampleFormatThrows() {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 8, 1)
                .addShort(TIFF.TAG_SAMPLE_FORMAT, 7);

        IIOException exception = assertThrows(IIOException.class, () -> readType(tiff));
        assertTrue(exception.getMessage().contains("Unknown TIFF SampleFormat"));
    }

    @Test
    void variableSampleFormatThrows() {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 8, 3)
                .addShort(TIFF.TAG_SAMPLE_FORMAT, 1, 2, 3);

        IIOException exception = assertThrows(IIOException.class, () -> readType(tiff));
        assertTrue(exception.getMessage().contains("Variable TIFF SampleFormat not supported"));
    }

    @Test
    void variableBitsPerSampleThrows() {
        TiffBuilder tiff = new TiffBuilder()
                .addLong(TIFF.TAG_IMAGE_WIDTH, 1)
                .addLong(TIFF.TAG_IMAGE_HEIGHT, 1)
                .addShort(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, TIFFBaseline.PHOTOMETRIC_RGB)
                .addShort(TIFF.TAG_SAMPLES_PER_PIXEL, 3)
                .addShort(TIFF.TAG_BITS_PER_SAMPLE, 8, 16, 8);

        IIOException exception = assertThrows(IIOException.class, () -> readType(tiff));
        assertTrue(exception.getMessage().contains("Variable BitsPerSample not supported"));
    }

    @Test
    void fiveSixFiveBitsPerSamplePassesVariabilityCheckButHasNoSupportedRawType() {
        TiffBuilder tiff = new TiffBuilder()
                .addLong(TIFF.TAG_IMAGE_WIDTH, 1)
                .addLong(TIFF.TAG_IMAGE_HEIGHT, 1)
                .addShort(TIFF.TAG_PHOTOMETRIC_INTERPRETATION, TIFFBaseline.PHOTOMETRIC_RGB)
                .addShort(TIFF.TAG_SAMPLES_PER_PIXEL, 3)
                .addShort(TIFF.TAG_BITS_PER_SAMPLE, 5, 6, 5);

        IIOException exception = assertThrows(IIOException.class, () -> readType(tiff));
        assertFalse(exception.getMessage().contains("Variable BitsPerSample"));
        assertTrue(exception.getMessage().contains("Unsupported SamplesPerPixel/BitsPerSample"));
    }

    @Test
    void imageIndexOutOfBoundsThrows() {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 8, 1);

        assertThrows(IndexOutOfBoundsException.class, () -> readType(tiff, 1));
    }

