    void thirtyTwoBitUintGrayUsesIntTransferType() throws IOException {
        ImageTypeSpecifier type = readType(base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 32, 1));

        assertEquals(1, type.getNumBands());
        assertEquals(32, type.getBitsPerBand(0));
        assertEquals(DataBuffer.TYPE_INT, type.getColorModel().getTransferType());
    }

    @Test
    void thirtyTwoBitUintRgbChunkyUsesIntTransferType() throws IOException {
        ImageTypeSpecifier type = readType(base(TIFFBaseline.PHOTOMETRIC_RGB, 32, 3));

        assertEquals(3, type.getNumBands());
        assertEquals(DataBuffer.TYPE_INT, type.getColorModel().getTransferType());
        assertInstanceOf(PixelInterleavedSampleModel.class, type.getSampleModel(1, 1));
    }

    @Test
    void thirtyTwoBitUintRgbPlanarUsesBandedIntType() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_RGB, 32, 3)
                .addShort(TIFF.TAG_PLANAR_CONFIGURATION, TIFFExtension.PLANARCONFIG_PLANAR);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(3, type.getNumBands());
        assertEquals(DataBuffer.TYPE_INT, type.getColorModel().getTransferType());
        assertInstanceOf(BandedSampleModel.class, type.getSampleModel(1, 1));
    }

    @Test
    void compatibleGrayIccProfileForGrayIsAccepted() throws IOException {
        TiffBuilder tiff = base(TIFFBaseline.PHOTOMETRIC_BLACK_IS_ZERO, 8, 1)
                .addUndefined(TIFF.TAG_ICC_PROFILE, iccProfile(ColorSpace.CS_GRAY));
        List<String> warnings = new ArrayList<>();

        ImageTypeSpecifier type = readType(tiff, warnings);

        assertEquals(ColorSpace.TYPE_GRAY, type.getColorModel().getColorSpace().getType());
        assertTrue(warnings.isEmpty(), "Unexpected warnings: " + warnings);
    }

    @Test
    void missingPhotometricWithJpegCompressionFallsBackToYcbcrRgbHandling() throws IOException {
        TiffBuilder tiff = withoutPhotometric(8, 3)
                .addShort(TIFF.TAG_COMPRESSION, TIFFExtension.COMPRESSION_JPEG);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(3, type.getNumBands());
        assertEquals(ColorSpace.TYPE_RGB, type.getColorModel().getColorSpace().getType());
    }

    @Test
    void missingPhotometricAccountsForExtraSamplesWhenGuessingRgb() throws IOException {
        TiffBuilder tiff = withoutPhotometric(8, 4)
                .addShort(TIFF.TAG_EXTRA_SAMPLES, TIFFBaseline.EXTRASAMPLE_UNSPECIFIED);

        ImageTypeSpecifier type = readType(tiff);

        assertEquals(4, type.getNumBands());
        assertEquals(ColorSpace.TYPE_RGB, type.getColorModel().getColorSpace().getType());
        assertFalse(type.getColorModel().hasAlpha());
        assertInstanceOf(PixelInterleavedSampleModel.class, type.getSampleModel(1, 1));
    }

