                {dest[1][0], dest[1][1], dest[1][2], dest[1][3]},
                {dest[2][0], dest[2][1], dest[2][2], dest[2][3]},
                {dest[3][0], dest[3][1], dest[3][2], dest[3][3]},
        };
    }

