package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Tests for {@code LoopFilter.loopFilterSimpleBlock}.
 * <p>
 * The simple loop filter only ever modifies the two pixels adjacent to an edge
 * (P0 and Q0 of the corresponding segment), moving them towards each other.
 * For a segment with {@code P1 != Q1}, the "outer tap" term is
 * {@code clamp(P1 - Q1)} and the applied correction is derived from
 * {@code a = clamp(clamp(P1 - Q1) + 3 * (Q0 - P0))}:
 * {@code Q0 += a >> 3} (rounded) and {@code P0 -= b >> 3} (rounded).
 * <p>
 * An edge is filtered at all only if
 * {@code |P0 - Q0| * 2 + |P1 - Q1| / 2 <= edge_limit}, where
 * {@code edge_limit} is {@code 3 * level + 4} for macro block edges (sharpness
 * 0) and {@code 2 * level + interior_limit} for inner sub block edges.
 */
class LoopFilterLoopFilterSimpleBlockTests {

    private static final SubBlock.Plane Y1 = SubBlock.Plane.Y1;

    /* ------------------------------------------------------------------ */
    /* Construction helpers                                               */
    /* ------------------------------------------------------------------ */

    /** Creates a 4x4 sub block whose rows all have the given constant value. */
    private static int[][] rows(int row0, int row1, int row2, int row3) {
        return new int[][]{
                {row0, row0, row0, row0},
                {row1, row1, row1, row1},
                {row2, row2, row2, row2},
                {row3, row3, row3, row3},
        };
    }

    private static int[][] uniform(int value) {
        return rows(value, value, value, value);
    }

    private static int[][] copy(int[][] source) {
        int[][] copy = new int[4][];
        for (int i = 0; i < 4; i++) {
            copy[i] = source[i].clone();
        }

        return copy;
    }

    private static MacroBlock newMacroBlock(int filterLevel) {
        MacroBlock macroBlock = new MacroBlock(1, 1, false);
        macroBlock.setFilterLevel(filterLevel);

        return macroBlock;
    }

    /** Fills every Y1 sub block of the macro block with the same 4x4 pattern. */
    private static void fillAll(MacroBlock macroBlock, int[][] pattern) {
        fillColumns(macroBlock, 0, pattern);
    }

    /** Fills all Y1 sub blocks of the given sub block column with a 4x4 pattern. */
    private static void fillColumns(MacroBlock macroBlock, int x, int[][] pattern) {
        for (int y = 0; y < 4; y++) {
            macroBlock.getSubBlock(Y1, x, y).setDest(copy(pattern));
        }
    }

    private static int[][][][] snapshot(MacroBlock macroBlock) {
        int[][][][] snapshot = new int[4][4][][];

        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                snapshot[x][y] = copy(macroBlock.getSubBlock(Y1, x, y).getDest());
            }
        }

        return snapshot;
    }

    /* ------------------------------------------------------------------ */
    /* Assertion helpers                                                  */
    /* ------------------------------------------------------------------ */

    private static void assertRow(String message, int[] expected, SubBlock subBlock, int row) {
        assertArrayEquals(expected, subBlock.getDest()[row], message);
    }

    private static void assertUnchanged(String message, MacroBlock macroBlock, int[][][][] snapshot) {
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                int[][] actual = macroBlock.getSubBlock(Y1, x, y).getDest();
                for (int r = 0; r < 4; r++) {
                    assertArrayEquals(snapshot[x][y][r], actual[r],
                            message + ": sub block (x=" + x + ", y=" + y + ") row " + r + " must be untouched");
                }
            }
        }
    }

    /* ------------------------------------------------------------------ */
    /* Tests                                                              */
    /* ------------------------------------------------------------------ */

    @Test
    @DisplayName("Filter level 0 must disable filtering entirely, for any sharpness level")
    void filterLevelZeroLeavesAllPixelsUntouched() {
        for (int sharpness : new int[]{0, 1, 3, 4, 5, 7}) {
            MacroBlock cmb = newMacroBlock(0);
            MacroBlock lmb = newMacroBlock(0);
            MacroBlock tmb = newMacroBlock(0);

            // Small differences at all edges: filtering these would be visible.
            fillAll(cmb, uniform(100));
            fillAll(lmb, uniform(110));
            fillAll(tmb, uniform(110));

            int[][][][] cmbBefore = snapshot(cmb);
            int[][][][] lmbBefore = snapshot(lmb);
            int[][][][] tmbBefore = snapshot(tmb);

            LoopFilter.loopFilterSimpleBlock(cmb, lmb, tmb, sharpness);

            assertUnchanged("sharpness " + sharpness + " cmb", cmb, cmbBefore);
            assertUnchanged("sharpness " + sharpness + " lmb", lmb, lmbBefore);
            assertUnchanged("sharpness " + sharpness + " tmb", tmb, tmbBefore);
        }
    }

    @Test
    @DisplayName("Level 7, sharpness 0: edge difference 25 equals the MB edge limit 3*7+4 and is filtered")
    void leftMacroBlockEdgeIsFilteredWhenDifferenceMatchesEdgeLimit() {
        // interior_limit = 7, sub_bedge_limit = 2*7 + 7 = 21, mbedge_limit = 21 + 4 = 25
        MacroBlock cmb = newMacroBlock(7);
        MacroBlock lmb = newMacroBlock(7);

        fillAll(cmb, uniform(100));
        fillAll(lmb, uniform(110));

        LoopFilter.loopFilterSimpleBlock(cmb, lmb, null, 0);

        // Segment straddling the left macro block edge: P1 = 110, P0 = 110 | Q0 = 100, Q1 = 100.
        // |110 - 100| * 2 + |110 - 100| / 2 = 25 <= 25, so the (simple) filter applies:
        // a = clamp(clamp(110 - 100) + 3 * (100 - 110)) = clamp(10 - 30) = -20
        // P0 += (-20 + 3) >> 3 = -3   -> 110 - 3 = 107
        // Q0 += (-20 + 4) >> 3 = -2   -> 100 - (-2) = 102
        for (int y = 0; y < 4; y++) {
            SubBlock leftNeighbour = lmb.getSubBlock(Y1, 3, y);

            for (int a = 0; a < 4; a++) {
                assertEquals(107, leftNeighbour.getDest()[3][a],
                        "P0 of the left MB edge (lmb, x=3, y=" + y + ") must be moved towards Q0");
                assertEquals(110, leftNeighbour.getDest()[2][a],
                        "P1 must not be modified by the simple filter (lmb, x=3, y=" + y + ")");
                assertEquals(110, leftNeighbour.getDest()[1][a],
                        "P2 must not be modified by the simple filter (lmb, x=3, y=" + y + ")");
            }
        }

        SubBlock edgeSubBlock = cmb.getSubBlock(Y1, 0, 0);
        assertEquals(102, edgeSubBlock.getDest()[0][0], "Q0 of the left MB edge must be moved towards P0");
        assertEquals(102, edgeSubBlock.getDest()[0][1], "Q0 of the left MB edge must be moved towards P0");
        assertEquals(102, edgeSubBlock.getDest()[0][2], "Q0 of the left MB edge must be moved towards P0");
        assertEquals(100, edgeSubBlock.getDest()[1][0], "Q1 must not be modified by the simple filter");

        // Sub blocks that are not adjacent to any filterable edge stay as they are.
        assertRow("cmb interior sub block must be untouched",
                new int[]{100, 100, 100, 100}, cmb.getSubBlock(Y1, 2, 2), 0);
        assertRow("cmb interior sub block must be untouched",
                new int[]{100, 100, 100, 100}, cmb.getSubBlock(Y1, 2, 2), 3);
        assertRow("lmb sub blocks left of the edge must be untouched",
                new int[]{110, 110, 110, 110}, lmb.getSubBlock(Y1, 1, 2), 3);
    }

    @Test
    @DisplayName("Level 6, sharpness 0: edge difference 25 exceeds the MB edge limit 3*6+4 and is not filtered")
    void leftMacroBlockEdgeIsNotFilteredWhenDifferenceExceedsEdgeLimit() {
        // interior_limit = 6, sub_bedge_limit = 2*6 + 6 = 18, mbedge_limit = 18 + 4 = 22 < 25
        MacroBlock cmb = newMacroBlock(6);
        MacroBlock lmb = newMacroBlock(6);

        fillAll(cmb, uniform(100));
        fillAll(lmb, uniform(110));

        int[][][][] cmbBefore = snapshot(cmb);
        int[][][][] lmbBefore = snapshot(lmb);

        LoopFilter.loopFilterSimpleBlock(cmb, lmb, null, 0);

        assertUnchanged("cmb", cmb, cmbBefore);
        assertUnchanged("lmb", lmb, lmbBefore);
    }

    @Test
    @DisplayName("Level 7, sharpness 0: the top macro block edge is filtered like the left one")
    void topMacroBlockEdgeIsFiltered() {
        MacroBlock cmb = newMacroBlock(7);
        MacroBlock tmb = newMacroBlock(7);

        fillAll(cmb, uniform(100));
        fillAll(tmb, uniform(110));

        LoopFilter.loopFilterSimpleBlock(cmb, null, tmb, 0);

        // Same numbers as for the left MB edge: P0 110 -> 107, Q0 100 -> 102.
        for (int x = 0; x < 4; x++) {
            SubBlock topNeighbour = tmb.getSubBlock(Y1, x, 3);

            for (int a = 0; a < 4; a++) {
                assertEquals(107, topNeighbour.getDest()[a][3],
                        "P0 of the top MB edge (tmb, x=" + x + ") must be moved towards Q0");
                assertEquals(110, topNeighbour.getDest()[a][2],
                        "P1 must not be modified by the simple filter (tmb, x=" + x + ")");
            }

            SubBlock edgeSubBlock = cmb.getSubBlock(Y1, x, 0);
            for (int a = 0; a < 4; a++) {
                assertEquals(102, edgeSubBlock.getDest()[a][0],
                        "Q0 of the top MB edge (cmb, x=" + x + ") must be moved towards P0");
                assertEquals(100, edgeSubBlock.getDest()[a][1],
                        "Q1 must not be modified by the simple filter (cmb, x=" + x + ")");
            }
        }

        assertRow("cmb interior sub block must be untouched",
                new int[]{100, 100, 100, 100}, cmb.getSubBlock(Y1, 1, 2), 0);
        assertRow("tmb sub blocks above the edge must be untouched",
                new int[]{110, 110, 110, 110}, tmb.getSubBlock(Y1, 1, 1), 0);
    }

    @Test
    @DisplayName("Level 10, sharpness 0: inner sub block edge difference 25 <= sub_bedge_limit 30 is filtered")
    void innerSubBlockEdgeIsFilteredForSharpnessZero() {
        // interior_limit = 10, sub_bedge_limit = 2*10 + 10 = 30, mbedge_limit = 34
        MacroBlock cmb = newMacroBlock(10);
        fillColumns(cmb, 0, uniform(110));
        fillColumns(cmb, 1, uniform(110));
        fillColumns(cmb, 2, uniform(100));
        fillColumns(cmb, 3, uniform(100));

        LoopFilter.loopFilterSimpleBlock(cmb, null, null, 0);

        // Edge between sub block columns x=1 and x=2: P1 = P0 = 110 | Q0 = Q1 = 100.
        // 25 <= 30  ->  P0 110 -> 107, Q0 100 -> 102.
        for (int y = 0; y < 4; y++) {
            SubBlock rightOfEdge = cmb.getSubBlock(Y1, 1, y);
            SubBlock leftOfEdge = cmb.getSubBlock(Y1, 2, y);

            for (int a = 0; a < 4; a++) {
                assertEquals(107, rightOfEdge.getDest()[3][a],
                        "P0 of the inner edge (x=1, y=" + y + ") must be moved towards Q0");
                assertEquals(102, leftOfEdge.getDest()[0][a],
                        "Q0 of the inner edge (x=2, y=" + y + ") must be moved towards P0");
            }

            assertRow("P1 of the inner edge must be untouched",
                    new int[]{110, 110, 110, 110}, rightOfEdge, 2);
            assertRow("Q1 of the inner edge must be untouched",
                    new int[]{100, 100, 100, 100}, leftOfEdge, 1);
        }

        assertRow("sub blocks left of x=1 are not adjacent to a filterable edge",
                new int[]{110, 110, 110, 110}, cmb.getSubBlock(Y1, 0, 0), 0);
        assertRow("sub blocks right of x=2 are not adjacent to a filterable edge",
                new int[]{100, 100, 100, 100}, cmb.getSubBlock(Y1, 3, 3), 3);
    }

    @Test
    @DisplayName("Level 10, sharpness 4: interior_limit 5 keeps sub_bedge_limit at 25, edge is still filtered")
    void innerSubBlockEdgeIsFilteredForSharpnessFour() {
