private static final SubBlock.Plane Y1 = SubBlock.Plane.Y1;

private static int[][] rows(int r0, int r1, int r2, int r3) {
    return new int[][] {
        {r0, r0, r0, r0}, {r1, r1, r1, r1}, {r2, r2, r2, r2}, {r3, r3, r3, r3}
    };
}

private static int[][] uniform(int v) { return rows(v, v, v, v); }

private static int[][] copy(int[][] a) {
    int[][] c = new int[4][4];
    for (int i = 0; i < 4; i++) c[i] = a[i].clone();
    return c;
}

private static MacroBlock newMacroBlock(int filterLevel) {
    MacroBlock mb = new MacroBlock(1, 1, false);
    mb.setFilterLevel(filterLevel);
    return mb;
}

private static void fillColumns(MacroBlock mb, int fromColumn, int toColumn, int[][] pattern) {
    for (int x = fromColumn; x <= toColumn; x++)
        for (int y = 0; y < 4; y++)
            mb.getSubBlock(Y1, x, y).setDest(copy(pattern));
}

