        int rv = leftOfFrame ? 129 : 127;

        int[][] r = new int[4][4];
        for (int j = 0; j < 4; j++) {
            for (int i = 0; i < 4; i++) {
                r[i][j] = rv;
            }
        }

        return r;
    }

