private static Segment getSegH(SubBlock rsb, SubBlock lsb, int a) {
    Segment seg = new Segment();
    int[][] rdest = rsb.getDest();
    int[][] ldest = lsb.getDest();

    seg.P0 = ldest[3][a];
    seg.P1 = ldest[2][a];
    seg.P2 = ldest[1][a];
    seg.P3 = ldest[0][a];
    seg.Q0 = rdest[0][a];
    seg.Q1 = rdest[1][a];
    seg.Q2 = rdest[2][a];
    seg.Q3 = rdest[3][a];

    return seg;
}

private static Segment getSegV(SubBlock bsb, SubBlock tsb, int a) {
    Segment seg = new Segment();
    int[][] bdest = bsb.getDest();
    int[][] tdest = tsb.getDest();

    seg.P0 = tdest[a][3];
    seg.P1 = tdest[a][2];
    seg.P2 = tdest[a][1];
    seg.P3 = tdest[a][0];
    seg.Q0 = bdest[a][0];
    seg.Q1 = bdest[a][1];
    seg.Q2 = bdest[a][2];
    seg.Q3 = bdest[a][3];

    return seg;
}

