package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Tests for {@link LoopFilter#loopFilterYBlock(MacroBlock, MacroBlock, MacroBlock, int, int)}.
 */
class LoopFilterLoopFilterYBlockTests {

    private static final SubBlock.Plane Y1 = SubBlock.Plane.Y1;

    @Test
    void zeroFilterLevelLeavesEveryPixelUntouched() {
        MacroBlock current = newMacroBlock();
        MacroBlock left = newMacroBlock();
        MacroBlock top = newMacroBlock();
        fill(current, 120);
        fill(left, 100);
        fill(top, 110);

        LoopFilter.loopFilterYBlock(current, left, top, 0, 0);

        assertAllPixels(current, 120);
        assertAllPixels(left, 100);
        assertAllPixels(top, 110);
    }

    @Test
    void filtersAcrossLeftMacroBlockEdge() throws Exception {
        MacroBlock current = newMacroBlock();
        MacroBlock left = newMacroBlock();
        fill(current, 120);
        fill(left, 100);
        current.setFilterLevel(20);
        skipInnerLoopFilter(current, true);

        LoopFilter.loopFilterYBlock(current, left, null, 0, 0);

        for (int rowBlock = 0; rowBlock < 4; rowBlock++) {
            assertBlockRows(left, 3, rowBlock, new int[]{100, 103, 106, 108});
            assertBlockRows(current, 0, rowBlock, new int[]{112, 114, 117, 120});
        }
    }

    @Test
    void filtersAcrossTopMacroBlockEdge() throws Exception {
        MacroBlock current = newMacroBlock();
        MacroBlock top = newMacroBlock();
        fill(current, 120);
        fill(top, 100);
        current.setFilterLevel(20);
        skipInnerLoopFilter(current, true);

        LoopFilter.loopFilterYBlock(current, null, top, 0, 0);

        for (int columnBlock = 0; columnBlock < 4; columnBlock++) {
            assertBlockRows(current, columnBlock, 0, new int[]{112, 114, 117, 120});
            assertBlockRows(top, columnBlock, 3, new int[]{100, 103, 106, 108});
        }
    }

    @Test
    void filtersFirstInternalVerticalSubblockEdge() {
        MacroBlock current = newMacroBlock();
        fill(current, 120);
        fillBlocksInFirstColumn(current, 100);
        current.setFilterLevel(20);

        LoopFilter.loopFilterYBlock(current, null, null, 0, 0);

        for (int rowBlock = 0; rowBlock < 4; rowBlock++) {
            assertBlockRows(current, 0, rowBlock, new int[]{100, 100, 104, 107});
            assertBlockRows(current, 1, rowBlock, new int[]{112, 116, 120, 120});
        }

        assertAllPixels(current, 2, 0, 120);
        assertAllPixels(current, 3, 0, 120);
        assertAllPixels(current, 2, 3, 120);
        assertAllPixels(current, 3, 3, 120);
    }

    @Test
    void sharpnessOneCanPreventFilteringOfInternalEdge() {
        MacroBlock current = newMacroBlock();
        fill(current, 120);
        setFirstColumnBlockRows(current, new int[]{100, 100, 109, 118});
        current.setFilterLevel(20);

        LoopFilter.loopFilterYBlock(current, null, null, 1, 0);

        assertFirstColumnBlockRows(current, new int[]{100, 100, 109, 118});
    }

    @Test
    void highSharpnessUsesShiftedAndCappedInteriorLimit() {
        MacroBlock current = newMacroBlock();
        fill(current, 120);
        setFirstColumnBlockRows(current, new int[]{100, 100, 105, 110});
        current.setFilterLevel(20);

        LoopFilter.loopFilterYBlock(current, null, null, 5, 0);

        assertFirstColumnBlockRows(current, new int[]{100, 100, 105, 110});
    }

    @Test
    void keyFrameUsesHighEdgeVarianceFilterAtLevelTwenty() throws Exception {
        MacroBlock current = newMacroBlock();
        MacroBlock left = newMacroBlock();
        fill(current, 120);
        fill(left, 112);
        setAllBlockRows(left, 3, new int[]{112, 112, 112, 110});
        current.setFilterLevel(20);
        skipInnerLoopFilter(current, true);

        LoopFilter.loopFilterYBlock(current, left, null, 0, 0);

        for (int rowBlock = 0; rowBlock < 4; rowBlock++) {
            assertBlockRows(left, 3, rowBlock, new int[]{112, 112, 112, 113});
            assertBlockRows(current, 0, rowBlock, new int[]{117, 120, 120, 120});
        }
    }

    @Test
    void interFrameUsesSmoothFilterForSameEdgeSamples() throws Exception {
        MacroBlock current = newMacroBlock();
        MacroBlock left = newMacroBlock();
        fill(current, 120);
        fill(left, 112);
        setAllBlockRows(left, 3, new int[]{112, 112, 112, 110});
        current.setFilterLevel(20);
        skipInnerLoopFilter(current, true);

        LoopFilter.loopFilterYBlock(current, left, null, 0, 1);

        for (int rowBlock = 0; rowBlock < 4; rowBlock++) {
            assertBlockRows(left, 3, rowBlock, new int[]{112, 114, 115, 115});
            assertBlockRows(current, 0, rowBlock, new int[]{115, 117, 118, 120});
        }
    }

    @Test
    void flatMacroBlockIsUnchangedWithNoNeighbours() {
        MacroBlock current = newMacroBlock();
        fill(current, 128);
        current.setFilterLevel(40);

        LoopFilter.loopFilterYBlock(current, null, null, 0, 1);

        assertAllPixels(current, 128);
    }

    @Test
    void nullCurrentMacroBlockIsRejected() {
        assertThrows(NullPointerException.class,
                () -> LoopFilter.loopFilterYBlock(null, null, null, 0, 0));
    }

    private static MacroBlock newMacroBlock() {
        return new MacroBlock(1, 1, false);
    }

    private static void fill(MacroBlock macroBlock, int value) {
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                int[][] pixels = new int[4][4];
                for (int row = 0; row < 4; row++) {
                    for (int column = 0; column < 4; column++) {
                        pixels[row][column] = value;
                    }
                }
                macroBlock.getSubBlock(Y1, x, y).setDest(pixels);
            }
        }
    }

    private static void fillBlocksInFirstColumn(MacroBlock macroBlock, int value) {
        for (int y = 0; y < 4; y++) {
            int[][] pixels = pixels(macroBlock, 0, y);
            for (int row = 0; row < 4; row++) {
                for (int column = 0; column < 4; column++) {
                    pixels[row][column] = value;
                }
            }
        }
    }

    private static void setFirstColumnBlockRows(MacroBlock macroBlock, int[] values) {
        for (int y = 0; y < 4; y++) {
            int[][] pixels = pixels(macroBlock, 0, y);
            for (int row = 0; row < 4; row++) {
                for (int column = 0; column < 4; column++) {
                    pixels[row][column] = values[row];
                }
            }
        }
    }

    private static void setAllBlockRows(MacroBlock macroBlock, int x, int[] values) {
        for (int y = 0; y < 4; y++) {
            int[][] pixels = pixels(macroBlock, x, y);
            for (int row = 0; row < 4; row++) {
                for (int column = 0; column < 4; column++) {
                    pixels[row][column] = values[row];
                }
            }
        }
    }

    private static int[][] pixels(MacroBlock macroBlock, int x, int y) {
        return macroBlock.getSubBlock(Y1, x, y).getDest();
    }

    private static void assertAllPixels(MacroBlock macroBlock, int expected) {
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertAllPixels(macroBlock, x, y, expected);
            }
        }
    }

    private static void assertAllPixels(MacroBlock macroBlock, int x, int y, int expected) {
        int[][] pixels = pixels(macroBlock, x, y);
        for (int[] row : pixels) {
            assertArrayEquals(new int[]{expected, expected, expected, expected}, row);
        }
    }

    private static void assertBlockRows(MacroBlock macroBlock, int x, int y, int[] expectedRows) {
        int[][] pixels = pixels(macroBlock, x, y);
        for (int row = 0; row < 4; row++) {
            assertArrayEquals(new int[]{expectedRows[row], expectedRows[row], expectedRows[row], expectedRows[row]},
                    pixels[row]);
        }
    }

    private static void assertFirstColumnBlockRows(MacroBlock macroBlock, int[] expectedRows) {
        for (int y = 0; y < 4; y++) {
            assertBlockRows(macroBlock, 0, y, expectedRows);
        }
    }

    private static void skipInnerLoopFilter(MacroBlock macroBlock, boolean skip) throws Exception {
        Field field = MacroBlock.class.getDeclaredField("skipInnerLoopFilter");
        field.setAccessible(true);
        field.setBoolean(macroBlock, skip);
    }
}
