package com.twelvemonkeys.imageio.plugins.webp.vp8;

import java.io.IOException;

final class SubBlock {
    public enum Plane {
        U, V, Y1, Y2
    }

    private final SubBlock above;

    private int[][] dest;
    /**
     * Snapshot of {@link #dest} as it was immediately after reconstruction, i.e.
     * *before* the loop filter modified it.
     * <p>
     * RFC 6386 applies the loop filter to the entire frame only after every
     * macroblock has been reconstructed, so intra prediction must always see
     * unfiltered neighbour samples. As this decoder interleaves reconstruction
     * and filtering macroblock by macroblock (to avoid buffering the whole
     * frame), the unfiltered samples have to be retained separately -- the same
     * approach libwebp takes with its saved top/left sample rows.
     */
    private int[][] recon;
    private int[][] diff;
    private boolean hasNoZeroToken;
    private final SubBlock left;
    private final MacroBlock macroBlock;
    private int mode;
    private final Plane plane;
    private int[][] predict;
    private int[] tokens = new int[16];

    SubBlock(MacroBlock macroBlock, SubBlock above, SubBlock left, Plane plane) {
        this.macroBlock = macroBlock;
        this.plane = plane;
        this.above = above;
        this.left = left;
        mode = 0;

        for (int z = 0; z < 16; z++) {
            tokens[z] = 0;
        }
    }

    public static int planeToType(Plane plane, boolean withY2) {
        switch (plane) {
            case Y2:
                return 1;
            case Y1:
                return withY2 ? 0 : 3;
            case U:
            case V:
                return 2;
        }

        return -1;
    }

    private int DCTextra(BoolDecoder bc2, int[] p) throws IOException {
        int v = 0;
        int offset = 0;
        do {
            v += v + bc2.readBool(p[offset]);
            offset++;
        } while (p[offset] > 0);
        return v;
    }

    public void decodeSubBlock(BoolDecoder bc2, int[][][][] coef_probs,
                               int ilc, int type, boolean withY2) throws IOException {
        SubBlock sb = this;
        int startAt = 0;
        if (withY2) {
            startAt = 1;
        }
        int lc = ilc;
        int c = 0;
        int v = 1;

        boolean skip = false;

        while (!(v == Globals.dct_eob) && c + startAt < 16) {

//			if (!skip)
//				v = bc2.readTree(Globals.vp8CoefTree,
//						coef_probs[type][Globals.vp8CoefBands[c + startAt]][lc]);
//			else
//				v = bc2.readTree(
//						Globals.vp8CoefTree,
//						coef_probs[type][Globals.vp8CoefBands[c + startAt]][lc],
//						1);
            v = bc2.readTree(Globals.vp8CoefTree, coef_probs[type][Globals.vp8CoefBands[c + startAt]][lc],
                    skip ? 1 : 0);

            int dv = decodeToken(bc2, v);
            lc = 0;
            skip = false;
            if (dv == 1 || dv == -1) {
                lc = 1;
            }
            else if (dv > 1 || dv < -1) {
                lc = 2;
            }
            else if (dv == Globals.DCT_0) {
                skip = true;
            }

            int[] tokens = sb.getTokens();

            if (v != Globals.dct_eob) {
                tokens[Globals.vp8defaultZigZag1d[c + startAt]] = dv;
            }
            c++;
        }
        hasNoZeroToken = false;
        for (int x = 0; x < 16; x++) {
            if (tokens[x] != 0) {
                hasNoZeroToken = true;
            }
        }
    }

    private int decodeToken(BoolDecoder bc2, int v) throws IOException {
        int r = v;

        if (v == Globals.dct_cat1) {
            r = 5 + DCTextra(bc2, Globals.Pcat1);
        }
        if (v == Globals.dct_cat2) {
            r = 7 + DCTextra(bc2, Globals.Pcat2);
        }
        if (v == Globals.dct_cat3) {
            r = 11 + DCTextra(bc2, Globals.Pcat3);
        }
        if (v == Globals.dct_cat4) {
            r = 19 + DCTextra(bc2, Globals.Pcat4);
        }
        if (v == Globals.dct_cat5) {
            r = 35 + DCTextra(bc2, Globals.Pcat5);
        }
        if (v == Globals.dct_cat6) {
            r = 67 + DCTextra(bc2, Globals.Pcat6);
        }
        if (v != Globals.DCT_0 && v != Globals.dct_eob) {
            if (bc2.readBit() > 0) {
                r = -r;
            }
        }

        return r;
    }

    public void dequantSubBlock(VP8Frame frame, Integer Dc) {
        SubBlock sb = this;

        int[] adjustedValues = new int[16];
        for (int i = 0; i < 16; i++) {
            int QValue;
            if (plane == Plane.U || plane == Plane.V) {
                QValue = frame.getSegmentQuants().getSegQuants()[this.getMacroBlock().getSegmentId()]
                        .getUvac_delta_q();
                if (i == 0) {
                    QValue = frame.getSegmentQuants().getSegQuants()[this.getMacroBlock().getSegmentId()]
                            .getUvdc_delta_q();
                }
            }
            else {
                QValue = frame.getSegmentQuants().getSegQuants()[this.getMacroBlock().getSegmentId()].getY1ac();
                if (i == 0) {
                    QValue = frame.getSegmentQuants().getSegQuants()[this.getMacroBlock().getSegmentId()]
                            .getY1dc();
                }
            }

            int inputValue = sb.getTokens()[i];
            adjustedValues[i] = inputValue * QValue;
        }

        if (Dc != null) {
            adjustedValues[0] = Dc;
        }

        int[][] diff = IDCT.idct4x4llm(adjustedValues);
        sb.setDiff(diff);
    }

    public void drawDebug() {
        if (dest != null) {
            dest[0][0] = 128;
            dest[1][0] = 128;
            dest[2][0] = 128;
            dest[3][0] = 128;
            dest[0][0] = 128;
            dest[0][1] = 128;
            dest[0][2] = 128;
            dest[0][3] = 128;
        }
    }

    public void drawDebugH() {
        if (dest != null) {
            dest[0][0] = 0;
            dest[1][0] = 0;
            dest[2][0] = 0;
            dest[3][0] = 0;
        }
    }

    public void drawDebugV() {
        if (dest != null) {
            dest[0][0] = 0;
            dest[0][1] = 0;
            dest[0][2] = 0;
            dest[0][3] = 0;
        }
    }

    public SubBlock getAbove() {
        return above;
    }

    public String getDebugString() {
        String r = "";
        r = r + "  " + plane;
        if (getMacroBlock().getYMode() == Globals.B_PRED
                && plane == Plane.Y1) {
            r = r + "\n  " + Globals.getSubBlockModeAsString(mode);
        }

        return r;
    }

    public int[][] getDest() {
        if (dest != null) {
            return dest;
        }
        else {
            return new int[4][4];
        }
    }

    public int[][] getDiff() {
        return diff;
    }

    public SubBlock getLeft() {
        return left;
    }

    public MacroBlock getMacroBlock() {
        return macroBlock;
    }

    /**
     * The unfiltered reconstruction of this sub block, for use as intra
     * prediction context by neighbouring blocks. See {@link #recon}.
     */
    public int[][] getRecon() {
        if (recon != null) {
            return recon;
        }

        return new int[4][4];
    }

    /**
     * Whether this sub block has been reconstructed.
     */
    public boolean hasRecon() {
        return recon != null;
    }

    /**
     * The unfiltered reconstruction, for use as the *above* prediction context.
     * Outside the frame the above row reads as 127 (RFC 6386, 12.2).
     */
    public int[][] getReconAbove() {
        if (recon != null) {
            return recon;
        }

        return borderSamples(false);
    }

    /**
     * The unfiltered reconstruction, for use as the *left* prediction context.
     * Outside the frame the left column reads as 129 (RFC 6386, 12.2).
     */
    public int[][] getReconLeft() {
        if (recon != null) {
            return recon;
        }

        return borderSamples(true);
    }

    /**
     * The unfiltered reconstruction, for use as the *above-left* prediction
     * context. Outside the frame this reads as 127 when the above row is also
     * outside the frame, and as 129 otherwise -- matching libwebp, which fills
     * the row above the first macroblock row (including its left-hand corner
     * sample) with 127, and the column left of the first macroblock column
     * (including its top corner sample) with 129.
     *
     * @param aboveRowAvailable whether the macroblock row above is inside the frame
     */
    public int[][] getReconAboveLeft(boolean aboveRowAvailable) {
        if (recon != null) {
            return recon;
        }

        return borderSamples(aboveRowAvailable);
    }

    /**
     * As {@link #getMacroBlockPredict(int)}, but returning the unfiltered
     * reconstruction. Use this when reading a *neighbouring* macroblock as
     * prediction context.
     */
    public int[][] getMacroBlockReconPredict(int intraMode) {
        if (recon != null) {
            return recon;
        }

        return borderSamples(intraMode == Globals.H_PRED);
    }

    /**
     * As {@link #getPredict(int, boolean)}, but returning the unfiltered
     * reconstruction. Use this when reading a *neighbouring* sub block as
     * prediction context.
     */
    public int[][] getReconPredict(int intraBMode, boolean left) {
        if (recon != null) {
            return recon;
        }
        if (predict != null) {
            return predict;
        }

        return borderSamples(left && isLeftBorder129(intraBMode));
    }

    private static boolean isLeftBorder129(int intraBMode) {
        return intraBMode == Globals.B_TM_PRED
                || intraBMode == Globals.B_DC_PRED
                || intraBMode == Globals.B_VE_PRED
                || intraBMode == Globals.B_HE_PRED
                || intraBMode == Globals.B_VR_PRED
                || intraBMode == Globals.B_RD_PRED
                || intraBMode == Globals.B_HD_PRED;
    }

    /**
     * Off-frame border samples: 129 to the left of the frame, 127 above it.
     */
    private static int[][] borderSamples(boolean leftOfFrame) {
        int rv = leftOfFrame ? 129 : 127;

        int[][] r = new int[4][4];
        for (int j = 0; j < 4; j++) {
            for (int i = 0; i < 4; i++) {
                r[i][j] = rv;
            }
        }

        return r;
    }

    public int[][] getMacroBlockPredict(int intra_mode) {
        if (dest != null) {
            return dest;
        }

        else {
            int rv = 127;
            if (intra_mode == Globals.H_PRED) {
                rv = 129;
            }
            int[][] r = new int[4][4];
            for (int j = 0; j < 4; j++) {
                for (int i = 0; i < 4; i++) {
                    r[i][j] = rv;
                }
            }
            return r;
        }
    }

    public int getMode() {
        return mode;
    }

    public Plane getPlane() {
        return plane;
    }

    public int[][] getPredict() {
        if (predict != null) {
            return predict;
        }
        return getPredict(Globals.B_DC_PRED, false);
    }

    public int[][] getPredict(int intra_bmode, boolean left) {
        if (dest != null) {
            return dest;
        }
        if (predict != null) {
            return predict;
        }
        else {
            int rv = 127;

            if ((intra_bmode == Globals.B_TM_PRED
                    || intra_bmode == Globals.B_DC_PRED
                    || intra_bmode == Globals.B_VE_PRED
                    || intra_bmode == Globals.B_HE_PRED
                    || intra_bmode == Globals.B_VR_PRED
                    || intra_bmode == Globals.B_RD_PRED || intra_bmode == Globals.B_HD_PRED)
                    && left) {
                rv = 129;
            }
            int[][] r = new int[4][4];
            for (int j = 0; j < 4; j++) {
                for (int i = 0; i < 4; i++) {
                    r[i][j] = rv;
                }
            }
            return r;
        }
    }

    int[] getTokens() {
        return tokens;
    }

    public boolean hasNoZeroToken() {
        return hasNoZeroToken;
    }

    public boolean isDest() {
        return dest != null;
    }

    public void predict(VP8Frame frame) {
        SubBlock sb = this;
        SubBlock aboveSb = frame.getAboveSubBlock(sb, sb.getPlane());
        SubBlock leftSb = frame.getLeftSubBlock(sb, sb.getPlane());

        int[] above = new int[4];
        int[] left = new int[4];

        above[0] = aboveSb.getReconPredict(sb.getMode(), false)[0][3];
        above[1] = aboveSb.getReconPredict(sb.getMode(), false)[1][3];
        above[2] = aboveSb.getReconPredict(sb.getMode(), false)[2][3];
        above[3] = aboveSb.getReconPredict(sb.getMode(), false)[3][3];
        left[0] = leftSb.getReconPredict(sb.getMode(), true)[3][0];
        left[1] = leftSb.getReconPredict(sb.getMode(), true)[3][1];
        left[2] = leftSb.getReconPredict(sb.getMode(), true)[3][2];
        left[3] = leftSb.getReconPredict(sb.getMode(), true)[3][3];
        SubBlock AL = frame.getLeftSubBlock(aboveSb, sb.getPlane());

        // for above left if left and above is null use left (129?) else use
        // above (127?)
        int al;
        if (!leftSb.hasRecon() && !aboveSb.hasRecon()) {

            al = AL.getReconPredict(sb.getMode(), false)[3][3];
        }
        else if (!aboveSb.hasRecon()) {

            al = AL.getReconPredict(sb.getMode(), false)[3][3];
        }
        else {
            al = AL.getReconPredict(sb.getMode(), true)[3][3];
        }
        SubBlock AR = frame.getAboveRightSubBlock(sb, sb.plane);
        int[] ar = new int[4];
        ar[0] = AR.getReconPredict(sb.getMode(), false)[0][3];
        ar[1] = AR.getReconPredict(sb.getMode(), false)[1][3];
        ar[2] = AR.getReconPredict(sb.getMode(), false)[2][3];
        ar[3] = AR.getReconPredict(sb.getMode(), false)[3][3];
        int[][] p = new int[4][4];
        int[] pp;
        switch (sb.getMode()) {
            case Globals.B_DC_PRED:
                // System.out.println("B_DC_PRED");
                int expected_dc = 0;

                for (int i = 0; i < 4; i++) {
                    expected_dc += above[i];
                    expected_dc += left[i];
                }
                expected_dc = (expected_dc + 4) >> 3;

                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        p[x][y] = expected_dc;
                    }
                }

                break;
            case Globals.B_TM_PRED:

                // System.out.println("B_TM_PRED");

                // prediction similar to true_motion prediction

                for (int r = 0; r < 4; r++) {
                    for (int c = 0; c < 4; c++) {

                        int pred = above[c] - al + left[r];
                        if (pred < 0) {
                            pred = 0;
                        }

                        if (pred > 255) {
                            pred = 255;
                        }

                        p[c][r] = pred;
                    }
                }
                break;
            case Globals.B_VE_PRED:
                // System.out.println("B_VE_PRED");

                int[] ap = new int[4];
                ap[0] = (al + 2 * above[0] + above[1] + 2) >> 2;
                ap[1] = (above[0] + 2 * above[1] + above[2] + 2) >> 2;
                ap[2] = (above[1] + 2 * above[2] + above[3] + 2) >> 2;
                ap[3] = (above[2] + 2 * above[3] + ar[0] + 2) >> 2;

                for (int r = 0; r < 4; r++) {
                    for (int c = 0; c < 4; c++) {

                        p[c][r] = ap[c];
                    }
                }
                break;
            case Globals.B_HE_PRED:
                // System.out.println("B_HE_PRED");

                int[] lp = new int[4];
                lp[0] = (al + 2 * left[0] + left[1] + 2) >> 2;
                lp[1] = (left[0] + 2 * left[1] + left[2] + 2) >> 2;
                lp[2] = (left[1] + 2 * left[2] + left[3] + 2) >> 2;
                lp[3] = (left[2] + 2 * left[3] + left[3] + 2) >> 2;

                for (int r = 0; r < 4; r++) {
                    for (int c = 0; c < 4; c++) {
                        p[c][r] = lp[r];
                    }
                }
                break;
            case Globals.B_LD_PRED:
                // System.out.println("B_LD_PRED");
                p[0][0] = (above[0] + above[1] * 2 + above[2] + 2) >> 2;
                p[1][0] = p[0][1] = (above[1] + above[2] * 2 + above[3] + 2) >> 2;
                p[2][0] = p[1][1] = p[0][2] = (above[2] + above[3] * 2 + ar[0] + 2) >> 2;
                p[3][0] = p[2][1] = p[1][2] = p[0][3] = (above[3] + ar[0] * 2
                        + ar[1] + 2) >> 2;
                p[3][1] = p[2][2] = p[1][3] = (ar[0] + ar[1] * 2 + ar[2] + 2) >> 2;
                p[3][2] = p[2][3] = (ar[1] + ar[2] * 2 + ar[3] + 2) >> 2;
                p[3][3] = (ar[2] + ar[3] * 2 + ar[3] + 2) >> 2;

                break;
            case Globals.B_RD_PRED:
                // System.out.println("B_RD_PRED");
                pp = new int[9];

                pp[0] = left[3];
                pp[1] = left[2];
                pp[2] = left[1];
                pp[3] = left[0];
                pp[4] = al;
                pp[5] = above[0];
                pp[6] = above[1];
                pp[7] = above[2];
                pp[8] = above[3];

                p[0][3] = (pp[0] + pp[1] * 2 + pp[2] + 2) >> 2;
                p[1][3] = p[0][2] = (pp[1] + pp[2] * 2 + pp[3] + 2) >> 2;
                p[2][3] = p[1][2] = p[0][1] = (pp[2] + pp[3] * 2 + pp[4] + 2) >> 2;
                p[3][3] = p[2][2] = p[1][1] = p[0][0] = (pp[3] + pp[4] * 2 + pp[5] + 2) >> 2;
