                p[3][1] = p[1][0] = (pp[3] + pp[4] * 2 + pp[5] + 2) >> 2;
                p[2][0] = (pp[4] + pp[5] * 2 + pp[6] + 2) >> 2;
                p[3][0] = (pp[5] + pp[6] * 2 + pp[7] + 2) >> 2;
