                p[0][0] = (left[0] + left[1] + 1) >> 1;
                p[1][0] = (left[0] + left[1] * 2 + left[2] + 2) >> 2;
                p[2][0] = p[0][1] = (left[1] + left[2] + 1) >> 1;
                p[3][0] = p[1][1] = (left[1] + left[2] * 2 + left[3] + 2) >> 2;
                p[2][1] = p[0][2] = (left[2] + left[3] + 1) >> 1;
                p[3][1] = p[1][2] = (left[2] + left[3] * 2 + left[3] + 2) >> 2;
