    public void reconstruct() {
        SubBlock sb = this;

        int r, c;
        int[][] p = sb.getPredict(1, false);

        int[][] dest = new int[4][4];
        int[][] diff = sb.getDiff();

        for (r = 0; r < 4; r++) {
            for (c = 0; c < 4; c++) {
                int a = diff[r][c] + p[r][c];

                if (a < 0) {
                    a = 0;
                }

                if (a > 255) {
                    a = 255;
                }

                dest[r][c] = a;
            }
        }

        sb.setDest(dest);
        if (!this.getMacroBlock().isKeepDebugInfo()) {
            sb.diff = null;
            sb.predict = null;
            sb.tokens = null;
        }
    }

    public void setDest(int[][] dest) {
        this.dest = dest;

        // Keep an unfiltered copy for intra prediction, see #recon.
        this.recon = new int[][] {
                {dest[0][0], dest[0][1], dest[0][2], dest[0][3]},
                {dest[1][0], dest[1][1], dest[1][2], dest[1][3]},
                {dest[2][0], dest[2][1], dest[2][2], dest[2][3]},
                {dest[3][0], dest[3][1], dest[3][2], dest[3][3]},
        };
    }

