package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.MemoryCacheImageInputStream;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link MacroBlock#dequantMacroBlock(VP8Frame)}.
 * <p>
 * Macro blocks are placed at the first position of a small macro block frame, so intra prediction
 * reads the RFC 6386 border samples: 127 for the row above the frame and 129 for the column left of
 * it. The macro blocks surrounding the frame are plain {@link Globals#DC_PRED} blocks that have
 * never been reconstructed.
 * <p>
 * With Q index 0 the dequantization factors are {@code y2dc == 2 * 4 == 8}, {@code y2ac == 8},
 * {@code y1dc == uvdc == 4} and {@code y1ac == uvac == 4} (see {@code Globals#vp8DcQLookup} and
 * {@code Globals#vp8AcQLookup}), which keeps the expected values small and easy to follow.
 */
class MacroBlockDequantMacroBlockTests {

    /** Q index 0 maps to {@code vp8DcQLookup[0] == 4} and {@code vp8AcQLookup[0] == 4}. */
    private static final int Q_INDEX = 0;

    /** DC prediction value of a block at the top left corner of the frame. */
    private static final int FRAME_ORIGIN_DC = 128;

    // ---------------------------------------------------------------------------------------------
    // Non B_PRED macro blocks (the luma DC is coded in the Y2 block and transformed by a
    // Walsh-Hadamard transform first)
    // ---------------------------------------------------------------------------------------------

    @Test
    void nonBPredWithoutCoefficientsReconstructsToPredictionOnly() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        assertConstantDiff("Y2", 0, macroBlock.getY2SubBlock().getDiff());

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                SubBlock yBlock = macroBlock.getYSubBlock(x, y);
                assertConstantDiff("Y[" + x + "][" + y + "]", 0, yBlock.getDiff());
                assertConstantBlock("Y[" + x + "][" + y + "]", FRAME_ORIGIN_DC, yBlock);
            }
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);

        // Only the 16 Y, 4 U and 4 V sub blocks are reconstructed, the Y2 block itself is not.
        assertFalse(macroBlock.getY2SubBlock().isDest(), "Y2 sub block must not be reconstructed");
    }

    @Test
    void nonBPredScalesY2DcCoefficientWithY2DcQuantizer() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        // DC coefficient 4 * y2dc (8) == 32
        macroBlock.getY2SubBlock().getTokens()[0] = 4;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        // A DC only inverse Walsh-Hadamard transform spreads the coefficient over all 16 samples:
        // (32 + 3) / 8 == 4.
        assertConstantDiff("Y2", 4, macroBlock.getY2SubBlock().getDiff());

        // Every Y block is dequantized with that DC value: (4 + 4) / 8 == 1 on top of the DC
        // prediction of 128.
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                SubBlock yBlock = macroBlock.getYSubBlock(x, y);
                assertConstantDiff("Y[" + x + "][" + y + "]", 1, yBlock.getDiff());
                assertConstantBlock("Y[" + x + "][" + y + "]", FRAME_ORIGIN_DC + 1, yBlock);
            }
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);
    }

    @Test
    void nonBPredScalesY2AcCoefficientsWithY2AcQuantizer() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        // First AC coefficient 8 * y2ac (8) == 64
        macroBlock.getY2SubBlock().getTokens()[1] = 8;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        // Unlike a DC only coefficient, an AC coefficient only reaches two of the four Y block
        // columns, with opposite signs, so the Y blocks are no longer uniform.
        int[][] y2Diff = macroBlock.getY2SubBlock().getDiff();
        assertNotNull(y2Diff, "Y2 diff");
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                int expected = i < 2 ? 8 : -8;
                assertEquals(expected, y2Diff[i][j], "Y2 diff[" + i + "][" + j + "]");
            }
        }

        for (int y = 0; y < 4; y++) {
            // Y blocks in the first two columns get +8, the last two get -8:
            // (8 + 4) / 8 == 1 and (-8 + 4) / 8 == -1.
            assertConstantBlock("Y[0][" + y + "]", FRAME_ORIGIN_DC + 1, macroBlock.getYSubBlock(0, y));
            assertConstantBlock("Y[1][" + y + "]", FRAME_ORIGIN_DC + 1, macroBlock.getYSubBlock(1, y));
            assertConstantBlock("Y[2][" + y + "]", FRAME_ORIGIN_DC - 1, macroBlock.getYSubBlock(2, y));
            assertConstantBlock("Y[3][" + y + "]", FRAME_ORIGIN_DC - 1, macroBlock.getYSubBlock(3, y));
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);
    }

    @Test
    void nonBPredUsesQuantizerOfTheSegmentOfTheMacroBlock() {
        SegmentQuants quants = segmentQuants(Q_INDEX);

        // Second segment: Q index 0 with a +30 delta, giving y2dc == 2 * vp8DcQLookup[30] == 54.
        SegmentQuant secondSegment = quants.getSegQuants()[1];
        secondSegment.setQindex(0);
        secondSegment.setY1dc(0);
        secondSegment.setY2dc(30);
        secondSegment.setY2ac_delta_q(0);
        secondSegment.setUvdc_delta_q(0);
        secondSegment.setUvac_delta_q(0);

        MacroBlock firstSegmentBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        firstSegmentBlock.setSegmentId(0);
        firstSegmentBlock.getY2SubBlock().getTokens()[0] = 4;
        firstSegmentBlock.dequantMacroBlock(frame(quants, firstSegmentBlock));

        MacroBlock secondSegmentBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        secondSegmentBlock.setSegmentId(1);
        secondSegmentBlock.getY2SubBlock().getTokens()[0] = 4;
        secondSegmentBlock.dequantMacroBlock(frame(quants, secondSegmentBlock));

        // Same token, different segment quantizer: 4 * 8 == 32 -> (32 + 3) / 8 == 4 versus
        // 4 * 54 == 216 -> (216 + 3) / 8 == 27.
        assertConstantDiff("Y2 segment 0", 4, firstSegmentBlock.getY2SubBlock().getDiff());
        assertConstantDiff("Y2 segment 1", 27, secondSegmentBlock.getY2SubBlock().getDiff());

        // (4 + 4) / 8 == 1 versus (27 + 4) / 8 == 3.
        assertConstantBlock("Y[0][0] segment 0", FRAME_ORIGIN_DC + 1, firstSegmentBlock.getYSubBlock(0, 0));
        assertConstantBlock("Y[0][0] segment 1", FRAME_ORIGIN_DC + 3, secondSegmentBlock.getYSubBlock(0, 0));
    }

    @Test
    void nonBPredUsesChromaQuantizersForTheChromaBlocks() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        // uvdc == 4: 4 * 4 == 16 -> (16 + 4) / 8 == 2
        macroBlock.getUSubBlock(0, 0).getTokens()[0] = 4;
        // uvac == 4: 4 * 4 == 16, an AC coefficient spreads over the block
        macroBlock.getUSubBlock(1, 1).getTokens()[1] = 4;
        // uvdc == 4: 2 * 4 == 8 -> (8 + 4) / 8 == 1
        macroBlock.getVSubBlock(0, 1).getTokens()[0] = 2;
        macroBlock.getVSubBlock(1, 1).getTokens()[1] = 4;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        assertConstantDiff("U[0][0]", 2, macroBlock.getUSubBlock(0, 0).getDiff());
        assertConstantBlock("U[0][0]", FRAME_ORIGIN_DC + 2, macroBlock.getUSubBlock(0, 0));

        assertConstantDiff("V[0][1]", 1, macroBlock.getVSubBlock(0, 1).getDiff());
        assertConstantBlock("V[0][1]", FRAME_ORIGIN_DC + 1, macroBlock.getVSubBlock(0, 1));

        // The inverse DCT of an AC only coefficient yields (0 + 16 + 4) / 8 == 3, 1, -1 and -2
        // for the four rows of the block, added to the prediction of 128.
        int[][] expectedAcBlock = {
                {131, 131, 131, 131},
                {129, 129, 129, 129},
                {127, 127, 127, 127},
                {126, 126, 126, 126},
        };
        assertBlockContent("U[1][1]", macroBlock.getUSubBlock(1, 1), expectedAcBlock);
        assertBlockContent("V[1][1]", macroBlock.getVSubBlock(1, 1), expectedAcBlock);

        // Untouched chroma blocks only contain the DC prediction.
        assertConstantBlock("U[1][0]", FRAME_ORIGIN_DC, macroBlock.getUSubBlock(1, 0));
        assertConstantBlock("U[0][1]", FRAME_ORIGIN_DC, macroBlock.getUSubBlock(0, 1));
        assertConstantBlock("V[0][0]", FRAME_ORIGIN_DC, macroBlock.getVSubBlock(0, 0));
        assertConstantBlock("V[1][0]", FRAME_ORIGIN_DC, macroBlock.getVSubBlock(1, 0));

        // Luma is not affected by chroma coefficients.
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertConstantBlock("Y[" + x + "][" + y + "]", FRAME_ORIGIN_DC, macroBlock.getYSubBlock(x, y));
            }
        }
    }

    @Test
    void nonBPredClampsReconstructionTo255() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        // 2000 * 8 == 16000 -> (16000 + 3) / 8 == 2000, (2000 + 4) / 8 == 250
        macroBlock.getY2SubBlock().getTokens()[0] = 2000;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        assertConstantDiff("Y2", 2000, macroBlock.getY2SubBlock().getDiff());
        assertConstantDiff("Y[0][0]", 250, macroBlock.getYSubBlock(0, 0).getDiff());
        // 128 + 250 == 378 is clamped to the maximum sample value.
        assertConstantBlock("Y[0][0]", 255, macroBlock.getYSubBlock(0, 0));

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertConstantBlock("Y[" + x + "][" + y + "]", 255, macroBlock.getYSubBlock(x, y));
            }
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);
    }

    @Test
    void nonBPredClampsReconstructionToZero() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        // -2000 * 8 == -16000 -> (-16000 + 3) / 8 == -2000, (-2000 + 4) / 8 == -250
        macroBlock.getY2SubBlock().getTokens()[0] = -2000;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        assertConstantDiff("Y2", -2000, macroBlock.getY2SubBlock().getDiff());
        assertConstantDiff("Y[3][2]", -250, macroBlock.getYSubBlock(3, 2).getDiff());
        // 128 - 250 == -122 is clamped to the minimum sample value.
        assertConstantBlock("Y[3][2]", 0, macroBlock.getYSubBlock(3, 2));

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertConstantBlock("Y[" + x + "][" + y + "]", 0, macroBlock.getYSubBlock(x, y));
            }
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);
    }

    @Test
    void nonBPredVerticalPredictionUsesSampleRowAboveTheFrame() {
        // V_PRED copies the row above the macro block, which is 127 outside the frame.
        assertPredictionOnlyReconstruction(Globals.V_PRED, 127);
    }

    @Test
    void nonBPredHorizontalPredictionUsesSampleColumnLeftOfTheFrame() {
        // H_PRED copies the column left of the macro block, which is 129 outside the frame.
        assertPredictionOnlyReconstruction(Globals.H_PRED, 129);
    }

    @Test
    void nonBPredTrueMotionPredictionUsesLeftPlusAboveMinusAboveLeft() {
        // TM_PRED is left (129) + above (127) - above left (127) == 129 at the frame origin.
        assertPredictionOnlyReconstruction(Globals.TM_PRED, 129);
    }

    @Test
    void nonBPredDcPredictionAveragesReconstructedNeighbours() {
        // Neighbouring macro blocks that were already reconstructed, with different brightness.
        MacroBlock above = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        reconstructConstant(above, 200);
        MacroBlock left = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        reconstructConstant(left, 100);

        // Second macro block of the frame: both the row above and the column to the left exist.
        MacroBlock macroBlock = new MacroBlock(2, 2, true);
        macroBlock.setYMode(Globals.DC_PRED);
        macroBlock.setUvMode(Globals.DC_PRED);

        MacroBlock[] rowAbove = {borderMacroBlock(0), borderMacroBlock(1), above};
        MacroBlock[] currentRow = {borderMacroBlock(0), left, macroBlock};

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), 2, 2, rowAbove, currentRow, 1));

        // The DC prediction is the rounded average of the 16 samples above (200) and the 16
        // samples to the left (100): (16 * 200 + 16 * 100 + 16) / 32 == 150, and likewise for the
        // chroma planes with (8 * 200 + 8 * 100 + 8) / 16 == 150.
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertConstantBlock("Y[" + x + "][" + y + "]", 150, macroBlock.getYSubBlock(x, y));
            }
        }

        assertChromaBlocksConstant(150, macroBlock);
    }

    // ---------------------------------------------------------------------------------------------
    // B_PRED macro blocks (every luma block has its own prediction mode and its own DC coefficient)
    // ---------------------------------------------------------------------------------------------

    @Test
    void bPredWithoutCoefficientsReconstructsToPredictionOnly() {
        MacroBlock macroBlock = macroBlock(Globals.B_PRED, Globals.DC_PRED);

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        // The luma DC is coded per block, so the Y2 block is never dequantized in this mode.
        assertNull(macroBlock.getY2SubBlock().getDiff(), "Y2 sub block must not be dequantized");
        assertFalse(macroBlock.getY2SubBlock().isDest(), "Y2 sub block must not be reconstructed");

        // Sub block modes default to 0 == B_DC_PRED. The first row averages 127 (above, outside the
        // frame) and 129 (left, outside the frame) to 128; afterwards the 128/129 neighbours
        // average to 129.
        for (int x = 0; x < 4; x++) {
            SubBlock yBlock = macroBlock.getYSubBlock(x, 0);
            assertConstantDiff("Y[" + x + "][0]", 0, yBlock.getDiff());
            assertConstantBlock("Y[" + x + "][0]", FRAME_ORIGIN_DC, yBlock);
        }

        for (int y = 1; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                SubBlock yBlock = macroBlock.getYSubBlock(x, y);
                assertConstantDiff("Y[" + x + "][" + y + "]", 0, yBlock.getDiff());
                assertConstantBlock("Y[" + x + "][" + y + "]", FRAME_ORIGIN_DC + 1, yBlock);
            }
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);
    }

    @Test
    void bPredDequantizesLumaWithY1QuantizersAndFeedsReconstructionIntoPrediction() {
        MacroBlock macroBlock = macroBlock(Globals.B_PRED, Globals.DC_PRED);
        // y1dc == 4: 2 * 4 == 8 -> (8 + 4) / 8 == 1
        macroBlock.getYSubBlock(1, 1).getTokens()[0] = 2;
        // uvdc == 4: 2 * 4 == 8 -> 1
        macroBlock.getUSubBlock(0, 0).getTokens()[0] = 2;
        // 3 * 4 == 12 -> (12 + 4) / 8 == 2
        macroBlock.getVSubBlock(1, 1).getTokens()[0] = 3;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        assertNull(macroBlock.getY2SubBlock().getDiff(), "Y2 sub block must not be dequantized");

        // The block with the coefficient: DC prediction of 128 (above) and 129 (left) averages to
        // 129, plus 1.
        assertConstantDiff("Y[1][1]", 1, macroBlock.getYSubBlock(1, 1).getDiff());
        assertConstantBlock("Y[1][1]", FRAME_ORIGIN_DC + 2, macroBlock.getYSubBlock(1, 1));

        // The remaining blocks of the first row predict from the left border column (129) and from
        // their already reconstructed left neighbour, which also averages to 129.
        for (int x : new int[] {0, 2, 3}) {
            assertConstantBlock("Y[" + x + "][1]", FRAME_ORIGIN_DC + 1, macroBlock.getYSubBlock(x, 1));
        }

        // Below the brighter block the prediction starts from the brighter reconstructed samples:
        // rows 2 and 3 of columns 1..3 reconstruct to 130, while the left border column, which
        // averages 129 (left of the frame) and 130 (above), stays at 129.
        for (int x : new int[] {1, 2, 3}) {
            assertConstantBlock("Y[" + x + "][2]", FRAME_ORIGIN_DC + 2, macroBlock.getYSubBlock(x, 2));
            assertConstantBlock("Y[" + x + "][3]", FRAME_ORIGIN_DC + 2, macroBlock.getYSubBlock(x, 3));
        }
        assertConstantBlock("Y[0][2]", FRAME_ORIGIN_DC + 1, macroBlock.getYSubBlock(0, 2));
        assertConstantBlock("Y[0][3]", FRAME_ORIGIN_DC + 1, macroBlock.getYSubBlock(0, 3));

        // The first row still predicts from the (unreconstructed) row above the frame.
        for (int x = 0; x < 4; x++) {
            assertConstantBlock("Y[" + x + "][0]", FRAME_ORIGIN_DC, macroBlock.getYSubBlock(x, 0));
        }

        assertConstantDiff("U[0][0]", 1, macroBlock.getUSubBlock(0, 0).getDiff());
        assertConstantBlock("U[0][0]", FRAME_ORIGIN_DC + 1, macroBlock.getUSubBlock(0, 0));
        assertConstantDiff("V[1][1]", 2, macroBlock.getVSubBlock(1, 1).getDiff());
        assertConstantBlock("V[1][1]", FRAME_ORIGIN_DC + 2, macroBlock.getVSubBlock(1, 1));

        assertConstantBlock("U[1][0]", FRAME_ORIGIN_DC, macroBlock.getUSubBlock(1, 0));
        assertConstantBlock("U[0][1]", FRAME_ORIGIN_DC, macroBlock.getUSubBlock(0, 1));
        assertConstantBlock("U[1][1]", FRAME_ORIGIN_DC, macroBlock.getUSubBlock(1, 1));
        assertConstantBlock("V[0][0]", FRAME_ORIGIN_DC, macroBlock.getVSubBlock(0, 0));
        assertConstantBlock("V[0][1]", FRAME_ORIGIN_DC, macroBlock.getVSubBlock(0, 1));
        assertConstantBlock("V[1][0]", FRAME_ORIGIN_DC, macroBlock.getVSubBlock(1, 0));
    }

    @Test
    void bPredClampsReconstructionToValidSampleRange() {
        MacroBlock brightBlock = macroBlock(Globals.B_PRED, Globals.DC_PRED);
        brightBlock.getYSubBlock(1, 1).getTokens()[0] = 2000;
        brightBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), brightBlock));

        assertConstantDiff("Y[1][1] bright", 1000, brightBlock.getYSubBlock(1, 1).getDiff());
        assertConstantBlock("Y[1][1] bright", 255, brightBlock.getYSubBlock(1, 1));

        MacroBlock darkBlock = macroBlock(Globals.B_PRED, Globals.DC_PRED);
        darkBlock.getYSubBlock(1, 1).getTokens()[0] = -2000;
        darkBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), darkBlock));

        assertConstantDiff("Y[1][1] dark", -1000, darkBlock.getYSubBlock(1, 1).getDiff());
        assertConstantBlock("Y[1][1] dark", 0, darkBlock.getYSubBlock(1, 1));
    }

    // ---------------------------------------------------------------------------------------------
    // Assertion helpers
    // ---------------------------------------------------------------------------------------------

    private void assertPredictionOnlyReconstruction(int mode, int expected) {
        MacroBlock macroBlock = macroBlock(mode, mode);

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                SubBlock yBlock = macroBlock.getYSubBlock(x, y);
                assertConstantDiff("Y[" + x + "][" + y + "]", 0, yBlock.getDiff());
                assertConstantBlock("Y[" + x + "][" + y + "]", expected, yBlock);
            }
        }

        assertChromaBlocksConstant(expected, macroBlock);
    }

    private static void assertChromaBlocksConstant(int expected, MacroBlock macroBlock) {
        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                assertConstantBlock("U[" + x + "][" + y + "]", expected, macroBlock.getUSubBlock(x, y));
                assertConstantBlock("V[" + x + "][" + y + "]", expected, macroBlock.getVSubBlock(x, y));
            }
        }
    }

    private static void assertConstantBlock(String label, int expected, SubBlock subBlock) {
        assertTrue(subBlock.isDest(), label + " must be reconstructed");
        assertBlockContent(label, subBlock, new int[][] {
                {expected, expected, expected, expected},
                {expected, expected, expected, expected},
                {expected, expected, expected, expected},
                {expected, expected, expected, expected},
        });
    }

    private static void assertBlockContent(String label, SubBlock subBlock, int[][] expected) {
        int[][] actual = subBlock.getDest();
        assertNotNull(actual, label + " dest");
        assertEquals(expected.length, actual.length, label + " dest height");

        for (int r = 0; r < expected.length; r++) {
            for (int c = 0; c < expected[r].length; c++) {
                assertEquals(expected[r][c], actual[r][c], label + " dest[" + r + "][" + c + "]");
            }
        }
    }

    private static void assertConstantDiff(String label, int expected, int[][] diff) {
        assertNotNull(diff, label + " diff");
        assertEquals(4, diff.length, label + " diff height");

        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                assertEquals(expected, diff[i][j], label + " diff[" + i + "][" + j + "]");
            }
        }
    }

    // ---------------------------------------------------------------------------------------------
    // Fixture helpers
    // ---------------------------------------------------------------------------------------------

    /**
     * Creates the macro block under test at the top left corner of the frame, keeping debug
     * information so the intermediate coefficients and samples can be inspected.
     */
    private static MacroBlock macroBlock(int yMode, int uvMode) {
        MacroBlock macroBlock = new MacroBlock(1, 1, true);
        macroBlock.setYMode(yMode);
        macroBlock.setUvMode(uvMode);

        return macroBlock;
    }

    /**
     * Creates a segment quantizer table where every segment uses the given Q index and no
     * delta Q values.
     */
    private static SegmentQuants segmentQuants(int qIndex) {
        SegmentQuants quants = new SegmentQuants();

        for (SegmentQuant quant : quants.getSegQuants()) {
            quant.setQindex(qIndex);
            quant.setY1dc(0);
            quant.setY2dc(0);
            quant.setY2ac_delta_q(0);
            quant.setUvdc_delta_q(0);
            quant.setUvac_delta_q(0);
        }

        return quants;
    }

    /**
     * Creates a minimal single macro block frame with {@code macroBlock} at position {@code 0,0}.
     */
    private static VP8Frame frame(SegmentQuants quants, MacroBlock macroBlock) {
        int macroBlockCols = 1;

        // The decoder surrounds the frame with a row above (y == -1) and a column left (x == -1) of
        // macro blocks that are never reconstructed, so predictions see the border samples.
        MacroBlock[] rowAbove = new MacroBlock[macroBlockCols + 2];
        MacroBlock[] currentRow = new MacroBlock[macroBlockCols + 2];

        for (int col = 0; col < macroBlockCols + 2; col++) {
            rowAbove[col] = borderMacroBlock(col);
            currentRow[col] = borderMacroBlock(col);
        }

        currentRow[1] = macroBlock;

        return frame(quants, macroBlockCols, 1, rowAbove, currentRow, 0);
    }

    /**
     * Creates a frame and injects the quantizers, geometry and macro block rows the decoder would
     * set up while decoding. {@link VP8Frame}s are normally created from a bit stream; the state
     * required for dequantization and reconstruction is injected here, so no bit stream is needed.
     */
    private static VP8Frame frame(SegmentQuants quants, int macroBlockCols, int macroBlockRows,
                                  MacroBlock[] rowAbove, MacroBlock[] currentRow, int currentRowIndex) {
        VP8Frame frame;

        try {
            frame = new VP8Frame(new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0])), true);
        }
        catch (IOException e) {
            throw new AssertionError("Could not create frame", e);
        }

        set(frame, "segmentQuants", quants);
        set(frame, "macroBlockCols", macroBlockCols);
        set(frame, "macroBlockRows", macroBlockRows);
        set(frame, "topMacroBlockRow", rowAbove);
        set(frame, "previousMacroBlockRow", rowAbove);
        set(frame, "currentMacroBlockRow", currentRow);
        set(frame, "currentMacroBlockRowIndex", currentRowIndex);
        set(frame, "lastNonBPredMacroBlockByColumn", rowAbove);

        return frame;
    }

    /**
     * Creates a macro block that has never been reconstructed, as found above and to the left of
     * the first macro block row/column of the frame.
     */
    private static MacroBlock borderMacroBlock(int column) {
        MacroBlock macroBlock = new MacroBlock(column, 0, true);
        macroBlock.setYMode(Globals.DC_PRED);
        macroBlock.setUvMode(Globals.DC_PRED);

        return macroBlock;
    }

    /**
     * Marks all sub blocks of the macro block as reconstructed with the given sample value.
     */
    private static void reconstructConstant(MacroBlock macroBlock, int value) {
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                macroBlock.getYSubBlock(x, y).setDest(constantBlock(value));
            }
        }

        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                macroBlock.getUSubBlock(x, y).setDest(constantBlock(value));
                macroBlock.getVSubBlock(x, y).setDest(constantBlock(value));
            }
        }
    }

    private static int[][] constantBlock(int value) {
        int[][] block = new int[4][4];

        for (int[] row : block) {
            Arrays.fill(row, value);
        }

        return block;
    }

    private static void set(Object target, String name, Object value) {
        try {
            Field field = target.getClass().getDeclaredField(name);
            field.setAccessible(true);
            field.set(target, value);
        }
        catch (ReflectiveOperationException e) {
            throw new AssertionError("Could not set " + target.getClass().getSimpleName() + "." + name, e);
        }
    }
}
