package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.MemoryCacheImageInputStream;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link MacroBlock#dequantMacroBlock(VP8Frame)}.
 * <p>
 * Macro blocks are placed at the first position of a small macro block frame, so intra prediction
 * reads the RFC 6386 border samples: 127 for the row above the frame and 129 for the column left of
 * it. The macro blocks surrounding the frame are plain {@link Globals#DC_PRED} blocks that have
 * never been reconstructed.
 * <p>
 * With Q index 0 the dequantization factors are {@code y2dc == 2 * 4 == 8}, {@code y2ac == 8},
 * {@code y1dc == uvdc == 4} and {@code y1ac == uvac == 4} (see {@code Globals#vp8DcQLookup} and
 * {@code Globals#vp8AcQLookup}), which keeps the expected values small and easy to follow.
 */
class MacroBlockDequantMacroBlockTests {

    /** Q index 0 maps to {@code vp8DcQLookup[0] == 4} and {@code vp8AcQLookup[0] == 4}. */
    private static final int Q_INDEX = 0;

    /** DC prediction value of a block at the top left corner of the frame. */
    private static final int FRAME_ORIGIN_DC = 128;

    // ---------------------------------------------------------------------------------------------
    // Non B_PRED macro blocks (the luma DC is coded in the Y2 block and transformed by a
    // Walsh-Hadamard transform first)
    // ---------------------------------------------------------------------------------------------

    @Test
    void nonBPredWithoutCoefficientsReconstructsToPredictionOnly() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        assertConstantDiff("Y2", 0, macroBlock.getY2SubBlock().getDiff());

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                SubBlock yBlock = macroBlock.getYSubBlock(x, y);
                assertConstantDiff("Y[" + x + "][" + y + "]", 0, yBlock.getDiff());
                assertConstantBlock("Y[" + x + "][" + y + "]", FRAME_ORIGIN_DC, yBlock);
            }
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);

        // Only the 16 Y, 4 U and 4 V sub blocks are reconstructed, the Y2 block itself is not.
        assertFalse(macroBlock.getY2SubBlock().isDest(), "Y2 sub block must not be reconstructed");
    }

    @Test
    void nonBPredScalesY2DcCoefficientWithY2DcQuantizer() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        // DC coefficient 4 * y2dc (8) == 32
        macroBlock.getY2SubBlock().getTokens()[0] = 4;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        // A DC only inverse Walsh-Hadamard transform spreads the coefficient over all 16 samples:
        // (32 + 3) / 8 == 4.
        assertConstantDiff("Y2", 4, macroBlock.getY2SubBlock().getDiff());

        // Every Y block is dequantized with that DC value: (4 + 4) / 8 == 1 on top of the DC
        // prediction of 128.
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                SubBlock yBlock = macroBlock.getYSubBlock(x, y);
                assertConstantDiff("Y[" + x + "][" + y + "]", 1, yBlock.getDiff());
                assertConstantBlock("Y[" + x + "][" + y + "]", FRAME_ORIGIN_DC + 1, yBlock);
            }
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);
    }

    @Test
    void nonBPredScalesY2AcCoefficientsWithY2AcQuantizer() {
