        // First AC coefficient 8 * y2ac (8) == 64
        macroBlock.getY2SubBlock().getTokens()[1] = 8;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        // Unlike a DC only coefficient, an AC coefficient only reaches two of the four Y block
        // columns, with opposite signs, so the Y blocks are no longer uniform.
        int[][] y2Diff = macroBlock.getY2SubBlock().getDiff();
        assertNotNull(y2Diff, "Y2 diff");
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                int expected = i < 2 ? 8 : -8;
                assertEquals(expected, y2Diff[i][j], "Y2 diff[" + i + "][" + j + "]");
            }
        }

        for (int y = 0; y < 4; y++) {
            // Y blocks in the first two columns get +8, the last two get -8:
            // (8 + 4) / 8 == 1 and (-8 + 4) / 8 == -1.
            assertConstantBlock("Y[0][" + y + "]", FRAME_ORIGIN_DC + 1, macroBlock.getYSubBlock(0, y));
            assertConstantBlock("Y[1][" + y + "]", FRAME_ORIGIN_DC + 1, macroBlock.getYSubBlock(1, y));
            assertConstantBlock("Y[2][" + y + "]", FRAME_ORIGIN_DC - 1, macroBlock.getYSubBlock(2, y));
            assertConstantBlock("Y[3][" + y + "]", FRAME_ORIGIN_DC - 1, macroBlock.getYSubBlock(3, y));
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);
    }

    @Test
    void nonBPredUsesQuantizerOfTheSegmentOfTheMacroBlock() {
