        assertConstantDiff("Y2 segment 0", 4, firstSegmentBlock.getY2SubBlock().getDiff());
        assertConstantDiff("Y2 segment 1", 27, secondSegmentBlock.getY2SubBlock().getDiff());

        // (4 + 4) / 8 == 1 versus (27 + 4) / 8 == 3.
        assertConstantBlock("Y[0][0] segment 0", FRAME_ORIGIN_DC + 1, firstSegmentBlock.getYSubBlock(0, 0));
        assertConstantBlock("Y[0][0] segment 1", FRAME_ORIGIN_DC + 3, secondSegmentBlock.getYSubBlock(0, 0));
    }

    @Test
    void nonBPredUsesChromaQuantizersForTheChromaBlocks() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        // uvdc == 4: 4 * 4 == 16 -> (16 + 4) / 8 == 2
        macroBlock.getUSubBlock(0, 0).getTokens()[0] = 4;
        // uvac == 4: 4 * 4 == 16, an AC coefficient spreads over the block
        macroBlock.getUSubBlock(1, 1).getTokens()[1] = 4;
        // uvdc == 4: 2 * 4 == 8 -> (8 + 4) / 8 == 1
        macroBlock.getVSubBlock(0, 1).getTokens()[0] = 2;
        macroBlock.getVSubBlock(1, 1).getTokens()[1] = 4;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        assertConstantDiff("U[0][0]", 2, macroBlock.getUSubBlock(0, 0).getDiff());
        assertConstantBlock("U[0][0]", FRAME_ORIGIN_DC + 2, macroBlock.getUSubBlock(0, 0));

        assertConstantDiff("V[0][1]", 1, macroBlock.getVSubBlock(0, 1).getDiff());
        assertConstantBlock("V[0][1]", FRAME_ORIGIN_DC + 1, macroBlock.getVSubBlock(0, 1));

        // The inverse DCT of an AC only coefficient yields (0 + 16 + 4) / 8 == 3, 1, -1 and -2
        // for the four rows of the block, added to the prediction of 128.
        int[][] expectedAcBlock = {
                {131, 131, 131, 131},
                {129, 129, 129, 129},
                {127, 127, 127, 127},
                {126, 126, 126, 126},
        };
        assertBlockContent("U[1][1]", macroBlock.getUSubBlock(1, 1), expectedAcBlock);
        assertBlockContent("V[1][1]", macroBlock.getVSubBlock(1, 1), expectedAcBlock);

        // Untouched chroma blocks only contain the DC prediction.
        assertConstantBlock("U[1][0]", FRAME_ORIGIN_DC, macroBlock.getUSubBlock(1, 0));
        assertConstantBlock("U[0][1]", FRAME_ORIGIN_DC, macroBlock.getUSubBlock(0, 1));
        assertConstantBlock("V[0][0]", FRAME_ORIGIN_DC, macroBlock.getVSubBlock(0, 0));
        assertConstantBlock("V[1][0]", FRAME_ORIGIN_DC, macroBlock.getVSubBlock(1, 0));

        // Luma is not affected by chroma coefficients.
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertConstantBlock("Y[" + x + "][" + y + "]", FRAME_ORIGIN_DC, macroBlock.getYSubBlock(x, y));
            }
        }
    }

    @Test
    void nonBPredClampsReconstructionTo255() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
        // 2000 * 8 == 16000 -> (16000 + 3) / 8 == 2000, (2000 + 4) / 8 == 250
        macroBlock.getY2SubBlock().getTokens()[0] = 2000;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        assertConstantDiff("Y2", 2000, macroBlock.getY2SubBlock().getDiff());
        assertConstantDiff("Y[0][0]", 250, macroBlock.getYSubBlock(0, 0).getDiff());
        // 128 + 250 == 378 is clamped to the maximum sample value.
        assertConstantBlock("Y[0][0]", 255, macroBlock.getYSubBlock(0, 0));

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertConstantBlock("Y[" + x + "][" + y + "]", 255, macroBlock.getYSubBlock(x, y));
            }
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);
    }

    @Test
    void nonBPredClampsReconstructionToZero() {
        MacroBlock macroBlock = macroBlock(Globals.DC_PRED, Globals.DC_PRED);
