        macroBlock.getY2SubBlock().getTokens()[0] = -2000;

        macroBlock.dequantMacroBlock(frame(segmentQuants(Q_INDEX), macroBlock));

        assertConstantDiff("Y2", -2000, macroBlock.getY2SubBlock().getDiff());
        assertConstantDiff("Y[3][2]", -250, macroBlock.getYSubBlock(3, 2).getDiff());
        // 128 - 250 == -122 is clamped to the minimum sample value.
        assertConstantBlock("Y[3][2]", 0, macroBlock.getYSubBlock(3, 2));

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertConstantBlock("Y[" + x + "][" + y + "]", 0, macroBlock.getYSubBlock(x, y));
            }
        }

        assertChromaBlocksConstant(FRAME_ORIGIN_DC, macroBlock);
    }

    @Test
    void nonBPredVerticalPredictionUsesSampleRowAboveTheFrame() {
        // V_PRED copies the row above the macro block, which is 127 outside the frame.
        assertPredictionOnlyReconstruction(Globals.V_PRED, 127);
    }

    @Test
    void nonBPredHorizontalPredictionUsesSampleColumnLeftOfTheFrame() {
        // H_PRED copies the column left of the macro block, which is 129 outside the frame.
        assertPredictionOnlyReconstruction(Globals.H_PRED, 129);
    }

    @Test
    void nonBPredTrueMotionPredictionUsesLeftPlusAboveMinusAboveLeft() {
        // TM_PRED is left (129) + above (127) - above left (127) == 129 at the frame origin.
        assertPredictionOnlyReconstruction(Globals.TM_PRED, 129);
