    else {
        int rv = 127;
        if (intra_mode == Globals.H_PRED) {
            rv = 129;
        }
        int[][] r = new int[4][4];
        for (int j = 0; j < 4; j++) {
            for (int i = 0; i < 4; i++) {
                r[i][j] = rv;
            }
        }
        return r;
    }
}

