     * Mutable builder for XWD (X11 Window Dump) file headers.
     * Defaults to a valid, 4x3 pixel, 24 bits per pixel true color header without color map
     * and without window name.
     */
    private static final class Xwd {
        int length = -1;                                        // -1 => computed from header + window name
        int version = HEADER_VERSION;
        int format = X11.PIXMAP_FORMAT_ZPIXMAP;
        int depth = 24;
        int width = 4;
        int height = 3;
        int xOffset = 0;
        int byteOrder = 1;
        int unit = 1;
        int bitOrder = 1;
        int pad = 0;
        int bitsPerPixel = 24;
        int bytesPerLine = -1;                                  // -1 => computed from width and bits per pixel
        int visualClass = X11.VISUAL_CLASS_TRUE_COLOR;
        int redMask = 0xFF0000;
        int greenMask = 0x00FF00;
        int blueMask = 0x0000FF;
        int bitsPerRGB = 8;
        int numColors = 0;
        int colorMapEntries = 0;
        int windowWidth = 4;
        int windowHeight = 3;
        int windowX = 0;
        int windowY = 0;
        int windowBorderWidth = 0;

        byte[] windowNameData = new byte[0];
        byte[] colorMapData = new byte[0];

        Xwd length(int length) {
            this.length = length;
            return this;
        }

        Xwd version(int version) {
            this.version = version;
            return this;
        }

        Xwd width(int width) {
            this.width = width;
            return this;
        }

        Xwd height(int height) {
            this.height = height;
            return this;
        }

        Xwd byteOrder(int byteOrder) {
            this.byteOrder = byteOrder;
            return this;
        }

        Xwd bitOrder(int bitOrder) {
            this.bitOrder = bitOrder;
            return this;
        }

        Xwd bitsPerPixel(int bitsPerPixel) {
            this.bitsPerPixel = bitsPerPixel;
            return this;
        }

        Xwd bitsPerRGB(int bitsPerRGB) {
            this.bitsPerRGB = bitsPerRGB;
            return this;
        }

        Xwd bytesPerLine(int bytesPerLine) {
            this.bytesPerLine = bytesPerLine;
            return this;
        }

        Xwd visualClass(int visualClass) {
            this.visualClass = visualClass;
            return this;
        }

        Xwd redMask(int redMask) {
            this.redMask = redMask;
            return this;
        }

        Xwd greenMask(int greenMask) {
            this.greenMask = greenMask;
            return this;
        }

        Xwd blueMask(int blueMask) {
            this.blueMask = blueMask;
            return this;
        }

        Xwd colorMapEntries(int colorMapEntries) {
            this.colorMapEntries = colorMapEntries;
            return this;
        }

        Xwd windowNameBytes(byte[] windowNameData) {
            this.windowNameData = windowNameData;
            return this;
        }

        Xwd windowName(String windowName) {
            return windowNameBytes((windowName + "\u0000").getBytes(StandardCharsets.UTF_8));
        }

        Xwd rawColorMap(byte[] colorMapData, int colorMapEntries) {
            this.colorMapData = colorMapData;
            this.colorMapEntries = colorMapEntries;
            return this;
        }

        Xwd colorMap(int[][] rgbEntries) {
            ByteArrayOutputStream out = new ByteArrayOutputStream();

            for (int[] rgb : rgbEntries) {
                out.write(0);            // pixel value (ignored by the reader)
                out.write(0);
                out.write(0);
                out.write(0);
                out.write(rgb[0]);       // red, high byte
                out.write(0);            // red, low byte
                out.write(rgb[1]);       // green, high byte
                out.write(0);
                out.write(rgb[2]);       // blue, high byte
                out.write(0);
                out.write(0);            // flags
                out.write(0);            // padding
            }

            return rawColorMap(out.toByteArray(), rgbEntries.length);
        }

        byte[] bytes() {
            int headerLength = length >= 0 ? length : HEADER_SIZE + windowNameData.length;
            int lineBytes = bytesPerLine >= 0 ? bytesPerLine : (int) (((long) width * bitsPerPixel + 7) / 8);

            try {
                ByteArrayOutputStream out = new ByteArrayOutputStream();
                DataOutputStream data = new DataOutputStream(out);

                data.writeInt(headerLength);        // header size, including window name
                data.writeInt(version);
                data.writeInt(format);
                data.writeInt(depth);
                data.writeInt(width);
                data.writeInt(height);
                data.writeInt(xOffset);
                data.writeInt(byteOrder);
                data.writeInt(unit);
                data.writeInt(bitOrder);
                data.writeInt(pad);
                data.writeInt(bitsPerPixel);
                data.writeInt(lineBytes);
                data.writeInt(visualClass);
                data.writeInt(redMask);
                data.writeInt(greenMask);
                data.writeInt(blueMask);
                data.writeInt(bitsPerRGB);
                data.writeInt(numColors);
                data.writeInt(colorMapEntries);
                data.writeInt(windowWidth);
                data.writeInt(windowHeight);
                data.writeInt(windowX);
                data.writeInt(windowY);
                data.writeInt(windowBorderWidth);

                data.write(windowNameData);
                data.write(colorMapData);
                data.flush();

                return out.toByteArray();
            }
            catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
