/**
 * Tests for {@link XWDX11Header#read(javax.imageio.stream.ImageInputStream)}.
 * <p>
 * The tests build XWD (X11 Window Dump) headers in memory, using the layout described
 * by the X11 {@code XWDFileHeader} structure:
 * <pre>
 * 25 x 32 bit big endian integers, followed by the window name (NUL terminated)
 * and finally the (optional) color map, 12 bytes per entry.
 * </pre>
 */
public class XWDX11HeaderReadTests {

    private static final int HEADER_SIZE = X11.X11_HEADER_SIZE;
    private static final int HEADER_VERSION = X11.X11_HEADER_VERSION;

    // ------------------------------------------------------------------------
