    // ------------------------------------------------------------------------

    @Test
    public void testReadMinimalHeader() throws IOException {
        Xwd header = new Xwd();

        XWDX11Header result = read(header.bytes());

        assertNotNull(result);
        assertEquals(4, result.width);
        assertEquals(3, result.height);
        assertEquals(24, result.bitsPerPixel);
        assertEquals(12, result.bytesPerLine, "bytesPerLine should be width * bitsPerPixel / 8");
        assertEquals(X11.VISUAL_CLASS_TRUE_COLOR, result.visualClass);
        assertEquals(8, result.bitsPerRGB);

        // No color map, no window name
        assertNull(result.colorMap, "No color map should be created when there are no color map entries");
        assertNull(result.windowName, "No window name should be present when length == header size");

        // Header starts at position 0, so the pixel data starts right after the header
        assertEquals(HEADER_SIZE, result.pixelOffset);

        // 24 bits per pixel, 8 bits per primary => 3 components
        assertEquals(3, result.numComponents());
    }

    @Test
    public void testReadDimensionsAndVisualClassPreserved() throws IOException {
        Xwd header = new Xwd()
                .width(640)
                .height(426)
                .visualClass(X11.VISUAL_CLASS_PSEUDO_COLOR)
                .bitsPerPixel(8)
                .bitsPerRGB(8);

        XWDX11Header result = read(header.bytes());

        assertEquals(640, result.width);
        assertEquals(426, result.height);
        assertEquals(X11.VISUAL_CLASS_PSEUDO_COLOR, result.visualClass);
        assertEquals(8, result.bitsPerPixel);
        assertEquals(8, result.bitsPerRGB);
        assertEquals(640, result.bytesPerLine);
        assertEquals(1, result.numComponents());
    }

    @Test
    public void testReadByteOrderMapping() throws IOException {
        XWDX11Header little = read(new Xwd().byteOrder(0).bytes());
        assertEquals(ByteOrder.LITTLE_ENDIAN, little.byteOrder);

        XWDX11Header big = read(new Xwd().byteOrder(1).bytes());
        assertEquals(ByteOrder.BIG_ENDIAN, big.byteOrder);

        // Any non-zero value means big endian (MSB first)
        XWDX11Header otherNonZero = read(new Xwd().byteOrder(42).bytes());
        assertEquals(ByteOrder.BIG_ENDIAN, otherNonZero.byteOrder);
    }

    @Test
    public void testReadBitFillOrderMapping() throws IOException {
        XWDX11Header lsbFirst = read(new Xwd().bitOrder(0).bytes());
        assertEquals(ByteOrder.LITTLE_ENDIAN, lsbFirst.bitFillOrder);

        XWDX11Header msbFirst = read(new Xwd().bitOrder(1).bytes());
        assertEquals(ByteOrder.BIG_ENDIAN, msbFirst.bitFillOrder);

        XWDX11Header otherNonZero = read(new Xwd().bitOrder(99).bytes());
        assertEquals(ByteOrder.BIG_ENDIAN, otherNonZero.bitFillOrder);
    }

