    XWDX11Header result = read(new Xwd().windowNameBytes(nameData).bytes());

    assertNotNull(result.windowName);
    assertEquals(Short.MAX_VALUE - 1, result.windowName.length());
    assertFalse(result.windowName.isEmpty());
    assertEquals('A', result.windowName.charAt(0));
